// The full chat surface — live transcript + prompt panel + composer.
// Shared verbatim between the in-grid SessionCard and the long-press full-height
// SessionTitleSheet so both drive the same send pipeline (no duplicated state).
// It owns the composer's own text/sending state; `error` is lifted to the host
// so model/assign errors can surface in the same bar.
// A prominent, explained "build paused" banner shown whenever the backend
// marks a session blocked. Two cases today: the session's model became
// unavailable (offer a one-click relaunch onto Opus — the backend respawns the
// pane on the new model since an injected `/model` can't recover a frozen
// session), or the build agent ran out of AI credits (explain + tell them to
// top up). Without this, a frozen session just shows a dead spinner and the
// user has no idea what happened or what to do.
function StaleCapabilitiesBanner({ session }: { session: Session }) {
  if (!session.capabilitiesStale) return null;
  return (
    <div className="border-b border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-900 dark:text-amber-200">
      This session started with an older omg.dev capability contract. Close and resume it to load the latest shipped tools and guidance.
    </div>
  );
}

function PausedBanner({
  session,
  onRefresh,
  onContinue,
}: {
  session: Session;
  onRefresh: () => Promise<void>;
  onContinue: () => Promise<void>;
}) {
  const authFlow = useContext(CodingAgentAuthContext);
  const [working, setWorking] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  if (session.status !== "blocked") return null;
  const sid = session.sessionId;
  const reason = session.statusReason;
  const reconnectKind =
    reason === "provider_auth" && session.agent && BROWSER_AUTH_KINDS.has(session.agent)
      ? (session.agent as AgentKind)
      : null;
  const reconnectLabel =
    reconnectKind === "codex" || reconnectKind === "codex-aisdk"
      ? "Codex"
      : reconnectKind === "grok"
        ? "Grok"
        : "Claude";
  const inlineAuth =
    sid && authFlow?.inlineSid === sid ? authFlow.session : null;
  const reconnected = !!sid && authFlow?.completedSid === sid;
  const canSwitchClaude =
    reason === "model_unavailable" && session.agent === "claude" && !!session.tmuxTarget && !!sid;
  const canSwitchOpencode =
    session.agent === "opencode" &&
    (reason === "provider_auth" || reason === "provider_error") &&
    !!sid;

  async function switchModel(model: string) {
    if (!sid) return;
    setWorking(true);
    setErr(null);
    try {
      await api(`/api/sessions/${sid}/model`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model }),
      });
      await onRefresh();
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally {
      setWorking(false);
    }
  }

  async function reconnectProvider() {
    if (!sid || !reconnectKind || !authFlow) return;
    setWorking(true);
    setErr(null);
    try {
      await authFlow.start(reconnectKind as AgentKind, sid);
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally {
      setWorking(false);
    }
  }

  async function continueSession() {
    setWorking(true);
    setErr(null);
    try {
      await onContinue();
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally {
      setWorking(false);
    }
  }

  const title =
    reason === "restart_recovered"
      ? "Session recovered after restart"
      : reason === "out_of_credits"
      ? "Build paused — out of credits"
      : reason === "provider_auth"
        ? reconnectKind
          ? `${reconnectLabel} sign-in expired`
          : "Build paused — provider rejected the model"
        : reason === "provider_error"
          ? "Build paused — provider error"
          : "Build paused";
  const detail =
    reason === "restart_recovered"
      ? session.statusDetail || "The previous turn was interrupted. Review the last output, then send a message to continue safely."
      : reason === "out_of_credits"
      ? "This app's build agent ran out of AI credits. Top up the wallet to resume the build."
      : reason === "provider_auth"
        ? reconnectKind
          ? reconnected
            ? `${reconnectLabel} is connected again. Send your message again to resume this session.`
            : `${session.statusDetail || `Your ${reconnectLabel} login is no longer valid.`} Sign in again here, then retry your message.`
          : `${session.statusDetail || "The selected provider rejected the request."} Check the OpenCode provider key or switch models.`
        : reason === "provider_error"
          ? pausedProviderErrorDetail(session)
      : `${session.statusDetail || "The selected model isn't available."} Switch to a working model to pick the build back up.`;

  return (
    <div className="border-b border-warning/30 bg-warning/12 px-3 py-2 text-xs">
      <div className="flex items-center justify-between gap-3">
        <div className="min-w-0">
          <div className="font-semibold text-warning">{title}</div>
          <div className="mt-0.5 text-foreground/70">{detail}</div>
          {err ? <div className="mt-1 text-destructive">{err}</div> : null}
        </div>
        {reason === "restart_recovered" ? (
          <button
            type="button"
            onClick={() => void continueSession()}
            disabled={working}
            className="shrink-0 rounded-lg bg-warning px-3 py-1.5 font-medium text-white disabled:opacity-50"
          >
            {working ? "Continuing…" : "Continue"}
          </button>
        ) : null}
        {canSwitchClaude ? (
          <button
            type="button"
            onClick={() => void switchModel("opus")}
            disabled={working}
            className="shrink-0 rounded-lg bg-warning px-3 py-1.5 font-medium text-white disabled:opacity-50"
          >
            {working ? "Resuming…" : "Resume on Opus"}
          </button>
        ) : null}
        {canSwitchOpencode ? (
          <button
            type="button"
            onClick={() => void switchModel("opencode/big-pickle")}
            disabled={working}
            className="shrink-0 rounded-lg bg-warning px-3 py-1.5 font-medium text-white disabled:opacity-50"
          >
            {working ? "Switching…" : "Use Big Pickle"}
          </button>
        ) : null}
        {reconnectKind && !inlineAuth && !reconnected ? (
          <button
            type="button"
            onClick={() => void reconnectProvider()}
            disabled={working || !authFlow}
            className="shrink-0 rounded-lg bg-warning px-3 py-1.5 font-medium text-white disabled:opacity-50"
          >
            {working ? "Opening…" : `Sign in to ${reconnectLabel}`}
          </button>
        ) : null}
        {reconnected ? (
          <span className="flex shrink-0 items-center gap-1.5 rounded-lg bg-emerald-500/15 px-3 py-1.5 font-medium text-emerald-700 dark:text-emerald-300">
            <Check className="size-3.5" />
            Connected
          </span>
        ) : null}
      </div>
      {inlineAuth && authFlow ? (
        <CodingAgentAuthPanel
          session={inlineAuth}
          inline
          onSessionChange={authFlow.setSession}
          onDismiss={authFlow.clear}
          onComplete={async () => {
            await authFlow.complete();
            await onRefresh();
          }}
        />
      ) : null}
    </div>
  );
}

function SkillSlashSuggest({
  active,
  onPick,
}: {
  active: SlashSkillState | null;
  onPick: (skill: SkillCatalogItem) => void;
}) {
  const [skills, setSkills] = useState<SkillCatalogItem[]>([]);
  const [selected, setSelected] = useState(0);

  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    loadSkillCatalog()
      .then((items) => {
        if (!cancelled) setSkills(items);
      })
      .catch(() => {
        if (!cancelled) setSkills([]);
      });
    return () => {
      cancelled = true;
    };
  }, [active]);

  useEffect(() => setSelected(0), [active?.query]);

  // Body text no longer ships with the catalog (it was 87% of its bytes), so
  // matching against a skill's prose happens on the box. Names still match
  // locally and instantly below — this only ADDS the deeper hits, debounced,
  // so the common case (type the skill's name) never waits on the network and
  // a slow or failed request can only mean "fewer results", never an empty
  // picker.
  const query = active?.query ?? "";
  const [deepHits, setDeepHits] = useState<{ q: string; items: SkillCatalogItem[] }>({
    q: "",
    items: [],
  });

  useEffect(() => {
    if (!active || !query) {
      setDeepHits({ q: "", items: [] });
      return;
    }
    let cancelled = false;
    const timer = setTimeout(() => {
      api<{ skills: SkillCatalogItem[] }>(`/api/skills?q=${encodeURIComponent(query)}`)
        .then((r) => {
          if (!cancelled) setDeepHits({ q: query, items: Array.isArray(r.skills) ? r.skills : [] });
        })
        .catch(() => {
          if (!cancelled) setDeepHits({ q: query, items: [] });
        });
    }, 140);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [active, query]);

  const matches = useMemo(() => {
    if (!active) return [];
    const q = active.query;
    const local = skills.filter((skill) => {
      const haystack = `${skill.trigger} ${skill.name} ${skill.description}`.toLowerCase();
      return !q || haystack.includes(q);
    });
    if (!q) return local;
    // Name matches first, then body-only matches, so ranking stays stable as
    // the deeper results land underneath what is already on screen.
    const seen = new Set(local.map((skill) => `${skill.source}:${skill.trigger}`));
    const deeper =
      deepHits.q === q
        ? deepHits.items.filter((skill) => !seen.has(`${skill.source}:${skill.trigger}`))
        : [];
    return [...local, ...deeper];
  }, [active, skills, deepHits]);

  if (!active || !matches.length) return null;

  return (
    <div
      data-no-composer-swipe
      onWheel={(event) => event.stopPropagation()}
      onTouchStart={(event) => event.stopPropagation()}
      onTouchMove={(event) => event.stopPropagation()}
      onTouchEnd={(event) => event.stopPropagation()}
      className="absolute bottom-full left-0 right-0 z-50 mb-2 overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground shadow-xl"
    >
      <div className="max-h-[min(18rem,42dvh)] overflow-y-auto overscroll-contain p-1 touch-pan-y">
        {matches.map((skill, idx) => (
          <button
            key={`${skill.source}:${skill.trigger}`}
            type="button"
            data-skill-suggest-option
            onMouseDown={(event) => {
              event.preventDefault();
            }}
            onClick={() => onPick(skill)}
            onMouseEnter={() => setSelected(idx)}
            className={cn(
              "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-sm",
              idx === selected ? "bg-accent text-accent-foreground" : "hover:bg-accent/70",
            )}
          >
            <span className="min-w-0 flex-1">
              <span className="block truncate font-medium">
                <span className="font-mono text-primary">/</span>
                {skill.trigger}
              </span>
              {skill.description ? (
                <span className="mt-0.5 block truncate text-xs leading-snug text-muted-foreground">
                  {skill.description}
                </span>
              ) : null}
            </span>
            <span className="shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[10px] uppercase text-muted-foreground">
              {skill.source} skill
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

/**
 * The `@` bot picker. Mirrors SkillSlashSuggest's shell (position, swipe/wheel
 * guards, option rows) so the two composer pickers stay visually identical.
 *
 * Source of truth is BotDirectoryContext, the roster the app already loaded
 * from GET /api/bots. No fetch here: the list is small and already in memory,
 * so the picker opens instantly and cannot show a spinner or a stale network
 * error.
 */
function BotMentionSuggest({
  active,
  matches,
  selected,
  onHover,
  onPick,
}: {
  active: BotMentionState | null;
  /** Owned by SkillTextarea, because the arrow keys arrive at the textarea. */
  matches: PersistentBot[];
  selected: number;
  onHover: (index: number) => void;
  onPick: (bot: PersistentBot) => void;
}) {
  const listRef = useRef<HTMLDivElement>(null);

  // Arrow keys can walk the highlight past the scroll viewport. A highlight
  // you cannot see reads as a menu that stopped responding.
  useEffect(() => {
    listRef.current
      ?.querySelector<HTMLElement>(`[data-bot-mention-option="${selected}"]`)
      ?.scrollIntoView({ block: "nearest" });
  }, [selected]);

  if (!active || !matches.length) return null;

  return (
    <div
      data-no-composer-swipe
      onWheel={(event) => event.stopPropagation()}
      onTouchStart={(event) => event.stopPropagation()}
      onTouchMove={(event) => event.stopPropagation()}
      onTouchEnd={(event) => event.stopPropagation()}
      className="absolute bottom-full left-0 right-0 z-50 mb-2 overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground shadow-xl"
    >
      <div
        ref={listRef}
        className="max-h-[min(18rem,42dvh)] overflow-y-auto overscroll-contain p-1 touch-pan-y"
      >
        {matches.map((bot, idx) => (
          <button
            key={bot.id}
            type="button"
            data-bot-mention-option={idx}
            aria-selected={idx === selected}
            onMouseDown={(event) => {
              event.preventDefault();
            }}
            onClick={() => onPick(bot)}
            onMouseEnter={() => onHover(idx)}
            className={cn(
              "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-sm",
              idx === selected ? "bg-accent text-accent-foreground" : "hover:bg-accent/70",
            )}
          >
            <BotMascot
              shape={bot.shape}
              colorway={bot.colorway}
              size={16}
              state="idle"
              seed={bot.id.length}
            />
            <span className="min-w-0 flex-1">
              <span className="block truncate font-medium">
                <span className="font-mono text-primary">@</span>
                {bot.name}
              </span>
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

// One owner for composer-picker keys, shared by the `/` skill picker and the
// `@` bot picker. `selector` names the option rows of whichever picker is open;
// only one ever is, because their trigger characters are distinct.
function handleSuggestKey(
  event: ReactKeyboardEvent<HTMLTextAreaElement>,
  active: SlashSkillState | BotMentionState | null,
  wrapper: HTMLElement | null,
  selector: string,
) {
  if (!active) return false;
  const buttons = Array.from(wrapper?.querySelectorAll<HTMLButtonElement>(selector) ?? []);
  if ((event.key === "Enter" || event.key === "Tab") && buttons[0]) {
    event.preventDefault();
    buttons[0].click();
    return true;
  }
  if (event.key === "Escape") return true;
  return false;
}

type SkillTextareaProps = Omit<
  ComponentProps<typeof Textarea>,
  "value" | "onChange" | "onKeyDown"
> & {
  value: string;
  onValueChange: (value: string) => void;
  onKeyDown?: (event: ReactKeyboardEvent<HTMLTextAreaElement>) => void;
  textareaRef?: Ref<HTMLTextAreaElement>;
  showSkillButton?: boolean;
  insetEnd?: boolean;
  // Bump only for changes that should keep the newest text visible (voice
  // partials/finals). A nonce instead of a boolean prevents later manual edits
  // in the middle of a long draft from being pulled back to the bottom.
  scrollToEndNonce?: number;
  // Lets a surrounding composer align adjacent controls to a single-line field
  // while still pinning them to the bottom once the textarea wraps or grows.
  onMultilineChange?: (multiline: boolean) => void;
};

function SkillTextarea({
  value,
  onValueChange,
  onKeyDown,
  textareaRef,
  showSkillButton = false,
  insetEnd = false,
  scrollToEndNonce = 0,
  onMultilineChange,
  ...props
}: SkillTextareaProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const fieldRef = useRef<HTMLTextAreaElement | null>(null);
  const followedScrollNonceRef = useRef(scrollToEndNonce);
  const multilineRef = useRef(false);
  const [skillSuggest, setSkillSuggest] = useState<SlashSkillState | null>(null);
  const [botMention, setBotMention] = useState<BotMentionState | null>(null);
  const [mentionIndex, setMentionIndex] = useState(0);
  const botDirectory = useContext(BotDirectoryContext);
  const mentionableBots = useMemo(() => Array.from(botDirectory.values()), [botDirectory]);
  // Owned here rather than in the popover: the arrow keys land on the
  // textarea, so the keyboard handler needs the list it is walking.
  const mentionMatches = useMemo(
    () => (botMention ? (matchBots(mentionableBots, botMention.query) as PersistentBot[]) : []),
    [botMention, mentionableBots],
  );
  // A new query is a new list, so the highlight returns to the top. Keyed on
  // the query text, not the state object, which is rebuilt on every keyup.
  useEffect(() => setMentionIndex(0), [botMention?.query]);

  // CSS `field-sizing: content` is still flaky across browsers (and loses to
  // rows/min-height combos), so grow from scrollHeight. max-height in className
  // clamps the box; overflow-y-auto scrolls past the cap.
  const resizeField = useCallback((el: HTMLTextAreaElement | null = fieldRef.current) => {
    if (!el) return;
    el.style.height = "0px";
    el.style.height = `${el.scrollHeight}px`;
    if (onMultilineChange) {
      const style = window.getComputedStyle(el);
      const lineHeight = Number.parseFloat(style.lineHeight);
      const padding = Number.parseFloat(style.paddingTop) + Number.parseFloat(style.paddingBottom);
      const contentHeight = el.scrollHeight - padding;
      const multiline = Number.isFinite(lineHeight) && contentHeight > lineHeight * 1.5;
      if (multilineRef.current !== multiline) {
        multilineRef.current = multiline;
        onMultilineChange(multiline);
      }
    }
  }, [onMultilineChange]);

  const setFieldRef = useCallback(
    (node: HTMLTextAreaElement | null) => {
      fieldRef.current = node;
      if (typeof textareaRef === "function") textareaRef(node);
      else if (textareaRef) {
        (textareaRef as React.MutableRefObject<HTMLTextAreaElement | null>).current = node;
      }
      resizeField(node);
    },
    [textareaRef, resizeField],
  );

  useLayoutEffect(() => {
    const field = fieldRef.current;
    resizeField(field);
    if (field && followedScrollNonceRef.current !== scrollToEndNonce) {
      field.scrollTop = field.scrollHeight;
      followedScrollNonceRef.current = scrollToEndNonce;
    }
  }, [value, resizeField, scrollToEndNonce]);

  // `sync` only runs on change/click/keyup, so a programmatic edit — most
  // importantly sendMessage clearing the draft — can leave a picker open over
  // text that no longer has a trigger. Blur used to hide that, but the composer
  // now keeps focus after send when only a hardware-keyboard helper is up.
  // Revalidate against the real value instead of relying on focus loss.
  useLayoutEffect(() => {
    if (!botMention) return;
    const caret = fieldRef.current?.selectionStart ?? value.length;
    if (!botMentionAt(value, caret)) setBotMention(null);
  }, [value, botMention]);

  function sync(target: HTMLTextAreaElement) {
    setSkillSuggest(slashSkillAt(target.value, target.selectionStart));
    setBotMention(botMentionAt(target.value, target.selectionStart));
  }

  function pickBot(bot: PersistentBot) {
    if (!botMention) return;
    const textarea = fieldRef.current;
    const next = applyBotMention(value, botMention, bot);
    onValueChange(next.value);
    setBotMention(null);
    requestAnimationFrame(() => {
      textarea?.focus();
      textarea?.setSelectionRange(next.cursor, next.cursor);
      resizeField(textarea);
    });
  }

  function pickSkill(skill: SkillCatalogItem) {
    if (!skillSuggest) return;
    const textarea = fieldRef.current;
    const replacement = `$${skill.trigger} `;
    const next =
      value.slice(0, skillSuggest.start) +
      replacement +
      value.slice(skillSuggest.end);
    const cursor = skillSuggest.start + replacement.length;
    onValueChange(next);
    setSkillSuggest(null);
    requestAnimationFrame(() => {
      textarea?.focus();
      textarea?.setSelectionRange(cursor, cursor);
      resizeField(textarea);
    });
  }

  function openSkillPicker() {
    const textarea = fieldRef.current;
    const cursor = textarea?.selectionStart ?? value.length;
    setSkillSuggest({ start: cursor, end: cursor, query: "" });
    requestAnimationFrame(() => {
      textarea?.focus();
      textarea?.setSelectionRange(cursor, cursor);
    });
  }

  return (
    <div ref={wrapRef} className="relative min-w-0 flex-1">
      <SkillSlashSuggest active={skillSuggest} onPick={pickSkill} />
      <BotMentionSuggest
        active={botMention}
        matches={mentionMatches}
        selected={mentionIndex}
        onHover={setMentionIndex}
        onPick={pickBot}
      />
      <Textarea
        {...props}
        ref={setFieldRef}
        value={value}
        className={cn(
          "relative z-0",
          props.className,
          showSkillButton && "!pl-11",
          insetEnd && "!pr-11",
        )}
        onChange={(event) => {
          onValueChange(event.target.value);
          sync(event.target);
          // Resize before paint so Enter/newline doesn't flash a one-line frame.
          resizeField(event.target);
        }}
        onClick={(event) => sync(event.currentTarget)}
        onKeyUp={(event) => sync(event.currentTarget)}
        onBlur={() =>
          window.setTimeout(() => {
            setSkillSuggest(null);
            setBotMention(null);
          }, 120)
        }
        onKeyDown={(event) => {
          if (skillSuggest) {
            if (event.key === "Escape") {
              event.preventDefault();
              setSkillSuggest(null);
              return;
            }
            if (handleSuggestKey(event, skillSuggest, wrapRef.current, "[data-skill-suggest-option]"))
              return;
          }
          // Runs before the caller's onKeyDown so Enter picks a bot instead of
          // submitting the message, and so the arrows walk the menu instead of
          // moving the caret.
          if (botMention && mentionMatches.length) {
            const count = mentionMatches.length;
            if (event.key === "Escape") {
              event.preventDefault();
              setBotMention(null);
              return;
            }
            if (event.key === "ArrowDown") {
              event.preventDefault();
              setMentionIndex((current) => (current + 1) % count);
              return;
            }
            if (event.key === "ArrowUp") {
              event.preventDefault();
              setMentionIndex((current) => (current - 1 + count) % count);
              return;
            }
            if (event.key === "Enter" || event.key === "Tab") {
              event.preventDefault();
              // Clamped: the list can shrink under a stale index between the
              // last keystroke and this one.
              pickBot(mentionMatches[Math.min(mentionIndex, count - 1)]);
              return;
            }
          }
          onKeyDown?.(event);
        }}
      />
      {showSkillButton ? (
        <button
          type="button"
          data-no-composer-swipe
          onMouseDown={(event) => event.preventDefault()}
          onClick={openSkillPicker}
          aria-label="Insert skill"
          title="Insert skill command"
          className="absolute left-1.5 top-1.5 z-20 flex size-8 touch-manipulation items-center justify-center rounded-full bg-muted/50 font-mono text-sm font-medium leading-none text-muted-foreground ring-1 ring-inset ring-border/40 transition active:scale-95 hover:bg-muted hover:text-foreground hover:ring-border/70 md:top-1"
        >
          /
        </button>
      ) : null}
    </div>
  );
}

// Shared growing field for the home and live-session chat composers. Keeping
// the cap here prevents the two entry points from drifting back to different
// viewport-relative heights, while SkillTextarea owns the resize/follow logic.
function ComposerTextarea({ className, ...props }: SkillTextareaProps) {
  return (
    <SkillTextarea
      {...props}
      className={cn(
        "max-h-40 min-w-0 flex-1 resize-none overflow-y-auto [field-sizing:fixed] md:max-h-36",
        className,
      )}
    />
  );
}

// Shared transcript page loader used to warm the cache ahead of a session open.
async function loadTranscriptPage(sid: string) {
  const page = await api<{ messages: Message[]; nextBefore?: number | null }>(
    transcriptPagePath(sid),
  );
  return {
    messages: omgMessagesToUIMessages(Array.isArray(page.messages) ? page.messages : []),
    nextBefore: page.nextBefore ?? null,
  };
}

type SessionChatProps = {
  session: Session;
  bot?: PersistentBot;
  busy: boolean;
  prompt: SessionPrompt | null;
  error: string | null;
  onError: (error: string | null) => void;
  onSubscribeTranscript?: OmgTranscriptSubscribe;
  onRefresh: () => Promise<void>;
  onDictatingChange?: (recording: boolean) => void;
  beforeComposer?: ReactNode;
};

/**
 * The chat surface, with the AI SDK held one dynamic import away.
 *
 * `useChat` is the app's only runtime use of @ai-sdk/react, and it pulls `ai`,
 * `@ai-sdk/*` and `zod` in behind it — 137 KB minified, 12.5% of the entry
 * chunk, none of which the session list needs in order to paint. Rather than
 * move this component and its ~1,400 lines of composer and transcript UI into
 * another module, only the hook moves: the engine below owns `useChat` and
 * publishes its state through context, and everything here reads it from there.
 *
 * The chunk is prefetched once the app is idle (see prefetchChatEngine), so in
 * practice it is already cached by the time a session is opened and the
 * fallback never renders.
 */
function SessionChat(rawProps: SessionChatProps) {
  // A bot-backed session is a bot chat wherever it is opened — the rail, a
  // stage column, the mobile sheet — not only inside the Bots surface that
  // used to hand the bot down by prop. Without this, opening the same session
  // from the session list would show the launch contract as a real message
  // and wait on anonymous dots instead of the creature.
  const directory = useContext(BotDirectoryContext);
  const contextBotId = productBotId(rawProps.session);
  const contextBot = contextBotId ? directory.get(contextBotId) : undefined;
  const props = rawProps.bot ? rawProps : { ...rawProps, bot: contextBot };
  const sid = props.session.sessionId;
  const botId = props.bot?.id;
  const { onError, onSubscribeTranscript } = props;
  const chatTransport = useMemo(
    () =>
      sid
        ? new OmgChatTransport({
            sessionId: sid,
            sendEndpoint: botId
              ? `/api/bots/${encodeURIComponent(botId)}/messages`
              : undefined,
            subscribeTranscript: onSubscribeTranscript,
          })
        : undefined,
    [sid, onSubscribeTranscript, botId],
  );
  const reportError = useCallback((message: string) => onError(message), [onError]);
  return (
    <Suspense fallback={<SessionChatSkeleton />}>
      <OmgChatEngine
        id={sid ?? "missing-session"}
        transport={chatTransport}
        onError={reportError}
      >
        <SessionChatBody {...props} />
      </OmgChatEngine>
    </Suspense>
  );
}

function SessionChatSkeleton() {
  return (
    <div className="flex flex-1 items-center justify-center py-10 text-sm text-muted-foreground">
      Loading chat…
    </div>
  );
}

function SessionChatBody({
  session,
  bot,
  busy,
  prompt,
  error,
  onError,
  onSubscribeTranscript,
  onRefresh,
  onDictatingChange,
  beforeComposer,
}: SessionChatProps) {
  const sid = session.sessionId;
  const reviewingShipped = !!session.shippedReview;
  // Open ask-user questions raised BY this session. The conversation shows them
  // above the composer (SessionQuestionPanel) and the composer is their reply
  // box — there is no second input, so what you type here is the answer.
  const sessionQuestions = useSessionQuestions([session.sessionId, session.nativeSessionId]);
  const { answerInSession } = useAsk();
  const stashContext = sid ? `session:${sid}` : "session:missing";
  const [messageText, setMessageTextState] = useState(
    () => readPromptDraft(stashContext)?.text ?? "",
  );
  const [sending, setSending] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [nextBefore, setNextBefore] = useState<number | null>(null);
  // Brief one-shot "launch" pulse on the composer as a message is sent, so the
  // send reads as the turn springing out of the input into the transcript.
  const [launching, setLaunching] = useState(false);
  const messageInputRef = useRef<HTMLTextAreaElement>(null);
  const [dictationScrollNonce, setDictationScrollNonce] = useState(0);
  const [messageMultiline, setMessageMultiline] = useState(false);
  // Shared composer file plumbing (same hook the new-session and fork composers
  // use): eager uploads, drag & drop, paste, annotate.
  const files = useComposerAttachments({
    endpoint: (att) =>
      sid
        ? reviewingShipped
          ? `/api/uploads?filename=${encodeURIComponent(att.name)}`
          : `/api/sessions/${sid}/upload?filename=${encodeURIComponent(att.name)}`
        : null,
    disabled: sending,
  });
  const {
    attachments,
    setAttachments,
    draggingFiles,
    addFiles,
    removeAttachment,
    previewUrls,
    resolveUpload,
    forgetAllUploads,
  } = files;
  // The focused chat has two listeners on the same transcript subscription:
  // useChat's transport (which turns live events into AI SDK chunks) and the
  // passive listener below (which keeps externally-driven turns current).
  // Claim ownership synchronously before sendChatMessage starts. Deriving this
  // from chatStatus is racy: React can deliver the first transcript event after
  // AbstractChat flips to "submitted" but before this component re-renders,
  // so both listeners append the same assistant/thinking rows. Those duplicate
  // UI messages then leak into the transcript cache and flash on a remount
  // (notably Settings -> Home) until the history refetch replaces them.
  // SessionChat is reused when the focused card changes. Ownership is scoped
  // by sid so a still-finishing send in the old card cannot suppress an
  // externally-driven event in the newly focused card.
  const [ownedChatStreams] = useState(() => new OmgChatStreamOwnership());
  // Provided by the lazily-loaded engine wrapping this component.
  const chat = useOmgChat();
  const { messages: uiMessages, setMessages, sendMessage: sendChatMessage, status: chatStatus } = chat;
  const chatMessages = useMemo(() => omgUIMessagesToMessages(uiMessages), [uiMessages]);
  // Busy straight from the transcript subscription: the harness flips it the
  // moment it starts a turn, ahead of the ~1s status-poll row that feeds the
  // `busy` prop, so the working indicator tracks the session even for turns
  // driven from another device (where chatStatus never leaves "ready").
  const [liveBusy, setLiveBusy] = useState(false);
  const chatBusy = busy || liveBusy || chatStatus === "submitted" || chatStatus === "streaming";
  const setMessageText = useCallback(
    (text: string) => {
      setMessageTextState(text);
      if (!sid) return;
      stashPromptDraft({
        contextKey: stashContext,
        source: "session",
        text,
        sessionId: sid,
        sessionTitle: session.title || session.project || "Session",
        project: session.project,
      });
    },
    [session.project, session.title, sid, stashContext],
  );
  const setDictatedMessageText = useCallback(
    (text: string, base: string) => {
      setMessageText(base.trim() ? `${base.trimEnd()} ${text}` : text);
      setDictationScrollNonce((nonce) => nonce + 1);
    },
    [setMessageText],
  );

  // SessionChat can be reused as the focused card changes. Recover that
  // session's own draft instead of carrying text across cards.
  useEffect(() => {
    setMessageTextState(readPromptDraft(stashContext)?.text ?? "");
  }, [stashContext]);

  useEffect(() => {
    if (!sid) {
      setMessages([]);
      setNextBefore(null);
      setHistoryLoading(false);
      return;
    }
    let cancelled = false;
    // Paint the last-known page for this session synchronously so re-opening a
    // session is instant instead of a blank pane + spinner while the network
    // round trip lands. We still refetch below and reconcile — the cached paint
    // just removes the wait from the critical path.
    const cached = readTranscriptCache(sid);
    if (cached) {
      setMessages(cached.messages);
      setNextBefore(cached.nextBefore);
      setHistoryLoading(false);
    } else {
      setHistoryLoading(true);
      setNextBefore(null);
      setMessages([]);
    }
    void api<{ messages: Message[]; nextBefore?: number | null }>(
      transcriptPagePath(sid),
      { cache: "no-store" },
    )
      .then((page) => {
        if (cancelled) return;
        const history = omgMessagesToUIMessages(Array.isArray(page.messages) ? page.messages : []);
        const historyIds = new Set(history.map((message) => message.id));
        // Anything the user had already paged in above this window stays put, in
        // its original order — the fresh page only replaces the tail it covers.
        const olderKept = cached
          ? cached.messages.slice(
              0,
              Math.max(0, cached.messages.findIndex((message) => historyIds.has(message.id))),
            )
          : [];
        let settled: OmgChatMessage[] = history;
        setMessages((current) => {
          const cachedIds = new Set(cached?.messages.map((message) => message.id) ?? []);
          return (settled = mergeHistoryPage(current, history, olderKept, cachedIds));
        });
        // Keep the deeper cursor when we preserved paged-in history above.
        const settledBefore = olderKept.length
          ? (cached?.nextBefore ?? null)
          : (page.nextBefore ?? null);
        setNextBefore(settledBefore);
        writeTranscriptCache(sid, settled, settledBefore);
      })
      .catch((err) => {
        if (!cancelled) onError(err instanceof Error ? err.message : String(err));
      })
      .finally(() => {
        if (!cancelled) setHistoryLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [onError, setMessages, sid]);

  useEffect(() => {
    if (!sid || !onSubscribeTranscript) return;
    setLiveBusy(false); // don't carry a previous session's busy across a switch
    return onSubscribeTranscript(sid, (event) => {
      if (event.type === "error") {
        onError(event.error);
        return;
      }
      if (event.type === "busy") setLiveBusy(event.busy);
      setMessages((current) => {
        const next = appendOmgTranscriptEvent(current, event, {
          streamActive: ownedChatStreams.owns(sid),
        });
        // Keep the cached page current so the next re-open paints the newest
        // state rather than a stale snapshot.
        if (next !== current) updateTranscriptCacheMessages(sid, next);
        return next;
      });
    });
  }, [onError, onSubscribeTranscript, ownedChatStreams, setMessages, sid]);

  const loadOlderMessages = useCallback(async () => {
    if (!sid || nextBefore == null) return false;
    const before = nextBefore;
    const page = await api<{ messages: Message[]; nextBefore: number | null }>(
      transcriptOlderPagePath(sid, before),
      { cache: "no-store" },
    );
    const older = omgMessagesToUIMessages(Array.isArray(page.messages) ? page.messages : []);
    setNextBefore(page.nextBefore ?? null);
    if (!older.length) return (page.nextBefore ?? null) !== null;
    let settled: OmgChatMessage[] = older;
    setMessages((current) => {
      const existing = new Set(current.map((message) => message.id));
      const prepend = older.filter((message) => !existing.has(message.id));
      return (settled = prepend.length ? [...prepend, ...current] : current);
    });
    // Cache the deeper window too, so scrolling back then leaving and returning
    // doesn't lose the pages the user already waited for.
    writeTranscriptCache(sid, settled, page.nextBefore ?? null);
    return (page.nextBefore ?? null) !== null;
  }, [nextBefore, setMessages, sid]);

  async function sendMessage(
    e?: FormEvent,
    overrideText?: string,
    mode: "steer" | "queue" = "steer",
  ) {
    e?.preventDefault();
    const text = (overrideText ?? messageText).trim();
    const files = attachments;
    if (!sid || (!text && !files.length)) return;
    // A queued send is a genuinely different state from a steered one: the agent
    // is still on the previous turn and has not read this text yet. The bubble
    // carries that state itself (waiting style, pinned under the
    // running turn) instead of a toast that is gone before the distinction
    // becomes visible. Only real queueing counts — an idle session cannot be interrupted,
    // so both modes deliver immediately there and the bubble is an ordinary
    // send.
    const queuedBehindTurn = mode === "queue" && chatBusy;
    // Dismiss a real soft keyboard so the newly-sent turn has room to read.
    // Keep focus when iPadOS only shows its compact hardware-keyboard helper:
    // blurring that field hides the helper, and WebKit restoring focus after
    // submit shows it again, producing two visualViewport layout shifts.
    if (document.documentElement.classList.contains("lfg-keyboard-open")) {
      messageInputRef.current?.blur();
    }
    const stashed = stagePromptSend({
      contextKey: stashContext,
      source: "session",
      text,
      sessionId: sid,
      sessionTitle: session.title || session.project || "Session",
      project: session.project,
    });
    setSending(true);
    feedback.send();
    onError(null);
    setMessageTextState("");
    try {
      // Uploads started when the files were attached; this normally resolves
      // immediately and only actually waits for bytes still in flight.
      const uploaded = files.length ? await Promise.all(files.map(resolveUpload)) : [];
      const outgoingText = composeAttachmentMessage(text, uploaded);
      // Pulse the composer so the send visibly launches into the transcript.
      setLaunching(true);
      window.setTimeout(() => setLaunching(false), 480);
      if (reviewingShipped) {
        await api<{ sessionId?: string }>("/api/sessions/resume", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId: sid,
            prompt: outgoingText,
            user: session.assignedUser || undefined,
          }),
        });
        setPromptStashStatus(stashed?.id, "sent");
        for (const att of files) {
          if (att.previewUrl) URL.revokeObjectURL(att.previewUrl);
        }
        setAttachments([]);
        forgetAllUploads();
        toast.success("Session resumed");
        await onRefresh();
        return;
      }
      void ownedChatStreams
        .run(sid, () =>
          sendChatMessage(
            {
              text: outgoingText,
              metadata: {
                omgMessage: {
                  role: "user",
                  kind: "text",
                  text: outgoingText,
                  html: escapeHtml(outgoingText).replace(/\n/g, "<br>"),
                  ts: Date.now(),
                  pending: true,
                  queued: queuedBehindTurn,
                },
              },
            },
            { body: { mode } },
          ),
        )
        .then(() => setPromptStashStatus(stashed?.id, "sent"))
        .catch((err) => {
          setPromptStashStatus(stashed?.id, "draft");
          setMessageTextState((current) => current || text);
          onError(err instanceof Error ? err.message : String(err));
        });
      // Typing here IS the answer to any question this session is waiting on:
      // the agent receives the text through the send above, so the ask store
      // only has to record it and take the badge, the card, and the sticky push
      // down. It must not inject the same sentence a second time, which is why
      // this goes through answerInSession rather than the delivering answer().
      for (const q of sessionQuestions) void answerInSession(q, text);
      for (const att of files) {
        if (att.previewUrl) URL.revokeObjectURL(att.previewUrl);
      }
      setAttachments([]);
      forgetAllUploads();
      setSending(false);
      void onRefresh().catch((err) => {
        onError(err instanceof Error ? err.message : String(err));
      });
    } catch (err) {
      setPromptStashStatus(stashed?.id, "draft");
      onError(err instanceof Error ? err.message : String(err));
      setMessageTextState((current) => current || text);
    } finally {
      setSending(false);
    }
  }

  async function interrupt() {
    if (!sid) return;
    try {
      await api(`/api/sessions/${sid}/interrupt`, { method: "POST" });
      await onRefresh();
    } catch (err) {
      onError(err instanceof Error ? err.message : String(err));
    }
  }

  // Re-queue a failed send. The next queue event repaints the bubble as
  // pending; delivery (and any further failure) flows from the server.
  const retryQueued = useCallback(
    (message: Message) => {
      if (!sid || !message.queueId) return;
      void retryQueuedMessage(sid, message.queueId).catch((err) =>
        onError(err instanceof Error ? err.message : String(err)),
      );
    },
    [sid, onError],
  );

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <StaleCapabilitiesBanner session={session} />
      <PausedBanner
        session={session}
        onRefresh={onRefresh}
        onContinue={() => sendMessage(undefined, "Continue.")}
      />
      <ChatStream
        sid={sid}
        messages={chatMessages}
        busy={chatBusy}
        loading={historyLoading}
        onLoadOlderMessages={loadOlderMessages}
        onRetryQueued={retryQueued}
        bot={bot}
        conversation={session.conversation}
      />

      <SessionQuestionPanel sessionIds={[session.sessionId, session.nativeSessionId]} />

      <PromptPanel prompt={prompt} sid={sid} onError={onError} />

      {error ? (
        <div className="border-t border-border/70 px-3 py-1.5 text-xs text-destructive">{error}</div>
      ) : null}

      {beforeComposer}

      {bot && !bot.enabled ? (
        <div className="px-2 pb-[calc(0.5rem+var(--lfg-safe-bottom))] pt-2">
          <div className="flex items-center gap-3 rounded-2xl border border-dashed border-border bg-muted/40 px-4 py-3 text-sm text-muted-foreground">
            <span className="min-w-0 flex-1">
              This bot is disabled. Re-enable it in settings to keep talking to it.
            </span>
          </div>
        </div>
      ) : /* A bot chat is a conversation, not a control surface for a process.
             canDriveSession asks whether this harness can be driven right now,
             which is the wrong question here: a bot whose session has died is
             re-launched by the very message you are trying to type, so gating
             the composer on liveness made an enabled bot unreachable until
             somebody restarted something for it. */
        bot || canDriveSession(session) || reviewingShipped ? (
        <form
          onSubmit={sendMessage}
          {...files.dropZoneProps}
          className={cn(
            // Sit on the same surface as the chat (no card/border seam) and let
            // the transcript melt into the bar via a soft gradient fade so the
            // composer reads as part of the conversation, not a bolted-on panel.
            // pb uses global --lfg-safe-bottom so embed host chrome never covers
            // the input (session portal is full-bleed outside the shell pad).
            "relative overflow-x-clip bg-background px-2 pb-[calc(0.5rem+var(--lfg-safe-bottom))] pt-1.5 transition-colors",
            "before:pointer-events-none before:absolute before:inset-x-0 before:-top-6 before:h-8 before:bg-gradient-to-t before:from-background before:to-transparent before:content-['']",
            draggingFiles && "bg-primary/8",
            launching && "lfg-composer-launching",
          )}
        >
          {files.fileInput}
          <ComposerAttachmentChips
            className="mb-2"
            items={attachments.map((att) => ({ att }))}
            disabled={sending}
            onAnnotate={files.setAnnotatingId}
            onRemove={removeAttachment}
            onToggleHd={files.setAttachmentHd}
          />
          {/* The bar itself (not just the textarea) is the field now: attach, type,
              mic and send all live inside one lfg-gfield pill, matching the
              wrapper pattern NewSessionDialog/ForkSessionDialog already use. That
              is also what makes "taller bar" and "attach moves inside, where /
              used to sit" the same change — there's one growing container, not a
              field plus loose buttons beside it. */}
          <div
            className={cn(
              // rounded-3xl, not the 2xl the other fields use. This one holds
              // circular controls on both ends, and a 16px corner beside a
              // 40px circle reads as a box that happens to contain pills. 24px
              // lets the bar agree with what is inside it. Not rounded-full:
              // the bar grows with the text, and a pill three lines tall bows
              // outward instead of looking round.
              "lfg-gfield relative flex gap-1 rounded-3xl px-2 py-1.5 transition-[background-color,border-color,box-shadow] duration-300 ease-ios md:gap-0.5 md:px-1.5 md:py-1",
              messageMultiline ? "items-end" : "items-center",
            )}
          >
            {/* Visible circle stays well under the bar's own height — the taller
                bar is breathing room around the text, not a mandate to blow the
                buttons up to match it. size-10 (40px) is still a full touch
                target on its own on mobile, so no padding trick is needed to
                keep the tap area honest; md:size-8 is mouse-precision, not
                touch, so it can go smaller. */}
            <Button
              size="icon"
              type="button"
              variant={draggingFiles ? "brand-soft" : "tint"}
              className="size-10 shrink-0 rounded-full md:size-8"
              onClick={files.openFilePicker}
              aria-label="Attach files"
              title="Attach files"
              disabled={sending}
            >
              <Plus className="size-4" />
            </Button>
            <ComposerTextarea
              textareaRef={messageInputRef}
              data-composer-sid={sid}
              value={messageText}
              onValueChange={setMessageText}
              onMultilineChange={setMessageMultiline}
              scrollToEndNonce={dictationScrollNonce}
              onPaste={files.onPasteFiles}
              onKeyDown={(e) => {
                if (e.key !== "Enter" || e.shiftKey) return;
                e.preventDefault();
                // Cmd/Ctrl+Enter is the keyboard twin of holding the send
                // button: queue behind the running turn instead of
                // interrupting it. Plain Enter still steers.
                if (e.metaKey || e.ctrlKey) {
                  void sendMessage(undefined, undefined, "queue");
                  return;
                }
                e.currentTarget.form?.requestSubmit();
              }}
              placeholder={
                attachments.length
                  ? "Add a note"
                  : bot
                    ? `Message ${bot.name}…`
                    : reviewingShipped
                    ? "Message to resume"
                    : // One question, one input: the composer says it is the
                      // reply box so the card above does not need its own.
                      sessionQuestions.length
                      ? "Reply to the question"
                      : "Message"
              }
              disabled={sending}
              rows={1}
              className={cn(
                // Height and follow-scroll are owned by ComposerTextarea. Chrome
                // (border/bg/shadow) now belongs to the wrapping bar above, not
                // the field — this only sizes and grows. Rest at one line; the
                // shared cap stops before the transcript. text-base (16px) on
                // mobile, not just a fallback: iOS auto-zooms any focused field
                // under 16px (see the (pointer: coarse) rule in index.css).
                // Trimmed a step. The bar was raised deliberately, then the
                // controls inside it were shrunk, and it was still reading
                // taller than the room it actually gives the text. The 40px
                // touch button is the floor on mobile, so min-h-11 keeps the
                // row honest without crowding it.
                // min-h-10 is the floor: it matches the 40px touch control
                // beside it, so the bar cannot get shorter without the row
                // becoming a button taller than the field it sits in.
                "min-h-10 resize-none border-0 bg-transparent px-1 py-2 text-base leading-5 shadow-none placeholder:text-muted-foreground focus-visible:border-0 focus-visible:ring-0 md:min-h-8 md:py-1.5 md:text-sm",
              )}
            />
            <MicButton
              className="size-10 shrink-0 rounded-full bg-foreground/[0.06] text-foreground/70 hover:bg-foreground/[0.12] hover:text-foreground md:size-8"
              baseText={messageText}
              onRecordingChange={onDictatingChange}
              onText={setDictatedMessageText}
              onInterim={setDictatedMessageText}
              onAutoSubmit={(text, base) => {
                const combined = base.trim() ? `${base.trimEnd()} ${text}` : text;
                void sendMessage(undefined, combined);
              }}
              onCancel={(base) => setMessageText(base)}
            />
            {chatBusy && canDriveSession(session) ? (
              <Button
                size="icon"
                type="button"
                variant="tint"
                className="size-10 shrink-0 rounded-full md:size-8"
                onClick={() => void interrupt()}
                aria-label="Stop (Esc or Ctrl/Cmd+.)"
                title="Stop — Esc or Ctrl/Cmd+."
              >
                <Pause className="size-4" />
              </Button>
            ) : null}
            {/* Mounted only once there's something to send (typed text, a
                dictation interim/final already folded into messageText, or an
                attachment) — an arrow with nothing behind it was dead chrome.
                `sending` keeps it visible through the round trip even after the
                text that triggered it is cleared, so it can't vanish mid-send.
                A live-but-still-silent recording has nothing to show here yet;
                the mic button's own recording state (red, level-reactive) is
                what carries "gesture in progress" until words land. */}
            {messageText.trim() || attachments.length || sending ? (
              <ComposerSendButton
                className="size-10 shrink-0 md:size-8"
                sending={sending}
                onSend={() => void sendMessage()}
                onQueue={() => void sendMessage(undefined, undefined, "queue")}
              />
            ) : null}
          </div>
          {reviewingShipped ? (
            <p className="mt-1.5 px-12 text-[11px] text-muted-foreground">
              Sending resumes this session.
            </p>
          ) : null}
        </form>
      ) : null}
      {files.annotator}
    </div>
  );
}

// Inline title field used by both the card and mobile detail-sheet header.
// Escape cancels; Enter / blur commits. Empty string clears the override.
function SessionTitleInlineEditor({
  initial,
  onCommit,
  onCancel,
}: {
  initial: string;
  onCommit: (next: string) => void | Promise<void>;
  onCancel: () => void;
}) {
  const [draft, setDraft] = useState(initial);
  const [saving, setSaving] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const committed = useRef(false);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  async function commit() {
    if (committed.current || saving) return;
    committed.current = true;
    setSaving(true);
    try {
      await onCommit(draft);
    } catch {
      committed.current = false;
      setSaving(false);
      inputRef.current?.focus();
    }
  }

  return (
    <form
      className="min-w-0 flex-1"
      onSubmit={(e) => {
        e.preventDefault();
        void commit();
      }}
    >
      <input
        ref={inputRef}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={() => void commit()}
        onKeyDown={(e) => {
          if (e.key === "Escape") {
            e.preventDefault();
            e.stopPropagation();
            committed.current = true;
            onCancel();
          }
        }}
        maxLength={200}
        disabled={saving}
        aria-label="Session name"
        autoComplete="off"
        autoCorrect="off"
        spellCheck={false}
        className="h-7 w-full min-w-0 rounded-md border border-ring/40 bg-background px-2 text-[15px] font-semibold leading-tight text-foreground outline-none ring-[3px] ring-ring/30"
      />
    </form>
  );
}

// ── tap session-title sheet ─────────────────────────────────────────────────
// A full-height modal that morphs out of the session title you tapped.
// The morph is a FLIP: the panel renders at full size, then we play it from a
// transform that maps full-screen → the title's on-screen rect back to
// identity, so it visually grows out of the title (and shrinks back into it on
// close). The body content cross-fades in once the panel has mostly expanded so
// the squished mid-morph layout is never seen.
const SHEET_EASE = "cubic-bezier(0.32, 0.72, 0, 1)";
const SHEET_MS = 420;

// The session title in the details sheet header, pinned to a single line. If
// the title is too wide to fit and the sheet has stayed open for 10s, a gentle
// ping-pong marquee scrolls the full title into view (and back) so it can be
// read without wrapping the header onto a second line.
function SessionTitleLine({ title }: { title: string }) {
  const lineRef = useRef<HTMLDivElement>(null);
  // px the text overflows its line; >0 turns the marquee on.
  const [shift, setShift] = useState(0);

  useLayoutEffect(() => {
    setShift(0);
    const id = setTimeout(() => {
      const el = lineRef.current;
      if (!el) return;
      const over = el.scrollWidth - el.clientWidth;
      if (over > 4) setShift(over);
    }, 10_000);
    return () => clearTimeout(id);
  }, [title]);

  const marquee = shift > 0;
  // Roughly constant scroll speed, with a floor so short overflows still ease.
  const duration = Math.max(2600, Math.round(shift * 28) + 1600);

  return (
    <div className="min-w-0 flex-1 overflow-hidden">
      <div
        ref={lineRef}
        className={cn(
          "text-[17px] font-semibold leading-tight whitespace-nowrap",
          marquee ? "lfg-marquee inline-block" : "overflow-hidden text-ellipsis",
        )}
        style={
          marquee
            ? ({
                "--lfg-marquee-shift": `-${shift}px`,
                animationDuration: `${duration}ms`,
              } as React.CSSProperties)
            : undefined
        }
      >
        {title}
      </div>
    </div>
  );
}

function useSessionActions({
  session,
  users,
  onRefresh,
  onRemove,
  onError,
}: {
  session: Session;
  users: User[];
  onRefresh: () => Promise<void>;
  onRemove: (sid: string) => void;
  onError: (error: string | null) => void;
}) {
  const [forkMode, setForkMode] = useState<"fork" | "continue" | null>(null);
  const sid = session.sessionId;
  const assignee = users.find((user) => user.email === session.assignedUser);

  async function assign(user: string) {
    if (!sid) return;
    onError(null);
    try {
      await api(`/api/sessions/${sid}/user`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user: user || null }),
      });
      await onRefresh();
    } catch (err) {
      onError(err instanceof Error ? err.message : String(err));
    }
  }

  async function interrupt() {
    if (!sid) return;
    onError(null);
    try {
      await api(`/api/sessions/${sid}/interrupt`, { method: "POST" });
      await onRefresh();
    } catch (err) {
      onError(err instanceof Error ? err.message : String(err));
    }
  }

  async function copyReference() {
    if (!sid) return;
    try {
      await copyMessageText(sessionReference(sid));
      toast.success("Session reference copied");
    } catch (err) {
      onError(err instanceof Error ? err.message : "Could not copy session reference");
    }
  }

  async function close() {
    if (!sid) return;
    onError(null);
    onRemove(sid); // drop the card now; the tombstone survives the next poll
    try {
      await closeSessionRequest(sid, "session_menu");
    } catch (err) {
      onError(err instanceof Error ? err.message : String(err));
    } finally {
      await onRefresh().catch((err) =>
        onError(err instanceof Error ? err.message : String(err)),
      );
    }
  }

  return {
    sid,
    assignee,
    forkMode,
    setForkMode,
    assign,
    interrupt,
    copyReference,
    close,
  };
}

function SessionActionsMenu({
  session,
  busy,
  users,
  onRefresh,
  onRemove,
  onError,
  onRename,
  triggerClassName,
  pinned,
  onTogglePin,
}: {
  session: Session;
  busy: boolean;
  users: User[];
  onRefresh: () => Promise<void>;
  onRemove: (sid: string) => void;
  onError: (error: string | null) => void;
  onRename?: () => void;
  triggerClassName?: string;
  pinned?: boolean;
  onTogglePin?: (sid: string) => void;
}) {
  const [tokenUsageOpen, setTokenUsageOpen] = useState(false);
  const [filesOpen, setFilesOpen] = useState(false);
  const {
    sid,
    assignee,
    forkMode,
    setForkMode,
    assign,
    interrupt,
    copyReference,
    close,
  } = useSessionActions({ session, users, onRefresh, onRemove, onError });
  const transcriptView = useContext(TranscriptViewContext);
  const openTerminal = useContext(SessionTerminalContext);

  // The sheet swaps sessions in place (swipe / arrow keys). Close the panel
  // rather than silently repointing it at another session's checkout.
  useEffect(() => {
    setFilesOpen(false);
  }, [sid]);

  return (
    <>
      {filesOpen && sid ? (
        <Suspense fallback={null}>
          <LazySessionFilesPanel sid={sid} onClose={() => setFilesOpen(false)} />
        </Suspense>
      ) : null}
      {tokenUsageOpen ? (
        <Suspense fallback={null}>
          <SessionTokenUsageDialog
            session={session}
            open={tokenUsageOpen}
            onOpenChange={setTokenUsageOpen}
          />
        </Suspense>
      ) : null}
      {forkMode ? (
        <ForkSessionDialog
          session={session}
          mode={forkMode}
          onClose={() => setForkMode(null)}
          onCreated={onRefresh}
        />
      ) : null}
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <button
              type="button"
              className={cn(
                "flex size-7 shrink-0 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted",
                triggerClassName,
              )}
              aria-label="Session menu"
            />
          }
        >
          <MoreVertical className="size-4" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="min-w-48">
          {!session.shippedReview ? (
            <DropdownMenuSub>
              <DropdownMenuSubTrigger disabled={!sid}>
                <UserRound className="size-4" />
                <span className="flex-1">Assign to</span>
                {session.assignedUser ? (
                  assignee?.avatar ? (
                    <img
                      src={assignee.avatar}
                      alt=""
                      className="size-5 shrink-0 rounded-full object-cover"
                    />
                  ) : (
                    <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                      <UserRound className="size-3" />
                    </span>
                  )
                ) : null}
              </DropdownMenuSubTrigger>
              <DropdownMenuSubContent align="start" className="min-w-48">
                <DropdownMenuRadioGroup
                  value={session.assignedUser ?? ""}
                  onValueChange={(value) =>
                    void assign(typeof value === "string" ? value : "")
                  }
                >
                  <DropdownMenuLabel>Assign to</DropdownMenuLabel>
                  <DropdownMenuRadioItem value="">
                    <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                      <UserRound className="size-3" />
                    </span>
                    Unassigned
                  </DropdownMenuRadioItem>
                  {users.map((user) => (
                    <DropdownMenuRadioItem key={user.email} value={user.email}>
                      {user.avatar ? (
                        <img
                          src={user.avatar}
                          alt=""
                          className="size-5 shrink-0 rounded-full object-cover"
                        />
                      ) : (
                        <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                          <UserRound className="size-3" />
                        </span>
                      )}
                      <span className="truncate capitalize">
                        {user.name ?? shortUser(user.email)}
                      </span>
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuSubContent>
            </DropdownMenuSub>
          ) : null}
          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <MessageSquare className="size-4" />
              <span className="flex-1">Display</span>
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent align="start" className="min-w-56">
              <DropdownMenuRadioGroup
                value={transcriptView.value}
                onValueChange={(value) => {
                  if (value !== "full" && value !== "user-lfg-output") return;
                  void transcriptView.onChange(value).catch((error) => {
                    toast.error(error instanceof Error ? error.message : "Couldn’t change message view");
                  });
                }}
              >
                <DropdownMenuLabel>Global message view</DropdownMenuLabel>
                <DropdownMenuRadioItem value="full">
                  Full transcript
                </DropdownMenuRadioItem>
                <DropdownMenuRadioItem value="user-lfg-output">
                  User + omg.dev output
                </DropdownMenuRadioItem>
              </DropdownMenuRadioGroup>
            </DropdownMenuSubContent>
          </DropdownMenuSub>
          <SessionThinkingLevelSubmenu
            session={session}
            onRefresh={onRefresh}
            onError={onError}
          />
          {onTogglePin ? (
            <DropdownMenuItem disabled={!sid} onClick={() => sid && onTogglePin(sid)}>
              <Pin className="size-4" fill={pinned ? "currentColor" : "none"} />
              {pinned ? "Unpin from top" : "Pin to top"}
            </DropdownMenuItem>
          ) : null}
          {onRename ? (
            <DropdownMenuItem disabled={!sid} onClick={() => onRename()}>
              <Pencil className="size-4" />
              Rename
            </DropdownMenuItem>
          ) : null}
          {/* Files lives in this menu with the rest of the per-session actions
              — it was briefly a separate header button. */}
          <DropdownMenuItem disabled={!sid} onClick={() => setFilesOpen(true)}>
            <FileCode className="size-4" />
            Files
          </DropdownMenuItem>
          <DropdownMenuItem disabled={!sid} onClick={() => sid && openTerminal(sid)}>
            <TerminalSquare className="size-4" />
            <span className="flex-1">Terminal</span>
            <kbd className="shrink-0 font-mono text-[10px] text-muted-foreground">t</kbd>
          </DropdownMenuItem>
          <DropdownMenuItem disabled={!sid} onClick={() => setTokenUsageOpen(true)}>
            <Gauge className="size-4" />
            Token usage
          </DropdownMenuItem>
          <DropdownMenuItem disabled={!sid} onClick={() => void copyReference()}>
            <Copy className="size-4" />
            Copy reference
          </DropdownMenuItem>
          {canDriveSession(session) ? (
            <DropdownMenuItem disabled={!sid} onClick={() => setForkMode("continue")}>
              <Play className="size-4" />
              Continue
            </DropdownMenuItem>
          ) : null}
          <DropdownMenuItem disabled={!sid} onClick={() => setForkMode("fork")}>
            <GitFork className="size-4" />
            Fork
          </DropdownMenuItem>
          {canDriveSession(session) ? (
            <>
              <DropdownMenuSeparator />
              {busy ? (
                <DropdownMenuItem onClick={() => void interrupt()}>
                  <Pause className="size-4" />
                  Stop
                </DropdownMenuItem>
              ) : null}
              <DoubleConfirmAction
                render={<DropdownMenuItem variant="destructive" />}
                label="Archive session"
                confirmLabel="Confirm archive"
                pendingLabel="Archiving…"
                icon={<Archive className="size-4" />}
                onConfirm={close}
                resetKey={sid}
              />
            </>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>
    </>
  );
}

// Desktop rail: right-click opens the same session actions without needing the
// ⋯ control on the row.
function RailSessionContextMenu({
  session,
  busy,
  users,
  onRefresh,
  onRemove,
  topPinned,
  onToggleTopPin,
  stagePinned,
  onToggleStagePin,
  onOpen,
  onCloseColumn,
  children,
}: {
  session: Session;
  busy: boolean;
  users: User[];
  onRefresh: () => Promise<void>;
  onRemove: (sid: string) => void;
  topPinned: boolean;
  onToggleTopPin: (sid: string) => void;
  stagePinned: boolean;
  onToggleStagePin: () => void;
  onOpen: () => void;
  onCloseColumn?: () => void;
  children: ReactNode;
}) {
  const {
    sid,
    assignee,
    forkMode,
    setForkMode,
    assign,
    interrupt,
    copyReference,
    close,
  } = useSessionActions({
    session,
    users,
    onRefresh,
    onRemove,
    onError: (error) => {
      if (error) toast.error(error);
    },
  });
  const transcriptView = useContext(TranscriptViewContext);

  return (
    <>
      {forkMode ? (
        <ForkSessionDialog
          session={session}
          mode={forkMode}
          onClose={() => setForkMode(null)}
          onCreated={onRefresh}
        />
      ) : null}
      <ContextMenu>
        <ContextMenuTrigger className="block min-w-0 rounded-xl">
          {children}
        </ContextMenuTrigger>
        <ContextMenuContent className="min-w-48">
          <ContextMenuItem disabled={!sid} onClick={onOpen}>
            <MessageSquare className="size-4" />
            Open
          </ContextMenuItem>
          <ContextMenuItem disabled={!sid} onClick={onToggleStagePin}>
            <Pin className="size-4" fill={stagePinned ? "currentColor" : "none"} />
            {stagePinned ? "Unpin column" : "Pin as column"}
          </ContextMenuItem>
          <ContextMenuItem
            disabled={!sid}
            onClick={() => sid && onToggleTopPin(sid)}
          >
            <Pin className="size-4" fill={topPinned ? "currentColor" : "none"} />
            {topPinned ? "Unpin from top" : "Pin to top"}
          </ContextMenuItem>
          <ContextMenuSeparator />
          <ContextMenuSub>
            <ContextMenuSubTrigger disabled={!sid}>
              <UserRound className="size-4" />
              <span className="flex-1">Assign to</span>
              {session.assignedUser ? (
                assignee?.avatar ? (
                  <img
                    src={assignee.avatar}
                    alt=""
                    className="size-5 shrink-0 rounded-full object-cover"
                  />
                ) : (
                  <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                    <UserRound className="size-3" />
                  </span>
                )
              ) : null}
            </ContextMenuSubTrigger>
            <ContextMenuSubContent className="min-w-48">
              <ContextMenuRadioGroup
                value={session.assignedUser ?? ""}
                onValueChange={(value) =>
                  void assign(typeof value === "string" ? value : "")
                }
              >
                <ContextMenuLabel>Assign to</ContextMenuLabel>
                <ContextMenuRadioItem value="">
                  <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                    <UserRound className="size-3" />
                  </span>
                  Unassigned
                </ContextMenuRadioItem>
                {users.map((user) => (
                  <ContextMenuRadioItem key={user.email} value={user.email}>
                    {user.avatar ? (
                      <img
                        src={user.avatar}
                        alt=""
                        className="size-5 shrink-0 rounded-full object-cover"
                      />
                    ) : (
                      <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted">
                        <UserRound className="size-3" />
                      </span>
                    )}
                    <span className="truncate capitalize">
                      {user.name ?? shortUser(user.email)}
                    </span>
                  </ContextMenuRadioItem>
                ))}
              </ContextMenuRadioGroup>
            </ContextMenuSubContent>
          </ContextMenuSub>
          <ContextMenuSub>
            <ContextMenuSubTrigger>
              <MessageSquare className="size-4" />
              <span className="flex-1">Display</span>
            </ContextMenuSubTrigger>
            <ContextMenuSubContent className="min-w-56">
              <ContextMenuRadioGroup
                value={transcriptView.value}
                onValueChange={(value) => {
                  if (value !== "full" && value !== "user-lfg-output") return;
                  void transcriptView.onChange(value).catch((error) => {
                    toast.error(error instanceof Error ? error.message : "Couldn’t change message view");
                  });
                }}
              >
                <ContextMenuLabel>Global message view</ContextMenuLabel>
                <ContextMenuRadioItem value="full">
                  Full transcript
                </ContextMenuRadioItem>
                <ContextMenuRadioItem value="user-lfg-output">
                  User + omg.dev output
                </ContextMenuRadioItem>
              </ContextMenuRadioGroup>
            </ContextMenuSubContent>
          </ContextMenuSub>
          <ContextMenuItem disabled={!sid} onClick={() => void copyReference()}>
            <Copy className="size-4" />
            Copy reference
          </ContextMenuItem>
          {canDriveSession(session) ? (
            <ContextMenuItem disabled={!sid} onClick={() => setForkMode("continue")}>
              <Play className="size-4" />
              Continue
            </ContextMenuItem>
          ) : null}
          <ContextMenuItem disabled={!sid} onClick={() => setForkMode("fork")}>
            <GitFork className="size-4" />
            Fork
          </ContextMenuItem>
          {onCloseColumn ? (
            <ContextMenuItem onClick={onCloseColumn}>
              <X className="size-4" />
              Close column
            </ContextMenuItem>
          ) : null}
          {canDriveSession(session) ? (
            <>
              <ContextMenuSeparator />
              {busy ? (
                <ContextMenuItem onClick={() => void interrupt()}>
                  <Pause className="size-4" />
                  Stop
                </ContextMenuItem>
              ) : null}
              <DoubleConfirmAction
                render={<ContextMenuItem variant="destructive" />}
                label="Archive session"
                confirmLabel="Confirm archive"
                pendingLabel="Archiving…"
                icon={<Archive className="size-4" />}
                onConfirm={close}
                resetKey={sid}
              />
            </>
          ) : null}
        </ContextMenuContent>
      </ContextMenu>
    </>
  );
}

const LIVE_THINKING_AGENTS = new Set([
  "claude",
  "aisdk",
  "codex-aisdk",
  "grok",
  "cursor",
  "pi",
]);

function SessionThinkingLevelSubmenu({
  session,
  onRefresh,
  onError,
}: {
  session: Session;
  onRefresh: () => Promise<void>;
  onError: (error: string | null) => void;
}) {
  const sid = session.sessionId;
  const agent = session.agent as AgentKind | undefined;
  const supportedLevels = useAgentThinkingLevels(agent ?? "aisdk");
  const levels = agent === "aisdk"
    ? supportedLevels.filter((level) => level !== "max")
    : supportedLevels;
  const [changing, setChanging] = useState(false);
  if (
    !sid ||
    !agent ||
    session.shippedReview ||
    !LIVE_THINKING_AGENTS.has(agent) ||
    (agent === "cursor" && session.model === "auto") ||
    !levels.length
  ) return null;

  async function changeThinkingLevel(thinkingLevel: string) {
    if (!sid || !thinkingLevel || thinkingLevel === session.thinkingLevel || changing) return;
    setChanging(true);
    onError(null);
    try {
      await api(`/api/sessions/${sid}/thinking-level`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ thinkingLevel }),
      });
      localStorage.setItem("lfg_thinking_level", thinkingLevel);
      await onRefresh();
      toast.success(`Thinking level set to ${thinkingLevel}`);
    } catch (error) {
      onError(error instanceof Error ? error.message : String(error));
    } finally {
      setChanging(false);
    }
  }

  return (
    <DropdownMenuSub>
      <DropdownMenuSubTrigger disabled={changing}>
        {changing ? (
          <Loader2 className="size-4 animate-spin" />
        ) : (
          <BrainCircuit className="size-4" />
        )}
        <span className="flex-1">Thinking</span>
        <span className="text-xs text-muted-foreground">
          {session.thinkingLevel || "Default"}
        </span>
      </DropdownMenuSubTrigger>
      <DropdownMenuSubContent align="start" className="min-w-40">
        <DropdownMenuRadioGroup
          value={session.thinkingLevel ?? ""}
          onValueChange={(value) =>
            void changeThinkingLevel(typeof value === "string" ? value : "")
          }
        >
          <DropdownMenuLabel>Thinking level</DropdownMenuLabel>
          {levels.map((level) => (
            <DropdownMenuRadioItem key={level} value={level}>
              {level}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuSubContent>
    </DropdownMenuSub>
  );
}

function SessionTitleSheet({
  sid,
  session,
  users,
  order,
  busyBySid,
  promptsBySid,
  origin,
  onSwitch,
  onSubscribeTranscript,
  onRefresh,
  onRenameSession,
  onRemove,
  pinned,
  onTogglePin,
  onClose,
}: {
  // The active session id. The sheet is a top-level modal (lifted out of any one
  // SessionCard) so it can swap which session it shows while staying mounted —
  // the morph-in/out animation always references the original `origin` rect.
  sid: string;
  session: Session;
  users: User[];
  // Sid navigation order, matching the on-screen card order (working then idle).
  order: string[];
  busyBySid: Record<string, boolean>;
  promptsBySid: Record<string, SessionPrompt | null>;
  origin: DOMRect;
  onSwitch: (sid: string) => void;
  onSubscribeTranscript?: OmgTranscriptSubscribe;
  onRefresh: () => Promise<void>;
  onRenameSession: RenameSession;
  onRemove: (sid: string) => void;
  pinned: boolean;
  onTogglePin?: (sid: string) => void;
  onClose: () => void;
}) {
  const [error, setError] = useState<string | null>(null);
  const [renamingInline, setRenamingInline] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const backdropRef = useRef<HTMLButtonElement>(null);
  const bodyRef = useRef<HTMLDivElement>(null);
  const closingRef = useRef(false);
  const switchDirRef = useRef<1 | -1 | null>(null);

  // Per-session live data, selected for whichever session is active right now.
  const busy = !!busyBySid[sid];
  const prompt = promptsBySid[sid] ?? null;

  // Prev/next neighbours in display order (null at the ends — no wrap-around).
  const idx = order.indexOf(sid);
  const prevSid = idx > 0 ? order[idx - 1] : null;
  const nextSid = idx >= 0 && idx < order.length - 1 ? order[idx + 1] : null;
  const go = useCallback(
    (target: string | null) => {
      if (!target || closingRef.current) return;
      const targetIdx = order.indexOf(target);
      const dir: 1 | -1 = targetIdx > idx ? 1 : -1;
      switchDirRef.current = dir;
      haptic("selection");
      const body = bodyRef.current;
      if (body) {
        body.getAnimations().forEach((animation) => animation.cancel());
        body.style.transition = "";
        body.style.transform = "";
        body.style.opacity = "";
      }
      onSwitch(target);
    },
    [idx, onSwitch, order],
  );

  // A stale composer error from the previous session shouldn't bleed across.
  useLayoutEffect(() => {
    setError(null);
    setRenamingInline(false);
  }, [sid]);

  const commitInlineRename = useCallback(
    async (next: string) => {
      setError(null);
      setRenamingInline(false);
      try {
        await onRenameSession(sid, next);
        toast.success("Session renamed");
      } catch (error) {
        setError(error instanceof Error ? error.message : String(error));
        setRenamingInline(true);
        throw error;
      }
    },
    [onRenameSession, sid],
  );

  // Force each session we view into the shared transcript stream so the chat's
  // useChat subscription receives idle-time updates. This uses the in-memory
  // forced-stream channel, NOT the `lfg-collapsed:` key, so the card behind the
  // sheet keeps its own collapse state and nothing leaks/sticks.
  const touchedRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    touchedRef.current.add(sid);
    addForcedStreamSid(sid);
  }, [sid]);
  useEffect(
    () => () => {
      for (const s of touchedRef.current) removeForcedStreamSid(s);
    },
    [],
  );

  // Slide the newly selected session in from the side its card/page would occupy.
  // The entrance morph below handles the very first mount, so skip this once.
  const firstRef = useRef(true);
  useEffect(() => {
    if (firstRef.current) {
      firstRef.current = false;
      return;
    }
    const body = bodyRef.current;
    if (!body) return;
    const dir = switchDirRef.current;
    switchDirRef.current = null;
    const reduceMotion =
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    if (!dir || reduceMotion) return;
    const inbound = dir === 1 ? 18 : -18;
    // Clear any inline transform/transition left by an in-progress swipe so the
    // transcript layout starts from a clean slate.
    body.getAnimations().forEach((animation) => animation.cancel());
    body.style.transition = "";
    body.style.transform = "";
    body.animate(
      [
        { opacity: 0, transform: `translateX(${inbound}px)` },
        { opacity: 1, transform: "translateX(0px)" },
      ],
      { duration: 150, easing: "ease-out" },
    );
  }, [sid]);

  // Swipe the session body or composer left/right to switch sessions. Horizontal
  // drags move the whole transcript with the finger; releasing past the threshold
  // commits to prev/next (rubber-banding at the ends). Vertical intent is
  // released back to the scroller untouched, and we only preventDefault once a
  // horizontal swipe is committed, so scrolling and controls behave normally.
  // Native non-passive listeners (React's are passive) so preventDefault holds.
  useEffect(() => {
    const body = bodyRef.current;
    if (!body) return;
    const SWIPE_COMMIT = 60; // px of travel needed to flip sessions
    const st = { active: false, decided: false, horizontal: false, x0: 0, y0: 0, dx: 0 };
    const setTx = (px: number) => {
      body.style.transition = "none";
      body.style.transform = px ? `translateX(${px}px)` : "";
    };
    const release = (animate: boolean) => {
      if (animate) {
        body.style.transition = "transform 180ms cubic-bezier(0.22,1,0.36,1)";
        body.style.transform = "";
      } else {
        setTx(0);
      }
    };
    const onStart = (e: TouchEvent) => {
      if (closingRef.current || e.touches.length !== 1) return;
      const target = e.target instanceof Element ? e.target : null;
      const startedInComposer = !!target?.closest("form");
      if (startedInComposer) {
        if (composerIsEditing(e.target)) return;
      } else if (blocksSessionSwipe(e.target)) {
        return;
      }
      const t = e.touches[0];
      st.active = true;
      st.decided = false;
      st.horizontal = false;
      st.x0 = t.clientX;
      st.y0 = t.clientY;
      st.dx = 0;
    };
    const onMove = (e: TouchEvent) => {
      if (!st.active) return;
      const t = e.touches[0];
      const dx = t.clientX - st.x0;
      const dy = t.clientY - st.y0;
      if (!st.decided) {
        if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
        st.decided = true;
        st.horizontal = Math.abs(dx) > Math.abs(dy);
        if (!st.horizontal) {
          st.active = false; // vertical → let the textarea / scroller have it
          return;
        }
      }
      if (!st.horizontal) return;
      e.preventDefault(); // suppress browser scroll + textarea caret scrub
      st.dx = dx;
      // Resist when there's nowhere to go in that direction.
      const blocked = dx > 0 ? !prevSid : !nextSid;
      setTx(dx * (blocked ? 0.18 : 0.5));
    };
    const onEnd = () => {
      if (!st.active) return;
      const { horizontal, dx } = st;
      st.active = false;
      if (!horizontal) return;
      const target = dx > SWIPE_COMMIT ? prevSid : dx < -SWIPE_COMMIT ? nextSid : null;
      if (target) {
        // The crossfade effect (on sid change) starts at opacity 0, so it both
        // resets the drag transform and fades the new session in — no spring-back
        // needed, and no transform "snap" is visible.
        go(target);
      } else {
        release(true); // nothing committed → ease back to rest
      }
    };
    body.addEventListener("touchstart", onStart, { passive: true });
    body.addEventListener("touchmove", onMove, { passive: false });
    body.addEventListener("touchend", onEnd, { passive: true });
    body.addEventListener("touchcancel", onEnd, { passive: true });
    return () => {
      body.removeEventListener("touchstart", onStart);
      body.removeEventListener("touchmove", onMove);
      body.removeEventListener("touchend", onEnd);
      body.removeEventListener("touchcancel", onEnd);
    };
  }, [go, prevSid, nextSid]);

  // The transform that maps the full-screen panel onto the title's rect.
  // transform-origin is the top-left corner, so scale shrinks toward (0,0) and
  // the translate then drops it onto the title.
  const flipTransform = useCallback(() => {
    const vw = window.innerWidth || 1;
    const vh = window.innerHeight || 1;
    const sx = Math.max(origin.width / vw, 0.0001);
    const sy = Math.max(origin.height / vh, 0.0001);
    return `translate(${origin.left}px, ${origin.top}px) scale(${sx}, ${sy})`;
  }, [origin]);

  // Enter morph — runs once on mount.
  useLayoutEffect(() => {
    const panel = panelRef.current;
    const backdrop = backdropRef.current;
    const body = bodyRef.current;
    if (!panel) return;
    const from = flipTransform();
    panel.animate(
      [
        { transform: from, borderRadius: "16px", opacity: 0.55 },
        { transform: "translate(0px,0px) scale(1,1)", borderRadius: "0px", opacity: 1 },
      ],
      { duration: SHEET_MS, easing: SHEET_EASE, fill: "both" },
    );
    backdrop?.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: SHEET_MS,
      easing: SHEET_EASE,
      fill: "both",
    });
    body?.animate(
      [
        { opacity: 0, transform: "translateY(12px)" },
        { opacity: 0, transform: "translateY(12px)", offset: 0.45 },
        { opacity: 1, transform: "translateY(0px)" },
      ],
      { duration: SHEET_MS, easing: "ease-out", fill: "both" },
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const requestClose = useCallback(() => {
    if (closingRef.current) return;
    closingRef.current = true;
    haptic("selection");
    const panel = panelRef.current;
    const backdrop = backdropRef.current;
    const body = bodyRef.current;
    const to = flipTransform();
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      onClose();
    };
    if (panel) {
      const anim = panel.animate(
        [
          { transform: "translate(0px,0px) scale(1,1)", borderRadius: "0px", opacity: 1 },
          { transform: to, borderRadius: "16px", opacity: 0.55 },
        ],
        { duration: SHEET_MS * 0.85, easing: SHEET_EASE, fill: "both" },
      );
      anim.onfinish = finish;
      anim.oncancel = finish;
    } else {
      finish();
    }
    backdrop?.animate([{ opacity: 1 }, { opacity: 0 }], {
      duration: SHEET_MS * 0.85,
      easing: SHEET_EASE,
      fill: "both",
    });
    body?.animate([{ opacity: 1 }, { opacity: 0 }], {
      duration: SHEET_MS * 0.4,
      easing: "ease-in",
      fill: "both",
    });
  }, [flipTransform, onClose]);

  // Full-details-only gesture: swipe up from the session composer to dismiss
  // the zoomed-in sheet. This deliberately starts only from the input bar area,
  // leaving transcript scroll and header touches alone.
  useEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const DISMISS_Y = 88;
    const VELOCITY = 0.45; // px/ms
    const st = { active: false, decided: false, dismissing: false, x0: 0, y0: 0, y: 0, t0: 0 };
    const setY = (y: number, animate = false) => {
      panel.style.transition = animate
        ? "transform 180ms cubic-bezier(0.22,1,0.36,1), opacity 180ms ease"
        : "none";
      panel.style.transform = y ? `translate3d(0, ${y}px, 0)` : "";
      panel.style.opacity = y ? `${1 - Math.min(0.16, Math.abs(y) / 1200)}` : "";
    };
    const finishDismiss = () => {
      if (closingRef.current) return;
      closingRef.current = true;
      haptic("selection");
      const backdrop = backdropRef.current;
      const body = bodyRef.current;
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        onClose();
      };
      panel.getAnimations().forEach((animation) => animation.cancel());
      panel.style.transition =
        "transform 300ms cubic-bezier(0.32,0.72,0,1), opacity 220ms ease-out";
      panel.style.transform = "translate3d(0, -105%, 0)";
      panel.style.opacity = "0.92";
      const onTransitionEnd = (event: TransitionEvent) => {
        if (event.propertyName !== "transform") return;
        panel.removeEventListener("transitionend", onTransitionEnd);
        finish();
      };
      panel.addEventListener("transitionend", onTransitionEnd);
      window.setTimeout(finish, 340);
      if (backdrop) {
        backdrop.style.transition = "opacity 240ms ease-out";
        backdrop.style.opacity = "0";
      }
      if (body) {
        body.style.transition = "transform 260ms cubic-bezier(0.32,0.72,0,1), opacity 180ms ease-out";
        body.style.transform = "translate3d(0, -18px, 0)";
        body.style.opacity = "0";
      }
    };
    const onStart = (event: TouchEvent) => {
      if (closingRef.current || event.touches.length !== 1) return;
      const target = event.target as HTMLElement | null;
      if (!target?.closest("form")) return;
      const touch = event.touches[0];
      st.active = true;
      st.decided = false;
      st.dismissing = false;
      st.x0 = touch.clientX;
      st.y0 = touch.clientY;
      st.y = 0;
      st.t0 = performance.now();
      panel.getAnimations().forEach((animation) => {
        if (animation.playState !== "finished") animation.cancel();
      });
      setY(0);
    };
    const onMove = (event: TouchEvent) => {
      if (!st.active) return;
      const touch = event.touches[0];
      const dx = touch.clientX - st.x0;
      const dy = touch.clientY - st.y0;
      if (!st.decided) {
        if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
        st.decided = true;
        st.dismissing = dy < 0 && Math.abs(dy) > Math.abs(dx) * 1.2;
        if (!st.dismissing) {
          st.active = false;
          return;
        }
      }
      if (!st.dismissing) return;
      event.preventDefault();
      st.y = -Math.min(Math.abs(dy), window.innerHeight * 0.6);
      setY(st.y);
      const backdrop = backdropRef.current;
      if (backdrop) backdrop.style.opacity = `${1 - Math.min(0.35, Math.abs(st.y) / 520)}`;
    };
    const onEnd = () => {
      if (!st.active) return;
      st.active = false;
      const dt = Math.max(1, performance.now() - st.t0);
      const velocity = st.y / dt;
      if (st.dismissing && (st.y <= -DISMISS_Y || velocity <= -VELOCITY)) {
        finishDismiss();
        return;
      }
      setY(0, true);
      const backdrop = backdropRef.current;
      if (backdrop) {
        backdrop.style.transition = "opacity 180ms ease";
        backdrop.style.opacity = "";
        window.setTimeout(() => {
          backdrop.style.transition = "";
        }, 200);
      }
      window.setTimeout(() => {
        panel.style.transition = "";
        panel.style.transform = "";
        panel.style.opacity = "";
      }, 200);
    };
    panel.addEventListener("touchstart", onStart, { passive: true });
    panel.addEventListener("touchmove", onMove, { passive: false });
    panel.addEventListener("touchend", onEnd, { passive: true });
    panel.addEventListener("touchcancel", onEnd, { passive: true });
    return () => {
      panel.removeEventListener("touchstart", onStart);
      panel.removeEventListener("touchmove", onMove);
      panel.removeEventListener("touchend", onEnd);
      panel.removeEventListener("touchcancel", onEnd);
    };
  }, [onClose]);

  // Escape-to-close, arrow-keys-to-switch + lock background scroll while open.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        if (renamingInline) return;
        requestClose();
        return;
      }
      // Don't hijack arrows while the user is typing in the composer / rename
      // field, or inside a shadow-DOM surface like the file tree or editor.
      if (isTypingTarget(e.target as HTMLElement | null) || isTypingTarget()) return;
      if (renamingInline) return;
      if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        e.preventDefault();
        go(prevSid);
      } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        e.preventDefault();
        go(nextSid);
      }
    };
    document.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
    };
  }, [requestClose, go, prevSid, nextSid, renamingInline]);

  const title = titleForSession(session);

  return createPortal(
    <div
      className="fixed inset-x-0 z-[90]"
      style={{
        top: "var(--lfg-visual-offset-top, 0px)",
        height: "var(--lfg-visual-height, var(--lfg-app-height, 100dvh))",
      }}
    >
      <button
        type="button"
        ref={backdropRef}
        onClick={requestClose}
        className="absolute inset-0 bg-black/50"
        aria-label="Close session details"
      />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label={title}
        style={{ transformOrigin: "top left" }}
        className="absolute inset-0 flex flex-col overflow-hidden bg-background text-foreground"
      >
        <div
          className="flex items-center gap-2 border-b border-border px-4 pb-3"
          style={{ paddingTop: "calc(env(safe-area-inset-top, 0px) + 0.75rem)" }}
        >
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Close session details"
            onClick={requestClose}
            className="shrink-0"
          >
            <ChevronDown />
          </Button>
          {/* Mobile's full-screen session sheet: same bot-aware identity mark
              as the session card header (see SessionHeaderIdentity), so a
              bot-driven conversation wears its own avatar here too instead of
              always falling back to the harness's agent icon. */}
          <SessionHeaderIdentity session={session} busy={busy} size={28} />
          {renamingInline ? (
            <SessionTitleInlineEditor
              initial={session.title?.trim() || title}
              onCommit={commitInlineRename}
              onCancel={() => setRenamingInline(false)}
            />
          ) : (
            <button
              type="button"
              className="flex min-w-0 flex-1 items-center text-left outline-none"
              title={session.shippedReview ? undefined : "Rename session"}
              aria-label={session.shippedReview ? title : `Rename ${title}`}
              onClick={() => {
                if (session.shippedReview) return;
                haptic("selection");
                setRenamingInline(true);
              }}
            >
              <SessionTitleLine title={title} />
            </button>
          )}
          {session.shippedReview ? (
            <span className="shrink-0 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-600 dark:text-emerald-400">
              Shipped
            </span>
          ) : null}
          <SessionActionsMenu
            session={session}
            busy={busy}
            users={users}
            onRefresh={onRefresh}
            onRemove={onRemove}
            onError={setError}
            onRename={
              session.shippedReview ? undefined : () => setRenamingInline(true)
            }
            triggerClassName="size-9"
            pinned={pinned}
            onTogglePin={onTogglePin}
          />
        </div>
        <div ref={bodyRef} className="flex min-h-0 flex-1 flex-col">
          <SessionChat
            session={session}
            busy={busy}
            prompt={prompt}
            error={error}
            onError={setError}
            onSubscribeTranscript={onSubscribeTranscript}
            onRefresh={onRefresh}
          />
        </div>
      </div>
    </div>,
    document.body,
  );
}

function defaultForkAgent(
  sourceAgent: string | null | undefined,
  availableOptions: readonly { key: AgentKind }[],
): AgentKind {
  const saved = localStorage.getItem("lfg_fork_agent") as AgentKind | null;
  if (saved && availableOptions.some((option) => option.key === saved)) return saved;
  const preferred = sourceAgent === "codex-aisdk" ? "aisdk" : "codex-aisdk";
  if (availableOptions.some((option) => option.key === preferred)) return preferred;
  return availableOptions[0]?.key ?? "aisdk";
}

type ForkSessionResult = {
  sessionId?: string;
  sourceArchived?: boolean;
  archiveError?: string;
};

function ForkSessionDialog({
  session,
  mode,
  onClose,
  onCreated,
}: {
  session: Session;
  mode: "fork" | "continue";
  onClose: () => void;
  onCreated: (created?: ForkSessionResult) => Promise<void>;
}) {
  const continuing = mode === "continue";
  const catalog = useAgentModelCatalog();
  const codingAgents = useContext(CodingAgentsContext);
  const accessMode = useContext(AgentAccessModeContext);
  const availableAgentOptions = useMemo(
    () => configuredLaunchOptions(codingAgents, accessMode),
    [accessMode, codingAgents],
  );
  const defaultModelFor = (key: AgentKind) => catalog.defaults[key] ?? AGENT_DEFAULT_MODEL[key];
  const defaultAgent = defaultForkAgent(session.agent, availableAgentOptions);
  const [agent, setAgent] = useState<AgentKind>(() => defaultAgent);
  const [claudeAccountId, setClaudeAccountId] = useState("");
  const [model, setModel] = useState(
    () =>
      localStorage.getItem(`lfg_fork_model_${defaultAgent}`) ||
      defaultModelFor(defaultAgent),
  );
  const [thinkingLevel, setThinkingLevel] = useState<ThinkingLevel>(() => savedThinkingLevel());
  const [prompt, setPrompt] = useState("");
  const sid = session.sessionId;
  const models = catalog.models[agent] ?? AGENT_MODELS[agent];
  const thinkingLevels = useAgentThinkingLevels(agent);
  const selectedLaunchId =
    agent === "aisdk" && claudeAccountId ? `aisdk:${claudeAccountId}` : agent;
  // Same composer plumbing as the new-session composer: eager uploads, drag &
  // drop, paste, annotate.
  const files = useComposerAttachments({
    endpoint: (att) => `/api/uploads?filename=${encodeURIComponent(att.name)}`,
  });

  useEffect(() => {
    if (!models.includes(model)) setModel(models[0]);
  }, [models, model]);
  useEffect(() => {
    if (availableAgentOptions.some((option) => option.key === agent)) return;
    const next = availableAgentOptions[0]?.key;
    if (!next) return;
    setAgent(next);
    setModel(localStorage.getItem(`lfg_fork_model_${next}`) || defaultModelFor(next));
  }, [agent, availableAgentOptions]);
  useEffect(() => {
    if (agent !== "aisdk") return;
    if (availableAgentOptions.some((option) => (option.selectorId ?? option.key) === selectedLaunchId)) return;
    const firstClaude = availableAgentOptions.find((option) => option.key === "aisdk");
    // Fall back to "" (Claude · Auto), not just to another account: the first
    // Claude option is Auto, which HAS no accountId, so guarding on one meant a
    // pin whose account got disconnected was never cleared. The strip then
    // rendered with nothing selected and the fork POSTed the dead id, which the
    // server rejects with "Claude account is missing or not connected".
    setClaudeAccountId(firstClaude?.accountId ?? "");
  }, [agent, availableAgentOptions, selectedLaunchId]);
  useEffect(() => {
    if (thinkingLevels.length && !thinkingLevels.includes(thinkingLevel)) {
      setThinkingLevel(thinkingLevels.includes("high") ? "high" : thinkingLevels[0]);
    }
  }, [thinkingLevel, thinkingLevels]);

  function submit(e?: FormEvent, overrideText?: string) {
    e?.preventDefault();
    if (!sid) return;
    if (!availableAgentOptions.some((option) => option.key === agent)) {
      toast.error(
        `Set up and sign in to a coding agent before ${continuing ? "continuing" : "forking"} a session.`,
      );
      return;
    }
    localStorage.setItem("lfg_fork_agent", agent);
    localStorage.setItem(`lfg_fork_model_${agent}`, model);
    if (agentSupportsThinking(agent)) localStorage.setItem("lfg_thinking_level", thinkingLevel);
    const text = (overrideText ?? prompt).trim();
    const attached = files.attachments;
    onClose();
    toast.promise(
      (async () => {
        // Started at attach time, so these are usually already resolved.
        const uploaded = attached.length
          ? await Promise.all(attached.map(files.resolveUpload))
          : [];
        const composedPrompt = composeAttachmentMessage(text, uploaded);
        return api<ForkSessionResult>(`/api/sessions/${sid}/fork`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            prompt: composedPrompt || undefined,
            user: session.assignedUser || undefined,
            agent,
            model,
            thinkingLevel: agentSupportsThinking(agent) ? thinkingLevel : undefined,
            claudeAccountId: agent === "aisdk" ? claudeAccountId || undefined : undefined,
            archiveSource: continuing || undefined,
          }),
        });
      })().then(async (created) => {
        await onCreated(created);
        return created;
      }),
      {
        loading: continuing ? "Continuing in a new session..." : "Forking session...",
        success: (created) =>
          continuing && created.sourceArchived === false
            ? "New session opened, but the old session could not be archived"
            : continuing
              ? "Continued in a new session"
              : "Session forked",
        error: (err) => (err instanceof Error ? err.message : "Couldn't open session"),
      },
    );
  }

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        showCloseButton={false}
        // Forking is an input-heavy flow. Keep it out of the mobile Vaul drawer:
        // the drawer's drag gesture and focus handling compete with textarea
        // scrolling while the soft keyboard resizes the viewport. A real modal
        // keeps the form stationary and gives the form itself the scroll area.
        className="max-h-[calc(var(--lfg-visual-height,100dvh)-1rem)] max-w-[calc(100%-1rem)] sm:max-w-xl"
        innerClassName="max-h-[calc(var(--lfg-visual-height,100dvh)-1rem)] gap-0 overflow-y-auto overscroll-contain p-0"
      >
        <DialogTitle className="sr-only">
          {continuing ? "Continue session" : "Fork session"}
        </DialogTitle>
        <form
          onSubmit={submit}
          {...files.dropZoneProps}
          className={cn(
            "min-w-0 px-4 pb-5 pt-3 transition-colors",
            files.draggingFiles && "bg-primary/8",
          )}
        >
          <div className="mb-3 flex items-center gap-2">
            {continuing ? (
              <Play className="size-4 text-muted-foreground" />
            ) : (
              <GitFork className="size-4 text-muted-foreground" />
            )}
            <div className="min-w-0">
              <div className="text-[15px] font-semibold">
                {continuing ? "Continue in a new session" : "Fork session"}
              </div>
              <div className="truncate text-xs text-muted-foreground">
                {continuing
                  ? `Archives this session after opening the replacement · ${titleForSession(session)}`
                  : titleForSession(session)}
              </div>
            </div>
          </div>

          {files.fileInput}

          <div className="lfg-gfield relative rounded-2xl px-2 py-1">
            <SkillTextarea
              value={prompt}
              onValueChange={setPrompt}
              onPaste={files.onPasteFiles}
              onKeyDown={(e) => {
                if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
                  e.preventDefault();
                  e.currentTarget.form?.requestSubmit();
                }
              }}
              placeholder={
                files.attachments.length
                  ? "Add a note for the files…"
                  : "Extra prompt for the new agent…"
              }
              className="min-h-32 max-h-[42dvh] resize-none overflow-y-auto border-0 bg-transparent px-1 py-1 pr-10 text-base leading-relaxed shadow-none focus-visible:border-0 focus-visible:ring-0"
            />
            <MicButton
              minimal
              className="absolute bottom-1 right-1 size-9 shrink-0"
              silenceMs={2500}
              baseText={prompt}
              onText={(text, base) => setPrompt(base.trim() ? `${base.trimEnd()} ${text}` : text)}
              onInterim={(text, base) => setPrompt(base.trim() ? `${base.trimEnd()} ${text}` : text)}
              onAutoSubmit={(text, base) => {
                const combined = base.trim() ? `${base.trimEnd()} ${text}` : text;
                setPrompt(combined);
                submit(undefined, combined);
              }}
              onCancel={(base) => setPrompt(base)}
            />
          </div>

          {files.attachments.length ? <div className="mt-2">{files.chips}</div> : null}

          <div className="mt-3 flex flex-wrap items-center gap-1.5">
            <AgentIconStrip
              options={availableAgentOptions}
              value={agent}
              selectedId={selectedLaunchId}
              onSelect={(key, option) => {
                setAgent(key);
                if (key === "aisdk") setClaudeAccountId(option?.accountId ?? "");
                setModel(localStorage.getItem(`lfg_fork_model_${key}`) || defaultModelFor(key));
              }}
            />

            <ModelPicker value={model} models={models} onChange={setModel} width="max-w-28" />

            <ThinkingLevelPill
              agent={agent}
              value={thinkingLevel}
              levels={thinkingLevels}
              onChange={setThinkingLevel}
              immersive
            />
          </div>

          <div className="mt-4 flex items-center gap-2">
            <Button
              size="icon-sm"
              type="button"
              variant={files.draggingFiles ? "brand-soft" : "outline"}
              className="size-8 rounded-full shadow-sm"
              onClick={files.openFilePicker}
              aria-label="Attach files"
              title="Attach files"
            >
              <Plus className="size-4" />
            </Button>
            <div className="ml-auto flex items-center gap-2">
              <Button type="button" variant="ghost" onClick={onClose}>
                Cancel
              </Button>
              <Button type="submit" variant="brand" disabled={!sid}>
                {continuing ? <Play className="size-4" /> : <GitFork className="size-4" />}
                {continuing ? "Continue" : "Open"}
              </Button>
            </div>
          </div>
        </form>
        {files.annotator}
      </DialogContent>
    </Dialog>
  );
}

function ConversationParticipantRow({ session, compact = false }: { session: Session; compact?: boolean }) {
  const botDirectory = useContext(BotDirectoryContext);
  const participants = activeConversationParticipants(session);
  if (participants.length < 2) return null;
  return (
    <div
      className="mt-0.5 flex min-w-0 max-w-full items-center gap-1 overflow-hidden"
      aria-label={`Conversation participants: ${participants.map((participant) => participant.display.name || participant.display.fallback).join(", ")}`}
    >
      {participants.slice(0, 5).map((participant) => {
        const name = participant.display.name?.trim() || participant.display.fallback;
        if (participant.kind === "bot") {
          const botId = participant.id.startsWith("bot:") ? participant.id.slice(4) : participant.id;
          const bot = botDirectory.get(botId);
          return (
            <span
              key={participant.id}
              className={cn(
                "flex min-w-0 shrink items-center rounded-full bg-muted text-[10px] leading-none text-muted-foreground",
                compact ? "size-4 justify-center" : "gap-1 px-1.5 py-0.5",
              )}
              title={`${name} · bot`}
              aria-label={`${name}, bot`}
            >
              <BotMascot
                shape={bot?.shape}
                colorway={bot?.colorway}
                size={14}
                state="idle"
                seed={botId.length}
              />
              {!compact ? <span className="max-w-20 truncate">{name}</span> : null}
            </span>
          );
        }
        const fallback = name.slice(0, 1).toUpperCase() || "M";
        return (
          <span
            key={participant.id}
            className="relative grid size-4 shrink-0 place-items-center overflow-hidden rounded-full bg-primary/12 text-[9px] font-semibold text-primary"
            title={`${name} · ${participant.role}`}
            aria-label={`${name}, ${participant.role}`}
          >
            {fallback}
            {participant.display.avatar ? (
              <img
                src={participant.display.avatar}
                alt=""
                className="absolute inset-0 size-full object-cover"
                onError={(event) => event.currentTarget.remove()}
              />
            ) : null}
          </span>
        );
      })}
      {participants.length > 5 ? (
        <span className="shrink-0 text-[10px] text-muted-foreground">+{participants.length - 5}</span>
      ) : null}
    </div>
  );
}

// memo'd: an SSE event for one session replaces the messagesBySid/etc. Record
// reference, re-rendering LiveView's map. Without memo every card re-renders;
// with it, only the card whose own message/busy/prompt reference changed does —
// so swipe + collapse animations aren't fighting full-list re-renders.
const SessionCard = memo(function SessionCard({
  session,
  users,
  messages,
  busy,
  prompt,
  onSubscribeTranscript,
  onRefresh,
  onRenameSession,
  onRemove,
  onOpenSheet,
  variant = "grid",
  onClose,
  entering = false,
  focusGlow = 0,
  pinned = false,
  onTogglePin,
  stageBotId,
}: {
  session: Session;
  users: User[];
  messages: Message[];
  busy: boolean;
  prompt: SessionPrompt | null;
  onSubscribeTranscript?: OmgTranscriptSubscribe;
  onRefresh: () => Promise<void>;
  onRenameSession: RenameSession;
  onRemove: (sid: string) => void;
  // Tapping the title asks the parent to open the full-height detail sheet
  // for this sid, anchored to the title's rect. The sheet lives at the parent so
  // it can switch between sessions; undefined → the gesture is disabled.
  onOpenSheet?: (sid: string, origin: DOMRect) => void;
  // "stage" = fill the column height and show a close affordance that removes
  // the column (without ending the session). Default "grid" keeps the classic
  // fixed-height card + mobile gestures.
  variant?: "grid" | "stage";
  onClose?: () => void;
  // True only on the first render after this session was created in-tab — plays
  // the one-shot entrance animation on the card root.
  entering?: boolean;
  // Incrementing token from RailStage: non-zero + change restarts the slow
  // primary glow so a rail click points at this pane among several columns.
  focusGlow?: number;
  // Narrow/mobile list preference. Desktop stage pinning is owned by RailStage.
  pinned?: boolean;
  onTogglePin?: (sid: string) => void;
  // Set only by the dedicated bot-stage column (RailStage, railSurface ===
  // "chat"): the id of the bot the caller resolved and navigated to. That
  // resolution already went through the canonical, botId-verified picker
  // (botCanonicalSessionId / botStageSession) — trust it outright rather than
  // re-derive identity from this session's own conversation snapshot, which
  // can lag behind rotation or point at a same-sessionId/child/stale
  // attachment. Undefined (every other caller: grid cards, regular stage
  // columns) keeps the existing productBotId-derived behavior unchanged.
  stageBotId?: string | null;
}) {
  const appDialog = useAppDialog();
  const catalog = useAgentModelCatalog();
  const isMobile = useIsMobile();
  const [error, setError] = useState<string | null>(null);
  // Desktop double-click and the actions menu on every viewport edit in place.
  const [renamingInline, setRenamingInline] = useState(false);

  // A session driven by a bot is that bot's chat. It gets the bot's face and
  // name in the header rather than a generated session title, wherever it is
  // opened from.
  const botDirectory = useContext(BotDirectoryContext);
  const headerBotId = renderedBotId(session, stageBotId);
  const headerBot = headerBotId ? botDirectory.get(headerBotId) ?? null : null;
  const editBot = useContext(EditBotContext);

  const sid = session.sessionId;
  // An ask-user question raised by this session is the one state on the live
  // grid that is blocked on a PERSON rather than on an agent. The card says so
  // itself — border, header badge — so a waiting session is findable without
  // opening each one to check.
  const pendingQuestions = useSessionQuestions([session.sessionId, session.nativeSessionId]);
  const needsYou = pendingQuestions.length > 0;

  const startRename = useCallback(() => {
    if (!sid) return;
    haptic("selection");
    setRenamingInline(true);
  }, [sid]);

  const commitInlineRename = useCallback(
    async (next: string) => {
      if (!sid) return;
      setError(null);
      setRenamingInline(false);
      try {
        await onRenameSession(sid, next);
        toast.success("Session renamed");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        setError(msg);
        setRenamingInline(true);
        throw e;
      }
    },
    [onRenameSession, sid],
  );

  async function changeModel(model: string) {
    if (!sid || !model || model === session.model) return;
    setError(null);
    try {
      await api(`/api/sessions/${sid}/model`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model }),
      });
      await onRefresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }

  // ── mobile gestures: tap-header-to-collapse + iOS swipe-to-archive ────────
  // Fall back to the list payload's last message when we aren't streaming this
  // card (collapsed) so the collapsed preview line still shows something.
  const latest = latestLine(messages) || plainPreviewText(session.last?.text ?? "");
  const sectionRef = useRef<HTMLElement>(null);
  // Rail selection glow: restart the CSS animation whenever the token bumps.
  useLayoutEffect(() => {
    if (!focusGlow) return;
    const el = sectionRef.current;
    if (!el) return;
    el.classList.remove("lfg-card-focus-glow");
    // Force reflow so re-selecting the same pane restarts the animation.
    void el.offsetWidth;
    el.classList.add("lfg-card-focus-glow");
    const clear = window.setTimeout(() => el.classList.remove("lfg-card-focus-glow"), 2000);
    return () => window.clearTimeout(clear);
  }, [focusGlow]);
  // True while voice dictation is recording in this card's composer — glows the
  // card border so it's clear which session is listening.
  const [dictating, setDictating] = useState(false);
  const headRef = useRef<HTMLDivElement>(null);
  const [headH, setHeadH] = useState(44);
  const [swipeOpen, setSwipeOpen] = useState(false);
  const [swipeIntent, setSwipeIntent] = useState<"archive" | null>(null);
  // True only while a horizontal swipe is in progress. The red archive action is
  // kept out of the paint tree unless this or swipeOpen is set — otherwise it
  // sits behind every card and bleeds at the edges during fast momentum scroll.
  const [swiping, setSwiping] = useState(false);
  // Mutable drag bookkeeping — kept in a ref so touchmove never re-renders.
  const drag = useRef({
    startX: 0, startY: 0, x: 0, w: 0,
    dragging: false, decided: false, horizontal: false, justSwiped: false,
  });
  const openRef = useRef<"none" | "archive">("none");
  const OPEN = 116;    // resting reveal width once snapped open — wide enough to
                       // leave a left gap before the icon + "Archive" label
  const COMMIT = 0.55; // drag past this fraction of the card → archive on release

  // Measure the header so the mobile card sits at exactly its header height.
  useEffect(() => {
    const el = headRef.current;
    if (!el) return;
    const measure = () => setHeadH(el.offsetHeight);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const setTransform = (pxX: number, pxY: number) => {
    const el = sectionRef.current;
    if (!el) return;
    const tx = pxX ? `translateX(${pxX}px)` : "";
    const ty = pxY ? `translateY(${pxY}px)` : "";
    el.style.transform = [tx, ty].filter(Boolean).join(" ") || "";
  };

  async function archiveSession() {
    if (!sid) return;
    onRemove(sid); // drop the card now; the tombstone survives the next poll
    // Fire-and-forget (see the setTimeout in commitArchive), so nothing is left
    // to catch a rejection: swallow here. Racing the card away against a
    // session that already ended 404s with "session not found", which used to
    // surface as an unhandledrejection even though the swipe did what the user
    // wanted — the card is gone and the refresh below reconciles the truth.
    try {
      await closeSessionRequest(sid, "mobile_swipe_archive");
    } catch {
      /* already gone — the refresh below is the source of truth */
    } finally {
      await onRefresh().catch(() => {});
    }
  }

  async function commitArchive() {
    const el = sectionRef.current;
    if (!sid) {
      closeSwipe();
      return;
    }
    const confirmed = await appDialog.confirm({
      title: `Archive ${titleForSession(session)}?`,
      description: "The session will leave the live view and can be resumed later from Recent sessions.",
      confirmLabel: "Archive session",
      destructive: true,
    });
    if (!confirmed) {
      closeSwipe();
      return;
    }
    haptic("warning");
    setSwipeOpen(false);
    openRef.current = "none";
    if (el) {
      el.style.transition = "transform 0.26s var(--ease-ios), opacity 0.26s";
      el.style.transform = `translateX(-${el.offsetWidth}px)`;
      el.style.opacity = "0";
    }
    window.setTimeout(() => void archiveSession(), 280);
  }

  function closeSwipe() {
    const el = sectionRef.current;
    if (el) el.style.transition = "";
    setSwipeOpen(false);
    setSwipeIntent(null);
    openRef.current = "none";
    setTransform(0, 0);
  }

const onTouchStart = (e: ReactTouchEvent) => {
    if (!isMobile || e.touches.length !== 1) return;
    if ((e.target as HTMLElement).closest("form")) return; // don't hijack the composer
    const el = sectionRef.current;
    if (!el) return;
    const t = e.touches[0];
    const d = drag.current;
    d.startX = t.clientX; d.startY = t.clientY; d.w = el.offsetWidth;
    d.dragging = true; d.decided = false; d.horizontal = false; d.justSwiped = false;
    el.style.transition = "none";
  };

  const onTouchMove = (e: ReactTouchEvent) => {
    const d = drag.current;
    if (!d.dragging) return;
    const t = e.touches[0];
    const mx = t.clientX - d.startX;
    const my = t.clientY - d.startY;
    if (!d.decided) {
      if (Math.abs(mx) < 8 && Math.abs(my) < 8) return;
      d.decided = true;
      d.horizontal = Math.abs(mx) > Math.abs(my);
      if (d.horizontal) {
        setSwiping(true); // horizontal swipe → reveal the archive action behind it
      } else {
        d.dragging = false; // vertical intent → let the transcript/page scroll
        return;
      }
    }
    if (d.horizontal) {
      let nx = (openRef.current === "archive" ? -OPEN : 0) + mx;
      if (nx < -d.w) nx = -d.w;
      if (nx > 0) nx = 0;
      d.x = nx;
      setSwipeIntent(nx < -6 ? "archive" : null);
      setTransform(nx, 0);
      return;
    }
  };

  const onTouchEnd = () => {
    const d = drag.current;
    if (!d.dragging) return;
    d.dragging = false;
    setSwipeIntent(null);
    const el = sectionRef.current;
    if (el) el.style.transition = "";
    if (!d.decided) {
      setSwiping(false);
      return;
    }
    if (d.horizontal) {
      setSwiping(false);
      d.justSwiped = Math.abs(d.x) > 6;
      if (d.x <= -d.w * COMMIT) {
        void commitArchive();
        return;
      }
      const nextOpen = d.x <= -OPEN * 0.5 ? "archive" : "none";
      if (nextOpen !== "none" && openRef.current === "none") haptic("selection");
      openRef.current = nextOpen;
      setSwipeOpen(nextOpen === "archive");
      setTransform(nextOpen === "archive" ? -OPEN : 0, 0);
      return;
    }
  };

  // ── tap the title → morphing full-height sheet ────────────────────────────
  // The sheet itself lives at the parent (so it can switch between sessions and
  // force whichever sid it shows into the live stream); the card just reports the
  // tap and the title's rect to anchor the morph. There is no in-place expand on
  // mobile any more: the row is the summary, the sheet is the session.
  const onHeaderTap = (e: React.MouseEvent<HTMLElement>) => {
    if (!isMobile) return;
    if (drag.current.justSwiped) { drag.current.justSwiped = false; return; }
    if (openRef.current !== "none") { closeSwipe(); return; }
    if (!onOpenSheet || !sid) return;
    haptic("selection");
    onOpenSheet(sid, e.currentTarget.getBoundingClientRect());
  };

  // Mobile cards are always the stripped-down row (no model chip, no actions
  // menu, transcript and composer unmounted): light to render, and the only way
  // into a session is opening it. Desktop keeps the full in-grid card.
  const collapsedView = isMobile;

  return (
    <div className={cn("relative min-w-0 md:static", variant === "stage" && "md:h-full")}>
      {/* swipe-to-archive action revealed behind the card (mobile only) */}
      <button
        type="button"
        aria-label="Archive session"
        tabIndex={swipeOpen ? 0 : -1}
        onClick={() => void commitArchive()}
        className={cn(
          "absolute inset-0 flex items-center justify-end gap-2 rounded-xl bg-destructive pr-6 text-sm font-semibold text-white md:hidden",
          swipeOpen || swipeIntent === "archive" ? "" : "hidden", // out of the paint tree unless mid-swipe
          swipeOpen ? "" : "pointer-events-none",
        )}
      >
        <Archive className="size-5" />
        Archive
      </button>
      <section
        ref={sectionRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        style={isMobile ? { height: headH } : undefined}
        className={cn(
          "live-pane relative z-[1] flex h-[22rem] touch-pan-y flex-col overflow-hidden rounded-xl border bg-card text-card-foreground transition-[height,transform,border-color,box-shadow] duration-300 ease-ios md:static md:transition-[border-color,box-shadow]",
          entering && "lfg-card-in",
          variant === "stage" ? "md:h-full" : "md:h-[clamp(30rem,72vh,46rem)]",
          // Listening: soften the border to primary and throw a faint glow ring.
          // Waiting on an answer gets the same primary edge, one step quieter,
          // so a blocked session stands out in a grid of running ones.
          // Otherwise the flat border gives way to a glass gradient edge.
          dictating
            ? "border-primary/60 shadow-[0_0_0_1px_var(--primary),0_0_16px_2px_color-mix(in_srgb,var(--primary)_35%,transparent)]"
            : needsYou
              ? "border-primary/50 shadow-[0_0_0_1px_color-mix(in_srgb,var(--primary)_45%,transparent)]"
              : "border-transparent lfg-gborder",
        )}
      >
        <div
          ref={headRef}
          className="flex min-h-[3.75rem] min-w-0 items-center gap-2 border-b border-border px-3 py-2"
        >
          {/* Agent identity + busy indicator. This used to double as a hidden
              "speak the session summary" button, which read as an avatar and
              was removed with the TTS feature. A bot-backed session wears the
              bot's face instead of the harness mark: the creature already says
              which agent it is, and it carries busy in its own posture, so the
              spinner would be saying it twice. See SessionHeaderIdentity. */}
          <SessionHeaderIdentity session={session} busy={busy} size={28} trustedBotId={headerBotId} />
          {renamingInline ? (
            <SessionTitleInlineEditor
              initial={session.title?.trim() || titleForSession(session)}
              onCommit={commitInlineRename}
              onCancel={() => setRenamingInline(false)}
            />
          ) : (
            <button
              type="button"
              onClick={onHeaderTap}
              onDoubleClick={(e) => {
                // Mobile tap still opens the session sheet; its ⋮ menu starts the
                // same in-place editor without changing the title-tap gesture.
                if (isMobile || session.shippedReview) return;
                e.preventDefault();
                e.stopPropagation();
                startRename();
              }}
              onDragStart={(e) => e.preventDefault()}
              onSelect={(e) => e.preventDefault()}
              onContextMenu={(e) => e.preventDefault()}
              title={
                isMobile || session.shippedReview
                  ? undefined
                  : "Double-click to rename"
              }
              className={cn(
                "flex min-w-0 flex-1 touch-manipulation select-none items-center gap-2 text-left outline-none [-webkit-touch-callout:none] [-webkit-user-drag:none] [-webkit-user-select:none] [user-select:none]",
                !isMobile &&
                  !session.shippedReview &&
                  "cursor-text rounded-md hover:bg-muted/50",
              )}
            >
              <div className="flex min-w-0 flex-1 flex-col">
                <div className="truncate text-[15px] font-semibold leading-tight">
                  {headerBot ? headerBot.name : titleForSession(session)}
                </div>
                {isMobile && latest ? (
                  <div className="truncate text-[11px] leading-tight text-muted-foreground">
                    {latest}
                  </div>
                ) : null}
                {/* A persistent bot conversation's header shows the bot's own
                    identity and settings only — never who created or owns it.
                    ConversationParticipantRow's human chip belongs beside each
                    message that sender actually wrote (see
                    OtherHumanMessageBubble), not on the card that represents
                    the bot itself. */}
                {headerBot ? null : <ConversationParticipantRow session={session} compact={isMobile} />}
              </div>
            </button>
          )}
        {/* Reads on the card itself, next to the shipped/model chips, because
            the live grid is where a person scans for what needs them. */}
        {needsYou ? (
          <span
            title={
              pendingQuestions.length === 1
                ? "This session is waiting for your answer"
                : `${pendingQuestions.length} questions are waiting for your answer`
            }
            className="flex shrink-0 items-center gap-1 rounded-full bg-primary/12 px-2 py-0.5 text-[10px] font-semibold text-primary"
          >
            <MessageCircleQuestion className="size-3" />
            Needs you
          </span>
        ) : null}
        {pinned ? (
          <span
            aria-label="Pinned to top"
            title="Pinned to top"
            className="flex size-5 shrink-0 items-center justify-center text-primary"
          >
            <Pin className="size-3.5" fill="currentColor" />
          </span>
        ) : null}
        {/* A bot-backed card is the authoritative desktop bot conversation.
            Keep its lifecycle menu on the same header instead of exposing the
            regular session menu or a settings-only shortcut. */}
        {!collapsedView && headerBot && editBot ? (
          <BotConversationMenu
            bot={headerBot}
            runtimeHealthy
            busy={busy}
            onEdit={() => editBot(headerBot)}
            onRefresh={onRefresh}
          />
        ) : null}
        {!collapsedView && !headerBot && session.botId && session.botName ? (
          <DrivenByBotBadge session={session} />
        ) : null}
        {/* A bot's header is its face, its name and its persona (spec §4.1).
            The harness it happens to run on is a session detail, and picking a
            model mid-conversation is a session action — both belong to the
            session view of this same session, not to the chat. */}
        {!collapsedView && !headerBot && (
          (session.agent === "claude" || session.agent === "opencode") &&
          (session.tmuxTarget || session.agent === "opencode") &&
          sid ? (
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  className="shrink-0 rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground hover:bg-muted/70"
                  aria-label="Change model"
                />
              }
            >
              {session.model || "model"}
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-32">
              <DropdownMenuRadioGroup
                value={session.model ?? ""}
                onValueChange={(value) =>
                  void changeModel(typeof value === "string" ? value : "")
                }
              >
                <DropdownMenuLabel>Model</DropdownMenuLabel>
                {((catalog.models[session.agent as AgentKind] ?? AGENT_MODELS[session.agent as AgentKind]) ?? CLAUDE_MODELS).map((item) => (
                  <DropdownMenuRadioItem key={item} value={item}>
                    {item}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : session.model ? (
          <span className="shrink-0 rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
            {session.model}
          </span>
        ) : null)}
        {/* Redundant on wide screens: the rail row for this session already
            carries the same state on its avatar, so only the narrow (no-rail)
            grid layout needs it here. */}
        {session.shippedReview ? (
          <span className="shrink-0 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-600 dark:text-emerald-400">
            {session.reviewLabel || "Shipped"}
          </span>
        ) : (
          /* A bot-backed card is exempt from the idle dot for the same reason
             the rail row drops its dot: the creature carries state in its own
             posture, so the dot is the same fact said twice — and "idle" is
             the resting state of a bot you are simply not talking to right
             now, which is not news. Blocked still shows, because there is no
             pose for it.

             Working is not passed at all any more. This header already draws
             it on the identity mark above (AgentMark, via
             SessionHeaderIdentity), so at narrow widths the same session was
             reporting working twice on one row, in two colours: the amber
             ring around the mark and a blue spinner further along. */
          <SessionStatusDot
            paused={session.status === "blocked"}
            className="lg:hidden"
            variant={headerBot ? "avatar" : "inline"}
          />
        )}
        {/* No fork, ship, close or archive in a bot chat: a bot session is not
            closed from the UI, and the gear beside its name is the one entry
            point to everything you can change about it. */}
        {!collapsedView && !headerBot && (
          <SessionActionsMenu
            session={session}
            busy={busy}
            users={users}
            onRefresh={onRefresh}
            onRemove={onRemove}
            onError={setError}
            onRename={session.shippedReview ? undefined : startRename}
            pinned={pinned}
            onTogglePin={session.shippedReview ? undefined : onTogglePin}
          />
        )}
        {variant === "stage" && onClose ? (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close column"
            className="flex size-7 shrink-0 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted"
          >
            <X className="size-4" />
          </button>
        ) : null}
      </div>

      {!collapsedView && (
        <SessionChat
          session={session}
          // Same trusted identity as the header: on the bot-stage column this
          // is the bot the caller already resolved, not whatever SessionChat's
          // own productBotId fallback would re-derive from the session's
          // conversation snapshot.
          bot={headerBot ?? undefined}
          busy={busy}
          prompt={prompt}
          error={error}
          onError={setError}
          onSubscribeTranscript={onSubscribeTranscript}
          onRefresh={onRefresh}
          onDictatingChange={setDictating}
        />
      )}
      </section>
    </div>
  );
});

/**
 * How many rows at the bottom of the transcript are always mounted.
 *
 * NEVER MODEL THE TAIL. These rows are DOM-measured through measureElement
 * whatever the scroll position is, for three reasons that all bite at once:
 *   - only the last row can be a streaming draft, and Streamdown runs
 *     parseIncompleteMarkdown on partial text, so a prefix's block set is NOT
 *     a prefix of the finished block set — a modelled height would be wrong in
 *     a way that changes shape, not just size;
 *   - startGlide re-reads live scrollHeight every frame, so the bottom of the
 *     document has to be real, not estimated;
 *   - the entrance animations (lfg-msg-in, lfg-user-send) play on rows that
 *     have just arrived, i.e. exactly here.
 */
const CHAT_TAIL_ROWS = 30;

/** The virtualizer must never write scrollTop. See the wiring comment below. */
const noVirtualizerScroll = () => {};

/**
 * How many matches one find read asks for. The server clamps to
 * TRANSCRIPT_SEARCH_MAX_LIMIT and reports `matchTotal` and `truncated`, so a
 * common word in a long session still says honestly how much was clipped.
 */
const FIND_HIT_LIMIT = 200;

/** Settle time before a keystroke turns into a search request. */
const FIND_DEBOUNCE_MS = 180;

/**
 * How many pages of older messages ONE next/previous press will load while
 * chasing a hit that is not in the loaded window. Each page is a round trip
 * for 80 messages, so this is a latency budget, not a correctness limit:
 * pressing again resumes from where it stopped.
 */
const FIND_MAX_LOAD_PAGES = 12;

/** Where in the viewport a hit lands, as a fraction of the viewport height. */
const FIND_HIT_HEADROOM = 0.3;

/** Keys that scroll a pane. A keyboard scroll is a gesture like any other. */
const SCROLL_KEYS = new Set([
  "PageUp",
  "PageDown",
  "Home",
  "End",
  "ArrowUp",
  "ArrowDown",
  " ",
]);

const ChatStream = memo(function ChatStream({
  sid,
  messages,
  busy,
  loading,
  onLoadOlderMessages,
  onRetryQueued,
  bot,
  conversation,
}: {
  sid: string | null;
  messages: Message[];
  busy: boolean;
  loading: boolean;
  onLoadOlderMessages: LoadOlderMessages;
  onRetryQueued?: (message: Message) => void;
  bot?: PersistentBot;
  // Only present for a shared bot conversation — see MessageBubble's own-vs-
  // other-human split. A plain session never has more than one human
  // participant, so there is nothing here to resolve.
  conversation?: ProductConversation | null;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const transcriptView = useContext(TranscriptViewContext);
  const [stick, setStick] = useState(true);
  // The new transcript stays transparent for its first layout pass. That pass
  // lands the scroller at its final bottom, then this marker starts one global
  // fade. No intermediate scroll position can be painted during a switch.
  const [revealedSid, setRevealedSid] = useState<string | null>(null);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [hasOlder, setHasOlder] = useState(true);
  const [diffBarVisible, setDiffBarVisible] = useState(false);
  // Generalised from {height, top} to an anchor. Two different things move the
  // content under the viewport now — a page of older messages prepended above
  // it, and a virtual row above it being re-measured from its estimate — and
  // both are the same problem: hold one identified row still. Keeping the
  // second one out of the virtualizer (see shouldAdjustScrollPositionOnItem-
  // SizeChange below) is what keeps a single owner for scrollTop.
  const preserveScrollRef = useRef<{
    anchorKey: string;
    anchorOffset: number;
    top: number;
    height: number;
  } | null>(null);
  // The row the viewport is currently pinned to, kept fresh from real scroll
  // events so a correction always has something to restore.
  const anchorRef = useRef<{ key: string; offset: number } | null>(null);
  // The last offset this component saw on the pane, its OWN writes included.
  // `stick` is now re-armed from a direction rather than from a distance (see
  // lib/transcript-stick), and a direction needs somewhere to measure from.
  // Every direct `el.scrollTop = ...` below records itself here, so the scroll
  // event that write raises reports no movement and cannot be mistaken for the
  // reader travelling back to the bottom.
  const lastScrollTopRef = useRef(0);
  // Is a real input gesture driving the pane right now?
  //
  // This is what makes the state machine in lib/transcript-stick honest. Only
  // a gesture may change the mode, so a clamp, a re-measure, a prepend
  // correction or our own glide can never pin or unpin the reader. Momentum
  // after a flick still counts, because the gesture that started it did: the
  // flag stays set until WE write `scrollTop` again, rather than expiring on a
  // timer that a long momentum scroll would outlive.
  const userDrivenRef = useRef(false);
  // When the last NON-programmatic scroll event landed. Recency is what tells
  // "a fling is in flight right now" apart from "they scrolled and stopped":
  // `userDrivenRef` stays true for both, but only a live fling keeps raising
  // events. Consumed by the anchor restore through lib/transcript-anchor —
  // a scrollTop write landing mid-fling cancels the momentum dead.
  const lastUserScrollAtRef = useRef(Number.NEGATIVE_INFINITY);
  const transcriptMessages = useMemo(
    () => {
      const filtered = messages.filter(
        (message) =>
          !message.seed &&
          (!bot ||
            (!isBotRuntimeContractMessage(message) &&
              !isBotBackgroundUpdateMessage(message) &&
              // A conversation does not narrate its own mechanics. The full log
              // is still one click away, in this session's ordinary view.
              !isBotHiddenLogKind(message.kind))),
      );
      if (!bot) return filtered;
      const delivered = new Set(
        filtered
          .filter((message) => message.role === "user" && !message.pending)
          .map((message) => botVisibleUserText(message.text ?? "", bot).trim())
          .filter(Boolean),
      );
      return filtered.filter(
        (message) =>
          !(
            message.role === "user" &&
            message.pending &&
            delivered.has(botVisibleUserText(message.text ?? "", bot).trim())
          ),
      );
    },
    [messages, bot],
  );
  const visibleMessages = useMemo(
    () => messagesForTranscriptView(transcriptMessages, transcriptView.value),
    [transcriptMessages, transcriptView.value],
  );
  // Queued turns are pinned below the live turn instead of sitting in timestamp
  // order — see splitQueuedRenderItems.
  const { items, queued: queuedItems } = useMemo(
    () => splitQueuedRenderItems(buildChatRenderItems(visibleMessages)),
    [visibleMessages],
  );
  const speakers = useMemo(() => items.map(chatRenderItemSpeaker), [items]);
  // Historical reasoning can remain in the transcript after its turn is done.
  // Only let reasoning at the active tail replace the typing dots; otherwise an
  // old thinking block would make a newly-busy session look idle. The tail here
  // is the live turn's, not the pinned queue's.
  const tailItem = items[items.length - 1];
  const tailMessage = tailItem?.type === "msg" ? tailItem.message : undefined;
  const showTypingIndicator = busy && tailMessage?.kind !== "thinking";

  // ---- Virtualization ----------------------------------------------------
  //
  // 4732 messages collapse to about 1282 rows, and a bot board can mount four
  // transcripts at once. Only the rows near the viewport are in the DOM; the
  // rest contribute a modelled height (lib/chat-row-height) so the scrollbar
  // and the offsets are believable before those rows have ever been rendered.
  //
  // The virtualizer supplies OFFSETS ONLY. ChatStream remains the single owner
  // of scroll position: startGlide, the pin-to-bottom snap and the anchor
  // restore in the layout effect are still the only code that assigns
  // scrollTop. Two settings enforce that and neither is optional:
  //
  //   - `scrollToFn` is a no-op. In @tanstack/virtual-core 3.17 every internal
  //     correction funnels through it, including one fired the moment the
  //     scroll element attaches — with a null scrollOffset that resolves to
  //     zero, i.e. it would yank an opened transcript to the top on mount.
  //   - `shouldAdjustScrollPositionOnItemSizeChange` returns false. Leaving it
  //     undefined does NOT mean "never adjust": undefined selects the built-in
  //     default, which DOES write scrollTop on an item's first measurement.
  //     That is precisely the second scroll owner this must not have — it
  //     would race the glide, which re-reads scrollHeight every frame.
  //
  // Nothing here calls scrollToIndex, scrollToOffset or scrollBy, from render
  // or from an effect.
  const virtualContainerRef = useRef<HTMLDivElement>(null);
  const [scrollMargin, setScrollMargin] = useState(0);
  const metrics = useChatMarkdownMetrics(ref, items.length);
  const heightCacheRef = useRef(new Map<string, number>());
  useEffect(() => {
    // Warm the lazily-loaded block splitter; until it resolves every row falls
    // back to a flat estimate.
    markdownBlockSplitter();
  }, []);
  const rowContext = useMemo<RowContext | null>(() => {
    const splitBlocks = markdownBlockSplitter();
    if (!metrics.assistant || !splitBlocks) return null;
    return {
      assistant: metrics.assistant,
      user: metrics.user ?? undefined,
      measure: pretextMeasurer,
      splitBlocks,
      mediaWidth: metrics.mediaWidth,
    };
  }, [metrics]);

  const estimateSize = useCallback(
    (index: number) => {
      const item = items[index];
      if (!item) return ASSISTANT_SINGLE_LINE_PX + ROW_GAP_PX;
      const speakerChanged = index > 0 && speakerRunEdges(speakers, index).firstOfRun;
      if (!rowContext) {
        return estimateUnprobedRowHeight(item, speakerChanged);
      }
      const text = item.type === "tools" ? "" : (item.message.text ?? "");
      const key = `${item.key}|${metrics.version}|${HEIGHT_MODEL_VERSION}|${speakerChanged ? 1 : 0}|${text.length}`;
      const cache = heightCacheRef.current;
      const cached = cache.get(key);
      if (cached != null) return cached;
      // A streaming row mints a new key per token. Cap the cache rather than
      // let one long session grow it without bound.
      if (cache.size > 8000) cache.clear();
      const height = estimateRowHeight(item, { ...rowContext, speakerChanged });
      cache.set(key, height);
      return height;
    },
    [items, speakers, rowContext, metrics.version],
  );

  const rangeExtractor = useCallback(
    (range: Range) => {
      const indexes = defaultRangeExtractor(range);
      const tailStart = Math.max(0, items.length - CHAT_TAIL_ROWS);
      if (!indexes.length || indexes[indexes.length - 1] >= tailStart) return indexes;
      const merged = new Set(indexes);
      for (let i = tailStart; i < items.length; i += 1) merged.add(i);
      return [...merged].sort((a, b) => a - b);
    },
    [items.length],
  );

  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => ref.current,
    estimateSize,
    getItemKey: (index) => items[index]?.key ?? index,
    rangeExtractor,
    overscan: 6,
    scrollMargin,
    scrollToFn: noVirtualizerScroll,
  });
  // Not an option, an instance field: the library reads it directly.
  virtualizer.shouldAdjustScrollPositionOnItemSizeChange = () => false;

  // TanStack does not include estimateSize in its measurement memo key. A new
  // metrics.version therefore changes our callback but leaves every old
  // fallback offset intact unless the instance is explicitly invalidated.
  // Re-measure mounted rows in the same layout pass so real DOM sizes stay
  // authoritative while unmounted rows switch to the harvested CSS model.
  const measuredMetricsVersionRef = useRef(0);
  useLayoutEffect(() => {
    if (!rowContext || metrics.version === measuredMetricsVersionRef.current) return;
    measuredMetricsVersionRef.current = metrics.version;
    virtualizer.measure();
    const container = virtualContainerRef.current;
    if (!container) return;
    for (const row of container.querySelectorAll<HTMLElement>("[data-index]")) {
      virtualizer.measureElement(row);
    }
  }, [metrics.version, rowContext, virtualizer]);

  const virtualRows = virtualizer.getVirtualItems();
  const totalSize = virtualizer.getTotalSize();
  const indexByKey = useMemo(() => {
    const map = new Map<string, number>();
    items.forEach((item, index) => map.set(item.key, index));
    return map;
  }, [items]);
  // A row's key is only its FIRST message's id, so this is a second, wider map
  // than indexByKey: every message id that a row draws, including the members
  // folded into a tool pill. See lib/transcript-find.
  const findRowIndex = useMemo(() => buildFindRowIndex(items), [items]);

  // Which row the viewport is sitting on, refreshed from real (non-glide)
  // scroll events. This is read-only bookkeeping: it never moves anything.
  const captureAnchor = useCallback(
    (el: HTMLDivElement) => {
      const row = virtualizer.getVirtualItemForOffset(el.scrollTop);
      if (!row) return;
      anchorRef.current = { key: String(row.key), offset: el.scrollTop - row.start };
    },
    [virtualizer],
  );

  // One-shot entrance for freshly-arrived assistant turns so the draft→final
  // swap (and non-streaming arrivals) fade in instead of popping. Ref-based —
  // not module-level like the card entrance — because the board can mount one
  // ChatStream per column and a shared set would clobber across columns. The
  // backlog is seeded silently on session switch so opening a busy session
  // doesn't replay entrances for its whole history; `entering` markers expire
  // so re-renders (scroll, delta streams, collapse/expand) never replay them.
  const seenIdsRef = useRef<Set<string>>(new Set());
  const enteringIdsRef = useRef<Map<string, number>>(new Map());
  const seededSidRef = useRef<string | null>(null);
  if (seededSidRef.current !== sid) {
    seededSidRef.current = sid;
    seenIdsRef.current = new Set(
      visibleMessages.filter((m) => m.id && isFinalAssistantText(m)).map((m) => m.id as string),
    );
    enteringIdsRef.current = new Map();
  } else {
    const now = Date.now();
    for (const [id, expiry] of enteringIdsRef.current) {
      if (expiry <= now) enteringIdsRef.current.delete(id);
    }
    for (const m of visibleMessages) {
      if (!m.id || !isFinalAssistantText(m) || seenIdsRef.current.has(m.id)) continue;
      seenIdsRef.current.add(m.id);
      // Only animate turns that land while the session is live; a settled
      // transcript stays put.
      if (busy) enteringIdsRef.current.set(m.id, now + 500);
    }
  }

  // Follow-to-bottom used to be one line — `el.scrollTop = el.scrollHeight`
  // on every change while `stick` — which snapped the viewport in the same
  // frame the new message's layout landed at full height (its own fade/slide
  // entrance is opacity+transform, which don't affect layout, so the height
  // was already final before that entrance had drawn a single frame). Two
  // motions arriving in the same frame reads as one flick, not two things
  // happening.
  //
  // A fast token stream is the reason this can't just become
  // `scrollTo({behavior:"smooth"})` everywhere: a smooth scroll that can't
  // keep up with the next token arriving 30ms later looks worse than a jump
  // (it visibly lags the text). So only *discrete* arrivals animate — a new
  // item appended, or the typing indicator mounting/unmounting — and the
  // streaming tail's own in-place growth still snaps instantly, same as
  // before.
  const programmaticScrollRef = useRef(false);
  const glideRafRef = useRef<number | null>(null);
  const glideSpringRef = useRef(createTranscriptGlideState());
  const growthKeyRef = useRef<{ len: number; typing: boolean } | null>(null);
  const prevStickRef = useRef(stick);
  const justSwitchedRef = useRef(true);

  const stopGlide = useCallback(() => {
    if (glideRafRef.current != null) {
      cancelAnimationFrame(glideRafRef.current);
      glideRafRef.current = null;
    }
    glideSpringRef.current = createTranscriptGlideState();
    programmaticScrollRef.current = false;
  }, []);
  useEffect(() => stopGlide, [stopGlide]);

  /**
   * A real input gesture arrived on the pane.
   *
   * Two jobs, deliberately together: hand scroll control back to the reader
   * (73a578b), and mark the events that follow as theirs, so the state machine
   * in lib/transcript-stick is allowed to act on them.
   */
  const beginUserScroll = useCallback(() => {
    userDrivenRef.current = true;
    stopGlide();
  }, [stopGlide]);

  // Springs toward the bottom rather than tweening a fixed start/end: re-reads
  // `scrollHeight` every frame, so a message that keeps growing while this is
  // in flight (a discrete arrival immediately followed by its own streamed
  // text) is chased instead of overshot-then-corrected. The spring integration
  // is time-corrected, so a faster display does not simply run the animation
  // twice as fast. `programmaticScrollRef` marks the window so the scroll
  // handler below doesn't mistake our own motion for the user grabbing the
  // scrollbar mid-glide.
  const startGlide = useCallback(
    (el: HTMLDivElement) => {
      stopGlide();
      programmaticScrollRef.current = true;
      const step = (tickMs: number) => {
        const target = el.scrollHeight - el.clientHeight;
        const delta = target - el.scrollTop;
        if (Math.abs(delta) < 1) {
          el.scrollTop = target;
          lastScrollTopRef.current = el.scrollTop;
          // Our write, not theirs: the event this raises must not move the mode.
          userDrivenRef.current = false;
          stopGlide();
          return;
        }
        const next = nextTranscriptGlideFrame(glideSpringRef.current, delta, tickMs);
        glideSpringRef.current = next.state;
        const previousScrollTop = el.scrollTop;
        el.scrollTop += next.offsetPx;
        glideSpringRef.current = completeTranscriptGlideFrame(
          glideSpringRef.current,
          el.scrollTop !== previousScrollTop,
        );
        lastScrollTopRef.current = el.scrollTop;
        // Our write, not theirs: the event this raises must not move the mode.
        userDrivenRef.current = false;
        glideRafRef.current = requestAnimationFrame(step);
      };
      glideRafRef.current = requestAnimationFrame(step);
    },
    [stopGlide],
  );

  // ---- Find in transcript ------------------------------------------------
  //
  // Virtualizing the transcript took the browser's own Ctrl+F away: only the
  // rows near the viewport exist in the DOM, so native find reaches about 6.5%
  // of a loaded transcript from the bottom and 2% of the rows at the tail.
  // This asks the server which MESSAGES match
  // (POST /api/sessions/:id/transcript/search), maps each hit to a row through
  // findRowIndex, and scrolls to it.
  //
  // Ctrl+F is deliberately NOT rebound. The transcript pane is not a focusable
  // element, so a binding scoped to it would never fire, and the only binding
  // that would work is a global one — taking the browser's find away from the
  // entire app to repair one pane is a worse trade than the bug. The button in
  // the pane is the affordance.
  const [findOpen, setFindOpen] = useState(false);
  const [findQuery, setFindQuery] = useState("");
  const [findHits, setFindHits] = useState<TranscriptFindHit[]>([]);
  const [findTerms, setFindTerms] = useState<string[]>([]);
  const [findMatchTotal, setFindMatchTotal] = useState(0);
  const [findTruncated, setFindTruncated] = useState(false);
  const [findCursor, setFindCursor] = useState(0);
  const [findBusy, setFindBusy] = useState<"searching" | "paging" | null>(null);
  const [findNotice, setFindNotice] = useState<string | null>(null);
  // The message the reader was last sent to. Drives the outline and the text
  // highlight; null means no hit is currently landed on. Deliberately a
  // message id and NOT a row index — see findHitRow below.
  const [findRow, setFindRow] = useState<string | null>(null);
  // A hit whose message has no row yet. Set only by a next/previous press; the
  // effect below pages older messages until it resolves or gives up.
  const [findJump, setFindJump] = useState<{ messageId: string; pages: number } | null>(null);
  const findInputRef = useRef<HTMLInputElement>(null);
  // Where the reader was before the bar opened, kept as an ANCHOR rather than
  // a raw scrollTop: chasing a hit can prepend pages above them, which moves
  // every raw offset. Same shape and same fallback as preserveScrollRef.
  const findReturnRef = useRef<{
    anchor: { key: string; offset: number } | null;
    top: number;
    stick: boolean;
  } | null>(null);
  const findPagingRef = useRef(false);
  // Bumped by anything that invalidates an in-flight page load: closing the
  // bar, switching session, or asking for a different hit.
  const findGenRef = useRef(0);

  /**
   * The find bar's ONE scroll write, and it only ever runs from a user action
   * (opening onto a hit, or pressing next/previous).
   *
   * It assigns `el.scrollTop` directly, exactly like the pin-to-bottom snap and
   * the anchor restore, because ChatStream is the single owner of scroll
   * position. It deliberately does not call `virtualizer.scrollToIndex`: every
   * virtualizer scroll API funnels through `scrollToFn`, which is a no-op here
   * (see the wiring comment above), so scrollToIndex would move nothing and
   * then spin a five-second reconcile loop chasing a target it can never
   * reach. Un-no-op-ing scrollToFn to make it work is precisely the second
   * scroll owner that comment exists to prevent. The virtualizer stays
   * offsets-only: the only thing read here is `measurementsCache[index].start`,
   * the same read the anchor restore already makes.
   */
  const jumpToFindRow = useCallback(
    (index: number, messageId: string) => {
      const el = ref.current;
      const measurement = virtualizer.measurementsCache[index];
      if (!el || !measurement) return;
      stopGlide();
      // Landing on a hit means the reader has left the bottom. Dropping stick
      // is what makes the jump-to-latest pill behave exactly as it does after
      // any manual scroll, instead of the pin effect hauling them back down.
      setStick(false);
      const target = measurement.start - Math.round(el.clientHeight * FIND_HIT_HEADROOM);
      const clamped = Math.max(0, Math.min(target, el.scrollHeight - el.clientHeight));
      el.scrollTop = clamped;
      lastScrollTopRef.current = el.scrollTop;
      // Our write, not theirs: the event this raises must not move the mode.
      userDrivenRef.current = false;
      // Hand the landed row to the anchor the layout effect restores from, so
      // rows above it settling from estimate to measured height keep it under
      // the reader rather than sliding it off screen.
      anchorRef.current = { key: items[index]?.key ?? "", offset: clamped - measurement.start };
      setFindRow(messageId);
    },
    [items, stopGlide, virtualizer],
  );

  const goToFindHit = useCallback(
    (cursor: number) => {
      const hit = findHits[cursor];
      if (!hit) return;
      findGenRef.current += 1;
      findPagingRef.current = false;
      setFindCursor(cursor);
      setFindNotice(null);
      const located = findRowIndex.get(hit.messageId);
      if (located != null) {
        setFindJump(null);
        jumpToFindRow(located, hit.messageId);
        return;
      }
      setFindRow(null);
      setFindJump({ messageId: hit.messageId, pages: 0 });
    },
    [findHits, findRowIndex, jumpToFindRow],
  );

  /**
   * Step through the hits.
   *
   * The server returns the most recent `limit` matches in ascending order, and
   * the reader is at the tail, so the cursor starts on the NEWEST hit and the
   * first press lands on it instead of stepping off it. From there "up" walks
   * backwards through the conversation, which is the direction the remaining
   * matches are in.
   */
  const stepFind = useCallback(
    (delta: number) => {
      if (!findHits.length) return;
      const landed = findRow != null || findJump != null;
      goToFindHit(landed ? stepFindHit(findHits.length, findCursor, delta) : findCursor);
    },
    [findCursor, findHits.length, findJump, findRow, goToFindHit],
  );

  // Chasing a hit that has not been paged in yet.
  //
  // The transcript pages backwards from the tail, so a hit older than the
  // loaded window has no row at all. Failing silently there would be the same
  // regression this bar exists to fix, so instead it loads older pages until
  // the row appears, and says plainly what happened when it cannot reach it.
  // This is the continuation of the user's press, not an autonomous scroll: it
  // runs only while `findJump` is set, and only a press sets it.
  useEffect(() => {
    if (!findJump) return;
    const located = findRowIndex.get(findJump.messageId);
    if (located != null) {
      setFindJump(null);
      setFindBusy(null);
      jumpToFindRow(located, findJump.messageId);
      return;
    }
    if (!sid || !hasOlder || findJump.pages >= FIND_MAX_LOAD_PAGES) {
      setFindJump(null);
      setFindBusy(null);
      setFindNotice(
        hasOlder && findJump.pages >= FIND_MAX_LOAD_PAGES
          ? "Still loading older messages toward that match. Press again to keep going."
          : "That match is not shown in this transcript view. Switch to the full view to see it.",
      );
      return;
    }
    // Either our own previous page or the scroll-triggered backfill is in
    // flight. Both land as a new `items` array, which re-runs this effect.
    if (findPagingRef.current || loadingOlder) return;
    findPagingRef.current = true;
    const generation = findGenRef.current;
    const target = findJump.messageId;
    setFindBusy("paging");
    setStick(false);
    setLoadingOlder(true);
    onLoadOlderMessages(sid)
      .then((more) => {
        if (generation !== findGenRef.current) return;
        setHasOlder(more);
        setFindJump((current) =>
          current && current.messageId === target
            ? { messageId: target, pages: current.pages + 1 }
            : current,
        );
      })
      .catch(() => {
        if (generation !== findGenRef.current) return;
        setFindJump(null);
        setFindBusy(null);
        setFindNotice("Could not load older messages to reach that match.");
      })
      .finally(() => {
        findPagingRef.current = false;
        if (generation === findGenRef.current) setLoadingOlder(false);
      });
  }, [
    findJump,
    findRowIndex,
    hasOlder,
    jumpToFindRow,
    loadingOlder,
    onLoadOlderMessages,
    sid,
  ]);

  // One search per settled query. Typing never scrolls: the reader asks for a
  // jump with Enter or the arrows, which keeps every scroll write behind a
  // deliberate action.
  useEffect(() => {
    if (!findOpen || !sid) return;
    const query = findQuery.trim();
    if (!query) {
      setFindHits([]);
      setFindTerms([]);
      setFindMatchTotal(0);
      setFindTruncated(false);
      setFindCursor(0);
      setFindRow(null);
      setFindJump(null);
      setFindNotice(null);
      setFindBusy(null);
      return;
    }
    let cancelled = false;
    setFindBusy("searching");
    const timer = setTimeout(() => {
      api<TranscriptSearchResponse>(
        `/api/sessions/${encodeURIComponent(sid)}/transcript/search`,
        {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ query, limit: FIND_HIT_LIMIT }),
        },
      )
        .then((page) => {
          if (cancelled) return;
          const hits = Array.isArray(page.results) ? page.results : [];
          setFindHits(hits);
          setFindTerms(transcriptFindTerms(query));
          setFindMatchTotal(page.matchTotal ?? hits.length);
          setFindTruncated(!!page.truncated);
          // Ascending order, reader at the tail: start on the newest match.
          setFindCursor(Math.max(0, hits.length - 1));
          setFindRow(null);
          setFindJump(null);
          setFindBusy(null);
          setFindNotice(hits.length ? null : "No matches.");
        })
        .catch((searchError) => {
          if (cancelled) return;
          setFindBusy(null);
          setFindNotice(
            searchError instanceof Error ? searchError.message : String(searchError),
          );
        });
    }, FIND_DEBOUNCE_MS);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [findOpen, findQuery, sid]);

  const openFind = useCallback(() => {
    const el = ref.current;
    if (el) {
      captureAnchor(el);
      findReturnRef.current = {
        anchor: anchorRef.current ? { ...anchorRef.current } : null,
        top: el.scrollTop,
        stick,
      };
    }
    setFindOpen(true);
    // The input does not exist until the bar has rendered.
    requestAnimationFrame(() => findInputRef.current?.focus());
  }, [captureAnchor, stick]);

  // Escape (and the close button) put the reader back where they were.
  const closeFind = useCallback(() => {
    findGenRef.current += 1;
    setFindOpen(false);
    setFindJump(null);
    setFindRow(null);
    setFindBusy(null);
    setFindNotice(null);
    setFindTerms([]);
    clearFindHighlight();
    const el = ref.current;
    const restore = findReturnRef.current;
    findReturnRef.current = null;
    if (!el || !restore) return;
    stopGlide();
    if (restore.stick) {
      // They were pinned to the bottom. Re-engaging stick is the same discrete
      // event jump-to-latest raises, so the pin effect glides back down and
      // this adds no second scroll write.
      setStick(true);
      return;
    }
    setStick(false);
    const index = restore.anchor ? indexByKey.get(restore.anchor.key) : undefined;
    const start = index == null ? undefined : virtualizer.measurementsCache[index]?.start;
    // Same fallback the layout effect uses when an anchor row did not survive.
    const next = start != null && restore.anchor ? start + restore.anchor.offset : restore.top;
    el.scrollTop = Math.max(0, Math.min(next, el.scrollHeight - el.clientHeight));
    lastScrollTopRef.current = el.scrollTop;
    // Our write, not theirs: the event this raises must not move the mode.
    userDrivenRef.current = false;
    anchorRef.current = restore.anchor ? { ...restore.anchor } : null;
  }, [indexByKey, stopGlide, virtualizer]);

  const onFindKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeFind();
        return;
      }
      if (event.key !== "Enter") return;
      event.preventDefault();
      stepFind(event.shiftKey ? 1 : -1);
    },
    [closeFind, stepFind],
  );

  // A find session belongs to one transcript. Kept out of the session-switch
  // reset below so the two stay independently reviewable.
  useEffect(() => {
    findGenRef.current += 1;
    findPagingRef.current = false;
    findReturnRef.current = null;
    setFindOpen(false);
    setFindQuery("");
    setFindHits([]);
    setFindTerms([]);
    setFindMatchTotal(0);
    setFindTruncated(false);
    setFindCursor(0);
    setFindRow(null);
    setFindJump(null);
    setFindBusy(null);
    setFindNotice(null);
    clearFindHighlight();
  }, [sid]);

  // Which row currently draws the landed hit. Resolved from the message id on
  // every render rather than kept as the index jumpToFindRow used, because
  // chasing a later hit can prepend pages above this one: the row is the same
  // row, but its index is not the same number.
  const findHitRow = findRow ? findRowIndex.get(findRow) ?? null : null;

  // Paint the matched text inside the landed row. The row can unmount and
  // remount as the virtual window slides, so this repaints whenever that
  // window moves; the key is a cheap stand-in for "the mounted range changed".
  const virtualWindowKey = virtualRows.length
    ? `${virtualRows[0].index}:${virtualRows.length}`
    : "";
  useEffect(() => {
    if (!findOpen || findHitRow == null || !findTerms.length) {
      clearFindHighlight();
      return;
    }
    paintFindHighlight(
      ref.current?.querySelector<HTMLElement>('[data-find-hit="true"]') ?? null,
      findTerms,
    );
  }, [findOpen, findHitRow, findTerms, virtualWindowKey]);
  useEffect(() => clearFindHighlight, []);

  useLayoutEffect(() => {
    // Scroll intent belongs to one transcript. A free-scrolled session must
    // not make the next session open away from latest or leave its jump pill
    // visible on a transcript that does not even overflow. Layout timing keeps
    // that old state out of the first paint.
    setStick(true);
    prevStickRef.current = true;
    setHasOlder(true);
    preserveScrollRef.current = null;
    anchorRef.current = null;
    // Our write, not theirs: the event this raises must not move the mode.
    userDrivenRef.current = false;
    lastUserScrollAtRef.current = Number.NEGATIVE_INFINITY;
    heightCacheRef.current.clear();
    growthKeyRef.current = null;
    justSwitchedRef.current = true;
    stopGlide();
    lastScrollTopRef.current = 0;
  }, [sid, stopGlide]);

  // A session switch is not a live arrival. The virtualizer can publish its
  // new total after the sid layout effect above, so revealing there can expose
  // a second pass that starts at scrollTop 0. Keep the surface hidden through
  // that pass. On the next frame, the complete transcript exists: snap it to
  // its live bottom, then start the opacity-only reveal. The follow effect
  // below also keeps snapping while this marker is pending, so no spring can
  // run behind the fade.
  useLayoutEffect(() => {
    if (loading || revealedSid === sid) return;
    const frame = requestAnimationFrame(() => {
      const el = ref.current;
      if (!el) return;
      stopGlide();
      const bottom = Math.max(0, el.scrollHeight - el.clientHeight);
      el.scrollTop = bottom;
      lastScrollTopRef.current = el.scrollTop;
      // Our write, not theirs: the event this raises must not move the mode.
      userDrivenRef.current = false;
      setRevealedSid(sid);
    });
    return () => cancelAnimationFrame(frame);
  }, [loading, revealedSid, sid, stopGlide]);

  // A manual jump-to-latest click is itself a discrete event — route it
  // through the same `stick` transition the effect below already treats as
  // one, instead of a second scroll call that would race the effect's own.
  const scrollToBottom = useCallback(() => {
    setStick(true);
  }, []);

  useEffect(() => {
    const el = ref.current;
    if (!el || !stick) {
      prevStickRef.current = stick;
      return;
    }
    const key = { len: items.length, typing: showTypingIndicator };
    const prevKey = growthKeyRef.current;
    const switched = justSwitchedRef.current;
    const switching = revealedSid !== sid;
    // Re-engaging stick (jump-to-latest, or scrolling back within range) is a
    // fresh intent — the user asked to go to the bottom — and deserves its
    // own glide even if one happens to be running. An appended item or a
    // typing-indicator toggle is just "more content arrived": the glide
    // already re-reads scrollHeight every frame, so it is chasing the growing
    // transcript correctly on its own and doesn't need a restart. The same
    // item just growing mid-stream (neither of these) isn't discrete at all.
    const reengaged = !switched && !prevStickRef.current;
    const grew = !switched && !!prevKey && (prevKey.len !== key.len || prevKey.typing !== key.typing);
    const discrete = reengaged || grew;
    growthKeyRef.current = key;
    prevStickRef.current = stick;
    // Only write when we're not already pinned: a redundant assignment still
    // emits a scroll event, which flips `stick` and re-runs this effect — an
    // self-sustaining loop that React kills with "maximum update depth".
    const bottom = el.scrollHeight - el.clientHeight;
    if (switching) {
      // The switch reveal owns this interval. Keep the virtualizer's late
      // layout passes pinned without starting the live-arrival spring; the
      // pane is still transparent, so only the final position can be seen.
      stopGlide();
      if (Math.abs(el.scrollTop - bottom) > 0.5) el.scrollTop = bottom;
      lastScrollTopRef.current = el.scrollTop;
      // Our write, not theirs: the event this raises must not move the mode.
      userDrivenRef.current = false;
      return;
    }
    justSwitchedRef.current = false;
    if (Math.abs(el.scrollTop - bottom) <= 0.5) {
      stopGlide();
      return;
    }
    const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const glideAction = transcriptGlideAction({
      discrete,
      reengaged,
      reducedMotion,
      running: glideRafRef.current != null,
    });
    // A glide already in flight is already chasing the live target every
    // frame. Both another discrete arrival and ordinary streamed growth must
    // leave it alone. Restarting stutters; stopping it snaps. Only a genuine
    // re-engage preempts it, while ordinary growth with no active glide keeps
    // the existing instant-follow policy.
    if (glideAction === "start") {
      startGlide(el);
    } else if (glideAction === "snap") {
      stopGlide();
      // The bottom offset, not the content height. The browser clamped the
      // old form to the same place, so this changes nothing on screen; it
      // stops the line from claiming an offset that does not exist.
      el.scrollTop = bottom;
      lastScrollTopRef.current = el.scrollTop;
      // Our write, not theirs: the event this raises must not move the mode.
      userDrivenRef.current = false;
    }
  }, [visibleMessages, busy, stick, items.length, showTypingIndicator, totalSize, revealedSid, sid, startGlide, stopGlide]);

  // The virtual list sits below the loading-older spinner, so the offsets the
  // virtualizer hands out are shifted by however much chrome is above it.
  // Recomputed only when that chrome changes; reading offsetTop forces layout.
  useLayoutEffect(() => {
    const el = virtualContainerRef.current;
    const next = el ? el.offsetTop : 0;
    setScrollMargin((prev) => (prev === next ? prev : next));
  }, [loadingOlder, items.length > 0, busy]);

  // The one place a content shift is corrected.
  //
  // Prepending a page of older messages and re-measuring an estimated row
  // above the fold are the same event seen twice: the offsets below the
  // viewport moved, and one identified row has to be held still. Both go
  // through this effect, because AGENTS.md forbids a second source of truth
  // and scroll position already has an owner here.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const requested = preserveScrollRef.current;
    preserveScrollRef.current = null;
    // While stuck to the bottom the glide owns the viewport; holding an old
    // row still would fight it.
    const current = anchorRef.current;
    const anchor =
      requested ??
      (stick || !current
        ? null
        : {
            anchorKey: current.key,
            anchorOffset: current.offset,
            top: el.scrollTop,
            height: el.scrollHeight,
          });
    if (!anchor) return;
    // A write landing while a fling is live cancels the momentum — the
    // mid-scroll dead stop. Skipping is debt-free: captureAnchor re-records
    // the anchor from the very next scroll event, so the shift this write
    // would have corrected is absorbed there instead. A requested prepend
    // hold still applies unconditionally. See lib/transcript-anchor.
    if (
      !shouldApplyAnchorCorrection({
        requested: requested != null,
        userDriven: userDrivenRef.current,
        msSinceUserScroll: performance.now() - lastUserScrollAtRef.current,
      })
    ) {
      return;
    }
    const index = indexByKey.get(anchor.anchorKey);
    const start = index == null ? undefined : virtualizer.measurementsCache[index]?.start;
    // No anchor row survived the update (it scrolled out of the loaded page).
    // Fall back to the whole-document delta, which is what this effect did
    // before rows had identities.
    const next =
      start == null
        ? requested
          ? el.scrollHeight - anchor.height + anchor.top
          : null
        : start + anchor.anchorOffset;
    if (next == null) return;
    const clamped = Math.max(0, Math.min(next, el.scrollHeight - el.clientHeight));
    if (Math.abs(clamped - el.scrollTop) > 0.5) el.scrollTop = clamped;
    // Whatever this pass settled on is where the pane now is, and none of it
    // was the reader moving: either this effect wrote the offset to hold one
    // row still, or the browser clamped it because the content shrank past
    // them. Recording it keeps the scroll event either one raises from reading
    // as a move toward the bottom and re-arming the pin. See
    // lib/transcript-stick.
    lastScrollTopRef.current = el.scrollTop;
    // Our write, not theirs: the event this raises must not move the mode.
    userDrivenRef.current = false;
    anchorRef.current = { key: anchor.anchorKey, offset: anchor.anchorOffset };
  }, [visibleMessages, totalSize, stick, indexByKey, virtualizer]);

  // A transcript that does not overflow sits at scrollTop 0 *and* at the
  // bottom, so no gesture can ever ask for more of it. The old guard refused
  // to load in that state and a deep but heavily folded session became
  // unreachable: 4234 messages that render as a handful of rows. It now
  // backfills instead, and because there is no scroll position to preserve it
  // keeps the pin to the bottom rather than clearing `stick` on every event.
  const maybeLoadOlder = useCallback(async (mode: "anchored" | "backfill") => {
    const el = ref.current;
    if (!sid || !el || loadingOlder || !hasOlder) return;
    if (mode !== "backfill") {
      captureAnchor(el);
      preserveScrollRef.current = {
        anchorKey: anchorRef.current?.key ?? "",
        anchorOffset: anchorRef.current?.offset ?? 0,
        top: el.scrollTop,
        height: el.scrollHeight,
      };
      setStick(false);
    }
    setLoadingOlder(true);
    try {
      const more = await onLoadOlderMessages(sid);
      setHasOlder(more);
    } catch {
      preserveScrollRef.current = null;
    } finally {
      setLoadingOlder(false);
    }
  }, [sid, loadingOlder, hasOlder, onLoadOlderMessages, captureAnchor]);

  // Nothing scrolls an underfilled transcript, so the backfill needs its own
  // trigger. It re-runs as messages land and stops as soon as the viewport
  // overflows or the history runs out.
  //
  // The loop stop is progress, not a round budget: one attempt per distinct
  // message count. A page that brings nothing new (or a cursor the stream has
  // not published yet) leaves the count where it was, so the effect goes quiet
  // instead of retrying, and any later arrival re-opens it.
  const backfilledAtRef = useRef(-1);
  useEffect(() => {
    backfilledAtRef.current = -1;
  }, [sid]);
  useEffect(() => {
    if (loading || loadingOlder || !hasOlder || !sid) return;
    const el = ref.current;
    if (!el || !visibleMessages.length) return;
    if (backfilledAtRef.current === visibleMessages.length) return;
    if (loadOlderIntent(el) !== "backfill") return;
    backfilledAtRef.current = visibleMessages.length;
    void maybeLoadOlder("backfill");
  }, [loading, loadingOlder, hasOlder, sid, visibleMessages, totalSize, maybeLoadOlder]);

  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
    <Conversation
      key={sid ?? "no-session"}
      ref={ref}
      data-session-ready={revealedSid === sid ? "true" : "false"}
      // A scroll event cannot say who caused it, and the glide emits one per
      // frame. Suppressing the handler for the glide's duration therefore
      // also swallowed the user's own scroll if it landed mid-flight: they
      // dragged up, `stick` was never re-read, and the glide kept hauling
      // them back to the bottom. These three CAN only come from a person, so
      // they cancel the glide outright and hand control back.
      onWheel={beginUserScroll}
      onTouchStart={beginUserScroll}
      onPointerDown={beginUserScroll}
      onKeyDown={(event) => {
        // Keyboard scrolling is a gesture too. Without this, PageUp could move
        // the view while the machine still believed nothing had happened.
        if (SCROLL_KEYS.has(event.key)) beginUserScroll();
      }}
      onScroll={(event) => {
        const el = event.currentTarget;
        // Read the baseline before it is replaced: `nextStick` needs the
        // offset this component last saw, and every event — the glide's
        // included — moves that baseline forward.
        const previousScrollTop = lastScrollTopRef.current;
        lastScrollTopRef.current = el.scrollTop;
        // Our own glide fires `scroll` events on every intermediate frame,
        // same as a user drag would. Reading `stick` from those would catch
        // the glide mid-flight (still >72px away, early on) and read it as
        // the user stepping back — dropping `stick` in the middle of the
        // motion that only exists because `stick` was true.
        if (!programmaticScrollRef.current) {
          lastUserScrollAtRef.current = performance.now();
          // NOT a distance. A re-measure can shrink the modelled total past
          // the reader, and the browser then clamps `scrollTop` and raises a
          // scroll event that a distance test reads as "they came back to the
          // bottom" — which is the snap that happens with no new message.
          // lib/transcript-stick carries the measurements and the rule.
          setStick((prev) =>
            nextScrollMode(prev ? "pinned" : "free", {
              scrollTop: el.scrollTop,
              scrollHeight: el.scrollHeight,
              clientHeight: el.clientHeight,
              previousScrollTop,
              userDriven: userDrivenRef.current,
            }) === "pinned",
          );
          // Remember where the reader actually is, so a later re-measure or a
          // prepend can put them back on the same row.
          captureAnchor(el);
        }
        const intent = loadOlderIntent(el);
        if (intent !== "none") void maybeLoadOlder(intent);
      }}
      className={cn(
        "chat-stream lfg-transcript-session min-h-0 flex-1 overflow-y-auto bg-background px-3 pt-3",
        // Only reserve room for the floating "files changed / Review" bar
        // while it's actually shown, so it never overlaps the last message.
        diffBarVisible ? "pb-16" : "pb-3",
      )}
    >
      {visibleMessages.length || busy ? (
        <ConversationContent>
          {loadingOlder ? (
            <div className="flex justify-center py-1 text-xs text-muted-foreground">
              <Loader2 className="mr-1.5 size-3.5 animate-spin" />
              Loading older messages
            </div>
          ) : null}
          {/* The virtual window. Rows are absolutely positioned, so the flex
              gap that used to separate them no longer applies — each row
              carries it as its own bottom padding instead, which also means
              the DOM measurement of a row includes exactly what the model
              predicts for it. */}
          <div
            ref={virtualContainerRef}
            className="relative w-full"
            style={{ height: `${totalSize}px` }}
          >
            {virtualRows.map((virtualRow) => {
              const index = virtualRow.index;
              const item = items[index];
              if (!item) return null;
              // A speaker change gets visible breathing room; a same-speaker
              // follow-up sits close to the turn before it, the way a real
              // chat reads. The row gap is the tight same-speaker baseline —
              // this only adds the extra space on top of it.
              const { firstOfRun, lastOfRun } = speakerRunEdges(speakers, index);
              const speakerChanged = index > 0 && firstOfRun;
              return (
                <div
                  key={item.key}
                  data-index={index}
                  // The find bar's landed row. Styled from CSS through this
                  // attribute rather than a class on the row, because the row
                  // is DOM-measured: the outline it draws must not be able to
                  // add a single pixel of height. Same reason the highlight
                  // inside it is a paint-only CSS Highlight rather than a
                  // wrapper element around the matched text.
                  data-find-hit={findHitRow === index ? "true" : undefined}
                  ref={virtualizer.measureElement}
                  className={cn("pb-2", speakerChanged && "pt-2.5")}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    transform: `translateY(${virtualRow.start - scrollMargin}px)`,
                  }}
                >
                  {item.type === "tools" ? (
                    <ToolGroup items={item.items} live={busy && index === items.length - 1} sid={sid} />
                  ) : (
                    <MessageBubble
                      message={item.message}
                      live={busy && index === items.length - 1}
                      entering={!!item.message.id && enteringIdsRef.current.has(item.message.id)}
                      onRetryQueued={onRetryQueued}
                      bot={bot}
                      conversation={conversation}
                      firstOfRun={firstOfRun}
                      lastOfRun={lastOfRun}
                    />
                  )}
                </div>
              );
            })}
          </div>
          <TypingIndicator visible={showTypingIndicator} bot={bot} />
          {/* Pinned below the working indicator: what the agent is doing now,
              then what it will read next. */}
          {queuedItems.map((item) =>
            item.type === "msg" ? (
              <MessageBubble
                key={item.key}
                message={item.message}
                onRetryQueued={onRetryQueued}
                bot={bot}
                conversation={conversation}
              />
            ) : null,
          )}
        </ConversationContent>
      ) : loading ? (
        <ConversationEmptyState
          icon={<Loader2 className="size-5 animate-spin" />}
          title="Loading transcript"
        >
          <Loader2 className="size-5 animate-spin" />
          <span>Loading transcript</span>
        </ConversationEmptyState>
      ) : (
        <ConversationEmptyState
          title={
            transcriptView.value === "user-lfg-output"
              ? "No user or omg.dev output messages yet"
              : "No transcript messages yet"
          }
        />
      )}
    </Conversation>
    {/* Find in transcript. Same floating-pill language as jump-to-latest, and
        the same click-through wrapper, parked at the top of the pane where a
        browser's own find bar sits. The button is always offered while there
        is a transcript to search — see the Ctrl+F note on the state above. */}
    {visibleMessages.length ? (
      <div className="pointer-events-none absolute inset-x-0 top-2 z-20 flex flex-col items-end gap-1 px-3">
        {findOpen ? (
          <>
            <div className="lfg-scroll-pill pointer-events-auto flex w-full max-w-sm items-center gap-1 rounded-full border border-border bg-card/95 py-1 pl-3 pr-1 shadow-md backdrop-blur">
              {findBusy ? (
                <Loader2 className="size-3.5 shrink-0 animate-spin text-muted-foreground" />
              ) : (
                <Search className="size-3.5 shrink-0 text-muted-foreground" />
              )}
              <input
                ref={findInputRef}
                type="text"
                value={findQuery}
                onChange={(event) => setFindQuery(event.target.value)}
                onKeyDown={onFindKeyDown}
                placeholder="Find in transcript"
                aria-label="Find in transcript"
                autoComplete="off"
                spellCheck={false}
                className="min-w-0 flex-1 bg-transparent text-xs text-foreground outline-none placeholder:text-muted-foreground"
              />
              <span
                aria-live="polite"
                className="shrink-0 whitespace-nowrap text-[11px] tabular-nums text-muted-foreground"
              >
                {findHits.length
                  ? `${findCursor + 1}/${findHits.length}${findTruncated ? ` of ${findMatchTotal}` : ""}`
                  : ""}
              </span>
              <button
                type="button"
                onClick={() => stepFind(-1)}
                disabled={!findHits.length}
                aria-label="Previous match, further back in the transcript"
                title="Previous match (Enter)"
                className="flex size-6 shrink-0 items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-40"
              >
                <ArrowUp className="size-3.5" />
              </button>
              <button
                type="button"
                onClick={() => stepFind(1)}
                disabled={!findHits.length}
                aria-label="Next match, further forward in the transcript"
                title="Next match (Shift+Enter)"
                className="flex size-6 shrink-0 items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-40"
              >
                <ArrowDown className="size-3.5" />
              </button>
              <button
                type="button"
                onClick={closeFind}
                aria-label="Close find"
                title="Close find (Escape)"
                className="flex size-6 shrink-0 items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                <X className="size-3.5" />
              </button>
            </div>
            {findNotice ? (
              <div className="pointer-events-auto max-w-sm rounded-xl border border-border bg-card/95 px-3 py-1.5 text-[11px] text-muted-foreground shadow-md backdrop-blur">
                {findNotice}
              </div>
            ) : null}
          </>
        ) : (
          <button
            type="button"
            onClick={openFind}
            aria-label="Find in transcript"
            title="Find in transcript"
            className="lfg-scroll-pill pointer-events-auto flex items-center gap-1.5 rounded-full border border-border bg-card/95 px-2.5 py-1.5 text-xs font-medium text-foreground shadow-md backdrop-blur hover:bg-accent"
          >
            <Search className="size-3.5" />
          </button>
        )}
      </div>
    ) : null}
    {/* Floating jump-to-latest control: appears once the user scrolls away
        from the bottom. The wrapper is click-through so it never blocks taps
        on the messages beneath it. When the "files changed / Review" bar is up
        it owns the bottom slot, so the pill stacks directly above it instead of
        being covered by it. */}
    <div
      className={cn(
        "pointer-events-none absolute inset-x-0 z-10 flex justify-center transition-[bottom] duration-200 ease-out",
        diffBarVisible ? "bottom-14" : "bottom-3",
      )}
    >
      <button
        type="button"
        onClick={scrollToBottom}
        aria-hidden={stick}
        tabIndex={stick ? -1 : 0}
        aria-label="Scroll to latest"
        className={cn(
          "lfg-scroll-pill pointer-events-auto flex items-center gap-1.5 rounded-full border border-border bg-card/95 px-3 py-1.5 text-xs font-medium text-foreground shadow-md backdrop-blur",
          stick && "lfg-scroll-pill--hidden",
        )}
      >
        <ArrowDown className="size-3.5" />
        {busy ? <span>New activity</span> : null}
      </button>
    </div>
    {/* Floating "diffs for review" bar: appears when this session's worktree
        has changes; opens the pierre-style diff viewer. Not in a bot chat —
        reviewing a diff is work you do on a session, and the bot's own repo is
        not where its heavy work happens anyway. */}
    {bot ? null : <SessionDiffBar sid={sid} onVisibilityChange={setDiffBarVisible} />}
    </div>
  );
});

// Desktop: require a deliberate hover before opening command details so a
// quick mouse pass over tool chips doesn't flash the popover. Click still
// opens immediately. Close keeps a short grace so pill ↔ popup transit works.
const TOOL_GROUP_HOVER_OPEN_MS = 450;
const TOOL_GROUP_HOVER_CLOSE_MS = 120;
const ORGANIC_ACTIVITY_EXIT_MS = 450;

function useOrganicActivityPresence(active: boolean) {
  const [exiting, setExiting] = useState(false);
  const wasActiveRef = useRef(active);
  const exitTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Preserve the effect during the render where active first drops. The layout
  // effect below turns that one-frame derived state into a timed exit before
  // the browser paints, so there is no unmount/remount flash.
  const startsExit = !active && wasActiveRef.current;

  useLayoutEffect(() => {
    if (exitTimerRef.current) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }

    if (active) {
      wasActiveRef.current = true;
      setExiting(false);
      return;
    }
    if (!wasActiveRef.current) return;

    wasActiveRef.current = false;
    setExiting(true);
    exitTimerRef.current = setTimeout(() => {
      exitTimerRef.current = null;
      setExiting(false);
    }, ORGANIC_ACTIVITY_EXIT_MS);

    return () => {
      if (exitTimerRef.current) {
        clearTimeout(exitTimerRef.current);
        exitTimerRef.current = null;
      }
    };
  }, [active]);

  return {
    present: active || exiting || startsExit,
    exiting: !active && (exiting || startsExit),
  };
}

function OrganicActivityEffect({
  active,
  className,
}: {
  active: boolean;
  className: string;
}) {
  const filterId = `lfg-organic-activity-${useId().replace(/:/g, "")}`;
  const presence = useOrganicActivityPresence(active);
  if (!presence.present) return null;

  return (
    <>
      <svg
        width="0"
        height="0"
        className="absolute"
        aria-hidden="true"
        focusable="false"
      >
        <defs>
          <filter
            id={filterId}
            x="-24%"
            y="-35%"
            width="148%"
            height="170%"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.011 0.026"
              numOctaves="2"
              seed="11"
              result="activityNoise"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="activityNoise"
              scale="18"
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>
      </svg>
      <span
        className={cn(
          "lfg-organic-activity",
          className,
          presence.exiting ? "is-exiting" : "is-active",
        )}
        aria-hidden="true"
      >
        <span
          className="lfg-organic-activity-wash"
          style={{ filter: `url(#${filterId}) blur(5px)` }}
        />
        <span className="lfg-organic-activity-edge lfg-organic-activity-edge--halo" />
        <span className="lfg-organic-activity-edge lfg-organic-activity-edge--soft" />
        <span className="lfg-organic-activity-edge lfg-organic-activity-edge--sharp" />
      </span>
    </>
  );
}

// Memoized with a custom comparator instead of a bare `memo()`: `items` is
// rebuilt into a brand-new array every time buildChatRenderItems reruns (once
// per streamed token, for every tool group in the transcript, not just the
// one currently growing — see ChatStream's `items` useMemo), so a plain
// reference check on `items` would never bail. The Message objects inside it
// are stable for any group that isn't the live one (same reasoning as
// MessageBubble above), so compare contents instead of array identity.
const ToolGroup = memo(function ToolGroup({ items, live, sid }: { items: Message[]; live: boolean; sid?: string | null }) {
  const label = toolGroupLabel(items);
  const isMobile = useIsMobile();
  const [open, setOpen] = useState(false);
  // Arguments are not on the wire until a reader opens the pill. The label
  // above is built from the tool NAMES, which are, so the counter still ticks
  // up live during a run without any of this having resolved.
  const toolArgs = useDeferredToolArgs(sid, items, open);
  const openRef = useRef(open);
  openRef.current = open;
  const hoverOpenTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hoverCloseTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearHoverTimers = () => {
    if (hoverOpenTimer.current) {
      clearTimeout(hoverOpenTimer.current);
      hoverOpenTimer.current = null;
    }
    if (hoverCloseTimer.current) {
      clearTimeout(hoverCloseTimer.current);
      hoverCloseTimer.current = null;
    }
  };

  useEffect(() => () => clearHoverTimers(), []);

  // Pill enter: delay open so skimming the transcript doesn't trigger popovers.
  const scheduleHoverOpen = () => {
    if (isMobile) return;
    if (hoverCloseTimer.current) {
      clearTimeout(hoverCloseTimer.current);
      hoverCloseTimer.current = null;
    }
    if (openRef.current || hoverOpenTimer.current) return;
    hoverOpenTimer.current = setTimeout(() => {
      hoverOpenTimer.current = null;
      setOpen(true);
    }, TOOL_GROUP_HOVER_OPEN_MS);
  };

  // Popup enter (or re-enter while already open): cancel close, stay open.
  const keepHoverOpen = () => {
    if (isMobile) return;
    clearHoverTimers();
    setOpen(true);
  };

  const scheduleHoverClose = () => {
    if (isMobile) return;
    if (hoverOpenTimer.current) {
      clearTimeout(hoverOpenTimer.current);
      hoverOpenTimer.current = null;
    }
    hoverCloseTimer.current = setTimeout(() => setOpen(false), TOOL_GROUP_HOVER_CLOSE_MS);
  };

  const toggleOpen = () => {
    clearHoverTimers();
    setOpen((value) => !value);
  };

  const handleOpenChange = (next: boolean) => {
    clearHoverTimers();
    setOpen(next);
  };

  const details = (
    <div className="space-y-3">
      {items.map((item, index) => {
        const isUse = item.kind === "tool_use";
        const isThought = item.kind === "thinking";
        // Thinking folded in from between the calls (see buildChatRenderItems).
        // Prose, not a command, so it is not set in mono and keeps no colon
        // split — the whole message is the body.
        if (isThought) {
          return (
            <div key={item.id ?? `thinking-${item.ts}-${index}`} className="min-w-0">
              <div className="mb-1 flex items-center gap-2 text-xs font-semibold text-foreground">
                <span className="size-1.5 rounded-full bg-muted-foreground/60" />
                <span className="truncate">Thought</span>
              </div>
              <div className="max-h-52 overflow-auto whitespace-pre-wrap break-words rounded-xl bg-muted/60 p-2.5 text-[11px] leading-relaxed text-muted-foreground">
                {item.text || "thinking..."}
              </div>
            </div>
          );
        }
        const text = item.text || (isUse ? "No command details" : "No result details");
        const separator = isUse ? text.indexOf(":") : -1;
        const title = isUse
          ? (separator >= 0 ? text.slice(0, separator) : text) || "Command"
          : `Result${items.filter((entry) => entry.kind === "tool_result").length > 1 ? ` ${index + 1}` : ""}`;
        const inlineBody = isUse && separator >= 0 ? text.slice(separator + 1).trim() : isUse ? "" : text;
        // A deferred call has no inline arguments at all: the server sent the
        // name only. Whatever the fetch has reached is the body instead.
        const deferred = isDeferredToolUse(item) ? toolArgs[item.id!] : undefined;
        const body = deferred?.status === "ready" ? deferred.args : inlineBody;
        return (
          <div key={item.id ?? `${item.kind}-${item.ts}-${index}`} className="min-w-0">
            <div className="mb-1 flex items-center gap-2 text-xs font-semibold text-foreground">
              <span className={cn("size-1.5 rounded-full", isUse ? "bg-primary" : "bg-muted-foreground/60")} />
              <span className="truncate font-mono">{title}</span>
            </div>
            {deferred?.status === "loading" ? (
              <div
                className="rounded-xl bg-muted/60 p-2.5 text-[11px] leading-relaxed text-muted-foreground"
                role="status"
                data-testid="tool-args-loading"
              >
                Loading command details...
              </div>
            ) : deferred?.status === "error" ? (
              <div
                className="rounded-xl bg-destructive/10 p-2.5 text-[11px] leading-relaxed text-destructive"
                role="alert"
                data-testid="tool-args-error"
              >
                {deferred.error}
              </div>
            ) : body ? (
              <pre className="max-h-52 overflow-auto whitespace-pre-wrap break-words rounded-xl bg-muted/60 p-2.5 font-mono text-[11px] leading-relaxed text-muted-foreground">
                {body}
              </pre>
            ) : null}
          </div>
        );
      })}
    </div>
  );

  const pill = (
    <button
      type="button"
      className={cn(
        "tool-call-row not-prose flex w-fit max-w-full cursor-pointer items-center gap-2 rounded-full px-2.5 py-1 text-left text-xs text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
        live && "tool-call-row--live text-foreground",
      )}
      aria-label={`${live ? "Running" : "Completed"} tool call${items.length === 1 ? "" : "s"}: ${label}. Show details`}
      aria-haspopup="dialog"
      aria-expanded={open}
      onClick={toggleOpen}
      onMouseEnter={scheduleHoverOpen}
      onMouseLeave={scheduleHoverClose}
    >
      <OrganicActivityEffect active={live} className="tool-call-organic" />
      <span
        className={cn(
          "relative z-[1] size-1.5 shrink-0 rounded-full bg-muted-foreground/55",
          live && "animate-pulse bg-foreground",
        )}
        aria-hidden="true"
      />
      <span className="relative z-[1] truncate font-mono">{label}</span>
    </button>
  );

  if (isMobile) {
    return (
      <div className="w-fit max-w-full">
        {pill}
        <VaulDrawer.Root open={open} onOpenChange={handleOpenChange} repositionInputs={false} shouldScaleBackground={false}>
          <VaulDrawer.Portal>
            <VaulDrawer.Overlay className="fixed inset-0 z-[149] bg-black/80" />
            <VaulDrawer.Content className="fixed inset-x-0 bottom-0 z-[150] mx-auto flex max-h-[82dvh] max-w-lg flex-col rounded-t-[2rem] border border-border bg-background p-4 pb-[max(var(--lfg-safe-bottom),1rem)] text-foreground shadow-2xl outline-none">
              <div className="mx-auto mb-3 h-1.5 w-24 shrink-0 rounded-full bg-muted" />
              <VaulDrawer.Title className="mb-3 text-base font-semibold">Command details</VaulDrawer.Title>
              <div className="min-h-0 overflow-y-auto">{details}</div>
            </VaulDrawer.Content>
          </VaulDrawer.Portal>
        </VaulDrawer.Root>
      </div>
    );
  }

  return (
    <Popover.Root open={open} onOpenChange={handleOpenChange}>
      <Popover.Trigger render={pill} />
      <Popover.Portal>
        <Popover.Positioner side="top" align="start" sideOffset={7} className="isolate z-[170] outline-none">
          <Popover.Popup
            onMouseEnter={keepHoverOpen}
            onMouseLeave={scheduleHoverClose}
            className="w-[min(28rem,calc(100vw-1rem))] rounded-2xl border border-border bg-popover p-3 text-popover-foreground shadow-2xl ring-1 ring-foreground/5 outline-none"
          >
            <div className="mb-2 text-xs font-semibold text-muted-foreground">Command details</div>
            {details}
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );
}, (prev, next) =>
  prev.live === next.live &&
  prev.items.length === next.items.length &&
  prev.items.every((message, index) => message === next.items[index]),
);

/**
 * The wait state.
 *
 * In a session chat this is the usual three dots. In a bot chat it is the bot
 * itself: a named creature you are talking to already has a face and a working
 * pose, so an anonymous pill standing in for it is a worse answer to "what is
 * happening" than just showing it at work.
 *
 * This is the *only* place the creature appears in the stream. A face beside
 * every reply read as a column of different speakers, and reserving the gutter
 * for it indented every bot message whether or not that message carried one.
 * The header already says who you are talking to; down here the avatar earns
 * its space only while there is something happening, so it is drawn bigger.
 */
function TypingIndicator({ visible = true, bot }: { visible?: boolean; bot?: PersistentBot }) {
  return (
    <div
      className={cn("typing-indicator-slot", visible && "is-visible")}
      aria-hidden={!visible}
    >
      {bot ? (
        <div className="typing-mascot" role="status" aria-label={`${bot.name} is working`}>
          <BotAvatar bot={bot} working size={40} />
        </div>
      ) : (
        <div className="typing-indicator" role="status" aria-label="Assistant is typing">
          <span aria-hidden="true" />
          <span aria-hidden="true" />
          <span aria-hidden="true" />
        </div>
      )}
    </div>
  );
}

/**
 * What a user turn should actually show: the typed text, plus the attachments
 * lifted out of the trailing "Attached file(s):" block.
 *
 * The message keeps its raw form everywhere it matters (copy, search, what the
 * agent received) — this only changes what gets painted.
 */
function renderableUserContent(
  text: string,
  html?: string,
): { html: string; attachments: MessageAttachment[] } {
  const parsed = parseMessageAttachments(text);
  if (!parsed.attachments.length) return { html: html || escapeHtml(text), attachments: [] };
  // Re-derive the HTML from the trimmed body: any pre-rendered `html` still
  // has the upload paths baked into it.
  return {
    html: escapeHtml(parsed.body).replace(/\n/g, "<br>"),
    attachments: parsed.attachments,
  };
}

// A named chip: the representation for an attachment with nothing to show
// inline — a PDF, or an image whose bytes are gone (uploads live in tmpdir,
// which a reboot clears). Still better than the raw path it replaces.
function UserAttachmentChip({ name }: { name: string }) {
  return (
    <span className="user-attachment-file" title={name}>
      <Paperclip className="size-3.5 shrink-0" />
      <span className="min-w-0 truncate">{name}</span>
    </span>
  );
}

/**
 * The files a user attached, as their own view above the text bubble.
 *
 * Deliberately not inside the bubble: an image isn't a run of text with a
 * background, and boxing it in bubble chrome made the caption and the picture
 * read as one cramped card. Sent media gets its own frame and the words get
 * theirs, the way every messaging client does it.
 */
function UserAttachments({
  attachments,
  pending,
}: {
  attachments: MessageAttachment[];
  pending?: boolean;
}) {
  return (
    <div className={cn("user-attachments", pending && "is-pending")}>
      {attachments.map((att) =>
        att.url ? (
          <AuthenticatedArtifactImage
            key={att.path}
            path={att.url}
            alt={att.name}
            zoomable
            fallback={<UserAttachmentChip name={att.name} />}
            className="user-attachment-image"
          />
        ) : (
          <UserAttachmentChip key={att.path} name={att.name} />
        ),
      )}
    </div>
  );
}

// A user turn's text bubble. When the content runs longer than the collapsed
// clamp (~10 lines) it's truncated with a small "Show more" / "Show less"
// toggle at the end. Content is injected HTML (pre-escaped user text), so the
// clamp lives on an inner wrapper and the toggle sits beside it in the bubble.
function UserBubble({
  html,
  pending,
  queued,
  failed,
  otherAuthor,
}: {
  html: string;
  pending?: boolean;
  queued?: boolean;
  failed?: boolean;
  // Someone else's turn in a shared bot conversation, not the viewer's own —
  // see OtherHumanMessageBubble. Same shape, a different tint (is-other in
  // index.css) so the two remain visually distinct at a glance.
  otherAuthor?: boolean;
}) {
  const [expanded, setExpanded] = useState(false);
  const [overflowing, setOverflowing] = useState(false);
  const bodyRef = useRef<HTMLDivElement>(null);

  // Only measure while collapsed: when clamped, scrollHeight exceeds
  // clientHeight iff content is being hidden. While expanded the clamp is off
  // so the two are equal — skip so the toggle keeps showing "Show less".
  useLayoutEffect(() => {
    if (expanded) return;
    const el = bodyRef.current;
    if (!el) return;
    const check = () => setOverflowing(el.scrollHeight - el.clientHeight > 1);
    check();
    const ro = new ResizeObserver(check);
    ro.observe(el);
    return () => ro.disconnect();
  }, [html, expanded]);

  return (
    <MessageContent
      className={cn(
        // MessageContent's own base classes include text-sm; since it and
        // .msg-text.markdown's font-size both land on this same element,
        // Tailwind's utilities layer beats our @layer components rule
        // regardless of selector specificity, so text-sm silently won and
        // sent bubbles rendered a size smaller than assistant replies.
        // text-base is also a utility, so it cleanly out-conflicts text-sm
        // via the same layer instead of fighting it on specificity.
        // Width cap lives on MessageActions (definite parent); bubble just
        // hugs content up to that cap so multi-line turns stay right-aligned.
        "msg-text markdown user-bubble text-base w-fit max-w-full",
        pending && !queued && "is-pending",
        queued && "is-queued",
        failed && "is-failed",
        otherAuthor && "is-other",
      )}
    >
      {/* The organic shimmer means "in flight". A queued turn is deliberately
          still — nothing is happening to it until the current turn ends. */}
      <OrganicActivityEffect active={!!pending && !queued} className="user-bubble-organic" />
      <div
        ref={bodyRef}
        className={cn(
          "user-bubble-body relative z-[1]",
          !expanded && "user-bubble-clamp",
        )}
        dangerouslySetInnerHTML={{ __html: html }}
      />
      {overflowing && (
        <button
          type="button"
          className="user-bubble-toggle relative z-[1]"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
        >
          {expanded ? "Show less" : "Show more"}
        </button>
      )}
    </MessageContent>
  );
}

// LFG's launch contract travels inside the first user turn because several
// agent CLIs have no separate system-prompt channel. Keep it available for
// inspection without making the user read through it to find their own task.
function OmgInstructionsBlock({
  instructions,
  version,
}: {
  instructions: string;
  version: string | null;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="flex max-w-[85%] flex-col items-end">
      <button
        type="button"
        className="flex items-center gap-1.5 rounded-lg border border-border/70 bg-muted/45 px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
        onClick={() => setOpen((value) => !value)}
        aria-expanded={open}
      >
        <ScrollText className="size-3.5" aria-hidden="true" />
        <span>omg.dev instructions</span>
        {version ? <span className="font-mono opacity-60">{version}</span> : null}
        <ChevronRight
          className={cn("size-3 transition-transform", open && "rotate-90")}
          aria-hidden="true"
        />
      </button>
      {open ? (
        <pre className="mt-1 max-h-72 w-[min(42rem,85vw)] max-w-full overflow-auto whitespace-pre-wrap rounded-xl border border-border/70 bg-muted/30 p-3 text-left font-mono text-[11px] leading-relaxed text-muted-foreground">
          {instructions}
        </pre>
      ) : null}
    </div>
  );
}

async function copyMessageText(text: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  // Older WebViews and non-secure local origins may not expose Clipboard API.
  const field = document.createElement("textarea");
  field.value = text;
  field.setAttribute("readonly", "");
  field.style.cssText = "position:fixed;left:-9999px;top:0";
  document.body.appendChild(field);
  field.select();
  const copied = document.execCommand("copy");
  field.remove();
  if (!copied) throw new Error("Clipboard unavailable");
}

function MessageActions({
  text,
  isUser,
  children,
}: {
  text: string;
  isUser: boolean;
  children: ReactNode;
}) {
  const contentRef = useRef<HTMLDivElement>(null);
  const [selecting, setSelecting] = useState(false);
  const [copied, setCopied] = useState(false);

  const copy = useCallback(async () => {
    if (!text) return;
    try {
      await copyMessageText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
      toast("Message copied");
      haptic("success");
    } catch {
      toast.error("Couldn’t copy message");
    }
  }, [text]);

  useEffect(() => {
    const onSelectionChange = () => {
      const selection = window.getSelection();
      const content = contentRef.current;
      const selectionTouchesMessage = Boolean(
        selection &&
          !selection.isCollapsed &&
          content &&
          selection.anchorNode &&
          selection.focusNode &&
          (content.contains(selection.anchorNode) || content.contains(selection.focusNode)),
      );
      setSelecting(selectionTouchesMessage);
    };
    document.addEventListener("selectionchange", onSelectionChange);
    return () => document.removeEventListener("selectionchange", onSelectionChange);
  }, []);

  return (
    <div
      className={cn(
        // Cap width on this direct child of Message (which has a definite
        // w-full). Nested max-w-[85%] on the bubble used to resolve against a
        // content-sized ancestor after MessageActions was introduced, so the
        // percentage collapsed and long user turns grew full-width / looked
        // left-aligned. Short turns still hug the trailing edge via items-end
        // + Message's justify-end.
        //
        // relative: the copy button below is absolutely positioned against
        // this box, so it never adds a row of its own to the transcript. That
        // out-of-flow button sits in the 2.25rem gutter beside the bubble
        // (1.75rem button + 0.25rem offset + 0.25rem slack), so the cap also
        // subtracts that gutter from the row: without it a bubble at the
        // percentage cap would push the button past the scroll container and
        // trade a vertical gap for a horizontal one. The percentage still
        // wins on wide viewports, where it is the smaller of the two.
        "message-actions-wrap relative flex min-w-0 flex-col",
        isUser
          ? "max-w-[min(85%,calc(100%-2.25rem))] items-end"
          : "max-w-[min(92%,calc(100%-2.25rem))] items-start",
        selecting && "is-selecting",
      )}
    >
      <div ref={contentRef} className="min-w-0 max-w-full">
        {children}
      </div>
      {text ? (
        <button
          type="button"
          onClick={() => void copy()}
          // Absolute, bottom-aligned in the gutter beside the bubble: in flow
          // (the old `mt-1` block) it reserved a full 28px row under every
          // single turn, so two replies in a row sat ~36px apart and the
          // transcript's vertical rhythm read as a stray empty band whenever
          // hover revealed the icon. Out of flow it stays attached to its own
          // message, costs no height, and — because it is never added or
          // removed on hover — shifts nothing when it appears.
          className={cn(
            "message-copy-button absolute bottom-0 flex size-7 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:text-foreground focus-visible:outline-none",
            isUser ? "right-full mr-1" : "left-full ml-1",
          )}
          aria-label={copied ? "Message copied" : "Copy message"}
          title={copied ? "Copied" : "Copy message"}
        >
          {copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
        </button>
      ) : null}
    </div>
  );
}

// Memoized: ChatStream recomputes `items` from a fresh `visibleMessages` array
// on every streamed token (see its useMemo above), even though only the one
// live-streaming message actually changed text. Message objects for anything
// else in the transcript keep the same reference across that recompute (the
// live-update reducers only replace the object matching the incoming
// id — see the `ai_part`/message handlers), so a shallow prop comparison
// correctly skips re-rendering every settled bubble on every token instead of
// re-running all of them for a change that touched exactly one.
const MessageBubble = memo(function MessageBubble({
  message,
  live = false,
  entering = false,
  onRetryQueued,
  bot,
  conversation,
  firstOfRun,
  lastOfRun,
}: {
  message: Message;
  // Whether the session is actively working on THIS turn — drives the thinking
  // shimmer so historical reasoning renders static instead of forever "Thinking...".
  live?: boolean;
  // First appearance of a settled assistant turn while live — plays a one-shot
  // entrance so the draft→final swap doesn't flash.
  entering?: boolean;
  // Retry a failed queue send through the server queue's retry endpoint.
  onRetryQueued?: (message: Message) => void;
  bot?: PersistentBot;
  conversation?: ProductConversation | null;
  // Same-speaker run edges from ChatStream. Only OtherHumanMessageBubble
  // reads these; own-turn and bot replies ignore them.
  firstOfRun?: boolean;
  lastOfRun?: boolean;
}) {
  const openArtifact = useContext(ArtifactViewerContext);
  const viewerParticipantId = useContext(ViewerIdentityContext);
  // A group-chat-style human turn: authored by someone other than the current
  // viewer, per the server-verified MessageAuthorRef — never inferred from the
  // bot's owner/creator, the current bot, or anything client-supplied. A
  // historical turn with no verified author (message.author is undefined or
  // `legacy`) falls through to the unchanged "own" rendering below rather than
  // guessing whose it was.
  const otherHumanSender =
    message.role === "user" && isOtherHumanMessageAuthor(message.author, viewerParticipantId)
      ? (conversationParticipantById(conversation, message.author!.participantId) ??
        unknownConversationParticipant(message.author!.participantId))
      : null;
  // Must run before the early returns below — hooks can't be conditional. The
  // effect itself no-ops for anything that isn't a just-sent user turn.
  const sendMorphRef = useSendMorph<HTMLDivElement>(
    message.role === "user" && !!message.pending,
  );
  const omgEnvelope = useMemo(
    () => (message.role === "user" ? parseOmgPromptEnvelope(message.text || "") : null),
    [message.role, message.text],
  );
  // Attachments ride along in the user's text as absolute upload paths (the
  // agent needs them); split them back out so the bubble shows the images.
  const userContent = useMemo(
    () =>
      message.role === "user"
        ? renderableUserContent(
            botVisibleUserText(omgEnvelope?.task ?? message.text ?? "", bot),
            omgEnvelope || bot ? undefined : message.html,
          )
        : { html: "", attachments: [] as MessageAttachment[] },
    [message.role, message.text, message.html, omgEnvelope, bot],
  );
  if (isRequestInterruptedMessage(message)) {
    return (
      <div
        role="status"
        aria-label="Request interrupted"
        className="flex w-full items-center justify-center py-0.5 text-[11px] text-muted-foreground/60"
      >
        Interrupted
      </div>
    );
  }
  if (message.kind === "thinking") {
    return (
      <AiMessage className="msg" from="assistant">
        <MessageContent>
          <Reasoning isStreaming={live}>
            <ReasoningTrigger isStreaming={live} />
            <ReasoningContent>{message.text || "thinking..."}</ReasoningContent>
          </Reasoning>
        </MessageContent>
      </AiMessage>
    );
  }

  if (message.kind === "html" && message.url) {
    const label = message.title || message.caption || message.text || message.name || "Artifact";
    return (
      <AiMessage className={cn("msg", entering && "lfg-msg-in")} from="assistant">
        <MessageContent className="not-prose w-full max-w-[min(42rem,92vw)] overflow-hidden rounded-lg border border-border bg-card p-0 shadow-sm">
          <div className="flex items-center justify-between gap-3 border-b border-border px-3 py-2 text-xs">
            <button
              type="button"
              onClick={() =>
                openArtifact({
                  url: message.url!,
                  kind: "html",
                  title: message.title,
                  caption: message.caption,
                  name: message.name,
                  version: message.version,
                  cacheKey: message.ts,
                })
              }
              className="flex min-w-0 items-center gap-2 font-medium transition-colors hover:text-foreground"
            >
              <LayoutDashboard className="size-3.5 shrink-0 text-muted-foreground" />
              <span className="min-w-0 truncate">{label}</span>
            </button>
            <span className="flex shrink-0 items-center gap-2 text-muted-foreground">
              {(message.version ?? 1) > 1 ? (
                <span className="flex items-center gap-1 rounded-full bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-medium text-emerald-600 dark:text-emerald-400">
                  <span className="size-1.5 animate-pulse rounded-full bg-emerald-500" />
                  live · v{message.version}
                </span>
              ) : null}
              <button
                type="button"
                onClick={() =>
                  openArtifact({
                    url: message.url!,
                    kind: "html",
                    title: message.title,
                    caption: message.caption,
                    name: message.name,
                    version: message.version,
                    cacheKey: message.ts,
                  })
                }
                aria-label="Open artifact full screen"
                className="transition-colors hover:text-foreground"
              >
                <Maximize2 className="size-3.5" />
              </button>
            </span>
          </div>
          {/* Rendered natively into a shadow root — see lib/native-artifact.ts.
              Height is the document's real layout height, so the transcript no
              longer animates a guessed box toward a postMessaged number. */}
          <NativeArtifactEmbed
            path={message.url}
            cacheKey={message.ts ?? message.version ?? 0}
            title={label}
            maxHeight={560}
            className="px-3 pb-2"
          />
          {message.caption && message.caption !== label ? (
            <div className="border-t border-border px-3 py-2 text-xs text-muted-foreground">
              {message.caption}
            </div>
          ) : null}
        </MessageContent>
      </AiMessage>
    );
  }

  if ((message.kind === "image" || message.kind === "video") && message.url) {
    const isVideo = message.kind === "video";
    const label =
      message.caption || message.text || message.name || (isVideo ? "Video" : "Image");
    return (
      <AiMessage className={cn("msg", entering && "lfg-msg-in")} from="assistant">
        <MessageContent className="not-prose inline-flex w-fit max-w-[min(34rem,92vw)] flex-col items-start overflow-hidden rounded-lg border border-border bg-card p-0 shadow-sm">
          {/* Media renders inline in-app — no navigation away to the raw URL. */}
          {isVideo ? (
            <AuthenticatedArtifactVideo
              path={message.url}
              label={message.alt || label}
              className="block max-h-[24rem] w-auto max-w-full self-center bg-black object-contain"
            />
          ) : (
            <AuthenticatedArtifactImage
              path={message.url}
              alt={message.alt || label}
              width={message.width}
              height={message.height}
              zoomable
              className="block max-h-[24rem] w-auto max-w-full self-center bg-muted object-contain"
            />
          )}
          {/* w-0 + min-w-full keeps long captions from participating in the
              shrink-to-fit width calculation. The rendered media owns the
              card width; this row then conforms to it and truncates. */}
          <div className="box-border flex w-0 min-w-full items-center justify-between gap-3 px-3 py-2 text-xs text-muted-foreground">
            <span className="min-w-0 truncate">{label}</span>
            {message.size ? <span className="shrink-0">{formatBytes(message.size)}</span> : null}
          </div>
        </MessageContent>
      </AiMessage>
    );
  }

  if (otherHumanSender) {
    return (
      <OtherHumanMessageBubble
        message={message}
        html={userContent.html}
        attachments={userContent.attachments}
        participant={otherHumanSender}
        entering={entering}
        firstOfRun={firstOfRun}
        lastOfRun={lastOfRun}
      />
    );
  }
  const isUser = message.role === "user";
  if (isUser) {
    const queued = !!message.queued && !!message.pending;
    const failed = !!message.failed;
    return (
      <AiMessage
        ref={sendMorphRef}
        className={cn("msg", entering && "lfg-msg-in", message.pending && "lfg-user-send")}
        from="user"
      >
        {/* w-full keeps each 85% cap resolving against a definite width. The
            launch contract is visually separate from the user's actual task. */}
        <div className="flex w-full min-w-0 flex-col items-end gap-1.5">
          {omgEnvelope ? (
            <OmgInstructionsBlock
              instructions={omgEnvelope.instructions}
              version={omgEnvelope.version}
            />
          ) : null}
          {/* A queued turn hasn't reached the agent, so it must not look like a
              turn that has. The label states what the bubble's muted, dashed
              styling implies, and disappears the moment the real transcript row
              replaces this optimistic one. */}
          {queued ? (
            <span className="user-queued-label" role="status">
              <Clock3 className="size-3" aria-hidden="true" />
              Queued · sends when this turn ends
            </span>
          ) : null}
          {/* A failed send never reached the agent at all. Keep it visible with
              the delivery error and offer retry through the queue's retry
              endpoint — disappearing here would silently drop the user's words. */}
          {failed ? (
            <span className="user-failed-label" role="alert">
              <TriangleAlert className="size-3" aria-hidden="true" />
              <span className="min-w-0">
                Failed to send{message.queueError ? ` — ${message.queueError}` : ""}
              </span>
              {message.queueId && onRetryQueued ? (
                <button
                  type="button"
                  className="user-failed-retry"
                  onClick={() => onRetryQueued(message)}
                >
                  <RotateCcw className="size-3" aria-hidden="true" />
                  Retry
                </button>
              ) : null}
            </span>
          ) : null}
          {userContent.attachments.length > 0 ? (
            <UserAttachments attachments={userContent.attachments} pending={message.pending} />
          ) : null}
          {/* A caption is optional: attach an image with nothing typed and the
              picture is the whole message, with no empty bubble under it. */}
          {userContent.html ? (
            <MessageActions text={botVisibleUserText(omgEnvelope?.task ?? message.text ?? "", bot)} isUser>
              <UserBubble html={userContent.html} pending={message.pending} queued={queued} failed={failed} />
            </MessageActions>
          ) : null}
        </div>
      </AiMessage>
    );
  }
  // A bot's turn reads as somebody talking, so it gets a bubble instead of bare
  // markdown on the canvas (spec §4.2). Only turns that have said something:
  // an empty one is the typing state, which is already the creature at work and
  // would otherwise put a second creature inside a bubble beside the first.
  const botBubble = !!bot && !!message.text;
  const body = (
    <MessageActions text={message.text || ""} isUser={false}>
        {/* Assistant turns render markdown from the raw source via Streamdown,
            which tolerates half-finished markdown mid-stream (no html injection). */}
        {/* max-w-full, not MessageContent's default 92% (or a second, tighter
            percentage for the bot bubble): the cap already lives on
            MessageActions, whose content div is content-sized (flex-col +
            items-start). A second percentage here resolves against that
            shrink-to-fit width, i.e. N% of the text's own max-content width,
            so any reply that would fit on one line gets pushed onto a second
            line — "Hi Benny!" wrapped to "Hi" / "Benny!", and a single short
            word like "Waiting." wrapped mid-word ("Waiti" / "ng."). Long
            replies hit the available width first and hid this until bots
            started replying in one-liners. A bot bubble still reads narrower
            than a full-width row because MessageActions already caps
            non-user turns at 92% — this doesn't need its own tighter cap on
            top of that one. */}
      <MessageContent
        className={cn(
          "max-w-full",
          // The card row shell every surface in the app uses, with a taller
          // corner so it reads as a chat bubble rather than a list row.
          botBubble && "rounded-[18px] border border-border bg-card px-3.5 py-2.5 text-[14.5px] leading-[1.55]",
        )}
      >
        {message.text ? (
          <MessageResponse
            animated={STREAMING_RESPONSE_ANIMATION}
            isAnimating={isDraftAssistantMessage(message) && !message.catchUp}
            mode={isDraftAssistantMessage(message) ? "streaming" : "static"}
          >
            {message.text}
          </MessageResponse>
        ) : (
          <TypingIndicator bot={bot} />
        )}
      </MessageContent>
    </MessageActions>
  );
  return (
    <AiMessage
      ref={sendMorphRef}
      className={cn(
        "msg",
        entering && "lfg-msg-in",
        // A just-sent (optimistic) user turn springs up out of the composer.
        // useSendMorph measures the real composer position and drives this via
        // WAAPI; the class is the fallback for reduced-motion and for the case
        // where the composer can't be found (it only sets the origin + a static
        // entrance, so the two never double up).
        isUser && message.pending && "lfg-user-send",
      )}
      from="assistant"
    >
      {body}
    </AiMessage>
  );
});

/**
 * A round face for one human conversation participant — the same visual
 * language as the header's (removed) participant row and the desktop card's
 * ConversationParticipantRow, so a sender reads consistently wherever their
 * face shows up. Falls back to their initial when there is no avatar, or the
 * avatar 404s (a deleted upload, a profile removed after the message was
 * sent): the fallback letter sits underneath the image the whole time, so a
 * broken <img> just uncovers it instead of leaving a blank circle.
 */
function HumanParticipantAvatar({
  participant,
  size = 20,
  className,
}: {
  participant: ConversationParticipant;
  size?: number;
  className?: string;
}) {
  const name = conversationParticipantDisplayName(participant);
  const initial = name.slice(0, 1).toUpperCase() || "M";
  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative grid shrink-0 place-items-center overflow-hidden rounded-full bg-primary/12 text-[10px] font-semibold text-primary",
        className,
      )}
      style={{ width: size, height: size }}
    >
      {initial}
      {participant.display.avatar ? (
        <img
          src={participant.display.avatar}
          alt=""
          className="absolute inset-0 size-full object-cover"
          onError={(event) => event.currentTarget.remove()}
        />
      ) : null}
    </span>
  );
}

/**
 * A human turn authored by someone other than the current viewer, in a shared
 * bot conversation — the "group chat inside a bot conversation" case (spec:
 * message-level sender avatars, never a header identity chip). Left-aligned
 * like an assistant turn so it never collides with the viewer's own
 * right-aligned turns, and carries its own name label + avatar so it can't be
 * mistaken for either "my message" or the bot's reply.
 *
 * The bubble reuses UserBubble (same clamp/attachments/pending affordances as
 * the viewer's own turns — this is still plain user prose, just not the
 * viewer's) with an `otherAuthor` tint so the two remain visually distinct at
 * a glance even though they share a shape.
 *
 * Consecutive beats from the same verified person share one caption: the
 * name on the first of the run, the face on the last (items-end, so a
 * multi-line run still pins the avatar to the bottom bubble). A single
 * message is both edges and still shows both. The aria-label keeps the
 * sender name on every bubble, including the ones that hide the visible
 * caption. Defaults keep both chrome when the caller has no siblings
 * (queued rows).
 */
function OtherHumanMessageBubble({
  message,
  html,
  attachments,
  participant,
  entering,
  firstOfRun = true,
  lastOfRun = true,
}: {
  message: Message;
  html: string;
  attachments: MessageAttachment[];
  participant: ConversationParticipant;
  entering?: boolean;
  firstOfRun?: boolean;
  lastOfRun?: boolean;
}) {
  const name = conversationParticipantDisplayName(participant);
  return (
    <AiMessage
      className={cn("msg", entering && "lfg-msg-in")}
      from="assistant"
      role="group"
      aria-label={`Message from ${name}`}
    >
      <div className="flex w-full min-w-0 items-end gap-2">
        {lastOfRun ? (
          <HumanParticipantAvatar participant={participant} size={22} className="mb-0.5" />
        ) : (
          <span aria-hidden="true" className="mb-0.5 size-[22px] shrink-0" />
        )}
        <div className="flex min-w-0 max-w-[calc(100%-1.75rem)] flex-col items-start gap-1">
          {firstOfRun ? (
            <span className="px-0.5 text-[11px] font-medium leading-none text-muted-foreground">{name}</span>
          ) : null}
          {attachments.length > 0 ? <UserAttachments attachments={attachments} /> : null}
          {html ? (
            <MessageActions text={message.text || ""} isUser={false}>
              <UserBubble html={html} otherAuthor />
            </MessageActions>
          ) : null}
        </div>
      </div>
    </AiMessage>
  );
}

function botVisibleUserText(text: string, bot?: PersistentBot): string {
  return botVisibleUserTextFor(text, !!bot);
}

function isBotRuntimeContractMessage(message: Message): boolean {
  return (
    (message.role === "user" || message.role === "system") &&
    isBotLaunchOnlyText(message.text ?? "")
  );
}

/**
 * A background task session reporting home. It arrives on the bot's session as
 * a user turn, so in a bot chat it would otherwise look like the human pasted
 * `[subagent complete] …` into their own conversation. The bot answers it in
 * plain words on the next turn; that reply is what the human reads.
 */
function isBotBackgroundUpdateMessage(message: Message): boolean {
  return (
    (message.role === "user" || message.role === "system") &&
    isSubagentUpdateText(message.text ?? "")
  );
}

function PromptPanel({
  prompt,
  sid,
  onError,
}: {
  prompt: SessionPrompt | null;
  sid: string | null;
  onError: (error: string | null) => void;
}) {
  // Selecting an option drives the tmux selector (arrow keys + Enter) and the
  // panel only clears on the next ~1s server poll. Without a lock the stale
  // options stay clickable, so a second click fires another /answer that
  // overshoots the (now different) selector — the "answer bricks" symptom.
  const sig = prompt
    ? `${prompt.question ?? ""}|${prompt.options.map((o) => o.label).join("|")}`
    : "";
  // `pending` holds the in-flight option index, or DISMISS while the skip (X)
  // request is in flight. Real option indices are positive, so -1 is a safe
  // sentinel that never collides with one.
  const DISMISS = -1;
  const [pending, setPending] = useState<number | null>(null);

  // Reset the lock whenever the prompt itself changes (answered → new / gone).
  useLayoutEffect(() => {
    setPending(null);
  }, [sig]);

  // Safety valve: if the prompt didn't clear (answer didn't land), re-enable so
  // the user can retry instead of being stuck on a dead panel.
  useEffect(() => {
    if (pending === null) return;
    const timer = setTimeout(() => setPending(null), 4000);
    return () => clearTimeout(timer);
  }, [pending]);

  if (!prompt || !sid) return null;
  const locked = pending !== null;
  return (
    <div className="prompt-panel border-t border-warning/25 bg-warning/12 px-3 py-2">
      <div className="mb-2 flex items-start justify-between gap-2">
        <div className="text-sm font-medium">{prompt.question ?? "Waiting for a choice"}</div>
        <Button
          type="button"
          variant="tint"
          size="icon-sm"
          className="-mr-1 shrink-0"
          disabled={locked}
          title="Skip this question without answering"
          aria-label="Dismiss question"
          onClick={async () => {
            setPending(DISMISS); // lock the panel while the skip is in flight
            onError(null);
            try {
              await api(`/api/sessions/${sid}/dismiss`, { method: "POST" });
            } catch (e) {
              onError(e instanceof Error ? e.message : String(e));
              setPending(null);
            }
          }}
        >
          {pending === DISMISS ? (
            <Loader2 className="size-3.5 animate-spin" />
          ) : (
            <X className="size-4" />
          )}
        </Button>
      </div>
      <div className="flex flex-wrap gap-2">
        {prompt.options.map((option) => (
          <Button
            key={option.index}
            type="button"
            variant={option.selected || pending === option.index ? "brand" : "secondary"}
            size="sm"
            className="h-auto min-h-8 max-w-full whitespace-normal py-1 text-left"
            disabled={locked}
            onClick={async () => {
              setPending(option.index);
              onError(null);
              try {
                await api(`/api/sessions/${sid}/answer`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ index: option.index }),
                });
              } catch (e) {
                onError(e instanceof Error ? e.message : String(e));
                setPending(null);
              }
            }}
          >
            {pending === option.index ? <Loader2 className="size-3.5 animate-spin" /> : null}
            {option.label}
          </Button>
        ))}
      </div>
    </div>
  );
}

// A closed/rebooted-away session that can be relaunched by its SDK backend.
export type ResumableSession = {
  sessionId: string;
  cwd: string | null;
  project: string;
  title: string;
  lastActivityAt: number | null;
  lastUserText: string | null;
  agent: "claude" | "codex" | "opencode" | "grok" | "cursor" | "fx";
  model?: string | null;
};

// Facet counts + total returned alongside the resumable roster so the picker can
// render agent/project filter chips with live counts (see /api/sessions/resumable).
type FolderBrowserPayload = {
  current: string;
  parent: string | null;
  isGitRepo: boolean;
  // isEmpty is optional so an older/proxied backend that doesn't send it just
  // renders no badge instead of claiming every folder has contents.
  directories: { name: string; path: string; isGitRepo: boolean; isEmpty?: boolean }[];
};

// What POST /api/projects/delete-folder reports back when called WITHOUT
// confirm — a dry run describing everything the delete would destroy.
type FolderDeletePlan = {
  path: string;
  name: string;
  empty: boolean;
  entryCount: number;
  entries: string[];
  isGitRepo: boolean;
  gitDirty: boolean;
  looksUnused: boolean;
  warnings: string[];
};

/**
 * Confirmation for deleting a project folder off disk.
 *
 * Opens straight into a dry run so the user is shown what is actually inside
 * before the destructive button appears. Abandoned scaffolding — an empty
 * folder, or a "New Project" shell that never got past its starter README —
 * gets a plain one-tap confirm, because burying the common case behind a scary
 * warning is what trains people to click through the scary warning. Anything
 * with real content gets the contents listed and a destructive-styled button.
 *
 * Rendered inline inside the picker rather than as a nested modal: the picker
 * is already a vaul Drawer, and stacking a second overlay on top of it fights
 * the drawer's focus trap on mobile for no UX gain.
 */
function DeleteFolderPanel({
  target,
  onClose,
  onDeleted,
}: {
  target: { path: string; name: string };
  onClose: () => void;
  onDeleted: (path: string) => void | Promise<void>;
}) {
  const [plan, setPlan] = useState<FolderDeletePlan | null>(null);
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const targetPath = target.path;

  useEffect(() => {
    setPlan(null);
    setError(null);
    setLoading(true);
    let cancelled = false;
    void (async () => {
      try {
        const res = await api<{ plan: FolderDeletePlan }>("/api/projects/delete-folder", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ path: targetPath }),
        });
        if (!cancelled) setPlan(res.plan);
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : "Couldn't inspect this folder");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [targetPath]);

  async function confirmDelete() {
    setDeleting(true);
    setError(null);
    try {
      await api("/api/projects/delete-folder", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: targetPath, confirm: true }),
      });
      toast.success(`Deleted ${target.name}`);
      await onDeleted(targetPath);
      onClose();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't delete this folder");
    } finally {
      setDeleting(false);
    }
  }

  const safe = plan?.looksUnused === true;

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto">
        <div>
          <h3 className="text-base font-semibold">Delete “{target.name}”?</h3>
          <p className="break-all text-xs text-muted-foreground">{targetPath}</p>
        </div>

        {loading ? (
          <div className="flex items-center gap-2 py-3 text-sm text-muted-foreground">
            <Loader2 className="size-4 animate-spin" /> Checking what’s inside…
          </div>
        ) : null}

        {plan && safe ? (
          <p className="text-sm text-muted-foreground">
            {plan.empty
              ? "This folder is empty."
              : "Nothing in here but an unused starter project."}{" "}
            Deleting it can’t be undone.
          </p>
        ) : null}

        {plan && !safe ? (
          <div className="space-y-2.5 rounded-xl border border-destructive/30 bg-destructive/5 p-3">
            <p className="flex items-center gap-2 text-sm font-semibold text-destructive">
              <TriangleAlert className="size-4 shrink-0" /> This folder has files in it
            </p>
            <ul className="space-y-1 text-xs text-muted-foreground">
              {plan.warnings.map((warning) => (
                <li key={warning}>• {warning}</li>
              ))}
            </ul>
            {plan.entries.length > 0 ? (
              <p className="break-words text-xs text-muted-foreground">
                <span className="font-medium text-foreground">Contains:</span>{" "}
                {plan.entries.join(", ")}
                {plan.entryCount > plan.entries.length
                  ? ` +${plan.entryCount - plan.entries.length} more`
                  : ""}
              </p>
            ) : null}
            <p className="text-xs text-muted-foreground">
              Everything above is permanently deleted. This can’t be undone.
            </p>
          </div>
        ) : null}

        {error ? <p className="text-sm text-destructive">{error}</p> : null}
      </div>

      <div className="mt-3 grid grid-cols-2 gap-2">
        <Button type="button" variant="outline" onClick={onClose} disabled={deleting}>
          Cancel
        </Button>
        <Button
          type="button"
          variant="destructive"
          disabled={!plan || deleting}
          onClick={() => void confirmDelete()}
        >
          {deleting ? <Loader2 className="size-4 animate-spin" /> : <Trash2 className="size-4" />}
          {deleting ? "Deleting…" : safe ? "Delete" : "Delete anyway"}
        </Button>
      </div>
    </div>
  );
}

function ProjectFolderBrowser({
  open,
  initialPath,
  startCreating = false,
  onOpenChange,
  onSelected,
  onReposChanged,
  onUnavailablePath,
}: {
  open: boolean;
  initialPath?: string;
  startCreating?: boolean;
  onOpenChange: (open: boolean) => void;
  onSelected: (project: Repo) => void | Promise<void>;
  /** Deleting a folder can retire a pinned project, so the picker's repo list
   *  has to be refetched — the browser itself doesn't own that state. Takes the
   *  deleted path so callers holding a local list can drop the row without a
   *  round trip; callers that refetch can ignore it. */
  onReposChanged?: (deletedPath: string) => void | Promise<void>;
  /** Clear an in-memory selection that still names a path which disappeared. */
  onUnavailablePath?: (path: string) => void;
}) {
  const [browser, setBrowser] = useState<FolderBrowserPayload | null>(null);
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [folderName, setFolderName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ path: string; name: string } | null>(null);
  const onUnavailablePathRef = useRef(onUnavailablePath);
  useEffect(() => {
    onUnavailablePathRef.current = onUnavailablePath;
  }, [onUnavailablePath]);

  // `browser?.directories` only guards the null payload, not a payload that
  // came back without the list (an error envelope, an older/proxied backend, a
  // 200 with an empty body). Reading `.map` off that undefined throws during
  // render, and since App is the ROOT route component the whole app lands in
  // the router crash boundary over a folder list. Default to empty instead.
  const directories = browser?.directories ?? [];

  const browse = useCallback(async (path?: string) => {
    setLoading(true);
    setError(null);
    setNotice(null);
    // Never leave the previous path actionable while the server is deciding
    // whether the requested path still exists.
    setBrowser(null);
    try {
      const result = await browseFolderWithRecovery(path, async (candidate) => {
        const query = candidate ? `?path=${encodeURIComponent(candidate)}` : "";
        return api<FolderBrowserPayload>(`/api/filesystem/directories${query}`);
      });
      setBrowser(result.payload);
      if (result.unavailablePath && result.recoveryLocation) {
        if (localStorage.getItem("lfg_v2_repo") === result.unavailablePath) {
          localStorage.removeItem("lfg_v2_repo");
        }
        onUnavailablePathRef.current?.(result.unavailablePath);
        setNotice(folderRecoveryNotice(result.unavailablePath, result.recoveryLocation));
      }
    } catch (e) {
      const message = e instanceof Error ? e.message : "Couldn't open this folder";
      const target = path ?? "your projects folder";
      setError(`Folder “${target}” could not be opened (${message}). Close this picker and check that the Computer is online.`);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!open) return;
    setCreating(startCreating);
    setFolderName("");
    setDeleteTarget(null);
    void browse(initialPath);
  }, [browse, initialPath, open, startCreating]);

  async function finish(endpoint: string, body: object) {
    setLoading(true);
    setError(null);
    try {
      const payload = await api<{ repo: Repo; repos?: Repo[] }>(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      await onSelected(payload.repos?.find((repo) => repo.cwd === payload.repo.cwd) ?? payload.repo);
      onOpenChange(false);
      toast.success("Project ready");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't create project");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Drawer open={open} onOpenChange={onOpenChange} shouldScaleBackground={false}>
      {/* The browser wants a tall, stable window so the list doesn't resize as
          you navigate; the delete confirmation is short and looks stranded in
          it, so let that one state hug its content. */}
      <DrawerContent
        // "New folder" and the delete confirmation both put a text field at
        // the bottom of a sheet that is already tall; DrawerContent's own
        // expand-on-focus morph keeps the keyboard from pushing them off.
        className={cn(
          "mx-auto max-w-lg overflow-hidden",
          deleteTarget ? "h-auto" : "h-[min(82dvh,42rem)]",
        )}
      >
        <DrawerTitle className="sr-only">Choose a project folder</DrawerTitle>
        <div className="flex min-h-0 flex-1 flex-col px-4 pb-[max(var(--lfg-safe-bottom),1rem)]">
          <div className="mb-3 flex items-center justify-between">
            <div className="min-w-0">
              <h2 className="text-lg font-semibold">Choose a project</h2>
              <p className="truncate text-xs text-muted-foreground">{browser?.current || "Opening…"}</p>
            </div>
            <button
              type="button"
              onClick={() => onOpenChange(false)}
              className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted"
              aria-label="Close"
            >
              <X className="size-4" />
            </button>
          </div>

          {deleteTarget ? (
            <DeleteFolderPanel
              target={deleteTarget}
              onClose={() => setDeleteTarget(null)}
              onDeleted={async (deletedPath) => {
                // Re-list the folder we're standing in so the deleted row goes
                // away, and refresh the picker in case it was a pinned project.
                await browse(browser?.current);
                await onReposChanged?.(deletedPath);
              }}
            />
          ) : (
          <>
          <div className="min-h-0 flex-1 overflow-y-auto rounded-2xl border border-border bg-muted/25">
            {browser?.parent ? (
              <button
                type="button"
                onClick={() => void browse(browser.parent!)}
                className="flex w-full items-center gap-3 border-b border-border px-3 py-3 text-left active:bg-muted"
              >
                <span className="flex size-9 items-center justify-center rounded-xl bg-muted">
                  <ChevronLeft className="size-4" />
                </span>
                <span className="text-sm font-medium">Back</span>
              </button>
            ) : null}
            {/* A row is a div, not a button, because the delete affordance is a
                button of its own and nesting buttons is invalid HTML (React
                renders it, but the inner click target behaves unpredictably). */}
            {directories.map((directory) => (
              <div
                key={directory.path}
                className="flex w-full items-center border-b border-border pr-1.5 last:border-0"
              >
                <button
                  type="button"
                  onClick={() => void browse(directory.path)}
                  className="flex min-w-0 flex-1 items-center gap-3 px-3 py-3 text-left active:bg-muted"
                >
                  <span className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-blue-500/10 text-blue-500">
                    <Folder className="size-4" />
                  </span>
                  <span className="min-w-0 flex-1 truncate text-sm font-medium">{directory.name}</span>
                  {directory.isEmpty ? (
                    <span className="shrink-0 rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">Empty</span>
                  ) : null}
                  {directory.isGitRepo ? (
                    <span className="shrink-0 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-medium text-emerald-500">Git</span>
                  ) : null}
                  <ChevronRight className="size-4 shrink-0 text-muted-foreground" />
                </button>
                <button
                  type="button"
                  onClick={() => setDeleteTarget({ path: directory.path, name: directory.name })}
                  aria-label={`Delete ${directory.name}`}
                  title={`Delete ${directory.name}`}
                  className="flex size-9 shrink-0 items-center justify-center rounded-xl text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive active:bg-destructive/15"
                >
                  <Trash2 className="size-4" />
                </button>
              </div>
            ))}
            {!loading && browser && directories.length === 0 ? (
              <div className="px-4 py-10 text-center text-sm text-muted-foreground">This folder is empty</div>
            ) : null}
            {loading ? (
              <div className="flex justify-center py-10"><Loader2 className="size-5 animate-spin text-muted-foreground" /></div>
            ) : null}
          </div>

          {notice ? <p className="mt-2 text-sm text-muted-foreground">{notice}</p> : null}
          {error ? <p className="mt-2 text-sm text-destructive">{error}</p> : null}
          {creating ? (
            <div className="mt-3 flex gap-2">
              <input
                value={folderName}
                onChange={(e) => setFolderName(e.target.value)}
                placeholder="Project name"
                autoFocus
                className="min-w-0 flex-1 rounded-xl border border-border bg-muted/40 px-3 py-2.5 text-sm outline-none"
              />
              <Button
                type="button"
                disabled={loading || !!error || !folderName.trim() || !browser}
                onClick={() => browser && void finish("/api/projects/create-folder", { parent: browser.current, name: folderName })}
              >
                Create
              </Button>
            </div>
          ) : (
            <div className="mt-3 grid grid-cols-2 gap-2">
              <Button type="button" variant="outline" onClick={() => setCreating(true)} disabled={!browser || loading || !!error}>
                <Plus className="size-4" /> New Folder
              </Button>
              <Button
                type="button"
                disabled={!browser || loading || !!error}
                onClick={() => browser && void finish("/api/projects/use-folder", { path: browser.current })}
              >
                <Check className="size-4" /> Use This Folder
              </Button>
            </div>
          )}
          {!browser?.isGitRepo && browser ? (
            <p className="mt-2 text-center text-[11px] text-muted-foreground">Git will be initialized in this folder.</p>
          ) : null}
          </>
          )}
        </div>
      </DrawerContent>
    </Drawer>
  );
}

function ComposerProjectSheet({
  open,
  repos,
  selected,
  onOpenChange,
  onSelect,
  onBrowse,
  onCreate,
  allSelected = false,
  onSelectAll,
  manageOnly = false,
  onReposChanged,
}: {
  open: boolean;
  repos: Repo[];
  selected: string;
  onOpenChange: (open: boolean) => void;
  onSelect: (repo: Repo) => void;
  onBrowse: () => void;
  onCreate: () => void;
  allSelected?: boolean;
  onSelectAll?: () => void;
  /**
   * Open as "add and manage folders", with no selection in it at all.
   *
   * The rail's folder button used to answer two questions with one control —
   * which folder am I scoped to, and which folders exist — and neither was
   * discoverable from the list it changed. Scoping is the folder title's job
   * now (see SessionGroups), so this opens as the folder manager: browse, add,
   * rename, remove. The composer still opens the selecting version, because
   * "where will my agent work" is a real choice a new session has to make.
   */
  manageOnly?: boolean;
  /** Called after a project leaves the list, with the cwd that went away. */
  onReposChanged?: (removedCwd?: string) => void | Promise<void>;
}) {
  // Paths are off by default: the folder name is almost always enough to pick
  // from, and dropping the second line halves each row so twice as many
  // projects fit before you have to scroll.
  const { showPaths } = useProjectListPrefs();
  const [query, setQuery] = useState("");
  // Managing is a MODE, not a per-row affordance. The common action here is
  // "pick a project", and hanging a delete button off every row puts a
  // destructive target under the thumb of the one gesture people repeat all
  // day. Behind a toggle, tapping a row still cannot destroy anything.
  const [managing, setManaging] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ path: string; name: string } | null>(null);
  const [busyCwd, setBusyCwd] = useState<string | null>(null);
  const canManage = !!onReposChanged;

  // A search box only earns its space once the list is long enough that
  // scanning it is the slow part.
  const searchable = repos.length > 7;
  const needle = searchable ? query.trim().toLowerCase() : "";

  // Reset the filter between openings so the sheet never reopens pre-filtered.
  // Managing resets too: reopening the picker straight into a list of delete
  // buttons is a mode you did not ask for and might not notice.
  useEffect(() => {
    if (!open) {
      setQuery("");
      setManaging(false);
      setDeleteTarget(null);
    }
  }, [open]);

  async function unlinkRepo(repo: Repo) {
    setBusyCwd(repo.cwd);
    try {
      await api("/api/repos", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cwd: repo.cwd }),
      });
      toast.success(`Removed ${repo.name}`, { description: "The folder is still on disk." });
      await onReposChanged?.(repo.cwd);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Couldn't remove that project");
    } finally {
      setBusyCwd(null);
    }
  }

  const visibleRepos = useMemo(() => {
    if (!needle) return repos;
    return repos.filter(
      (repo) =>
        repo.name.toLowerCase().includes(needle) ||
        repo.cwd.toLowerCase().includes(needle),
    );
  }, [repos, needle]);

  // `selected` (the concrete repo a new session will run in) and `allSelected`
  // (the live-view filter sitting on "__all") are independent inputs, and the
  // composer passes both at once: with no project filter it still falls back to
  // a real repo for the session, so it hands us selected="/…/duet-app"
  // *alongside* allSelected. Ticking each row off its own prop then drew two
  // ticks in a single-choice list. The concrete repo wins — it's the honest
  // answer to "choose where your agent will work" — so "All projects" only
  // ticks when there is no concrete target, which is exactly the live-view
  // rail's sheet (it passes selected="" whenever the filter is "__all").
  const allTicked = allSelected && !selected;

  const rowClass = cn(
    "flex w-full items-center gap-2.5 border-b border-border px-3 text-left last:border-0 active:bg-muted",
    showPaths ? "py-2.5" : "py-2",
  );

  return (
    <Drawer open={open} onOpenChange={onOpenChange} shouldScaleBackground={false}>
      <DrawerContent className="mx-auto max-h-[78dvh] max-w-lg overflow-hidden">
        <DrawerTitle className="sr-only">Projects</DrawerTitle>
        <div className="flex min-h-0 flex-col px-4 pb-[max(var(--lfg-safe-bottom),1rem)]">
          <div className="mb-2.5 flex items-start justify-between gap-2">
            <div className="min-w-0">
              <h2 className="text-lg font-semibold">Projects</h2>
              <p className="text-xs text-muted-foreground">
                {managing
                  ? "Remove from the list, or delete the folder"
                  : manageOnly
                    ? "Add a folder, or manage the ones you have"
                    : "Choose where your agent will work"}
              </p>
            </div>
            <div className="flex shrink-0 items-center gap-1.5">
              {canManage ? (
                <button
                  type="button"
                  onClick={() => setManaging((on) => !on)}
                  aria-pressed={managing}
                  title={managing ? "Done managing" : "Manage projects"}
                  className={cn(
                    "flex h-8 items-center gap-1.5 rounded-full px-2.5 text-xs font-medium transition-colors",
                    managing ? "bg-blue-500/15 text-blue-500" : "bg-muted text-muted-foreground",
                  )}
                >
                  {managing ? <Check className="size-3.5" /> : <Pencil className="size-3.5" />}
                  {managing ? "Done" : "Manage"}
                </button>
              ) : null}
              <button
                type="button"
                onClick={() => setProjectListPrefs({ showPaths: !showPaths })}
                aria-pressed={showPaths}
                title={showPaths ? "Hide folder paths" : "Show folder paths"}
                className={cn(
                  "flex h-8 items-center gap-1.5 rounded-full px-2.5 text-xs font-medium transition-colors",
                  showPaths ? "bg-blue-500/15 text-blue-500" : "bg-muted text-muted-foreground",
                )}
              >
                {showPaths ? <Eye className="size-3.5" /> : <EyeOff className="size-3.5" />}
                Paths
              </button>
              <button type="button" onClick={() => onOpenChange(false)} className="flex size-8 items-center justify-center rounded-full bg-muted" aria-label="Close">
                <X className="size-4" />
              </button>
            </div>
          </div>
          {deleteTarget ? (
            <DeleteFolderPanel
              target={deleteTarget}
              onClose={() => setDeleteTarget(null)}
              onDeleted={async (deletedPath) => {
                await onReposChanged?.(deletedPath);
              }}
            />
          ) : (
          <>
          {searchable ? (
            <div className="relative mb-2">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
              {/* Deliberately not autofocused — on mobile the keyboard would
                  swallow the extra rows this redesign just bought. */}
              <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder={`Search ${repos.length} projects`}
                aria-label="Search projects"
                className="h-9 w-full rounded-xl border border-border bg-muted/25 pl-8 pr-3 text-sm outline-none placeholder:text-muted-foreground focus:border-blue-500/50"
              />
            </div>
          ) : null}
          {/* data-vaul-no-drag keeps a vertical swipe inside the list scrolling
              the list instead of dragging the whole sheet closed — with the old
              20dvh window almost every flick hit the drawer's drag handler. */}
          <div
            data-vaul-no-drag
            className="max-h-[min(52dvh,26rem)] min-h-0 overflow-y-auto overscroll-contain rounded-2xl border border-border bg-muted/25"
          >
            {onSelectAll && !manageOnly && !needle && !managing ? (
              <button
                type="button"
                onClick={onSelectAll}
                className={rowClass}
              >
                <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground">
                  <Folder className="size-4" />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium">All projects</span>
                  {showPaths ? (
                    <span className="block truncate text-xs text-muted-foreground">
                      Show every session
                    </span>
                  ) : null}
                </span>
                {allTicked ? (
                  <Check className="size-4 shrink-0 text-emerald-500" />
                ) : (
                  <ChevronRight className="size-4 shrink-0 text-muted-foreground" />
                )}
              </button>
            ) : null}
            {visibleRepos.map((repo) =>
              managing ? (
                // A div, not a button: the row carries two buttons of its own,
                // and nested buttons are invalid HTML.
                <div key={repo.cwd} className={rowClass}>
                  <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-blue-500/10 text-blue-500">
                    <Folder className="size-4" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{repo.name}</span>
                    <span className="block truncate text-xs text-muted-foreground">{repo.cwd}</span>
                  </span>
                  {busyCwd === repo.cwd ? (
                    <Loader2 className="size-4 shrink-0 animate-spin text-muted-foreground" />
                  ) : (
                    <>
                      <button
                        type="button"
                        onClick={() => void unlinkRepo(repo)}
                        aria-label={`Remove ${repo.name} from the list`}
                        title="Remove from list (keeps the folder)"
                        className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground active:bg-muted/70"
                      >
                        <EyeOff className="size-4" />
                      </button>
                      <button
                        type="button"
                        onClick={() => setDeleteTarget({ path: repo.cwd, name: repo.name })}
                        aria-label={`Delete the ${repo.name} folder`}
                        title="Delete the folder from disk"
                        className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground active:bg-destructive/15 active:text-destructive"
                      >
                        <Trash2 className="size-4" />
                      </button>
                    </>
                  )}
                </div>
              ) : (
                <button
                  key={repo.cwd}
                  type="button"
                  onClick={() => onSelect(repo)}
                  className={rowClass}
                >
                  <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-blue-500/10 text-blue-500"><Folder className="size-4" /></span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{repo.name}</span>
                    {showPaths ? (
                      <span className="block truncate text-xs text-muted-foreground">{repo.cwd}</span>
                    ) : null}
                  </span>
                  {repo.cwd === selected ? <Check className="size-4 shrink-0 text-emerald-500" /> : <ChevronRight className="size-4 shrink-0 text-muted-foreground" />}
                </button>
              ),
            )}
            {visibleRepos.length === 0 ? (
              <p className="px-3 py-6 text-center text-xs text-muted-foreground">
                {needle ? `No projects match "${query.trim()}"` : "No projects yet"}
              </p>
            ) : null}
          </div>
          {managing ? (
            <p className="mt-2 px-1 text-[11px] leading-snug text-muted-foreground">
              Removing takes a project off this list without touching your files. Deleting erases
              the folder from disk and asks you to confirm first.
            </p>
          ) : null}
          <div className="mt-3 grid grid-cols-2 gap-2">
            <Button type="button" variant="outline" onClick={onBrowse}><Folder className="size-4" /> Browse</Button>
            <Button type="button" onClick={onCreate}><Plus className="size-4" /> New Project</Button>
          </div>
          </>
          )}
        </div>
      </DrawerContent>
    </Drawer>
  );
}

function NewSessionDialog({
  open,
  repos,
  users,
  defaultUser,
  scopedProject,
  projectOptions,
  onProjectChange,
  onClose,
  onCreated,
  onReposChanged,
  onProjectSwipe,
  // Presentation shell for the shared composer core:
  //  - "drawer" (default): desktop bottom sheet (Vaul), opened by the "C"
  //    shortcut.
  //  - "inline": mobile home screen — anchored at the bottom of the viewport,
  //    compact at rest and expandable. Always mounted (no open/close).
  variant = "drawer",
  expanded = false,
  onExpandedChange,
  focusNonce = 0,
  codingAgents,
  agentRequest,
}: {
  open: boolean;
  repos: Repo[];
  users: User[];
  defaultUser: string;
  // The active project filter from the live view. When it's a specific project
  // (not "__all"), creating a session is locked to that project's repo and the
  // repo picker is hidden.
  scopedProject: string;
  // Inline only: render the live project selector as a centered tab overlapping
  // the composer edge. The drawer version keeps project selection in its normal
  // repo controls instead.
  projectOptions?: string[];
  onProjectChange?: (value: string) => void;
  onClose: () => void;
  onCreated: (result?: { launchId?: string; sessionId?: string; session?: Session | null }) => Promise<void>;
  // Inline only: horizontal swipes cycle the live-view project filter.
  onProjectSwipe?: (dir: 1 | -1) => boolean;
  onReposChanged: () => Promise<void>;
  variant?: "drawer" | "inline";
  // Inline only: compact↔full controls toggle (lifted to the parent so other
  // affordances can drive it).
  expanded?: boolean;
  onExpandedChange?: (next: boolean) => void;
  // Inline only: bump to focus the textarea ("new session").
  focusNonce?: number;
  codingAgents?: CodingAgentInfo[];
  // Set when a surface outside the composer picks the agent for it (the usage
  // campfire). The nonce lets the same agent be requested more than once.
  agentRequest?: { kind: AgentKind; accountId?: string; nonce: number } | null;
}) {
  const catalog = useAgentModelCatalog();
  const accessMode = useContext(AgentAccessModeContext);
  const { defaultAgent } = useEmbeddedHostOptions();
  const defaultModelFor = (key: AgentKind) => catalog.defaults[key] ?? AGENT_DEFAULT_MODEL[key];
  const [agent, setAgent] = useState<AgentKind>(
    () => resolveInitialAgent(localStorage.getItem("lfg_v2_agent"), defaultAgent),
  );
  const [claudeAccountId, setClaudeAccountId] = useState("");
  const [repo, setRepo] = useState(() => localStorage.getItem("lfg_v2_repo") || "");
  const [model, setModel] = useState(
    () =>
      localStorage.getItem(`lfg_model_${agent}`) ||
      localStorage.getItem("lfg_model") ||
      defaultModelFor(agent),
  );
  const [thinkingLevel, setThinkingLevel] = useState<ThinkingLevel>(
    () => savedThinkingLevel(),
  );
  // Default the owner to the active profile, falling back to the first known user
  // — never empty when a roster exists. An unowned session lands unassigned, and
  // the live view's auto-default filter (which flips to a specific user) then
  // hides it, so "I created a session but don't see it". The Owner dropdown still
  // lets you pick Unassigned explicitly.
  const [user, setUser] = useState(() =>
    resolveRosterUser(defaultUser || localStorage.getItem("lfg_user"), users),
  );
  const [prompt, setPromptState] = useState(
    () => readPromptDraft("new-session")?.text ?? "",
  );
  // A mirror of `prompt` for callbacks that outlive the render that made them.
  // The agent-cap offer is the one that does: it now waits to be answered, so
  // the box can be edited while it sits there, and answering it must send what
  // the person can currently see rather than what they typed a minute ago.
  const promptRef = useRef(prompt);
  promptRef.current = prompt;
  const [dictationScrollNonce, setDictationScrollNonce] = useState(0);
  const [promptMultiline, setPromptMultiline] = useState(false);
  const [pendingUploads, setPendingUploads] = useState<ComposerAttachment[]>([]);
  const [pendingCreates, setPendingCreates] = useState(0);
  const [error, setError] = useState<string | null>(null);
  // Shared composer file plumbing (same hook the chat and fork composers use).
  // An attachment can be mid-upload in either list: submit() moves it from
  // `attachments` to `pendingUploads` so the composer clears immediately, and
  // the chip row renders both — so patch both via onPatchExtra and its progress
  // keeps ticking across the handoff.
  const files = useComposerAttachments({
    endpoint: (att) => `/api/uploads?filename=${encodeURIComponent(att.name)}`,
    onPatchExtra: (id, patch) =>
      setPendingUploads((current) =>
        current.map((item) => (item.id === id ? { ...item, ...patch } : item)),
      ),
  });
  const {
    attachments,
    setAttachments,
    draggingFiles,
    addFiles,
    removeAttachment,
    setAnnotatingId,
    previewUrls,
    resolveUpload,
    forgetUpload,
  } = files;
  // Resumable (closed / rebooted-away) sessions. Fetched lazily when the user
  // expands the section so opening the dialog stays instant; reset on close.
  const [resumeOpen, setResumeOpen] = useState(false);
  const [resumable, setResumable] = useState<ResumableSession[] | null>(null);
  const [agentPopoverOpen, setAgentPopoverOpen] = useState(false);
  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
  const [projectSheetOpen, setProjectSheetOpen] = useState(false);
  const [folderBrowserCreate, setFolderBrowserCreate] = useState(false);
  const [modelLayerOpen, setModelLayerOpen] = useState(false);
  // Swipe-to-switch state for the inline composer's agent icon. `dir`/`nonce`
  // drive the slide+fade animation when the icon swaps; the button ref lets us
  // own the gesture with native listeners.
  const agentIconBtnRef = useRef<HTMLButtonElement>(null);
  const cycleAgentRef = useRef<(dir: 1 | -1) => void>(() => {});
  const [agentIconDir, setAgentIconDir] = useState<1 | -1>(1);
  const [agentIconNonce, setAgentIconNonce] = useState(0);
  const handleModelLayerOpenChange = useCallback((next: boolean) => {
    setModelLayerOpen(next);
  }, []);
  const handleAgentPopoverOpenChange = useCallback(
    (next: boolean) => {
      // Keep the agent popover open while its nested model layer is open.
      if (!next && modelLayerOpen) return;
      setAgentPopoverOpen(next);
    },
    [modelLayerOpen],
  );

  // Own the agent-icon gesture end-to-end with pointer events (one code path
  // for mouse-drag, touch and pen) plus wheel/trackpad. Base UI's trigger opens
  // the menu on press-*down* (useClick event:'mousedown'), which fires before we
  // can tell a tap from a swipe — so we swallow its native mousedown/click
  // (stopPropagation keeps the event from bubbling to React's root, where Base
  // UI's handler lives) and instead open the popover ourselves on a clean tap.
  // A vertical drag past threshold steps through agents (repeatably within one
  // drag) and never opens the menu. `touch-action: none` on the button keeps a
  // vertical drag from scrolling the page. Callbacks read cycle/open through
  // refs/functional-setState, so a mid-gesture re-render never drops the drag.
  useEffect(() => {
    const el = agentIconBtnRef.current;
    if (!el) return;
    const SWIPE_PX = 22;
    const WHEEL_PX = 40;
    let drag:
      | { x: number; y: number; lastStepY: number; dragged: boolean; pointerId: number }
      | null = null;
    const blockNativeMouseDown = (e: Event) => {
      // Stop Base UI's mousedown-to-open; we drive open on pointerup instead.
      e.stopPropagation();
    };
    const blockNativeClick = (e: MouseEvent) => {
      // Swallow pointer-derived clicks (detail > 0) so they can't open the menu,
      // but let keyboard-activated clicks (Enter/Space → detail 0) through so
      // Base UI still opens the popover for keyboard users.
      if (e.detail > 0) e.stopPropagation();
    };
    // Move/up are tracked on window, not the 32px button: the pointer leaves
    // the tiny target within ~16px, well under the swipe threshold, so listening
    // on the element alone drops the drag. setPointerCapture is unreliable for
    // this (and no-ops in some engines), so window listeners are the robust path.
    const onPointerMove = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.pointerId) return;
      const totalDy = e.clientY - drag.y;
      const totalDx = e.clientX - drag.x;
      if (!drag.dragged && Math.abs(totalDy) >= SWIPE_PX && Math.abs(totalDy) > Math.abs(totalDx)) {
        drag.dragged = true;
      }
      if (drag.dragged) {
        const stepDy = e.clientY - drag.lastStepY;
        if (Math.abs(stepDy) >= SWIPE_PX) {
          drag.lastStepY = e.clientY;
          cycleAgentRef.current(stepDy < 0 ? 1 : -1); // drag up = next agent
        }
      }
    };
    const endDrag = (e: PointerEvent) => {
      if (drag && e.pointerId !== drag.pointerId) return;
      const d = drag;
      drag = null;
      window.removeEventListener("pointermove", onPointerMove, true);
      window.removeEventListener("pointerup", endDrag, true);
      window.removeEventListener("pointercancel", endDrag, true);
      // A clean press with no drag is a tap → toggle the popover ourselves.
      if (d && !d.dragged && e.type === "pointerup") {
        setAgentPopoverOpen((current) => !current);
      }
    };
    const onPointerDown = (e: PointerEvent) => {
      if (e.button > 0) return; // ignore right/middle press
      drag = {
        x: e.clientX,
        y: e.clientY,
        lastStepY: e.clientY,
        dragged: false,
        pointerId: e.pointerId,
      };
      window.addEventListener("pointermove", onPointerMove, true);
      window.addEventListener("pointerup", endDrag, true);
      window.addEventListener("pointercancel", endDrag, true);
    };
    let wheelAcc = 0;
    let wheelTs = 0;
    const onWheel = (e: WheelEvent) => {
      if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
      e.preventDefault();
      const now = e.timeStamp;
      if (now - wheelTs > 250) wheelAcc = 0;
      wheelTs = now;
      wheelAcc += e.deltaY;
      if (Math.abs(wheelAcc) >= WHEEL_PX) {
        const dir = wheelAcc < 0 ? 1 : -1; // scroll/swipe up = next agent
        wheelAcc = 0;
        cycleAgentRef.current(dir);
      }
    };
    el.addEventListener("mousedown", blockNativeMouseDown);
    el.addEventListener("click", blockNativeClick);
    el.addEventListener("pointerdown", onPointerDown);
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("mousedown", blockNativeMouseDown);
      el.removeEventListener("click", blockNativeClick);
      el.removeEventListener("pointerdown", onPointerDown);
      el.removeEventListener("wheel", onWheel);
      // Drop any window listeners left over from an in-flight drag.
      window.removeEventListener("pointermove", onPointerMove, true);
      window.removeEventListener("pointerup", endDrag, true);
      window.removeEventListener("pointercancel", endDrag, true);
    };
  }, [open, variant]);
  // Close the resume sheet and drop the cached list so the next open refetches
  // (and shows the skeleton) instead of flashing a stale roster.
  const closeResume = useCallback(() => {
    setResumeOpen(false);
    setResumable(null);
  }, []);
  // Inline variant: focus the textarea (and pop the soft keyboard) when an
  // external affordance bumps `focusNonce`. The shadcn Textarea isn't a
  // forwardRef, so reach it through the wrapping element.
  const fieldRef = useRef<HTMLDivElement>(null);
  const inlineBarRef = useRef<HTMLDivElement>(null);
  const inlineShellRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (variant !== "inline" || !focusNonce) return;
    fieldRef.current?.querySelector("textarea")?.focus();
  }, [focusNonce, variant]);
  useLayoutEffect(() => {
    if (variant !== "inline") return;
    const bar = inlineBarRef.current;
    if (!bar) return;
    const sync = () => {
      document.documentElement.style.setProperty(
        "--lfg-inline-composer-height",
        `${Math.ceil(bar.getBoundingClientRect().height)}px`,
      );
    };
    sync();
    const ro = new ResizeObserver(sync);
    ro.observe(bar);
    window.addEventListener("resize", sync);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", sync);
      document.documentElement.style.removeProperty("--lfg-inline-composer-height");
    };
  }, [variant]);
  // True while the post-commit swap animation is in flight. Committing a swipe
  // changes project/tab, which recreates onProjectSwipe and re-attaches the
  // effect below — without this guard its cleanup wipes the in-flight
  // transform and the bar flashes centered before sliding in again (same race
  // as the page-level swipe in App).
  const composerSwipeAnim = useRef(false);
  // Same stability trick as the page-level swipe: onProjectSwipe is recreated
  // on every live-session update, so the listeners read it via ref instead of
  // re-attaching (a mid-drag re-attach resets gesture state and kills the swipe).
  const composerSwipeCtx = useRef({ onProjectSwipe, pendingCreates });
  composerSwipeCtx.current = { onProjectSwipe, pendingCreates };
  useEffect(() => {
    if (variant !== "inline" || !onProjectSwipe) return;
    const shell = inlineShellRef.current;
    if (!shell) return;
    const SWIPE_COMMIT = 64;
    const RESUME_SWIPE_Y = 104;
    const RESUME_SWIPE_RATIO = 1.55;
    const RESUME_SWIPE_CANCEL_Y = RESUME_SWIPE_Y + 28;
    const st = { active: false, decided: false, horizontal: false, x0: 0, y0: 0, dx: 0 };
    const reducedMotion = () =>
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const setTx = (px: number) => {
      shell.style.transition = "none";
      shell.style.transform = px ? `translateX(${px}px)` : "";
      shell.style.opacity = px ? String(Math.max(0.72, 1 - Math.abs(px) / 520)) : "";
    };
    const release = () => {
      shell.style.transition =
        "transform 190ms cubic-bezier(0.22,1,0.36,1), opacity 190ms ease-out";
      shell.style.transform = "";
      shell.style.opacity = "";
    };
    const finish = (dir: 1 | -1) => {
      const changed = composerSwipeCtx.current.onProjectSwipe?.(dir) ?? false;
      if (!changed || reducedMotion()) {
        release();
        return;
      }
      const width = Math.max(320, window.innerWidth || shell.clientWidth || 320);
      const out = dir === 1 ? -width : width;
      const inbound = -out;
      composerSwipeAnim.current = true;
      // Covers the full out (130ms) + in (210ms) timeline with headroom.
      window.setTimeout(() => {
        composerSwipeAnim.current = false;
      }, 480);
      shell.style.transition =
        "transform 130ms cubic-bezier(0.32,0.72,0,1), opacity 130ms ease-out";
      shell.style.transform = `translateX(${out}px)`;
      shell.style.opacity = "0.15";
      window.setTimeout(() => {
        shell.style.transition = "none";
        shell.style.transform = `translateX(${inbound}px)`;
        shell.style.opacity = "0.35";
        requestAnimationFrame(() => {
          shell.style.transition =
            "transform 210ms cubic-bezier(0.22,1,0.36,1), opacity 210ms ease-out";
          shell.style.transform = "";
          shell.style.opacity = "";
        });
      }, 130);
    };
    const onStart = (event: TouchEvent) => {
      if (event.touches.length !== 1 || composerSwipeCtx.current.pendingCreates > 0) return;
      const target = event.target as HTMLElement | null;
      if (!target?.closest("form")) return;
      if (target.closest("select, button, input[type='file'], [data-no-composer-swipe]")) return;
      if (composerIsEditing(target)) return;
      const touch = event.touches[0];
      const viewportHeight = window.visualViewport?.height ?? window.innerHeight;
      if (startsInBottomSystemGestureZone(touch.clientY, viewportHeight)) return;
      st.active = true;
      st.decided = false;
      st.horizontal = false;
      st.x0 = touch.clientX;
      st.y0 = touch.clientY;
      st.dx = 0;
    };
    const onMove = (event: TouchEvent) => {
      if (!st.active) return;
      const touch = event.touches[0];
      const dx = touch.clientX - st.x0;
      const dy = touch.clientY - st.y0;
      const maybeOpenHistory = () => {
        if (dy < -RESUME_SWIPE_Y && Math.abs(dy) > Math.abs(dx) * RESUME_SWIPE_RATIO) {
          event.preventDefault();
          haptic("selection");
          setResumeOpen(true);
          st.active = false;
          return true;
        }
        return false;
      };
      if (!st.decided) {
        if (Math.abs(dx) < 9 && Math.abs(dy) < 9) return;
        st.decided = true;
        st.horizontal = Math.abs(dx) > Math.abs(dy) * 1.18;
        if (!st.horizontal) {
          if (maybeOpenHistory()) return;
          if (dy > 18 || Math.abs(dy) > RESUME_SWIPE_CANCEL_Y) st.active = false;
          return;
        }
      }
      if (!st.horizontal) {
        if (maybeOpenHistory()) return;
        if (dy > 18 || Math.abs(dy) > RESUME_SWIPE_CANCEL_Y) {
          st.active = false;
        }
        return;
      }
      event.preventDefault();
      st.dx = dx;
      setTx(dx * 0.48);
    };
    const onEnd = () => {
      if (!st.active) return;
      const { horizontal, dx } = st;
      st.active = false;
      if (!horizontal) return;
      if (dx > SWIPE_COMMIT) {
        haptic("selection");
        finish(-1);
      } else if (dx < -SWIPE_COMMIT) {
        haptic("selection");
        finish(1);
      } else {
        release();
      }
    };
    shell.addEventListener("touchstart", onStart, { passive: true });
    shell.addEventListener("touchmove", onMove, { passive: false });
    shell.addEventListener("touchend", onEnd, { passive: true });
    shell.addEventListener("touchcancel", onEnd, { passive: true });
    return () => {
      shell.removeEventListener("touchstart", onStart);
      shell.removeEventListener("touchmove", onMove);
      shell.removeEventListener("touchend", onEnd);
      shell.removeEventListener("touchcancel", onEnd);
      // A committed swipe re-runs this effect mid-animation; resetting styles
      // here would flash the bar centered before the inbound slide. The
      // animation always ends by clearing the styles itself.
      if (!composerSwipeAnim.current) {
        shell.style.transition = "";
        shell.style.transform = "";
        shell.style.opacity = "";
      }
    };
  }, [variant, !onProjectSwipe]);
  useEffect(() => {
    // On desktop the resume picker replaces the new-session dialog, so the
    // dialog is intentionally closed while this request is in flight.
    if (!resumeOpen || resumable) return;
    api<{ sessions: ResumableSession[] }>("/api/sessions/resumable?limit=20")
      // A 200 with an empty/odd body (seen on mobile Safari) parses to {} so
      // r.sessions is undefined — never store that, or the picker below crashes.
      .then((r) => setResumable(Array.isArray(r.sessions) ? r.sessions : []))
      .catch(() => setResumable([]));
  }, [resumeOpen, resumable]);

  function resume(session: ResumableSession) {
    const resumePrompt = prompt.trim();
    const stashed = stagePromptSend({
      contextKey: `session:${session.sessionId}`,
      source: "session",
      text: resumePrompt,
      sessionId: session.sessionId,
      sessionTitle: session.title,
      project: session.project,
    });
    const resumeModel =
      session.agent === "claude"
        ? ["fable", "opus", "sonnet", "haiku"].includes(model)
          ? model
          : undefined
        : session.agent === "opencode"
          ? (catalog.models.opencode ?? AGENT_MODELS.opencode).includes(model)
            ? model
            : defaultModelFor("opencode")
        : session.agent === "codex"
          ? (catalog.models["codex-aisdk"] ?? AGENT_MODELS["codex-aisdk"]).includes(model)
            ? model
            : defaultModelFor("codex-aisdk")
          : undefined;
    const resumeUser = resolveRosterUser(user, users);
    onClose();
    // A cold resume starts a process, so it clears the same cap a create does —
    // and gets the same way through it.
    const resume = (overLimit: boolean) =>
      toast.promise(
        api("/api/sessions/resume", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId: session.sessionId,
            prompt: resumePrompt || undefined,
            user: resumeUser || undefined,
            model: resumeModel,
            overLimit: overLimit || undefined,
          }),
        })
          .then(() => {
            setPromptStashStatus(stashed?.id, "sent");
            if (resumePrompt) setPromptState("");
            return onCreated();
          })
          .catch((err) => {
            setPromptStashStatus(stashed?.id, "draft");
            setPromptState((current) => current || resumePrompt);
            throw err;
          }),
        {
          loading: "Resuming session…",
          success: "Session resumed",
          // Always the object form: sonner spreads it over the toast it is
          // already swapping the "Resuming…" one for, so the override rides on
          // that single toast instead of arriving as a second, competing copy.
          // (Its types accept one shape per callback, not a union of both.)
          error: (err) => {
            const message = err instanceof Error ? err.message : "Couldn't resume session";
            if (!overLimit && isAgentLimitError(err)) {
              return {
                message,
                // Same reasoning as toastAgentLimit: the offer waits to be
                // answered instead of expiring under the reader.
                duration: Infinity,
                closeButton: true,
                action: {
                  label: "Start anyway",
                  onClick: () => {
                    resume(true);
                  },
                },
              };
            }
            return { message };
          },
        },
      );
    resume(false);
  }

  // Each time the dialog opens, default the owner to the currently selected
  // user (the live-view filter / active profile) so a new session lands with us.
  useEffect(() => {
    if (open) {
      setUser(resolveRosterUser(defaultUser || localStorage.getItem("lfg_user"), users));
    }
  }, [open, defaultUser, users]);

  const models = catalog.models[agent] ?? AGENT_MODELS[agent];
  const thinkingLevels = useAgentThinkingLevels(agent);
  // When the live view is filtered to a specific project, lock new sessions to
  // that project's repo (and hide the picker below). Falls back to the normal
  // localStorage/first-repo default when viewing "All projects" or when the
  // filtered project has no matching repo in the list.
  const scopedRepo =
    scopedProject !== "__all"
      ? repos.find((r) => repoProject(r) === scopedProject)
      : undefined;
  const projectScoped = !!scopedRepo;
  // The live view is unfiltered. There is no chosen folder to name, only the
  // fallback the next session would land in, so the chip does not claim one.
  const allProjects = scopedProject === "__all";
  const selectedRepo = resolveComposerRepo({
    scopedCwd: scopedRepo?.cwd,
    lastCwd: repo,
    repos,
  });
  const selectedRepoName =
    repos.find((candidate) => candidate.cwd === selectedRepo)?.name ||
    (selectedRepo ? shortProject(selectedRepo) : "Project");
  const launching = pendingCreates > 0;
  // The project the resume picker should open scoped to: the composer's currently
  // selected repo (which already folds in the live-view filter via `scopedRepo`),
  // falling back to the live filter, then "all". Matches the backend `project`
  // field on resumable rows (both derive from the repo's top-folder name).
  const composerProject = (() => {
    const r = repos.find((x) => x.cwd === selectedRepo);
    if (r) return repoProject(r);
    return scopedProject !== "__all" ? scopedProject : "__all";
  })();

  function setPrompt(text: string) {
    setPromptState(text);
    stashPromptDraft({
      contextKey: "new-session",
      source: "new-session",
      text,
      project: composerProject,
    });
  }

  function openProjectSheet() {
    setAgentPopoverOpen(false);
    setProjectSheetOpen(true);
  }

  function openFolderBrowser(create: boolean) {
    setProjectSheetOpen(false);
    setFolderBrowserCreate(create);
    window.setTimeout(() => setFolderBrowserOpen(true), 180);
  }

  function chooseComposerRepo(next: Repo) {
    setRepo(next.cwd);
    localStorage.setItem("lfg_v2_repo", next.cwd);
    if (onProjectChange) onProjectChange(repoProject(next));
    setProjectSheetOpen(false);
  }

  // A pinned account shows its own limits. Claude Auto has no pinned account,
  // so it folds every connected Claude profile into one combined-capacity ring.
  const { usage, loading: usageLoading } = useProviderUsage({
    agent,
    accountId: agent === "aisdk" ? claudeAccountId || null : null,
    combineAccounts: agent === "aisdk" && !claudeAccountId,
    enabled: open,
  });

  useEffect(() => {
    if (!models.includes(model)) setModel(models[0]);
  }, [models, model]);
  useEffect(() => {
    if (thinkingLevels.length && !thinkingLevels.includes(thinkingLevel)) {
      setThinkingLevel(thinkingLevels.includes("high") ? "high" : thinkingLevels[0]);
    }
  }, [thinkingLevel, thinkingLevels]);

  const visibleAgentOptions = useMemo(() => {
    return configuredLaunchOptions(codingAgents, accessMode);
  }, [accessMode, codingAgents]);
  // What the strip DRAWS — launchable agents plus greyed, tap-to-connect
  // placeholders. Kept apart from visibleAgentOptions, which is what the
  // composer is allowed to LAUNCH; see agentPickerOptions.
  const pickerAgentOptions = useMemo(() => {
    return agentPickerOptions(codingAgents, accessMode);
  }, [accessMode, codingAgents]);
  const openSettingsPage = useOpenSettingsPage();
  const handlePlanLimit = usePlanLimitHandler();

  const selectedLaunchId =
    agent === "aisdk" && claudeAccountId ? `aisdk:${claudeAccountId}` : agent;

  useEffect(() => {
    if (visibleAgentOptions.some((option) => option.key === agent)) return;
    const next = visibleAgentOptions[0]?.key;
    if (!next) return;
    setAgent(next);
    setModel(localStorage.getItem(`lfg_model_${next}`) || defaultModelFor(next));
  }, [agent, visibleAgentOptions]);

  useEffect(() => {
    if (agent !== "aisdk") return;
    const selected = visibleAgentOptions.find(
      (option) => (option.selectorId ?? option.key) === selectedLaunchId,
    );
    if (selected) return;
    const firstClaude = visibleAgentOptions.find((option) => option.key === "aisdk");
    setClaudeAccountId(firstClaude?.accountId ?? "");
  }, [agent, selectedLaunchId, visibleAgentOptions]);

  // An outside surface (the usage campfire) picked an agent for us. Keyed on the
  // nonce so choosing the same agent twice still applies.
  const appliedAgentNonce = useRef<number | null>(null);
  useEffect(() => {
    if (!agentRequest) return;
    if (appliedAgentNonce.current === agentRequest.nonce) return;
    appliedAgentNonce.current = agentRequest.nonce;
    setAgent(agentRequest.kind);
    if (agentRequest.kind === "aisdk") setClaudeAccountId(agentRequest.accountId ?? "");
    setModel(
      localStorage.getItem(`lfg_model_${agentRequest.kind}`) ||
        defaultModelFor(agentRequest.kind),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [agentRequest]);

  // Keep this component alive while the resume picker is open. On desktop its
  // owning dialog closes first, otherwise the dialog's modal backdrop and focus
  // trap sit above the full-screen picker and dismissing the dialog unmounts it.
  if (!open && !resumeOpen) return null;

  // overrideThinking comes from a hold-to-scrub release on Start: the level was
  // chosen and launched in the same gesture, so it can't be read back off state
  // yet (setThinkingLevel hasn't re-rendered).
  function submit(e?: FormEvent, overrideText?: string, overrideThinking?: ThinkingLevel) {
    e?.preventDefault();
    if (launching) return;
    const taskPrompt = (overrideText ?? prompt).trim();
    const files = attachments;
    if (!taskPrompt && !files.length) return;
    if (!visibleAgentOptions.some((option) => option.key === agent)) {
      const message = "Set up and sign in to a coding agent before starting a session.";
      setError(message);
      toast.error(message);
      return;
    }
    const launchUser = resolveRosterUser(user, users) || null;
    const launchAgent = agent;
    const launchModel = model;
    const launchThinkingLevel = overrideThinking ?? thinkingLevel;
    const launchClaudeAccountId = launchAgent === "aisdk" ? claudeAccountId || undefined : undefined;
    const stashed = stagePromptSend({
      contextKey: "new-session",
      source: "new-session",
      text: taskPrompt,
      project: composerProject,
    });
    const uploadIds = new Set(files.map((att) => att.id));
    setError(null);
    // Retire any waiting "Start anyway" from a previous refusal. That offer
    // holds the PREVIOUS prompt, and it now outlives its toast's old four
    // seconds — so left standing it would answer a submit the person has
    // already replaced, starting a second session from stale text.
    toast.dismiss(agentLimitToastId("create"));
    setPromptState("");
    setAttachments([]);
    // Carry each attachment's real upload state across. Most will already be
    // "uploaded" because the bytes went up when the file was attached; only
    // genuinely unstarted ones should read as uploading.
    setPendingUploads((current) => [
      ...current,
      ...files.map((att) =>
        att.status === "ready" ? { ...att, status: "uploading" as const, progress: 0, error: undefined } : att,
      ),
    ]);
    setPendingCreates((n) => n + 1);
    localStorage.setItem("lfg_v2_agent", launchAgent);
    localStorage.setItem("lfg_v2_repo", selectedRepo);
    localStorage.setItem(`lfg_model_${launchAgent}`, launchModel);
    if (agentSupportsThinking(launchAgent)) localStorage.setItem("lfg_thinking_level", launchThinkingLevel);
    if (launchAgent === "claude") localStorage.setItem("lfg_model", launchModel);
    if (launchUser) localStorage.setItem("lfg_user", launchUser);
    // Keep both composer variants mounted while the session boots so the
    // creating overlay can acknowledge the submit immediately. Release the
    // inline textarea to dismiss the mobile keyboard; the drawer closes from
    // onCreated after the server has returned the new session.
    if (variant === "inline") {
      fieldRef.current?.querySelector("textarea")?.blur();
    }
    void (async () => {
      type CreateResult = {
        sessionId?: string;
        // The created row, so the list can render it without waiting for the
        // next /api/sessions scan to notice it.
        session?: Session | null;
        archivedSessionCount?: number;
      };
      // Split from the surrounding flow so the agent-cap override can repeat
      // exactly this request. It takes the already-composed prompt, which means
      // a retry never re-uploads the attachments — their ids are in that string.
      const postCreate = (composedPrompt: string, overLimit: boolean) =>
        api<CreateResult>("/api/sessions/new", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            cwd: selectedRepo,
            prompt: composedPrompt || undefined,
            user: launchUser || undefined,
            agent: launchAgent,
            model: launchModel,
            thinkingLevel: agentSupportsThinking(launchAgent) ? launchThinkingLevel : undefined,
            claudeAccountId: launchClaudeAccountId,
            overLimit: overLimit || undefined,
          }),
        });
      const settle = async (res: CreateResult) => {
        const sid = res?.sessionId;
        if (sid) {
          markCreatedSid(sid);
          markCollapsedSid(sid);
        }
        if (res.archivedSessionCount) {
          toast.info(
            `Archived ${res.archivedSessionCount} idle session${res.archivedSessionCount === 1 ? "" : "s"} to free memory`,
            { description: "Their transcripts are still available from Resume." },
          );
        }
        setPromptStashStatus(stashed?.id, "sent");
        await onCreated({ launchId: sid, sessionId: sid, session: res?.session ?? null });
      };
      try {
        // Started at attach time; usually already resolved by now.
        const uploaded = files.length ? await Promise.all(files.map(resolveUpload)) : [];
        const composedPrompt = composeAttachmentMessage(taskPrompt, uploaded);
        let res: CreateResult;
        try {
          res = await postCreate(composedPrompt, false);
        } catch (err) {
          if (!isAgentLimitError(err)) throw err;
          // The local cap, which its owner can overrule. Put the task back in
          // the box first so the offer is genuinely optional — declining it
          // must leave you exactly where you were, with your prompt intact.
          setPromptStashStatus(stashed?.id, "draft");
          setPromptState((current) => current || taskPrompt);
          toastAgentLimit(err, "create", () => {
            void (async () => {
              try {
                // Send what is in the box now. The offer waits, so the prompt
                // it was raised for can have been rewritten since — sending the
                // original would both ignore that edit and then clear it.
                const edited = promptRef.current.trim();
                const outgoing =
                  edited && edited !== taskPrompt.trim()
                    ? composeAttachmentMessage(promptRef.current, uploaded)
                    : composedPrompt;
                const retried = await postCreate(outgoing, true);
                setPromptState("");
                await settle(retried);
              } catch (retryError) {
                const message =
                  retryError instanceof Error ? retryError.message : String(retryError);
                toast.error(message || "Couldn't create session");
              }
            })();
          });
          return;
        }
        await settle(res);
      } catch (err) {
        setPromptStashStatus(stashed?.id, "draft");
        setPromptState((current) => current || taskPrompt);
        // A plan ceiling the host can sell past is not an error to show — it's
        // an upgrade prompt to open. The prompt is already restored above, so
        // whoever comes back from checkout finds their task still typed.
        if (handlePlanLimit(err, "start-session")) return;
        const message = err instanceof Error ? err.message : String(err);
        setError(message);
        toast.error(message || "Couldn't create session");
      } finally {
        for (const att of files) {
          if (att.previewUrl) URL.revokeObjectURL(att.previewUrl);
        }
        const uploadPreviewUrls = new Set(
          files.map((att) => att.previewUrl).filter((url): url is string => !!url),
        );
        previewUrls.current = previewUrls.current.filter((url) => !uploadPreviewUrls.has(url));
        setPendingUploads((current) => current.filter((att) => !uploadIds.has(att.id)));
        for (const id of uploadIds) forgetUpload(id);
        setPendingCreates((n) => Math.max(0, n - 1));
      }
    })();
  }

  // Inline composer resting state: only the agent icon + prompt + mic + Start
  // show; tapping the agent icon morphs the controls row open. The drawer
  // variant is always expanded.
  const compact = variant === "inline" && !expanded;
  const canSubmit =
    !!selectedRepo &&
    visibleAgentOptions.some((option) => option.key === agent) &&
    (!!prompt.trim() || attachments.length > 0);
  const selectedAgentOption = displayedAgentOption<AgentLaunchOption>(
    AGENT_CATALOG,
    visibleAgentOptions,
    agent,
    selectedLaunchId,
  ) ?? (AGENT_CATALOG[0] as AgentLaunchOption);
  // Keep every agent in a fixed position so picking one never reshuffles the
  // icons. The selected agent is highlighted in place rather than hoisted out.
  const agentButtons = pickerAgentOptions;

  // Swipe/scroll the composer's agent icon to step through the visible agents.
  // dir +1 = next (swipe up), -1 = previous (swipe down); wraps around. Mirrors
  // the popover buttons' behaviour (also re-syncs the model) and records the
  // direction + a nonce so the icon replays a slide+fade in the swiped
  // direction. Kept in a ref so the native gesture listeners always call the
  // latest closure.
  const cycleAgent = (dir: 1 | -1) => {
    const opts = visibleAgentOptions;
    if (opts.length < 2) return;
    const idx = opts.findIndex((option) => (option.selectorId ?? option.key) === selectedLaunchId);
    const nextIdx = ((idx < 0 ? 0 : idx) + dir + opts.length) % opts.length;
    const next = opts[nextIdx];
    const nextKey = next.key;
    if ((next.selectorId ?? nextKey) === selectedLaunchId) return;
    setAgentIconDir(dir);
    setAgentIconNonce((n) => n + 1);
    setAgent(nextKey);
    if (nextKey === "aisdk") setClaudeAccountId(next.accountId ?? "");
    setModel(localStorage.getItem(`lfg_model_${nextKey}`) || defaultModelFor(nextKey));
    feedback.swipe();
  };
  cycleAgentRef.current = cycleAgent;

  const agentSelector = (
    <AgentIconStrip
      options={agentButtons}
      value={agent}
      selectedId={selectedLaunchId}
      flat={variant === "inline"}
      onLocked={() => {
        // The whole point of drawing an agent we can't run: this is the one
        // tap between "I have a Claude account" and using it.
        //
        // Get the composer out of the way FIRST, in whichever shape it has.
        // The drawer is a modal sheet, so leaving it up parks it squarely over
        // the settings page we just navigated to — the tap looked like it did
        // nothing. The inline composer only needs its controls row collapsed;
        // the bar itself is meant to stay.
        feedback.tap();
        onExpandedChange?.(false);
        if (variant === "drawer") onClose();
        openSettingsPage("coding-agents");
      }}
      onSelect={(key, option) => {
        // Re-tapping the already-selected agent collapses the row.
        if (
          variant === "inline" &&
          expanded &&
          selectedLaunchId === (option?.selectorId ?? key)
        ) {
          onExpandedChange?.(false);
          return;
        }
        setAgent(key);
        if (key === "aisdk") setClaudeAccountId(option?.accountId ?? "");
        setModel(localStorage.getItem(`lfg_model_${key}`) || defaultModelFor(key));
      }}
    />
  );

  const modelControls = (
    <>
      <ModelPicker
        value={model}
        models={models}
        onChange={setModel}
        flat={variant === "inline"}
        width="max-w-28"
        onMobileLayerOpenChange={variant === "inline" ? handleModelLayerOpenChange : undefined}
      />

      <ThinkingLevelPill
        agent={agent}
        value={thinkingLevel}
        levels={thinkingLevels}
        onChange={setThinkingLevel}
        flat={variant === "inline"}
        immersive
      />


      {!projectScoped && (
        <FieldPill flat={variant === "inline"} icon={<Folder className="size-3.5 text-muted-foreground" />}>
          <button
            type="button"
            onClick={openProjectSheet}
            aria-label="Choose project"
            className="max-w-28 truncate pr-1 text-xs font-medium outline-none"
          >
            {repos.find((item) => item.cwd === selectedRepo)?.name || "Choose project"}
          </button>
        </FieldPill>
      )}
    </>
  );

  // In the inline composer the controls reveal as two independent mini cards:
  // agent choices first, then model/thinking/project. Each card enters from the
  // trigger's bottom-left corner so the stack feels emitted by the agent icon.
  // The drawer keeps the same controls in its existing wrapping row.
  const controlsInner = variant === "inline" ? (
    <div className="flex w-max max-w-[calc(100vw-1rem)] origin-bottom-left flex-col items-start gap-1.5">
      {agentButtons.length ? (
        <div className="origin-bottom-left rounded-2xl bg-popover px-2 py-1.5 shadow-xl ring-1 ring-foreground/5 animate-in fade-in-0 zoom-in-75 slide-in-from-bottom-3 duration-200 ease-out">
          {agentSelector}
        </div>
      ) : null}
      <div className="flex max-w-full origin-bottom-left items-center gap-1.5 overflow-hidden rounded-2xl bg-popover px-2.5 py-1.5 shadow-xl ring-1 ring-foreground/5 animate-in fade-in-0 zoom-in-75 slide-in-from-bottom-3 duration-200 ease-out [animation-delay:55ms] [animation-fill-mode:backwards]">
        {modelControls}
      </div>
    </div>
  ) : (
    <div className="flex flex-wrap items-center gap-1.5 pb-0.5">
      {agentSelector}
      {modelControls}
    </div>
  );

  // Stash + recent-session recovery. This stays visible in the inline mobile
  // composer too; the upward-swipe shortcut remains, but recovery should not
  // depend on discovering a hidden gesture.
  const resumeButton = (
    <button
      type="button"
      onClick={() => {
        setResumeOpen(true);
        if (variant !== "inline") onClose();
      }}
      title="Open Stash and recent sessions"
      aria-label="Open Stash and recent sessions"
      className="flex size-8 shrink-0 items-center justify-center rounded-full border border-border bg-background text-muted-foreground shadow-sm transition hover:text-foreground"
    >
      <Archive className="size-4" />
    </button>
  );

  // Inline composer: the agent icon sits at the start of the input's action row
  // and opens the full agent / model / thinking / repo controls in a popover
  // *above* it — reclaiming the separate row those controls used to occupy while
  // the tall field leaves plenty of empty space.
  const agentPopover = (
    <DropdownMenu open={agentPopoverOpen} onOpenChange={handleAgentPopoverOpenChange}>
      <DropdownMenuTrigger
        render={
          <button
            ref={agentIconBtnRef}
            type="button"
            title={`${selectedAgentOption.label} — swipe to switch agent`}
            aria-label={`Agent: ${selectedAgentOption.label}. Swipe up or down to switch.`}
            style={{ touchAction: "none" }}
            className="relative flex size-8 shrink-0 items-center justify-center rounded-full border border-border bg-background text-foreground shadow-sm transition active:scale-[0.96]"
          >
            <span className="pointer-events-none relative flex size-5 items-center justify-center overflow-hidden">
              <img
                key={`${agent}-${agentIconNonce}`}
                src={agentIconSrc(agent)}
                alt=""
                draggable={false}
                className={cn(
                  "size-5 select-none",
                  agentIconNonce > 0 &&
                    (agentIconDir === 1
                      ? "animate-in fade-in-0 slide-in-from-bottom-2 duration-200"
                      : "animate-in fade-in-0 slide-in-from-top-2 duration-200"),
                )}
              />
            </span>
            {selectedAgentOption.badge != null ? (
              <span className="pointer-events-none absolute -bottom-0.5 -right-0.5 flex size-3.5 items-center justify-center rounded-full bg-foreground text-[8px] font-bold leading-none text-background ring-1 ring-background">
                {selectedAgentOption.badge}
              </span>
            ) : null}
          </button>
        }
      />
      <DropdownMenuContent
        side="top"
        align="start"
        sideOffset={8}
        className="w-max min-w-0 max-w-[calc(100vw-1rem)] origin-bottom-left overflow-visible bg-transparent p-0 shadow-none ring-0"
      >
        {controlsInner}
      </DropdownMenuContent>
    </DropdownMenu>
  );

  const formBody = (
    <>
    <form
      onSubmit={submit}
      {...files.dropZoneProps}
      aria-busy={launching}
      className={cn(
        // Inline home: original device home-indicator pad when standalone.
        // Embed cancels --lfg-device-safe-bottom to 0 (host owns that zone) and
        // the shell still applies host-inset, so Start clears the pill without
        // a double gap. Drawer / dialog are full-bleed → global safe bottom.
        "relative max-h-[70dvh] overscroll-contain px-2 transition-colors",
        variant === "inline"
          ? "overflow-visible pb-[max(var(--lfg-device-safe-bottom),0.5rem)] pt-1.5"
          : "overflow-y-auto pb-[max(var(--lfg-safe-bottom),0.5rem)] pt-1",
        draggingFiles && "bg-primary/8",
      )}
    >
      {files.fileInput}
      <div
        className={cn(
          "lfg-gfield relative rounded-2xl",
          // Inline: a single row with the agent icon, field, and mic all
          // centered at rest, then pinned to the bottom as the textarea grows.
          variant === "inline"
            ? cn(
                "flex gap-1.5 overflow-visible px-2.5 py-2",
                promptMultiline ? "items-end" : "items-center",
              )
            : "relative px-2 py-1",
        )}
        ref={fieldRef}
      >
        {launching ? (
          <div
            role="status"
            aria-live="polite"
            className="absolute inset-0 z-30 flex items-center justify-center rounded-2xl bg-background/90 backdrop-blur-sm animate-in fade-in-0 duration-150"
          >
            <ShimmerText className="text-sm font-medium">Creating session…</ShimmerText>
          </div>
        ) : null}
        {variant === "inline" ? agentPopover : null}
        <ComposerTextarea
          value={prompt}
          onValueChange={setPrompt}
          onMultilineChange={variant === "inline" ? setPromptMultiline : undefined}
          scrollToEndNonce={dictationScrollNonce}
          onPaste={files.onPasteFiles}
          onKeyDown={(e) => {
            if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
              e.preventDefault();
              e.currentTarget.form?.requestSubmit();
            }
          }}
          placeholder={attachments.length ? "Add a note for the files…" : "What should we work on?"}
          className={cn(
            "border-0 bg-transparent text-base leading-relaxed shadow-none focus-visible:border-0 focus-visible:ring-0",
            variant === "inline"
              ? "min-h-9 flex-1 px-1 py-1.5"
              : "min-h-40 max-h-[42dvh] px-1 py-1 pr-10",
          )}
        />
        <MicButton
          minimal
          className={cn("size-9 shrink-0", variant !== "inline" && "absolute bottom-1 right-1")}
          silenceMs={2500}
          baseText={prompt}
          onText={(text, base) => {
            setPrompt(base.trim() ? `${base.trimEnd()} ${text}` : text);
            setDictationScrollNonce((nonce) => nonce + 1);
          }}
          onInterim={(text, base) => {
            setPrompt(base.trim() ? `${base.trimEnd()} ${text}` : text);
            setDictationScrollNonce((nonce) => nonce + 1);
          }}
          onAutoSubmit={(text, base) => {
            const combined = base.trim() ? `${base.trimEnd()} ${text}` : text;
            void submit(undefined, combined);
          }}
          onCancel={(base) => setPrompt(base)}
        />
      </div>

      <ComposerAttachmentChips
        className="mt-2"
        items={[
          // Chips already handed off to an in-flight session creation can no
          // longer be edited or removed; live composer attachments always can,
          // even while their upload is still running.
          ...pendingUploads.map((att) => ({ att, locked: true })),
          ...attachments.map((att) => ({ att, locked: false })),
        ]}
        onAnnotate={setAnnotatingId}
        onRemove={removeAttachment}
        onToggleHd={files.setAttachmentHd}
      />

      {/* The drawer variant keeps its always-open controls row; the inline
          composer carries these inside the agent popover instead. This row is
          ONLY the configuration pills (agent / model / thinking / project) —
          usage and resume live in the action row below, so both variants read
          as the same two-row composer instead of a ragged four-row stack. */}
      {variant !== "inline" ? (
        <div className="mt-2 flex flex-wrap items-center gap-1.5">{controlsInner}</div>
      ) : null}

      <div
        className={cn(
          "flex items-center gap-2",
          compact ? "mt-2" : "mt-3",
        )}
      >
        {/* Left: Apple-Watch-style usage rings; tap to expand the breakdown. */}
        {usageLoading ? (
          <UsageRingsLoadingIndicator />
        ) : usage ? (
          <UsageRingsButton provider={usage} />
        ) : null}
        <span
          className={cn(
            "min-w-0 flex-1 truncate text-xs",
            error ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {error || ""}
        </span>
        {/* Right cluster: resume + folder + photo + send, stacked together. */}
        <div className="flex shrink-0 items-center gap-2">
          {resumeButton}
          {variant === "inline" && projectOptions && onProjectChange ? (
            <Button
              size="sm"
              type="button"
              variant="outline"
              className={cn(
                "h-8 shrink-0 rounded-full shadow-sm",
                // Icon alone when nothing is scoped — the same shape
                // MobileProjectPicker collapses to for "__all". Naming the
                // composer's fallback repo here made choosing "All projects"
                // look ignored: the list widened while the chip went on
                // showing the folder you had just moved away from.
                allProjects ? "size-8 px-0" : "max-w-36 px-2.5",
              )}
              onClick={openProjectSheet}
              aria-label={
                allProjects
                  ? "Choose project. Showing all projects"
                  : `Choose project. Current project: ${selectedRepoName}`
              }
              title={allProjects ? "All projects" : selectedRepo || "Choose project"}
            >
              <Folder className="size-4 shrink-0" />
              {allProjects ? null : <span className="truncate">{selectedRepoName}</span>}
            </Button>
          ) : null}
          <Button
            size="icon-sm"
            type="button"
            variant={draggingFiles ? "brand-soft" : "outline"}
            className="size-8 rounded-full shadow-sm"
            onClick={files.openFilePicker}
            aria-label="Attach files"
            title="Attach files"
          >
            <Plus className="size-4" />
          </Button>
          <ComposerStartButton
            disabled={!canSubmit}
            thinkingLevel={thinkingLevel}
            thinkingLevels={agentSupportsThinking(agent) ? thinkingLevels : []}
            onLaunch={(next) => {
              setThinkingLevel(next);
              submit(undefined, undefined, next);
            }}
          />
        </div>
      </div>

      {resumeOpen ? (
        <Suspense fallback={null}>
          <ResumeSessionSheet
            initial={resumable}
            scopedProject={composerProject}
            onRestore={(entry) => setPrompt(entry.text)}
            onPick={(session) => {
              closeResume();
              resume(session);
            }}
            onClose={closeResume}
          />
        </Suspense>
      ) : null}
      <ProjectFolderBrowser
        open={folderBrowserOpen}
        initialPath={selectedRepo || undefined}
        startCreating={folderBrowserCreate}
        onOpenChange={setFolderBrowserOpen}
        onSelected={async (project) => {
          chooseComposerRepo(project);
          await onReposChanged();
        }}
        onUnavailablePath={(path) => {
          setRepo((current) => (current === path ? "" : current));
        }}
        onReposChanged={onReposChanged}
      />
      <ComposerProjectSheet
        open={projectSheetOpen}
        repos={repos}
        selected={selectedRepo}
        onOpenChange={setProjectSheetOpen}
        onSelect={chooseComposerRepo}
        onBrowse={() => openFolderBrowser(false)}
        onCreate={() => openFolderBrowser(true)}
        // "All projects" is deliberately NOT in the mobile swipe cycle, so on a
        // phone the project menu was the only way back to it. The embedded
        // header no longer carries that menu, which would have made __all a
        // one-way door — the composer's own sheet offers it instead. Same row
        // the desktop rail's sheet already shows.
        allSelected={allProjects}
        onSelectAll={
          onProjectChange
            ? () => {
                onProjectChange("__all");
                setProjectSheetOpen(false);
              }
            : undefined
        }
        onReposChanged={async (removedCwd?: string) => {
          // A composer pointed at a project that no longer exists would launch
          // into a 400 "unknown repo", so drop the selection when the thing it
          // named is what just went away.
          if (removedCwd && selectedRepo === removedCwd) setRepo("");
          await onReposChanged();
        }}
      />
    </form>
    {files.annotator}
    </>
  );

  // Mobile home screen: render the shared composer as a real bottom flex child
  // of the app shell. The App root is pinned to visualViewport.height, so this
  // participates in layout and moves above the soft keyboard instead of relying
  // on fixed-position keyboard offsets (which vary across iOS PWA/Safari modes).
  if (variant === "inline") {
    return (
      <div
        ref={inlineBarRef}
        aria-busy={launching}
        className="mobile-scroll-composer-fade pointer-events-auto relative z-[55] mt-auto shrink-0 overflow-x-clip bg-background/95 shadow-[0_-8px_24px_rgba(0,0,0,0.12)] backdrop-blur-xl"
      >
        <div ref={inlineShellRef} className="mx-auto max-w-lg will-change-transform">
          {formBody}
        </div>
      </div>
    );
  }

  // Desktop resume is a page-level surface, independent of the dialog it was
  // launched from. Rendering it without the Drawer removes the dialog's z-160
  // overlay/focus trap and lets Back close only the resume page.
  if (!open && resumeOpen) {
    return (
      <Suspense fallback={null}>
        <ResumeSessionSheet
          initial={resumable}
          scopedProject={composerProject}
          onRestore={(entry) => setPrompt(entry.text)}
          onPick={(session) => {
            closeResume();
            resume(session);
          }}
          onClose={closeResume}
        />
      </Suspense>
    );
  }

  return (
    <Drawer
      open
      // Let the browser (viewport `interactive-widget=resizes-content`) handle the
      // on-screen keyboard. Vaul's default reposition imperatively rewrites the
      // sheet's height/bottom on every visualViewport change, which fights the
      // reflow and causes the layout shift/jump when a field takes focus.
      repositionInputs={false}
      onOpenChange={(o) => {
        if (!o) onClose();
      }}
    >
      {/* max-w-xl (not lg): at the old width the agent / model / thinking /
          project pills wrapped onto a second line, which is what made this
          dialog read as a ragged stack. 576px fits them on one row. The
          sm: variant is required — DialogContent's own `sm:max-w-md` wins over
          an unprefixed utility no matter the class order. */}
      <DrawerContent className="mx-auto max-w-xl sm:max-w-xl">
        {/* A real, visible header rather than an sr-only one: this surface is
            the "new session" dialog, so it names itself. (An earlier pass put
            a per-session name field in here instead — wrong idea; the title
            belongs to the dialog, and sessions are renamed from their own
            header once they exist.) */}
        <DrawerTitle className="px-3 pt-0.5 pb-1.5">New session</DrawerTitle>
        {formBody}
      </DrawerContent>
    </Drawer>
  );
}

// Compact recovery surface. The shared Drawer renders this as a bottom drawer
// on mobile and a centered dialog on desktop.
function FieldPill({ icon, children, flat = false }: { icon?: ReactNode; children: ReactNode; flat?: boolean }) {
  return (
    <label
      className={cn(
        "relative inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full text-foreground",
        flat ? "px-1" : "bg-muted px-3",
      )}
    >
      {icon}
      {children}
      <ChevronDown className="size-3 shrink-0 text-muted-foreground/70" />
    </label>
  );
}

// The thinking/reasoning-effort select shared by the new-session composer,
// fork dialog, and auto-agent + finding sheets. Prefer `immersive` so launch
// surfaces share ComposerThinkingControl (signal + hold-to-scrub). Renders
// nothing when the agent has no reasoning knob.
function ThinkingLevelPill({
  agent,
  value,
  levels,
  onChange,
  flat = false,
  immersive = false,
}: {
  agent: AgentKind;
  value: ThinkingLevel;
  levels: ThinkingLevel[];
  onChange: (value: ThinkingLevel) => void;
  flat?: boolean;
  immersive?: boolean;
}) {
  if (!agentSupportsThinking(agent)) return null;
  if (immersive) {
    return (
      <ComposerThinkingControl
        value={value}
        levels={levels}
        onChange={onChange}
        flat={flat}
      />
    );
  }
  return (
    <FieldPill flat={flat}>
      <span className="text-xs font-medium">Thinking</span>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value as ThinkingLevel)}
        aria-label="Thinking"
        title={`Thinking: ${value}`}
        className="absolute inset-0 size-full cursor-pointer appearance-none opacity-0"
      >
        {levels.map((item) => (
          <option key={item} value={item}>
            {item}
          </option>
        ))}
      </select>
    </FieldPill>
  );
}

const THINKING_HOLD_MS = 360;
// Travel on either axis past this locks the scrub to that axis. Horizontal is
// the natural direction for the inline pill; vertical rescues corner-pinned
// triggers like Start, where there is no room left to drag sideways.
const THINKING_AXIS_LOCK_PX = 6;
// Distance from the upright panel's right edge to the centre of its bar
// (right padding + half the bar). Used to park the bar over the trigger.
const THINKING_VERTICAL_BAR_INSET = 30;
// The thumb's on-screen edge (--thinking-thumb: 1.3rem). Half of it is the
// track's travel inset at each end, which the click mapping has to match.
const THINKING_THUMB_PX = 21;
// Pixels of travel per thinking level while scrubbing. Higher = less
// sensitive. Scales mildly with how many steps the agent exposes.
function thinkingScrubStepWidth(levelCount: number): number {
  return Math.max(34, Math.min(52, 240 / Math.max(1, levelCount - 1)));
}

// The scrub drag belongs entirely to the gesture. `user-select: none` on the
// trigger alone does not stop it: the browser still anchors a selection on
// press and extends it across whatever the finger passes over, so a drag off
// the button smears a highlight down the session list behind it. Killing
// selectstart/dragstart for the life of the press is what actually consumes it.
function preventThinkingDragDefault(event: Event) {
  event.preventDefault();
}

// Level names are lowercase in the catalog ("xhigh"), and every surface wants
// them title-cased. Done here rather than with `text-transform: capitalize`
// because Chromium drops the transform on the absolutely-positioned stop
// labels of the upright bar — same frame, same computed style, half the labels
// rendered lowercase. Capitalising the string is deterministic everywhere.
function thinkingLevelLabel(level: ThinkingLevel): string {
  return level ? level.charAt(0).toUpperCase() + level.slice(1) : level;
}

// Where stop `index` sits along the bar, inset by half a thumb at each end so
// the squircle never overhangs. Shared by the tick marks and the upright bar's
// level names, which is what keeps a name aligned with its own tick.
function thinkingStopOffset(index: number, count: number, vertical: boolean): CSSProperties {
  const progress = count > 1 ? index / (count - 1) : 0;
  const offset = `calc(var(--thinking-thumb-half) + ${progress} * (100% - var(--thinking-thumb)))`;
  return vertical ? { bottom: offset } : { left: offset };
}

// Same blue → indigo → violet → fuchsia stops as the organic send wash /
// thinking scrubber fill, so the pill signal and hold-to-scrub control morph
// together as effort intensifies.
const THINKING_ACCENT_STOPS: ReadonlyArray<readonly [number, number, number]> = [
  [0, 122, 255],
  [90, 110, 255],
  [175, 82, 222],
  [232, 121, 249],
];

function thinkingAccentColor(progress: number): string {
  const clamped = Math.max(0, Math.min(1, progress));
  const scaled = clamped * (THINKING_ACCENT_STOPS.length - 1);
  const i = Math.floor(scaled);
  const t = scaled - i;
  const a = THINKING_ACCENT_STOPS[i]!;
  const b = THINKING_ACCENT_STOPS[Math.min(i + 1, THINKING_ACCENT_STOPS.length - 1)]!;
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return `rgb(${r}, ${g}, ${bl})`;
}

function ThinkingSignal({
  value,
  levels,
}: {
  value: ThinkingLevel;
  levels: ThinkingLevel[];
}) {
  const index = Math.max(0, levels.indexOf(value));
  const progress = levels.length > 1 ? index / (levels.length - 1) : 0;
  const strength = /^(none|off)$/i.test(value)
    ? 0
    : Math.max(1, Math.ceil(((index + 1) / Math.max(1, levels.length)) * 4));
  const color = thinkingAccentColor(progress);

  return (
    <span
      aria-hidden="true"
      className="flex h-4 w-4 shrink-0 select-none items-end justify-center gap-px"
    >
      {[4, 7, 10, 13].map((height, barIndex) => {
        const active = barIndex < strength;
        return (
          <span
            key={height}
            className={cn(
              "w-0.5 rounded-full bg-foreground/20 transition-[height,background-color,box-shadow] duration-200",
              active && barIndex === strength - 1 && "shadow-[0_0_8px_currentColor]",
            )}
            style={{
              height,
              color: active ? color : undefined,
              backgroundColor: active ? color : undefined,
            }}
          />
        );
      })}
    </span>
  );
}

// One hold-to-scrub engine shared by the composer's Thinking pill and the
// Start button: press and hold, slide either axis to pick an effort, release to
// commit. Returns the trigger's pointer props plus the floating scrubber panel,
// so a caller only has to spread the props and render the node.
function useThinkingScrub({
  value,
  levels,
  onCommit,
  enabled = true,
  caption = "Thinking",
  openOnDrag = false,
  orientation = "horizontal",
}: {
  value: ThinkingLevel;
  levels: ThinkingLevel[];
  onCommit: (next: ThinkingLevel) => void;
  /** False disables the gesture entirely (agent has no reasoning knob, etc.). */
  enabled?: boolean;
  /** Small label above the level name in the floating panel. */
  caption?: string;
  /** Pill only: sideways intent opens the scrubber before the hold elapses. */
  openOnDrag?: boolean;
  /**
   * "vertical" swaps the bar upright and drives it from up/down travel only.
   * Corner-pinned triggers like Start have almost no room to swipe sideways,
   * so there the axis has to be the one the thumb can actually reach.
   */
  orientation?: "horizontal" | "vertical";
}) {
  const holdTimerRef = useRef<number | null>(null);
  const originRef = useRef({ x: 0, y: 0 });
  const axisRef = useRef<"x" | "y" | null>(null);
  const startIndexRef = useRef(0);
  const previewIndexRef = useRef(0);
  const scrubbingRef = useRef(false);
  // Whether the press currently in flight ever opened the scrubber. Any such
  // press ends in a click the browser attributes to the trigger, and that click
  // belongs to the gesture rather than to the trigger's own action — including
  // when the scrub was abandoned with Escape, where "start anyway" would be a
  // surprising thing for a cancel to do.
  const gestureOpenedRef = useRef(false);
  const suppressClickRef = useRef(false);
  // Upright bar only: measured to map the pointer onto real stop positions,
  // and a latch for "the finger has reached the bar, start tracking it".
  const barRef = useRef<HTMLDivElement | null>(null);
  const absoluteEngagedRef = useRef(false);
  const [scrubbing, setScrubbing] = useState(false);
  // The click path: a plain tap/click parks the same panel open as a normal
  // popover you can point at, so the gesture is a shortcut rather than the only
  // way in. Mirrored in a ref because pointer handlers read it synchronously.
  const [sticky, setSticky] = useState(false);
  const stickyRef = useRef(false);
  const stickyDraggingRef = useRef(false);
  // Set when a press on the trigger dismissed an open panel, so the press that
  // follows knows its click is already spent.
  const stickyDismissRef = useRef(false);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const triggerRef = useRef<HTMLElement | null>(null);
  const [previewIndex, setPreviewIndex] = useState(() => Math.max(0, levels.indexOf(value)));
  const [panelStyle, setPanelStyle] = useState<CSSProperties>({});
  const [placement, setPlacement] = useState<"above" | "below">("above");

  const currentIndex = Math.max(0, levels.indexOf(value));
  const canScrub = enabled && levels.length > 1;
  const safePreview = Math.max(0, Math.min(levels.length - 1, previewIndex));
  const previewLevel = levels[safePreview] ?? value;
  const previewProgress = levels.length > 1 ? safePreview / (levels.length - 1) : 0;
  const previewAccent = thinkingAccentColor(previewProgress);
  const vertical = orientation === "vertical";
  // Size the upright bar to the gesture's own step width so one level of finger
  // travel is one stop on screen — the thumb tracks the thumb, near enough 1:1.
  const verticalTravelPx = Math.round(
    Math.max(120, Math.min(260, (levels.length - 1) * thinkingScrubStepWidth(levels.length))),
  );

  const clearHoldTimer = () => {
    if (holdTimerRef.current != null) {
      window.clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
  };

  // Armed on press (not on scrub-open) so the drag that *opens* the scrubber is
  // swallowed too, and released on every exit path including unmount.
  const selectionGuardedRef = useRef(false);
  const guardSelection = () => {
    if (selectionGuardedRef.current) return;
    selectionGuardedRef.current = true;
    document.addEventListener("selectstart", preventThinkingDragDefault, true);
    document.addEventListener("dragstart", preventThinkingDragDefault, true);
  };
  const releaseSelectionGuard = () => {
    if (!selectionGuardedRef.current) return;
    selectionGuardedRef.current = false;
    document.removeEventListener("selectstart", preventThinkingDragDefault, true);
    document.removeEventListener("dragstart", preventThinkingDragDefault, true);
  };

  useEffect(
    () => () => {
      clearHoldTimer();
      releaseSelectionGuard();
    },
    [],
  );

  // Belt and braces for a selection already in progress when the press landed,
  // plus the grabbing cursor while the panel is up.
  useEffect(() => {
    if (!scrubbing) return;
    document.body.classList.add("thinking-scrubbing");
    return () => document.body.classList.remove("thinking-scrubbing");
  }, [scrubbing]);

  // Resync the resting preview when the level changes from elsewhere (session
  // submenu, agent-switch clamp) so the next hold opens on the truth.
  useEffect(() => {
    if (!scrubbingRef.current && !stickyDraggingRef.current) {
      previewIndexRef.current = currentIndex;
      setPreviewIndex(currentIndex);
    }
  }, [currentIndex]);

  const placePanel = (trigger: HTMLElement) => {
    const rect = trigger.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    if (vertical) {
      // Always above: the gesture travels up, so the panel has to be where the
      // thumb is heading. The bar itself is right-aligned inside the panel and
      // parked directly over the trigger, so the finger slides along the bar
      // rather than beside it; the level names hang off to its left.
      const width = 168;
      const left = Math.max(
        12,
        Math.min(window.innerWidth - width - 12, centerX + THINKING_VERTICAL_BAR_INSET - width),
      );
      const panelHeight = verticalTravelPx + 70;
      const top = Math.max(12, rect.top - panelHeight - 12);
      setPlacement("above");
      setPanelStyle({ left, top, width, transformOrigin: `${centerX - left}px 100%` });
      return;
    }
    const width = Math.min(360, Math.max(248, window.innerWidth - 24));
    const left = Math.max(12, Math.min(window.innerWidth - width - 12, centerX - width / 2));
    const panelHeight = 124;
    const above = rect.top - panelHeight - 12 >= 12;
    const top = above
      ? rect.top - panelHeight - 12
      : Math.min(window.innerHeight - panelHeight - 12, rect.bottom + 12);
    setPlacement(above ? "above" : "below");
    setPanelStyle({
      left,
      top,
      width,
      transformOrigin: `${centerX - left}px ${above ? "100%" : "0%"}`,
    });
  };

  const beginScrub = (trigger: HTMLElement) => {
    if (scrubbingRef.current) return;
    const index = Math.max(0, levels.indexOf(value));
    document.getSelection()?.removeAllRanges();
    previewIndexRef.current = index;
    axisRef.current = null;
    absoluteEngagedRef.current = false;
    scrubbingRef.current = true;
    gestureOpenedRef.current = true;
    setPreviewIndex(index);
    placePanel(trigger);
    setScrubbing(true);
    // Engage the scrub surface — heavy so the hold-to-slide is unmistakable.
    haptic("heavy");
  };

  const finishScrub = (commit: boolean) => {
    clearHoldTimer();
    if (!scrubbingRef.current) return;
    scrubbingRef.current = false;
    setScrubbing(false);
    if (commit) {
      const next = levels[previewIndexRef.current];
      // Commit always ticks success so releasing the finger is felt even when
      // the level didn't change.
      feedback.success();
      if (next) onCommit(next);
    }
  };

  const closeSticky = () => {
    if (!stickyRef.current) return;
    stickyRef.current = false;
    stickyDraggingRef.current = false;
    setSticky(false);
    previewIndexRef.current = currentIndex;
    setPreviewIndex(currentIndex);
  };

  /** Park the panel open as a plain popover, anchored to the trigger. */
  const openSticky = (trigger: HTMLElement) => {
    if (!canScrub || scrubbingRef.current) return;
    triggerRef.current = trigger;
    const index = Math.max(0, levels.indexOf(value));
    previewIndexRef.current = index;
    setPreviewIndex(index);
    placePanel(trigger);
    stickyRef.current = true;
    setSticky(true);
    haptic("light");
  };

  /** Click toggles: a second click on the trigger puts the panel away. */
  const toggleSticky = (trigger: HTMLElement) => {
    if (stickyRef.current) closeSticky();
    else openSticky(trigger);
  };

  /** Pick a level from the open popover — commits and closes. */
  const pickLevel = (level: ThinkingLevel) => {
    closeSticky();
    feedback.success();
    onCommit(level);
  };

  // Escape aborts an open scrub without committing — the only bail-out once the
  // panel is up, since the pointer is captured by the trigger. The same key puts
  // a clicked-open panel away.
  useEffect(() => {
    if (!scrubbing && !sticky) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      finishScrub(false);
      closeSticky();
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrubbing, sticky]);

  // Clicked-open panel: anything outside it dismisses. A press on the trigger
  // itself dismisses too, and marks the trailing click spent so the toggle
  // doesn't immediately reopen what this just closed.
  useEffect(() => {
    if (!sticky) return;
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (target && panelRef.current?.contains(target)) return;
      if (target && triggerRef.current?.contains(target)) {
        suppressClickRef.current = true;
        stickyDismissRef.current = true;
      }
      closeSticky();
    };
    const onDismiss = () => closeSticky();
    document.addEventListener("pointerdown", onPointerDown, true);
    window.addEventListener("resize", onDismiss);
    window.addEventListener("scroll", onDismiss, true);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown, true);
      window.removeEventListener("resize", onDismiss);
      window.removeEventListener("scroll", onDismiss, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sticky]);

  const applyScrub = (clientX: number, clientY: number) => {
    // Upright bar: the bar is parked directly over the trigger, so the finger
    // is on it. Map the pointer straight onto the bar's own stop positions —
    // the level beside your thumb is the level you get, not an accumulated
    // offset from where the press happened.
    if (vertical) {
      applyAbsoluteScrub(clientY);
      return;
    }
    // Horizontal: relative travel from the press origin, projected onto
    // whichever axis the gesture locked to. Right and up both mean "more".
    const dx = clientX - originRef.current.x;
    const dy = clientY - originRef.current.y;
    if (!axisRef.current) {
      if (Math.abs(dx) < THINKING_AXIS_LOCK_PX && Math.abs(dy) < THINKING_AXIS_LOCK_PX) return;
      axisRef.current = Math.abs(dx) >= Math.abs(dy) ? "x" : "y";
    }
    applyScrubTravel(axisRef.current === "x" ? dx : -dy);
  };

  // The panel opens above the press, so at first the finger is below the bar
  // entirely. Hold the starting level until it actually reaches the bar, then
  // track absolutely — that way a press with no real movement never changes
  // the level, and once you are on the bar the thumb sits under your finger.
  const applyAbsoluteScrub = (clientY: number) => {
    const bar = barRef.current;
    if (!bar) return;
    const rect = bar.getBoundingClientRect();
    if (rect.height <= 0) return;
    const thumbPx = Math.max(0, rect.height - verticalTravelPx);
    const lowStop = rect.bottom - thumbPx / 2;
    const highStop = rect.top + thumbPx / 2;
    if (!absoluteEngagedRef.current) {
      if (clientY > lowStop) return;
      absoluteEngagedRef.current = true;
    }
    const span = Math.max(1, lowStop - highStop);
    const ratio = Math.max(0, Math.min(1, (lowStop - clientY) / span));
    commitPreviewIndex(Math.round(ratio * (levels.length - 1)));
  };

  const applyScrubTravel = (travel: number) => {
    commitPreviewIndex(
      Math.round(startIndexRef.current + travel / thinkingScrubStepWidth(levels.length)),
    );
  };

  const commitPreviewIndex = (index: number) => {
    const nextIndex = Math.max(0, Math.min(levels.length - 1, index));
    if (nextIndex === previewIndexRef.current) return;
    previewIndexRef.current = nextIndex;
    setPreviewIndex(nextIndex);
    // Step tick — medium (not ultra-light selection) so each level stop is felt
    // on-device while scrubbing.
    haptic("medium");
  };

  // Clicked-open panel: the bar is a real slider you can point at. Absolute in
  // both orientations — the pointer starts on the bar, so the stop beside it is
  // the stop it gets, with no engage latch to wait for.
  const stickyIndexFromPoint = (clientX: number, clientY: number) => {
    const bar = barRef.current;
    if (!bar) return null;
    const rect = bar.getBoundingClientRect();
    const clamp01 = (n: number) => Math.max(0, Math.min(1, n));
    if (vertical) {
      if (rect.height <= 0) return null;
      const thumbPx = Math.max(0, rect.height - verticalTravelPx);
      const lowStop = rect.bottom - thumbPx / 2;
      const highStop = rect.top + thumbPx / 2;
      const span = Math.max(1, lowStop - highStop);
      return Math.round(clamp01((lowStop - clientY) / span) * (levels.length - 1));
    }
    if (rect.width <= 0) return null;
    const inset = Math.min(rect.width / 2, THINKING_THUMB_PX / 2);
    const span = Math.max(1, rect.width - inset * 2);
    return Math.round(clamp01((clientX - rect.left - inset) / span) * (levels.length - 1));
  };

  const trackStickyPointer = (event: React.PointerEvent<HTMLElement>) => {
    const index = stickyIndexFromPoint(event.clientX, event.clientY);
    if (index != null) commitPreviewIndex(index);
  };

  const stickyBarProps = {
    onPointerDown: (event: React.PointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      event.preventDefault();
      stickyDraggingRef.current = true;
      event.currentTarget.setPointerCapture(event.pointerId);
      trackStickyPointer(event);
    },
    onPointerMove: (event: React.PointerEvent<HTMLElement>) => {
      if (!stickyDraggingRef.current) return;
      trackStickyPointer(event);
    },
    onPointerUp: (event: React.PointerEvent<HTMLElement>) => {
      if (!stickyDraggingRef.current) return;
      stickyDraggingRef.current = false;
      trackStickyPointer(event);
      const next = levels[previewIndexRef.current];
      if (next) pickLevel(next);
    },
    onPointerCancel: () => {
      stickyDraggingRef.current = false;
    },
  };

  const pointerProps = {
    onPointerDown: (event: React.PointerEvent<HTMLElement>) => {
      if (!canScrub || event.button !== 0) return;
      clearHoldTimer();
      originRef.current = { x: event.clientX, y: event.clientY };
      axisRef.current = null;
      // A fresh press: nothing to suppress until this one opens a scrubber —
      // unless this very press just dismissed an open panel, in which case its
      // click is already spent and must not toggle the panel back open.
      gestureOpenedRef.current = false;
      suppressClickRef.current = stickyDismissRef.current;
      stickyDismissRef.current = false;
      startIndexRef.current = currentIndex;
      guardSelection();
      event.currentTarget.setPointerCapture(event.pointerId);
      // Immediate light tick inside the user-gesture window (iOS often blocks
      // vibrate/switch haptics that fire only after the hold timeout).
      haptic("light");
      const trigger = event.currentTarget;
      holdTimerRef.current = window.setTimeout(() => beginScrub(trigger), THINKING_HOLD_MS);
    },
    onPointerMove: (event: React.PointerEvent<HTMLElement>) => {
      if (!scrubbingRef.current) {
        if (!openOnDrag || holdTimerRef.current == null) return;
        // Horizontal intent opens the slider immediately (no menu to protect).
        if (Math.abs(event.clientX - originRef.current.x) <= 8) return;
        clearHoldTimer();
        beginScrub(event.currentTarget);
        applyScrub(event.clientX, event.clientY);
        event.preventDefault();
        return;
      }
      event.preventDefault();
      applyScrub(event.clientX, event.clientY);
    },
    onPointerUp: (event: React.PointerEvent<HTMLElement>) => {
      clearHoldTimer();
      releaseSelectionGuard();
      // Set even when Escape already closed the panel, so an aborted scrub
      // swallows its trailing click instead of falling through to the trigger.
      if (!gestureOpenedRef.current) return;
      event.preventDefault();
      suppressClickRef.current = true;
      finishScrub(true);
    },
    // A cancelled pointer (scroll takeover, palm rejection) fires no click.
    onPointerCancel: () => {
      clearHoldTimer();
      releaseSelectionGuard();
      finishScrub(false);
    },
    onContextMenu: (event: React.MouseEvent) => {
      if (canScrub) event.preventDefault();
    },
  };

  /** True once per gesture-release, so callers can swallow the trailing click. */
  const consumeSuppressedClick = () => {
    if (!suppressClickRef.current) return false;
    suppressClickRef.current = false;
    return true;
  };

  /** Keyboard equivalent of one scrub step. */
  const nudge = (delta: number) => {
    if (!canScrub) return;
    const next = levels[Math.max(0, Math.min(levels.length - 1, currentIndex + delta))];
    if (!next || next === value) return;
    feedback.select();
    onCommit(next);
  };

  const panel = scrubbing || sticky
    ? createPortal(
        <div
          ref={panelRef}
          role="status"
          aria-live="polite"
          aria-label={`${caption} ${previewLevel}`}
          style={panelStyle}
          className={cn(
            "fixed z-[220] select-none animate-in fade-in-0 zoom-in-90 duration-200",
            // A gesture panel is pure readout under a captured pointer; a
            // clicked-open one is the control itself, so it takes the pointer.
            sticky ? "pointer-events-auto" : "pointer-events-none",
            placement === "above"
              ? "origin-bottom slide-in-from-bottom-2"
              : "origin-top slide-in-from-top-2",
          )}
        >
          <div className="thinking-scrubber-panel" data-orientation={orientation}>
            <div className="thinking-scrubber-caption">
              <span className="thinking-scrubber-caption-label">{caption}</span>
              <span
                className="thinking-scrubber-caption-value transition-colors duration-150"
                style={{ color: previewAccent }}
              >
                {thinkingLevelLabel(previewLevel)}
              </span>
            </div>
            <div className="thinking-scrubber-body">
              <div
                ref={barRef}
                className="thinking-scrubber"
                data-orientation={orientation}
                data-interactive={sticky ? "" : undefined}
                {...(sticky ? stickyBarProps : {})}
                style={
                  {
                    "--thinking-progress": previewProgress,
                    "--thinking-accent": previewAccent,
                    ...(vertical ? { "--thinking-travel": `${verticalTravelPx}px` } : {}),
                    ...(sticky ? { touchAction: "none", cursor: "pointer" } : {}),
                  } as CSSProperties
                }
              >
                <span aria-hidden="true" className="thinking-scrubber-halo" />
                <div className="thinking-scrubber-track">
                  <div aria-hidden="true" className="thinking-scrubber-matrix" />
                  <div className="thinking-scrubber-fill" />
                </div>
                {/* One stop per level, so the number of steps and where you are
                    in them is readable even when the names don't all fit. */}
                <span aria-hidden="true" className="thinking-scrubber-ticks">
                  {levels.map((level, index) => (
                    <span
                      key={level}
                      data-passed={index <= safePreview ? "" : undefined}
                      style={thinkingStopOffset(index, levels.length, vertical)}
                    />
                  ))}
                </span>
                <span aria-hidden="true" className="thinking-scrubber-thumb" />
              </div>
              {/* Upright: every stop is named beside the bar, pinned to the
                  exact height its tick sits at, so the label under your thumb
                  is the one you are about to commit. */}
              {vertical ? (
                <div className="thinking-scrubber-stops">
                  {levels.map((level, index) => {
                    const stopStyle = {
                      ...thinkingStopOffset(index, levels.length, true),
                      ...(index === safePreview ? { color: previewAccent } : {}),
                    };
                    // Clicked open, every named stop is a target you can just
                    // hit — no travel, no release timing.
                    return sticky ? (
                      <button
                        key={level}
                        type="button"
                        data-active={index === safePreview ? "" : undefined}
                        style={stopStyle}
                        onPointerEnter={() => commitPreviewIndex(index)}
                        onClick={() => pickLevel(level)}
                      >
                        {thinkingLevelLabel(level)}
                      </button>
                    ) : (
                      <span
                        key={level}
                        data-active={index === safePreview ? "" : undefined}
                        style={stopStyle}
                      >
                        {thinkingLevelLabel(level)}
                      </span>
                    );
                  })}
                </div>
              ) : null}
            </div>
            {/* Clicked open, the row names every level and each one is a button.
                During a gesture it is a readout: every stop while they fit, and
                past ~5 just the two endpoints so the labels never overlap. */}
            {vertical ? null : sticky ? (
              <div className="thinking-scrubber-picks">
                {levels.map((level, index) => (
                  <button
                    key={level}
                    type="button"
                    data-active={index === safePreview ? "" : undefined}
                    style={index === safePreview ? { color: previewAccent } : undefined}
                    onPointerEnter={() => commitPreviewIndex(index)}
                    onClick={() => pickLevel(level)}
                  >
                    {thinkingLevelLabel(level)}
                  </button>
                ))}
              </div>
            ) : (
              <div className="thinking-scrubber-ends">
                {(levels.length <= 5 ? levels : [levels[0]!, levels[levels.length - 1]!]).map(
                  (level) => (
                    <span
                      key={level}
                      data-active={level === previewLevel ? "" : undefined}
                      style={level === previewLevel ? { color: previewAccent } : undefined}
                    >
                      {thinkingLevelLabel(level)}
                    </span>
                  ),
                )}
              </div>
            )}
          </div>
        </div>,
        document.body,
      )
    : null;

  return {
    scrubbing,
    sticky,
    previewLevel,
    previewAccent,
    pointerProps,
    consumeSuppressedClick,
    toggleSticky,
    nudge,
    panel,
  };
}

// Session composers: click (or hold, or slide) to open the effort scrubber —
// no dropdown menu. A plain click parks the slider open as a popover you point
// at and click; hold-and-slide is the one-motion shortcut; arrow keys work once
// the pill has focus.
function ComposerThinkingControl({
  value,
  levels,
  onChange,
  flat,
}: {
  value: ThinkingLevel;
  levels: ThinkingLevel[];
  onChange: (value: ThinkingLevel) => void;
  flat: boolean;
}) {
  const scrub = useThinkingScrub({
    value,
    levels,
    onCommit: onChange,
    openOnDrag: true,
  });
  const currentIndex = Math.max(0, levels.indexOf(value));
  // The pill reads out the level under the finger while a scrub is open, so
  // the trigger and the floating panel never disagree.
  const shown = scrub.scrubbing || scrub.sticky ? scrub.previewLevel : value;

  return (
    <>
      <button
        type="button"
        role="slider"
        aria-label="Thinking effort"
        aria-valuemin={0}
        aria-valuemax={Math.max(0, levels.length - 1)}
        aria-valuenow={currentIndex}
        aria-valuetext={value}
        aria-expanded={scrub.sticky}
        title="Click for the slider — or hold and slide, or use the arrow keys"
        {...scrub.pointerProps}
        onClick={(event) => {
          // A press that opened the scrubber ends in a click of its own; that
          // click belongs to the gesture, not to the trigger.
          if (scrub.consumeSuppressedClick()) return;
          scrub.toggleSticky(event.currentTarget);
        }}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") return;
          // Standard slider keys, so the control is reachable without a
          // pointer at all (the gesture used to be the only way in).
          const step =
            event.key === "ArrowRight" || event.key === "ArrowUp"
              ? 1
              : event.key === "ArrowLeft" || event.key === "ArrowDown"
                ? -1
                : event.key === "Home"
                  ? -levels.length
                  : event.key === "End"
                    ? levels.length
                    : 0;
          if (!step) return;
          event.preventDefault();
          scrub.nudge(step);
        }}
        style={{
          touchAction: "none",
          userSelect: "none",
          WebkitUserSelect: "none",
          WebkitTouchCallout: "none",
        } as CSSProperties}
        className={cn(
          "relative inline-flex h-8 cursor-pointer select-none items-center gap-1.5 rounded-full text-foreground outline-none transition-all duration-200 focus-visible:ring-2 focus-visible:ring-ring active:scale-[0.98]",
          flat ? "px-1" : "bg-muted px-3",
          (scrub.scrubbing || scrub.sticky) && "scale-[1.02] bg-foreground/10",
        )}
      >
        <ThinkingSignal value={shown} levels={levels} />
        <span className="text-xs font-medium">Thinking</span>
        <span aria-hidden="true" className="text-[11px] text-muted-foreground/60">·</span>
        <span
          className={cn(
            "max-w-14 truncate text-[11px] font-medium capitalize transition-colors duration-150",
            scrub.scrubbing ? "text-foreground" : "text-muted-foreground",
          )}
          style={scrub.scrubbing ? { color: scrub.previewAccent } : undefined}
        >
          {thinkingLevelLabel(shown)}
        </span>
      </button>

      {scrub.panel}
    </>
  );
}

// The composer's Start button. A tap submits at the current effort; holding it
// raises the same thinking scrubber the pill uses, and releasing sets the level
// and launches in one motion — so picking a deeper effort never costs a second
// trip to the controls row.
function ComposerStartButton({
  disabled,
  thinkingLevel,
  thinkingLevels,
  onLaunch,
}: {
  disabled: boolean;
  thinkingLevel: ThinkingLevel;
  /** Empty when the selected agent has no reasoning knob — hold does nothing. */
  thinkingLevels: ThinkingLevel[];
  onLaunch: (thinking: ThinkingLevel) => void;
}) {
  const scrub = useThinkingScrub({
    value: thinkingLevel,
    levels: thinkingLevels,
    enabled: !disabled,
    caption: "Start thinking",
    // Start is pinned to the bottom-right corner with no room to swipe
    // sideways, so its scrubber stands upright and reads up/down travel.
    orientation: "vertical",
    onCommit: (next) => onLaunch(next),
  });
  const holdable = !disabled && thinkingLevels.length > 1;

  return (
    <>
      <Button
        type="submit"
        size="sm"
        variant="secondary"
        disabled={disabled}
        aria-label={
          holdable
            ? `Start session. Hold and slide up to set thinking effort, currently ${thinkingLevel}.`
            : "Start session"
        }
        title={holdable ? "Tap to start · hold and slide up for thinking effort" : undefined}
        {...scrub.pointerProps}
        onClick={(event) => {
          // A scrub release already launched with its own level; the click the
          // browser fires afterwards would submit a second time.
          if (scrub.consumeSuppressedClick()) {
            event.preventDefault();
            event.stopPropagation();
          }
        }}
        style={
          {
            ...(holdable
              ? {
                  touchAction: "none",
                  userSelect: "none",
                  WebkitUserSelect: "none",
                  WebkitTouchCallout: "none",
                }
              : {}),
          } as CSSProperties
        }
      >
        {/* The button stays exactly as it is during a scrub — no ring, scale,
            icon or label swap. The floating panel carries the live level. */}
        <Send className="size-4" />
        <span>Start</span>
      </Button>

      {scrub.panel}
    </>
  );
}

function ModelPicker({
  value,
  models,
  onChange,
  flat = false,
  width = "max-w-36",
  onMobileLayerOpenChange,
}: {
  value: string;
  models: string[];
  onChange: (value: string) => void;
  flat?: boolean;
  width?: string;
  onMobileLayerOpenChange?: (open: boolean) => void;
}) {
  const isMobile = useIsMobile();
  const [open, setOpen] = useState(false);
  const [mobileMounted, setMobileMounted] = useState(false);
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const mobileTransitionMs = 360;
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return models;
    return models.filter((item) => item.toLowerCase().includes(q));
  }, [models, query]);
  const searchable = models.length > 8;

  useEffect(() => {
    if (!open) setQuery("");
  }, [open]);
  useEffect(() => {
    if (!open || !isMobile) return;
    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isMobile, open]);
  useEffect(() => {
    if (!isMobile) {
      setMobileMounted(false);
      return;
    }
    if (open) {
      setMobileMounted(true);
      return;
    }

    const timer = window.setTimeout(() => setMobileMounted(false), mobileTransitionMs);
    return () => window.clearTimeout(timer);
  }, [isMobile, open]);
  useEffect(() => {
    onMobileLayerOpenChange?.(isMobile && mobileMounted);
  }, [isMobile, mobileMounted, onMobileLayerOpenChange]);
  useEffect(() => {
    return () => onMobileLayerOpenChange?.(false);
  }, [onMobileLayerOpenChange]);

  const choose = (item: string) => {
    onChange(item);
    setOpen(false);
  };

  const triggerClass = cn(
    "inline-flex min-w-0 cursor-pointer items-center gap-1.5 rounded-full text-foreground transition active:scale-[0.98]",
    isMobile ? "h-11" : "h-8",
    flat ? (isMobile ? "px-2" : "px-1") : isMobile ? "bg-muted px-4" : "bg-muted px-3",
  );

  const trigger = (
    <button
      type="button"
      aria-label="Model"
      aria-haspopup="dialog"
      aria-expanded={open}
      className={triggerClass}
    >
      <span className={cn("truncate text-xs font-medium", isMobile && "text-sm", width)}>
        {value || "model"}
      </span>
      <ChevronDown className={cn("shrink-0 text-muted-foreground/70", isMobile ? "size-4" : "size-3")} />
    </button>
  );

  const search = searchable ? (
    <div className="relative">
      <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
      <input
        ref={inputRef}
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        onKeyDown={(event) => {
          event.stopPropagation();
          if (event.key === "Escape") setOpen(false);
          if (event.key === "Enter" && filtered[0]) choose(filtered[0]);
        }}
        placeholder="Filter models"
        className="h-10 w-full rounded-xl border border-border bg-background pl-9 pr-3 text-sm outline-none transition-colors placeholder:text-muted-foreground focus:border-foreground/30"
      />
    </div>
  ) : null;

  const list = (
    <div className={cn("overflow-y-auto pr-1", isMobile ? "max-h-[52dvh]" : "max-h-72")}>
      {filtered.length ? (
        filtered.map((item) => {
          const selected = value === item;
          return (
            <button
              key={item}
              type="button"
              onClick={() => choose(item)}
              className={cn(
                "flex w-full min-w-0 items-center gap-3 rounded-xl px-3 text-left text-sm outline-none transition-colors",
                isMobile ? "h-12" : "h-10",
                selected
                  ? "bg-primary/12 text-foreground ring-1 ring-inset ring-primary/20"
                  : cn("text-foreground focus-visible:bg-muted", !isMobile && "hover:bg-muted"),
              )}
            >
              <Check className={cn("size-4 shrink-0 text-primary", selected ? "opacity-100" : "opacity-0")} />
              <span className="min-w-0 flex-1 truncate">{item}</span>
            </button>
          );
        })
      ) : (
        <div className="px-3 py-8 text-center text-sm text-muted-foreground">
          No matching models
        </div>
      )}
    </div>
  );

  if (isMobile) {
    return (
      <>
        <button
          type="button"
          aria-label="Model"
          aria-haspopup="dialog"
          aria-expanded={open}
          onClick={() => setOpen(true)}
          className={triggerClass}
        >
          <span className={cn("truncate text-sm font-medium", width)}>
            {value || "model"}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground/70" />
        </button>
        {mobileMounted ? (
          <VaulDrawer.Root
            open={open}
            onOpenChange={setOpen}
            repositionInputs={false}
            shouldScaleBackground={false}
          >
            <VaulDrawer.Portal>
              <VaulDrawer.Overlay className="fixed inset-0 z-[179] bg-black/80" />
              <VaulDrawer.Content
                data-slot="model-picker-drawer-content"
                className="fixed inset-x-0 bottom-0 z-[180] mx-auto flex max-h-[82dvh] max-w-lg select-none flex-col rounded-t-[2rem] border border-border bg-background p-4 pb-[max(var(--lfg-safe-bottom),1rem)] text-foreground shadow-2xl outline-none"
                aria-label="Model"
              >
                <div className="mx-auto mb-3 h-1.5 w-24 shrink-0 rounded-full bg-muted" />
                <VaulDrawer.Title className="mb-3 text-base font-semibold">
                  Model
                </VaulDrawer.Title>
                <div className="min-h-0 space-y-3">
                  {search}
                  {list}
                </div>
              </VaulDrawer.Content>
            </VaulDrawer.Portal>
          </VaulDrawer.Root>
        ) : null}
      </>
    );
  }
  return (
    <Popover.Root open={open} onOpenChange={setOpen}>
      <Popover.Trigger render={trigger} />
      <Popover.Portal>
        <Popover.Positioner
          side="bottom"
          align="start"
          sideOffset={6}
          className="isolate z-[170] outline-none"
        >
          <Popover.Popup
            initialFocus={searchable ? inputRef : true}
            className="w-80 max-w-[calc(100vw-1rem)] rounded-2xl border border-border bg-popover p-2 text-popover-foreground shadow-2xl ring-1 ring-foreground/5 outline-none"
          >
            <div className="space-y-2">
              {search}
              {list}
            </div>
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );
}

/**
 * Agent + model + thinking row for the auto-agent sheets and the finding sheet.
 *
 * It renders the SAME strip as the new-session composer and the fork dialog,
 * off the same catalog and with the same per-account Claude chips. Pass
 * `scheduledOnly` when the choice is going onto a cron, which is the only place
 * the roster legitimately narrows.
 */
function AgentModelRow<K extends AgentKind>({
  backend,
  setBackend,
  model,
  setModel,
  thinkingLevel,
  setThinkingLevel,
  codingAgents,
  claudeAccountId = "",
  setClaudeAccountId,
  scheduledOnly,
}: {
  backend: K;
  setBackend: (v: K) => void;
  model: string;
  setModel: (v: string) => void;
  thinkingLevel: ThinkingLevel;
  setThinkingLevel: (v: ThinkingLevel) => void;
  codingAgents?: CodingAgentInfo[];
  claudeAccountId?: string;
  setClaudeAccountId?: (v: string) => void;
  /**
   * Required, not optional-with-a-default: `K` and this flag have to agree, and
   * a call site that narrows `K` to AutoAgentBackend but forgets the flag would
   * hand pi/copilot to a setter that can't take them. Making it a conscious
   * choice is what justifies the cast below.
   */
  scheduledOnly: boolean;
}) {
  const catalog = useAgentModelCatalog();
  const accessMode = useContext(AgentAccessModeContext);
  const models = useAgentModels(backend);
  const thinkingLevels = useAgentThinkingLevels(backend);
  const defaultModelFor = (key: AgentKind) =>
    catalog.defaults[key] ?? AGENT_DEFAULT_MODEL[key];
  // The catalog is keyed by the full AgentKind union; `scheduledOnly` narrows it
  // to exactly the keys K allows, which the type system can't see through the
  // filter. Every onSelect key therefore comes back as K by construction.
  const visibleOptions = useMemo(
    () =>
      configuredLaunchOptions(codingAgents, accessMode, { scheduledOnly }) as unknown as (
        AgentLaunchOption & { key: K }
      )[],
    [accessMode, codingAgents, scheduledOnly],
  );

  const selectedLaunchId =
    backend === "aisdk" && claudeAccountId ? `aisdk:${claudeAccountId}` : backend;

  useEffect(() => {
    if (visibleOptions.some((option) => option.key === backend)) return;
    const next = visibleOptions[0]?.key;
    if (!next) return;
    setBackend(next);
    setModel(defaultModelFor(next));
  }, [backend, setBackend, setModel, visibleOptions]);

  // A pinned account that is no longer connected falls back to Claude · Auto —
  // that is the first `aisdk` option and it carries no accountId — so the strip
  // never renders with nothing selected.
  useEffect(() => {
    if (!setClaudeAccountId) return;
    if (backend !== "aisdk") return;
    if (visibleOptions.some((option) => (option.selectorId ?? option.key) === selectedLaunchId))
      return;
    const firstClaude = visibleOptions.find((option) => option.key === "aisdk");
    setClaudeAccountId(firstClaude?.accountId ?? "");
  }, [backend, selectedLaunchId, setClaudeAccountId, visibleOptions]);

  useEffect(() => {
    if (thinkingLevels.length && !thinkingLevels.includes(thinkingLevel)) {
      setThinkingLevel(thinkingLevels.includes("high") ? "high" : thinkingLevels[0]);
    }
  }, [setThinkingLevel, thinkingLevel, thinkingLevels]);

  return (
    <div className="mt-2 flex flex-wrap items-center gap-1.5">
      {!visibleOptions.length ? (
        <span className="text-xs text-muted-foreground">No configured coding agents</span>
      ) : null}
      <AgentIconStrip
        options={visibleOptions}
        value={backend}
        selectedId={selectedLaunchId}
        onSelect={(key, option) => {
          setBackend(key);
          setClaudeAccountId?.(key === "aisdk" ? option?.accountId ?? "" : "");
          setModel(defaultModelFor(key));
        }}
      />

      <ModelPicker value={model} models={models} onChange={setModel} width="max-w-28" />

      <ThinkingLevelPill
        agent={backend}
        value={thinkingLevel}
        levels={thinkingLevels}
        onChange={setThinkingLevel}
        immersive
      />
    </div>
  );
}

// ---------- auto agents: sheets + manage view ----------

// Bottom sheet built on the shadcn Drawer (vaul) primitive — gives us the drag
// handle, focus trap, escape-to-close, and overlay for free, matching the rest
// of the app's UI kit. `title` feeds the a11y-required (visually hidden) label.
function BottomSheet({
  onClose,
  title,
  page = false,
  expandOnFocus = true,
  footer,
  children,
}: {
  onClose: () => void;
  title: string;
  /** Morph from a content-sized card into a full-height page. See the
   *  `.lfg-sheet-page` rule in index.css for what that means geometrically —
   *  the short version is that the sheet claims the band above the keyboard so
   *  the footer lands on it instead of being shoved off-screen. */
  page?: boolean;
  /** Enter page mode by itself whenever a field inside the sheet takes focus,
   *  instead of the caller deciding up front. A content-sized card cannot win
   *  against the soft keyboard — it gets shoved off the top — and the caller
   *  usually cannot know in advance whether this particular visit will involve
   *  typing. FindingSheet has driven `page` from focus by hand since page mode
   *  landed; this is that behaviour made available to every sheet, so the
   *  auto-agent forms stop being the ones that still fight the keyboard. */
  expandOnFocus?: boolean;
  /** Pinned to the bottom of the sheet: in page mode this is what ends up
   *  sitting directly on the keyboard, so it should hold the field the user is
   *  typing into and its actions — nothing that scrolls. */
  footer?: ReactNode;
  children: ReactNode;
}) {
  return (
    <Drawer
      open
      // The viewport already shrinks around the mobile keyboard. Vaul's input
      // repositioning applies a second offset, which can push the focused auto-
      // agent field (and the rest of the sheet) out of the visible viewport.
      repositionInputs={false}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DrawerContent
        // Bottom sheets can be launched from the full-screen chat layer (z-90).
        // Keep both the scrim and sheet above it without raising every Drawer in
        // the app, since page-level drawers intentionally sit below some screens.
        overlayClassName="z-[100]"
        className="z-[100]"
        // The morph lives in DrawerContent now, so every drawer in the app has
        // it. `page` still lets a caller force it; `expandOnFocus` is kept as
        // an explicit opt-out for sheets with no fields.
        page={page}
        expandOnFocus={expandOnFocus}
      >
        <DrawerTitle className="sr-only">{title}</DrawerTitle>
        {/* min-h-0 twice on purpose: without it a flex child refuses to shrink
            below its content, and the body would push the footer out of the
            sheet instead of scrolling under it. */}
        {/* flex-auto, not flex-1: with a `0%` basis these children contribute
            nothing to an auto-height sheet, and how much a flex container then
            resolves from their content is exactly where engines disagree. A
            content basis sizes the compact card off its content everywhere, and
            still fills (and shrinks, hence min-h-0) once page mode fixes the
            height. */}
        <div className="flex min-h-0 flex-auto flex-col">
          {/* flex-col on the scroller so a caller can `mt-auto` its content to
              sit against the footer. Deliberately margin-auto and not
              justify-end: a flex-end scroll container clips its own overflow at
              the top, and this one overflows the moment the keyboard is up. */}
          <div className="flex min-h-0 flex-auto flex-col overflow-y-auto overscroll-contain">
            {children}
          </div>
          {footer ? <div className="shrink-0">{footer}</div> : null}
        </div>
      </DrawerContent>
    </Drawer>
  );
}

function FindingSheet({
  finding,
  agentName,
  sourceAgent,
  codingAgents,
  onClose,
  onReply,
  onDismiss,
  onRefineAgent,
}: {
  finding: AutoFinding;
  agentName: string;
  sourceAgent?: AutoAgent;
  codingAgents?: CodingAgentInfo[];
  onClose: () => void;
  onReply: (
    f: AutoFinding,
    text: string,
    opts?: {
      agent?: AgentKind;
      model?: string;
      thinkingLevel?: string;
      claudeAccountId?: string;
    },
  ) => Promise<void>;
  onDismiss: (f: AutoFinding) => void;
  onRefineAgent?: (f: AutoFinding, feedback: string) => void;
}) {
  const defaultModel = useAgentDefaultModel(sourceAgent?.agent ?? "aisdk");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  // Everything that isn't the finding itself starts folded away. The sheet's
  // job is to be read in one glance: which agent, what it found, what it
  // suggests. Launch settings and the long tail of reasoning are one tap deep.
  const [showSettings, setShowSettings] = useState(false);
  const [showAllReasoning, setShowAllReasoning] = useState(false);
  const [tuning, setTuning] = useState(false);
  const [feedbackText, setFeedbackText] = useState("");
  // The composer is behind a button now. Opening the sheet with a focused field
  // meant the keyboard covered the finding you came to read, on a surface whose
  // most common answer is the one-tap "Make the change" — no typing at all.
  const [instructing, setInstructing] = useState(false);
  const feedbackRef = useRef<HTMLTextAreaElement>(null);
  const footerRef = useRef<HTMLDivElement>(null);
  // Graduating a finding starts an ordinary session, so the picker below offers
  // the whole roster — not just the backends a cron'd auto agent can run. It
  // only *starts* on the originating agent's backend.
  const [backend, setBackend] = useState<AgentKind>(sourceAgent?.agent ?? "aisdk");
  const [claudeAccountId, setClaudeAccountId] = useState(sourceAgent?.claudeAccountId ?? "");
  const [model, setModel] = useState(
    sourceAgent?.model ?? defaultModel,
  );
  const [thinkingLevel, setThinkingLevel] = useState<ThinkingLevel>(
    (sourceAgent?.thinkingLevel as ThinkingLevel | undefined) ?? savedThinkingLevel(),
  );
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const backendModels = useAgentModels(backend);
  const backendDefaultModel = useAgentDefaultModel(backend);
  const supportsThinking = agentSupportsThinking(backend);

  useEffect(() => {
    if (!backendModels.includes(model)) setModel(backendDefaultModel);
  }, [backendDefaultModel, backendModels, model]);

  // The pin is seeded from the source agent, which may name an account that has
  // since been removed or signed out. Launching with a dead id is a hard 400
  // ("Claude account is missing or not connected"), which would make every
  // finding from that agent ungraduatable — and the settings row's own reset
  // can't help, because it only runs once you tap the row open. Degrade to
  // Claude · Auto instead, matching what the scheduled runner does with a dead
  // pin rather than failing the one-tap path.
  const connectedClaudeAccountIds = useMemo(
    () =>
      new Set(
        (codingAgents?.find((agent) => agent.key === "aisdk")?.status.accounts ?? [])
          .filter((account) => account.connected)
          .map((account) => account.id),
      ),
    [codingAgents],
  );
  const livePin =
    claudeAccountId && connectedClaudeAccountIds.has(claudeAccountId) ? claudeAccountId : "";

  const launchOpts = (): {
    agent: AgentKind;
    model: string;
    thinkingLevel?: string;
    claudeAccountId?: string;
  } => ({
    agent: backend,
    model,
    thinkingLevel: supportsThinking ? thinkingLevel : undefined,
    claudeAccountId: backend === "aisdk" ? livePin || undefined : undefined,
  });

  // Page mode. The sheet stops being a card sized by its content and becomes a
  // full-height surface whose body scrolls under a pinned footer, so the
  // keyboard has something sane to push against instead of shoving the finding
  // off the top of the screen. Any field taking focus enters it — the reveal
  // buttons below just do that by focusing what they open.
  const [paged, setPaged] = useState(false);
  const exitTimer = useRef<number | null>(null);
  const cancelExit = () => {
    if (exitTimer.current !== null) {
      window.clearTimeout(exitTimer.current);
      exitTimer.current = null;
    }
  };
  useEffect(() => cancelExit, []);

  // Leaving the last field folds the sheet back down — but only if nothing was
  // typed, so work in progress can't vanish under someone dismissing the
  // keyboard to read the finding again. The delay (and the pointer-down
  // cancel below) is what keeps a tap on the footer's own buttons from
  // unmounting them between blur and click.
  function scheduleExit() {
    cancelExit();
    exitTimer.current = window.setTimeout(() => {
      exitTimer.current = null;
      const root = footerRef.current?.closest("[data-slot=drawer-content]");
      if (root && root.contains(deepActiveElement())) return;
      if (text.trim() || feedbackText.trim()) return;
      setPaged(false);
      setInstructing(false);
      setTuning(false);
    }, 260);
  }

  // Reveal a field and put the cursor in it. The rAF lets the footer swap and
  // the sheet start its height morph first; focusing a node that is still being
  // laid out is what makes iOS scroll the wrong thing under the keyboard.
  function reveal(which: "instruct" | "tune") {
    cancelExit();
    setPaged(true);
    if (which === "instruct") setInstructing(true);
    else setTuning(true);
    requestAnimationFrame(() => {
      window.setTimeout(() => {
        (which === "instruct" ? inputRef : feedbackRef).current?.focus();
      }, 60);
    });
  }

  // `override` carries the freshly dictated text: the mic's auto-submit fires
  // in the same tick as setText, so the closed-over `text` is still stale.
  async function send(override?: string) {
    const t = (override ?? text).trim();
    if (!t || busy) return;
    setBusy(true);
    logFindingAction(finding.id, "reply", true);
    try {
      await onReply(finding, t, launchOpts());
    } finally {
      setBusy(false);
    }
  }

  // One-tap path: graduate the finding into a session that immediately acts on
  // the agent's suggested fix, with no typing required. Only offered in the
  // empty state — once the user types, the composer send IS this action (same
  // onReply call), so we collapse to the single ArrowUp affordance.
  async function execute() {
    if (busy) return;
    setBusy(true);
    logFindingAction(finding.id, "execute", !!text.trim());
    try {
      await onReply(
        finding,
        text.trim() || "Go ahead and implement this fix now.",
        launchOpts(),
      );
    } finally {
      setBusy(false);
    }
  }

  async function copyReference() {
    try {
      await copyMessageText(findingReference(finding, agentName));
      logFindingAction(finding.id, "copy", !!text.trim());
      toast.success("Finding reference copied");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Could not copy finding reference");
    }
  }

  // Feedback is about the agent, not this row: hand it to the parent, which
  // rewrites the agent's standing instruction and closes the sheet.
  function submitFeedback() {
    const t = feedbackText.trim();
    if (!t || busy || !onRefineAgent) return;
    logFindingAction(finding.id, "feedback", !!text.trim());
    onRefineAgent(finding, t);
  }

  const REASONING_PREVIEW = 3;
  const reasoning = finding.reasoning;
  const shownReasoning =
    showAllReasoning || reasoning.length <= REASONING_PREVIEW + 1
      ? reasoning
      : reasoning.slice(0, REASONING_PREVIEW);
  const hiddenReasoning = reasoning.length - shownReasoning.length;
  const settingsSummary = [model, supportsThinking ? `${thinkingLevel} thinking` : null]
    .filter(Boolean)
    .join(" · ");

  // Launch settings, folded to one line of text. Lives just above whatever the
  // footer's primary control is, in both modes, because it describes what that
  // control is about to run.
  const settingsRow = (
    <div className="px-1 pb-2">
      <button
        type="button"
        onClick={() => setShowSettings((v) => !v)}
        aria-expanded={showSettings}
        className="flex max-w-full items-center gap-1 text-[11.5px] text-muted-foreground/80 hover:text-muted-foreground"
      >
        <span className="truncate">{settingsSummary}</span>
        <ChevronDown
          className={cn("size-3 shrink-0 transition-transform", showSettings && "rotate-180")}
        />
      </button>
      {showSettings ? (
        <AgentModelRow
          backend={backend}
          setBackend={setBackend}
          model={model}
          setModel={setModel}
          thinkingLevel={thinkingLevel}
          setThinkingLevel={setThinkingLevel}
          codingAgents={codingAgents}
          claudeAccountId={livePin}
          setClaudeAccountId={setClaudeAccountId}
          scheduledOnly={false}
        />
      ) : null}
    </div>
  );

  const footer = (
    <div
      ref={footerRef}
      className="px-2 pb-1 pt-2"
      // A tap heading for one of the footer's own buttons must not be read as
      // "left the field" — the blur lands first and would unmount the button
      // before its click.
      onPointerDownCapture={cancelExit}
      onFocusCapture={(e) => {
        if (isTypingTarget(e.target as Element)) {
          cancelExit();
          setPaged(true);
        }
      }}
      onBlurCapture={scheduleExit}
    >
      {tuning ? (
        /* Feedback goes to the AGENT, not this finding: what the user types
           here is folded into the agent's standing instruction, so the next
           scheduled run behaves differently. */
        <div className="rounded-2xl border border-border/70 bg-muted/30 p-3">
          <div className="flex items-center gap-2 text-[13px] font-semibold">
            <SlidersHorizontal className="size-4 text-primary" />
            <span className="truncate">Tune {agentName}</span>
          </div>
          <p className="mt-1 text-xs leading-relaxed text-muted-foreground">
            Say what it should do differently. This rewrites the agent's instruction for every
            future run — it doesn't touch this finding.
          </p>
          <Textarea
            ref={feedbackRef}
            value={feedbackText}
            onChange={(e) => setFeedbackText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                submitFeedback();
              }
            }}
            rows={3}
            placeholder="e.g. stop flagging cosmetic nits — only surface things that break the build"
            className="mt-2.5 min-h-[4.5rem] bg-background/60 text-base"
          />
          <div className="mt-2.5 flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              className="text-muted-foreground"
              onClick={() => {
                setFeedbackText("");
                setTuning(false);
                setPaged(false);
              }}
            >
              Cancel
            </Button>
            <Button
              variant="brand"
              size="sm"
              className="flex-1"
              disabled={busy || !feedbackText.trim()}
              onClick={submitFeedback}
            >
              <Check className="size-4" />
              Update agent
            </Button>
          </div>
        </div>
      ) : instructing ? (
        <>
          {settingsRow}
          {/* Same field treatment as the new-session composer: gradient-edge
              gfield, mic dictation, ⌘↵ to send. In page mode this row is what
              sits on top of the keyboard. */}
          <div className="lfg-gfield flex items-center gap-1.5 rounded-2xl px-2.5 py-2">
            <SkillTextarea
              textareaRef={inputRef}
              value={text}
              onValueChange={setText}
              onKeyDown={(e) => {
                if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                  e.preventDefault();
                  void send();
                }
              }}
              rows={1}
              placeholder="Type to start a session…"
              // text-base (16px) on mobile keeps iOS from auto-zooming the
              // viewport on focus.
              className="max-h-28 min-h-9 flex-1 resize-none overflow-y-auto border-0 bg-transparent px-1 py-1.5 text-base leading-relaxed shadow-none focus-visible:border-0 focus-visible:ring-0"
            />
            <MicButton
              minimal
              className="size-9 shrink-0"
              silenceMs={2500}
              baseText={text}
              onText={(spoken, base) => setText(base.trim() ? `${base.trimEnd()} ${spoken}` : spoken)}
              onInterim={(spoken, base) =>
                setText(base.trim() ? `${base.trimEnd()} ${spoken}` : spoken)
              }
              onAutoSubmit={(spoken, base) => {
                const combined = base.trim() ? `${base.trimEnd()} ${spoken}` : spoken;
                setText(combined);
                void send(combined);
              }}
              onCancel={(base) => setText(base)}
            />
            <Button
              size="icon-sm"
              variant="brand"
              disabled={busy || !text.trim()}
              onClick={() => void send()}
            >
              {busy ? <Loader2 className="size-4 animate-spin" /> : <ArrowUp className="size-4" />}
            </Button>
          </div>
        </>
      ) : (
        <>
          {settingsRow}
          {/* One row, two intents: run the agent's own suggestion as-is, or say
              something first. The composer used to be open at all times for the
              second case, which is the rarer one. */}
          <div className="flex items-center gap-2">
            <Button
              variant="brand"
              disabled={busy}
              onClick={() => void execute()}
              className="flex-1"
            >
              {busy ? <Loader2 className="size-4 animate-spin" /> : <Check className="size-4" />}
              Make the change
            </Button>
            <Button
              variant="tint"
              size="icon"
              disabled={busy}
              onClick={() => reveal("instruct")}
              title="Say something first"
              aria-label="Say something first"
            >
              <MessageSquare className="size-4" />
            </Button>
          </div>

          {/* Everything secondary on one quiet row. Three stacked full-width
              buttons read as three competing CTAs; these are exits, not the
              point of the sheet. */}
          <div className="mt-2 flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              disabled={busy}
              onClick={() => void copyReference()}
              className="flex-1 text-[12.5px] font-medium text-muted-foreground"
            >
              <Copy className="size-3.5" />
              Copy
            </Button>
            {onRefineAgent ? (
              <Button
                variant="ghost"
                size="sm"
                disabled={busy}
                onClick={() => reveal("tune")}
                className="flex-1 text-[12.5px] font-medium text-muted-foreground"
              >
                <SlidersHorizontal className="size-3.5" />
                Feedback
              </Button>
            ) : null}
            <Button
              variant="ghost"
              size="sm"
              disabled={busy}
              onClick={() => {
                logFindingAction(finding.id, "dismiss", !!text.trim());
                onDismiss(finding);
              }}
              className="flex-1 text-[12.5px] font-medium text-muted-foreground"
            >
              <X className="size-3.5" />
              Dismiss
            </Button>
          </div>
        </>
      )}
    </div>
  );

  return (
    <BottomSheet onClose={onClose} title={`${agentName} finding`} page={paged} footer={footer}>
      {/* Bottom-anchored once this is a page: the finding stays next to the
          field you're typing into, and the slack sits above it where the
          keyboard is — not as a hole between the two. */}
      <div className={cn("px-2 pb-2 pt-1", paged && "mt-auto")}>
        {/* One quiet identity line. The old header set the agent name at the
            same weight as the title, so two lines competed to be read first —
            the finding is the headline, the agent is metadata. */}
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <span className={cn("size-2 shrink-0 rounded-full", SEV_DOT[finding.severity])} />
          <span className="truncate font-medium text-foreground/75">{agentName}</span>
          <span aria-hidden>·</span>
          <span className="shrink-0">{relTime(finding.createdAt)}</span>
        </div>

        <p className="mt-2 text-[17px] font-semibold leading-snug tracking-[-0.01em]">
          {finding.title}
        </p>

        {shownReasoning.length ? (
          <ul className="mt-2.5 flex flex-col gap-1.5">
            {shownReasoning.map((r) => (
              <li
                key={r}
                className="flex gap-2 text-[13.5px] leading-relaxed text-muted-foreground"
              >
                <span className="mt-[0.6em] size-1 shrink-0 rounded-full bg-muted-foreground/45" />
                <span className="min-w-0">{r}</span>
              </li>
            ))}
          </ul>
        ) : null}
        {/* A long reasoning list buries the suggestion and the actions below the
            fold. Show the top few and keep the rest one tap away. */}
        {hiddenReasoning > 0 ? (
          <button
            type="button"
            onClick={() => setShowAllReasoning(true)}
            className="mt-2 text-xs font-medium text-muted-foreground/80 underline-offset-4 hover:underline"
          >
            {hiddenReasoning} more {hiddenReasoning === 1 ? "detail" : "details"}
          </button>
        ) : null}

        {finding.suggest ? (
          <div className="mt-3.5 rounded-xl border border-border/60 bg-muted/40 px-3 py-2.5">
            <div className="text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/80">
              Suggested
            </div>
            <div className="mt-1 text-[13.5px] leading-relaxed">{finding.suggest}</div>
          </div>
        ) : null}

        {/* Something was already done about this. The feed hides non-open
            findings by default, so the only people who read this are looking
            at one deliberately — and the question they have is "was this ever
            dealt with". A two-month-old finding whose fix landed four minutes
            after it was filed cost an evening to re-derive; the commit is the
            answer, so it says the commit. */}
        {finding.fixCommit ? (
          <div className="mt-3.5 flex items-center gap-2 text-[13px] text-muted-foreground">
            <Check className="size-3.5 shrink-0 text-success" />
            <span>
              {finding.status === "resolved" ? "Fixed in" : "Fix landed in"}{" "}
              <code className="rounded bg-muted px-1 py-0.5 font-mono text-xs text-foreground">
                {finding.fixCommit.slice(0, 7)}
              </code>
              {finding.fixLandedAt ? ` · ${relTime(finding.fixLandedAt)} ago` : ""}
            </span>
          </div>
        ) : null}

      </div>
    </BottomSheet>
  );
}

// Single-box create: the whole "new auto agent" UI is one prompt. The user
// describes what they want watched; /api/auto/compose derives a name, a cron
// schedule, and the enhanced watch instruction, and we save it straight away.
// Everything stays editable afterward via the full editor (tap the agent).
function NewAutoAgentComposer({
  repos,
  scopedProject,
  codingAgents,
  onClose,
  onCreate,
}: {
  repos: Repo[];
  scopedProject: string;
  codingAgents?: CodingAgentInfo[];
  onClose: () => void;
  onCreate: (
    idea: string,
    cwd: string | undefined,
    opts: {
      agent?: AutoAgentBackend;
      model?: string;
      thinkingLevel?: string;
      claudeAccountId?: string | null;
    },
  ) => void;
}) {
  const [idea, setIdea] = useState("");
  const scopedRepo =
    scopedProject !== "__all"
      ? repos.find((repo) => repoProject(repo) === scopedProject)
      : undefined;
  const [cwd, setCwd] = useState(scopedRepo?.cwd ?? repos[0]?.cwd ?? "");
  const [backend, setBackend] = useState<AutoAgentBackend>("aisdk");
  const [claudeAccountId, setClaudeAccountId] = useState("");
  const defaultModel = useAgentDefaultModel("aisdk");
  const [model, setModel] = useState(defaultModel);
  const [thinkingLevel, setThinkingLevel] = useState<ThinkingLevel>(savedThinkingLevel());
  const backendModels = useAgentModels(backend);
  const backendDefaultModel = useAgentDefaultModel(backend);
  const supportsThinking = agentSupportsThinking(backend);

  useEffect(() => {
    if (!backendModels.includes(model)) setModel(backendDefaultModel);
  }, [backendDefaultModel, backendModels, model]);

  // Fire-and-close: hand the idea to the parent (which runs compose → save
  // under a loading toast) and dismiss the sheet immediately. The slow,
  // repo-inspecting work happens in the background — nothing blocks here.
  function submit() {
    if (!idea.trim()) return;
    onCreate(idea.trim(), cwd || undefined, {
      agent: backend,
      model,
      thinkingLevel: supportsThinking ? thinkingLevel : undefined,
      claudeAccountId: backend === "aisdk" ? claudeAccountId || null : null,
    });
    onClose();
  }

  return (
    <BottomSheet onClose={onClose} title="New auto agent">
      <div className="px-2 pb-4 pt-1">
        <div className="flex items-center gap-2">
          <Sparkles className="size-5 text-primary" />
          <div className="flex-1 text-[15px] font-semibold">New agent</div>
          <Button
            size="sm"
            variant="brand"
            disabled={!idea.trim()}
            onClick={submit}
          >
            Create
          </Button>
        </div>

        <SkillTextarea
          value={idea}
          onValueChange={setIdea}
          rows={5}
          autoFocus
          placeholder="What to watch, and how often…"
          className="mt-3 resize-none text-sm leading-relaxed"
        />

        <div className="mt-2 flex items-center justify-between rounded-xl border border-border px-3 py-2">
          <div className="flex items-center gap-2 text-sm">
            <Folder className="size-4 text-muted-foreground" /> Repo
          </div>
          <select
            value={cwd}
            onChange={(e) => setCwd(e.target.value)}
            aria-label="Repo"
            className="max-w-44 appearance-none truncate bg-transparent text-right text-[13px] font-medium outline-none"
          >
            {repos.length === 0 ? <option value="">(no repos)</option> : null}
            {repos.map((item) => (
              <option key={item.cwd} value={item.cwd}>
                {item.name}
              </option>
            ))}
          </select>
        </div>

        <AgentModelRow
          backend={backend}
          setBackend={setBackend}
          model={model}
          setModel={setModel}
          thinkingLevel={thinkingLevel}
          setThinkingLevel={setThinkingLevel}
          codingAgents={codingAgents}
          claudeAccountId={claudeAccountId}
          setClaudeAccountId={setClaudeAccountId}
          scheduledOnly
        />
      </div>
    </BottomSheet>
  );
}

function ManagedByBotNote({ botId }: { botId: string }) {
  const directory = useContext(BotDirectoryContext);
  const openBot = useContext(OpenBotContext);
  const bot = directory.get(botId);
  return (
    <button
      type="button"
      onClick={() => openBot(botId)}
      className="mt-2 flex items-center gap-1.5 text-xs font-medium text-primary hover:underline"
    >
      <BotMascot shape={bot?.shape} colorway={bot?.colorway} size={14} state="idle" seed={botId.length} />
      Managed by {bot?.name ?? "a deleted bot"}
    </button>
  );
}

function AgentEditorSheet({
  agent,
  repos,
  tz,
  codingAgents,
  running,
  onClose,
  onSave,
  onDelete,
  onRunNow,
}: {
  agent: AutoAgent | "new";
  repos: Repo[];
  tz: string;
  codingAgents?: CodingAgentInfo[];
  running?: boolean;
  onClose: () => void;
  onSave: (input: {
    id?: string;
    name: string;
    prompt: string;
    schedule: string;
    enabled: boolean;
    cwd?: string;
    agent?: AutoAgentBackend;
    model?: string;
    thinkingLevel?: string;
    claudeAccountId?: string | null;
  }) => Promise<void>;
  onDelete: (id: string) => void;
  onRunNow: (id: string) => void;
}) {
  const isNew = agent === "new";
  const existing = isNew ? null : agent;
  const [name, setName] = useState(existing?.name ?? "");
  const [prompt, setPrompt] = useState(existing?.prompt ?? "");
  const [schedule, setSchedule] = useState(existing?.schedule ?? "0 9 * * *");
  // The list ships a ~200-char preview, so a long agent opens here showing a
  // clipped prompt. Pull the real text once, and only adopt it if the field is
  // still exactly the preview — a user who started typing during the fetch
  // keeps their edit rather than having it overwritten from under them.
  const [promptHydrated, setPromptHydrated] = useState(!existing?.promptTruncated);
  useEffect(() => {
    if (isNew || !existing?.promptTruncated) return;
    let cancelled = false;
    const preview = existing.prompt ?? "";
    api<{ agent: AutoAgent }>(`/api/auto/agents/${encodeURIComponent(existing.id)}`)
      .then((r) => {
        if (cancelled) return;
        const full = r.agent?.prompt;
        if (typeof full === "string") {
          setPrompt((current) => (current === preview ? full : current));
        }
        setPromptHydrated(true);
      })
      .catch(() => {
        // Leave the editor on the preview and let the user retype rather than
        // silently saving a clipped prompt: the save button stays disabled.
        if (!cancelled) setPromptHydrated(false);
      });
    return () => {
      cancelled = true;
    };
  }, [isNew, existing?.id, existing?.promptTruncated]);
  // Schedule picker: "simple" drives the cron from friendly controls; "advanced"
  // exposes the raw cron field. We open in simple mode when the existing cron maps
  // to a pattern the picker can represent, else advanced.
  const initialSimple = parseToSimple(existing?.schedule ?? "0 9 * * *");
  const [simple, setSimple] = useState<SimpleSchedule>(initialSimple ?? DEFAULT_SIMPLE);
  const [schedMode, setSchedMode] = useState<"simple" | "advanced">(
    initialSimple ? "simple" : "advanced",
  );
  // In simple mode the picker is the source of truth → keep cron in sync.
  const updateSimple = (patch: Partial<SimpleSchedule>) => {
    setSimple((prev) => {
      const next = { ...prev, ...patch };
      setSchedule(buildCron(next));
      return next;
    });
  };
  const [enabled, setEnabled] = useState(existing?.enabled ?? true);
  // The base repo this agent runs in (and that graduated sessions inherit). Same
  // repo list as the Create Session dialog. Default to the agent's saved base,
  // else the first repo.
  const [cwd, setCwd] = useState(existing?.cwd ?? repos[0]?.cwd ?? "");
  const [backend, setBackend] = useState<AutoAgentBackend>(existing?.agent ?? "aisdk");
  const [claudeAccountId, setClaudeAccountId] = useState(existing?.claudeAccountId ?? "");
  const initialDefaultModel = useAgentDefaultModel(existing?.agent ?? "aisdk");
  const [model, setModel] = useState(
    existing?.model ?? initialDefaultModel,
  );
  const [thinkingLevel, setThinkingLevel] = useState<ThinkingLevel>(
    (existing?.thinkingLevel as ThinkingLevel | undefined) ?? savedThinkingLevel(),
  );
  const [busy, setBusy] = useState(false);
  const [enhancing, setEnhancing] = useState(false);
  const [enhanceErr, setEnhanceErr] = useState<string | null>(null);
  // Scan only when the schedule changes, not on every keystroke elsewhere.
  const nextPreview = useMemo(() => nextRunAt(schedule, tz), [schedule, tz]);
  const backendModels = useAgentModels(backend);
  const backendDefaultModel = useAgentDefaultModel(backend);
  const supportsThinking = agentSupportsThinking(backend);

  useEffect(() => {
    if (!backendModels.includes(model)) setModel(backendDefaultModel);
  }, [backendDefaultModel, backendModels, model]);

  // Rewrite the user's rough idea into a sharp watch-agent prompt in place. The
  // server runs a one-shot, tool-less claude pass; we swap the result into the
  // textarea so it stays fully editable afterward.
  async function enhance() {
    if (enhancing || !prompt.trim()) return;
    setEnhancing(true);
    setEnhanceErr(null);
    try {
      const r = await api<{ prompt: string }>("/api/auto/enhance-prompt", {
        method: "POST",
        body: JSON.stringify({
          prompt: prompt.trim(),
          name: name.trim() || undefined,
          cwd: cwd || undefined,
        }),
      });
      if (r.prompt?.trim()) setPrompt(r.prompt.trim());
    } catch (e) {
      setEnhanceErr(e instanceof Error ? e.message : "enhance failed");
    } finally {
      setEnhancing(false);
    }
  }

  async function save() {
    if (!name.trim() || !prompt.trim() || busy) return;
    // Never write back a prompt we only ever held a preview of. The list
    // truncates at 200 chars, so saving before the full text arrives would
    // quietly replace a 9 KB agent instruction with its own first line.
    if (!promptHydrated) return;
    setBusy(true);
    try {
      await onSave({
        id: existing?.id,
        name: name.trim(),
        prompt: prompt.trim(),
        schedule: schedule.trim(),
        enabled,
        cwd: cwd || undefined,
        agent: backend,
        model: model.trim() || undefined,
        thinkingLevel: supportsThinking ? thinkingLevel : undefined,
        // null, not undefined: JSON.stringify drops undefined, and an absent
        // field means "keep the stored pin" — so clearing one has to be said
        // out loud or the save is a silent no-op.
        claudeAccountId: backend === "aisdk" ? claudeAccountId || null : null,
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <BottomSheet
      onClose={onClose}
      title={isNew ? "New auto agent" : "Edit auto agent"}
    >
      <div className="px-2 pb-4 pt-1">
        <div className="flex items-center gap-2">
          <Bot className="size-5 text-primary" />
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            aria-label="Auto agent name"
            placeholder="agent-name"
            className="flex-1 bg-transparent text-[17px] font-semibold outline-none placeholder:text-muted-foreground"
          />
          <Button
            size="sm"
            variant="brand"
            disabled={busy || !promptHydrated}
            title={promptHydrated ? undefined : "Loading this agent's full prompt…"}
            onClick={() => void save()}
          >
            {busy || !promptHydrated ? <Loader2 className="size-4 animate-spin" /> : null}
            Save
          </Button>
        </div>

        {/* Editing here stays fully allowed — a human is always admin over
            every automation, bot-owned included — but the row is also
            self-managed from inside the bot's own chat, so say so. */}
        {existing?.owner?.kind === "bot" ? <ManagedByBotNote botId={existing.owner.botId} /> : null}

        {(() => {
          const locale = typeof navigator !== "undefined" ? navigator.language : undefined;
          const weekdays = [0, 1, 2, 3, 4, 5, 6].map((d) => ({
            v: d,
            label: new Date(Date.UTC(2024, 0, 7 + d)).toLocaleDateString(locale, {
              weekday: "long",
              timeZone: "UTC",
            }),
          }));
          const next = nextPreview;
          const selectCls =
            "appearance-none rounded-lg bg-muted px-2 py-1 text-right text-[13px] font-medium outline-none";
          const numCls = "w-14 rounded-lg bg-muted px-2 py-1 text-right text-[13px] outline-none";
          const freqOptions: { v: SimpleFreq; label: string }[] = [
            { v: "minutes", label: "Every N minutes" },
            { v: "hourly", label: "Every hour" },
            { v: "daily", label: "Every day" },
            { v: "weekday", label: "Every weekday" },
            { v: "weekly", label: "Every week" },
            { v: "monthly", label: "Every month" },
          ];
          return (
            <div className="mt-3 rounded-xl border border-border px-3 py-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm">
                  <CalendarClock className="size-4 text-muted-foreground" /> Schedule
                </div>
                <button
                  type="button"
                  onClick={() => {
                    if (schedMode === "advanced") {
                      const parsed = parseToSimple(schedule);
                      if (parsed) {
                        setSimple(parsed);
                        setSchedMode("simple");
                      }
                    } else {
                      setSchedMode("advanced");
                    }
                  }}
                  className="text-[11px] font-semibold uppercase tracking-wide text-primary disabled:text-muted-foreground"
                  disabled={schedMode === "advanced" && !parseToSimple(schedule)}
                >
                  {schedMode === "simple" ? "Cron" : "Picker"}
                </button>
              </div>

              {schedMode === "simple" ? (
                <div className="mt-2 flex flex-wrap items-center justify-end gap-1.5 text-[13px]">
                  <select
                    value={simple.freq}
                    onChange={(e) => updateSimple({ freq: e.target.value as SimpleFreq })}
                    aria-label="Frequency"
                    className={selectCls}
                  >
                    {freqOptions.map((o) => (
                      <option key={o.v} value={o.v}>
                        {o.label}
                      </option>
                    ))}
                  </select>

                  {simple.freq === "minutes" ? (
                    <input
                      type="number"
                      min={1}
                      max={59}
                      value={simple.every}
                      onChange={(e) => updateSimple({ every: parseInt(e.target.value, 10) || 1 })}
                      aria-label="Every N minutes"
                      className={numCls}
                    />
                  ) : null}

                  {simple.freq === "hourly" ? (
                    <input
                      type="number"
                      min={0}
                      max={59}
                      value={simple.minute}
                      onChange={(e) =>
                        updateSimple({
                          minute: Math.max(0, Math.min(59, parseInt(e.target.value, 10) || 0)),
                        })
                      }
                      aria-label="Minute of the hour"
                      className={numCls}
                    />
                  ) : null}

                  {simple.freq === "weekly" ? (
                    <select
                      value={simple.dow}
                      onChange={(e) => updateSimple({ dow: parseInt(e.target.value, 10) })}
                      aria-label="Day of week"
                      className={selectCls}
                    >
                      {weekdays.map((d) => (
                        <option key={d.v} value={d.v}>
                          {d.label}
                        </option>
                      ))}
                    </select>
                  ) : null}

                  {simple.freq === "monthly" ? (
                    <input
                      type="number"
                      min={1}
                      max={31}
                      value={simple.dom}
                      onChange={(e) =>
                        updateSimple({
                          dom: Math.max(1, Math.min(31, parseInt(e.target.value, 10) || 1)),
                        })
                      }
                      aria-label="Day of month"
                      className={numCls}
                    />
                  ) : null}

                  {simple.freq === "daily" ||
                  simple.freq === "weekday" ||
                  simple.freq === "weekly" ||
                  simple.freq === "monthly" ? (
                    <input
                      type="time"
                      value={simple.time}
                      onChange={(e) => updateSimple({ time: e.target.value })}
                      aria-label="Time of day"
                      className="rounded-lg bg-muted px-2 py-1 text-[13px] outline-none"
                    />
                  ) : null}
                </div>
              ) : (
                <input
                  value={schedule}
                  onChange={(e) => setSchedule(e.target.value)}
                  aria-label="Cron schedule"
                  placeholder="0 9 * * *"
                  className="mt-2 w-full rounded-lg bg-muted px-2 py-1 font-mono text-[13px] outline-none"
                />
              )}

              <div className="mt-2 border-t border-border pt-1.5 text-xs text-muted-foreground">
                {describeCron(schedule, locale)}
                {next ? <span> · next {formatRelative(next, locale)}</span> : null}
                <span className="ml-1 text-muted-foreground/60">({tz})</span>
              </div>
            </div>
          );
        })()}

        <div className="mt-2 flex items-center justify-between rounded-xl border border-border px-3 py-2">
          <div className="flex items-center gap-2 text-sm">
            <Folder className="size-4 text-muted-foreground" /> Repo
          </div>
          <select
            value={cwd}
            onChange={(e) => setCwd(e.target.value)}
            aria-label="Repo"
            className="max-w-44 appearance-none truncate bg-transparent text-right text-[13px] font-medium outline-none"
          >
            {repos.length === 0 ? <option value="">(no repos)</option> : null}
            {repos.map((item) => (
              <option key={item.cwd} value={item.cwd}>
                {item.name}
              </option>
            ))}
          </select>
        </div>

        <AgentModelRow
          backend={backend}
          setBackend={setBackend}
          model={model}
          setModel={setModel}
          thinkingLevel={thinkingLevel}
          setThinkingLevel={setThinkingLevel}
          codingAgents={codingAgents}
          claudeAccountId={claudeAccountId}
          setClaudeAccountId={setClaudeAccountId}
          scheduledOnly
        />

        <button
          type="button"
          onClick={() => setEnabled((v) => !v)}
          className="mt-2 flex w-full items-center justify-between rounded-xl border border-border px-3 py-2"
        >
          <div className="flex items-center gap-2 text-sm">
            <Power className="size-4 text-muted-foreground" /> Enabled
          </div>
          <span
            className={cn(
              "relative h-6 w-11 rounded-full transition-colors",
              enabled ? "bg-success" : "bg-border",
            )}
          >
            <span
              className={cn(
                "absolute left-0.5 top-0.5 size-5 rounded-full bg-white transition-transform",
                enabled ? "translate-x-5" : "",
              )}
            />
          </span>
        </button>

        <div className="mt-3 flex items-center justify-between">
          <div className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
            Prompt
          </div>
          <button
            type="button"
            disabled={enhancing || !prompt.trim()}
            onClick={() => void enhance()}
            className="flex items-center gap-1 text-[11px] font-semibold uppercase tracking-wide text-primary disabled:text-muted-foreground"
            title="Rewrite into a sharper watch prompt"
          >
            {enhancing ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <Sparkles className="size-3.5" />
            )}
            {enhancing ? "Enhancing…" : "Enhance"}
          </button>
        </div>
        <SkillTextarea
          value={prompt}
          onValueChange={setPrompt}
          rows={5}
          disabled={enhancing}
          placeholder="What to watch for…"
          className="mt-1.5 resize-none text-sm leading-relaxed"
        />
        {enhanceErr ? (
          <div className="mt-1.5 px-1 text-[11px] text-destructive">{enhanceErr}</div>
        ) : null}

        {existing ? (
          <div className="mt-4 flex gap-2">
            <Button
              variant="outline"
              className="flex-1"
              disabled={running}
              onClick={() => onRunNow(existing.id)}
            >
              {running ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <Play className="size-4" />
              )}{" "}
              {running ? "Running…" : "Run now"}
            </Button>
            <Button
              variant="outline"
              className="flex-1 text-destructive"
              onClick={() => onDelete(existing.id)}
            >
              <Trash2 className="size-4" /> Delete
            </Button>
          </div>
        ) : null}
      </div>
    </BottomSheet>
  );
}

const navLocale = typeof navigator !== "undefined" ? navigator.language : undefined;

function ScheduleSummary({
  expr,
  tz,
  relativeClassName,
}: {
  expr: string;
  tz: string;
  /** Extra classes on the "· next in 17 hours" tail. The Schedules row hides
   *  it below sm, where the row has no width to spare and the cron
   *  description is the part you actually scan for. */
  relativeClassName?: string;
}) {
  // describeCron is cheap; nextRunAt scans, so compute it only when expr/tz
  // change — NOT on every 30s re-render.
  const desc = useMemo(() => describeCron(expr, navLocale), [expr]);
  const [tick, force] = useState(0);
  const next = useMemo(() => nextRunAt(expr, tz), [expr, tz, tick]);
  // Tick the relative label; only rescan when the previous run actually passed.
  useEffect(() => {
    const id = setInterval(() => {
      force((n) => n + 1);
    }, 30_000);
    return () => clearInterval(id);
  }, []);
  return (
    <span className="flex items-center gap-1" title={expr}>
      <CalendarClock className="size-3.5 shrink-0" />
      <span className="truncate">
        {desc}
        {next ? (
          <span className={cn("text-muted-foreground/70", relativeClassName)}>
            {" "}· next {formatRelative(next, navLocale)}
          </span>
        ) : null}
      </span>
    </span>
  );
}

type ProviderOption = { id: string; label: string; available: boolean };
type VoiceConfig = {
  settings: { sttProvider: string };
  providers: { stt: ProviderOption[] };
};

function ProviderRow({
  icon,
  label,
  value,
  options,
  onChange,
  disabled,
}: {
  icon: ReactNode;
  label: string;
  value?: string;
  options?: ProviderOption[];
  onChange: (v: string) => void;
  disabled?: boolean;
}) {
  return (
    <div className="flex items-center justify-between gap-4 px-4 py-2.5">
      <div className="flex items-center gap-3">
        <span className="flex size-7 items-center justify-center rounded-[7px] bg-primary text-white">
          {icon}
        </span>
        <span className="text-sm font-medium">{label}</span>
      </div>
      <select
        className="max-w-[55%] rounded-lg border border-border bg-background px-2 py-1 text-sm disabled:opacity-50"
        value={value ?? ""}
        disabled={disabled || !options}
        onChange={(e) => onChange(e.target.value)}
        aria-label={label}
      >
        {!options ? (
          <option value="">Loading…</option>
        ) : (
          options.map((o) => (
            <option key={o.id} value={o.id} disabled={!o.available}>
              {o.label}
              {o.available ? "" : " (no key)"}
            </option>
          ))
        )}
      </select>
    </div>
  );
}

function VoiceSettingsSection() {
  const [cfg, setCfg] = useState<VoiceConfig | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    let alive = true;
    void omgFetch("/api/voice/config")
      .then((r) => (r.ok ? r.json() : null))
      .then((d: VoiceConfig | null) => {
        if (alive && d) setCfg(d);
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);

  const update = async (patch: Partial<VoiceConfig["settings"]>) => {
    setCfg((c) => (c ? { ...c, settings: { ...c.settings, ...patch } } : c));
    setSaving(true);
    try {
      const r = await omgFetch("/api/voice/config", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(patch),
      });
      const d = (await r.json().catch(() => null)) as { settings?: VoiceConfig["settings"] } | null;
      if (d?.settings) setCfg((c) => (c ? { ...c, settings: d.settings! } : c));
      // Switching provider changes what the mic path is allowed to do — drop the
      // shared cache so the next dictation tap gates on the new selection.
      invalidateVoiceConfig();
      prefetchVoiceConfig();
    } catch {
      // keep the optimistic value; next load reconciles
    } finally {
      setSaving(false);
    }
  };

  const selectedInput = cfg?.providers.stt.find((p) => p.id === cfg.settings.sttProvider);
  const needsSetup = !!cfg && !selectedInput?.available;

  return (
    // No section header: the card holds exactly one row, and that row's own
    // label ("Voice input") already said "Voice" — a group label above it
    // was a second copy of the same word, not new information.
    <section className="space-y-2">
      <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
        <ProviderRow
          icon={<Mic className="size-4" />}
          label="Voice input"
          value={cfg?.settings.sttProvider}
          options={cfg?.providers.stt}
          onChange={(v) => void update({ sttProvider: v })}
          disabled={!cfg || saving}
        />
      </div>
      {needsSetup ? (
        <div className="px-4 pt-1">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => showVoiceSetup("input")}
          >
            <KeyRound className="size-4" /> Set up voice API key
          </Button>
        </div>
      ) : null}
    </section>
  );
}

function browserTimeZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || DEFAULT_SCHED_TZ;
  } catch {
    return DEFAULT_SCHED_TZ;
  }
}

function timeZoneOptions(current?: string): string[] {
  const intl = Intl as typeof Intl & { supportedValuesOf?: (key: "timeZone") => string[] };
  const zones = intl.supportedValuesOf?.("timeZone") ?? [];
  const all = new Set<string>();
  for (const zone of [DEFAULT_SCHED_TZ, browserTimeZone(), current]) {
    if (zone) all.add(zone);
  }
  for (const zone of zones) all.add(zone);
  return [...all].sort((a, b) => a.localeCompare(b));
}

function TimeZoneSettingsSection({
  settings,
  onChange,
}: {
  settings: GlobalSettings;
  onChange: (patch: Partial<GlobalSettings>) => Promise<void>;
}) {
  const [saving, setSaving] = useState(false);
  const zones = useMemo(() => timeZoneOptions(settings.timeZone), [settings.timeZone]);

  async function save(timeZone: string) {
    if (!timeZone || timeZone === settings.timeZone || saving) return;
    setSaving(true);
    try {
      await onChange({ timeZone });
      toast.success("Timezone updated");
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Could not update timezone");
    } finally {
      setSaving(false);
    }
  }

  return (
    <section className="space-y-2">
      {/* Not uppercased — see RailGroup: group labels read quieter lowercase. */}
      <h2 className="px-4 text-xs font-semibold text-muted-foreground">
        Scheduling
      </h2>
      <div className="overflow-hidden rounded-2xl border border-border bg-card/40">
        {/* What the value affects is a fact about it, not a control — it goes
            in the title attribute instead of a permanent second line, the
            same move the Ping row made for its refresh cadence. */}
        <div
          className="flex flex-wrap items-center justify-between gap-3 px-4 py-2.5"
          title="Auto-agent runs and model-refresh schedules use this timezone."
        >
          <div className="flex items-center gap-3">
            <span className="flex size-7 items-center justify-center rounded-[7px] bg-primary text-white">
              <Globe className="size-4" />
            </span>
            <span className="text-sm font-medium">Timezone</span>
          </div>
          <div className="flex min-w-0 items-center gap-2">
            <button
              type="button"
              onClick={() => void save(browserTimeZone())}
              disabled={saving || browserTimeZone() === settings.timeZone}
              className="rounded-full bg-muted px-3 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground disabled:opacity-50"
            >
              Use device
            </button>
            <label className="flex min-w-0 items-center gap-1 rounded-full bg-muted px-3 py-1.5">
              <select
                value={settings.timeZone}
                onChange={(event) => void save(event.target.value)}
                disabled={saving}
                aria-label="Schedule timezone"
                className="max-w-[12rem] appearance-none truncate bg-transparent text-right text-xs font-medium outline-none"
              >
                {zones.map((zone) => (
                  <option key={zone} value={zone}>
                    {zone}
                  </option>
                ))}
              </select>
              <ChevronDown className="size-3 text-muted-foreground/70" />
            </label>
          </div>
        </div>
      </div>
    </section>
  );
}

// Poll the live server snapshot while a component is mounted. Cheap endpoint
// (cached session list + one systemctl call), so a 3s cadence is comfortable.
function useServerStats(active: boolean, intervalMs = 3000): ServerStats | null {
  const [stats, setStats] = useState<ServerStats | null>(null);
  useEffect(() => {
    if (!active) return;
    let stopped = false;
    const tick = async () => {
      try {
        const payload = await api<{ stats?: ServerStats }>("/api/server/stats");
        // Same guard as the warning poller: a response that isn't the snapshot
        // must not land in state as an undefined "ServerStats".
        if (!stopped) setStats(payload.stats ?? null);
      } catch {
        /* transient — keep the last snapshot */
      }
    };
    void tick();
    const timer = window.setInterval(() => void tick(), intervalMs);
    return () => {
      stopped = true;
      window.clearInterval(timer);
    };
  }, [active, intervalMs]);
  return stats;
}

// The per-session breakdown, polled only while it is actually on screen.
//
// This endpoint walks every process in /proc reading smaps_rollup, cmdline,
// cgroup and environ, so it is an order of magnitude dearer than the aggregate
// snapshot above. It is fetched on expand and refreshed slowly: the panel's job
// is deciding which session to close, and that answer does not change in 3s.
// Polling it hard would make the memory-pressure tool a memory-pressure source.
function useSessionUsage(active: boolean, intervalMs = 15000): SessionUsage | null {
  const [usage, setUsage] = useState<SessionUsage | null>(null);
  useEffect(() => {
    if (!active) return;
    let stopped = false;
    const tick = async () => {
      try {
        const payload = await api<{ usage?: SessionUsage }>("/api/server/session-usage");
        if (!stopped) setUsage(payload.usage ?? null);
      } catch {
        /* transient — keep the last snapshot */
      }
    };
    void tick();
    const timer = window.setInterval(() => void tick(), intervalMs);
    return () => {
      stopped = true;
      window.clearInterval(timer);
    };
  }, [active, intervalMs]);
  return usage;
}

const LIVE_AGENT_LIMIT_OPTIONS = [0, 4, 8, 10, 12, 16, 24, 32];

// No 0/unlimited option here on purpose — see GlobalSettings.maxBotSchedules.
const BOT_SCHEDULE_LIMIT_OPTIONS = [1, 2, 3, 5, 8, 10, 15, 20];
const BOT_COMPACTION_THRESHOLD_OPTIONS = [60, 70, 75, 78, 80, 85, 90, 95];

function AgentConcurrencySettingsSection({
  settings,
  onChange,
}: {
  settings: GlobalSettings;
  onChange: (patch: Partial<GlobalSettings>) => Promise<void>;
}) {
  const [saving, setSaving] = useState(false);
  const [savingBotCap, setSavingBotCap] = useState(false);
  const [savingCompaction, setSavingCompaction] = useState(false);
  const stats = useServerStats(true);

  async function saveLimit(maxLiveAgents: number) {
    if (maxLiveAgents === settings.maxLiveAgents || saving) return;
    setSaving(true);
    try {
      await onChange({ maxLiveAgents });
      toast.success(
        maxLiveAgents === 0
          ? "Agent limit removed (unlimited)"
          : `Agent limit set to ${maxLiveAgents}`,
      );
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Could not update agent limit");
    } finally {
      setSaving(false);
    }
  }

  async function saveBotCap(maxBotSchedules: number) {
    if (maxBotSchedules === settings.maxBotSchedules || savingBotCap) return;
    setSavingBotCap(true);
    try {
      await onChange({ maxBotSchedules });
      toast.success(`Per-bot schedule limit set to ${maxBotSchedules}`);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Could not update the bot schedule limit");
    } finally {
      setSavingBotCap(false);
    }
  }

  async function saveBotCompaction(patch: Partial<Pick<
    GlobalSettings,
    "botAutoCompactionEnabled" | "botCompactionThresholdPercent"
  >>) {
    if (savingCompaction) return;
    setSavingCompaction(true);
    try {
      await onChange(patch);
      toast.success("Bot context refresh settings updated");
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Could not update bot context refresh settings");
    } finally {
      setSavingCompaction(false);
    }
  }

  const working = stats?.agents.working ?? 0;
  const live = stats?.agents.live ?? 0;
  // 0 = unlimited. The cap counts every LIVE agent, idle included — an idle
  // agent has stopped using CPU but has not given back its memory.
  const cap = settings.maxLiveAgents;
  const atCap = cap > 0 && live >= cap;

  return (
    <section className="space-y-2">
      {/* Not uppercased — see RailGroup: shouting a group label was the
          loudest text on a settings page that should read quiet. */}
      <h2 className="px-4 text-xs font-semibold text-muted-foreground">
        Agent capacity
      </h2>
      <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
        {/* Live counter */}
        <div className="flex items-center justify-between gap-3 px-4 py-2.5">
          <div className="flex min-w-0 items-center gap-3">
            <span className="flex size-7 shrink-0 items-center justify-center rounded-[7px] bg-primary text-white">
              <Bot className="size-4" />
            </span>
            <div className="min-w-0">
              <div className="text-sm font-medium tabular-nums">
                {working} working
                <span className="text-muted-foreground"> · {live} live</span>
              </div>
              <div className={cn(
                "text-xs",
                atCap ? "font-medium text-warning" : "text-muted-foreground",
              )}>
                {cap === 0
                  ? "No limit"
                  : atCap
                    ? `Limit reached · ${live}/${cap} live`
                    : `${live}/${cap} live · limit`}
              </div>
            </div>
          </div>
          <label className="flex shrink-0 items-center gap-1 rounded-full bg-muted px-3 py-1.5">
            <select
              value={cap}
              onChange={(event) => void saveLimit(Number(event.target.value))}
              disabled={saving}
              aria-label="Maximum live agents"
              className="appearance-none bg-transparent text-right text-xs font-medium outline-none"
            >
              {LIVE_AGENT_LIMIT_OPTIONS.map((count) => (
                <option key={count} value={count}>
                  {count === 0 ? "Unlimited" : count}
                </option>
              ))}
            </select>
            <ChevronDown className="size-3 text-muted-foreground/70" />
          </label>
        </div>
        {/* Per-bot cap on self-scheduled routines (omg_schedule_routine). A
            separate knob from live-agent capacity above: this bounds how many
            concerns any one bot is tracking at once, not concurrency. */}
        <div className="flex items-center justify-between gap-3 px-4 py-2.5">
          <div className="flex min-w-0 items-center gap-3">
            <span className="flex size-7 shrink-0 items-center justify-center rounded-[7px] bg-foreground/70 text-white">
              <CalendarClock className="size-4" />
            </span>
            <div className="min-w-0">
              <div className="text-sm font-medium">Bot schedule limit</div>
              <div className="text-xs text-muted-foreground">
                Max routines a bot can schedule on itself
              </div>
            </div>
          </div>
          <label className="flex shrink-0 items-center gap-1 rounded-full bg-muted px-3 py-1.5">
            <select
              value={settings.maxBotSchedules}
              onChange={(event) => void saveBotCap(Number(event.target.value))}
              disabled={savingBotCap}
              aria-label="Maximum schedules per bot"
              className="appearance-none bg-transparent text-right text-xs font-medium outline-none"
            >
              {BOT_SCHEDULE_LIMIT_OPTIONS.map((count) => (
                <option key={count} value={count}>{count}</option>
              ))}
            </select>
            <ChevronDown className="size-3 text-muted-foreground/70" />
          </label>
        </div>
        <div className="flex items-center justify-between gap-3 px-4 py-2.5">
          <div className="flex min-w-0 items-center gap-3">
            <span className={cn(
              "flex size-7 shrink-0 items-center justify-center rounded-[7px] text-white transition-colors duration-200 ease-apple",
              settings.botAutoCompactionEnabled ? "bg-primary" : "bg-foreground/70",
            )}>
              <RotateCcw className="size-4" />
            </span>
            <div className="min-w-0">
              <div className="text-sm font-medium">Refresh full bot contexts</div>
              <div className="text-xs text-muted-foreground">
                {settings.botAutoCompactionEnabled
                  ? `At ${settings.botCompactionThresholdPercent}% measured context use`
                  : "Off — bots keep one runtime until manually refreshed"}
              </div>
            </div>
          </div>
          <div className="flex shrink-0 items-center gap-2">
            <label className="flex items-center gap-1 rounded-full bg-muted px-3 py-1.5">
              <select
                value={settings.botCompactionThresholdPercent}
                onChange={(event) => void saveBotCompaction({
                  botCompactionThresholdPercent: Number(event.target.value),
                })}
                disabled={savingCompaction || !settings.botAutoCompactionEnabled}
                aria-label="Bot context refresh threshold"
                className="appearance-none bg-transparent text-right text-xs font-medium outline-none disabled:opacity-50"
              >
                {BOT_COMPACTION_THRESHOLD_OPTIONS.map((percent) => (
                  <option key={percent} value={percent}>{percent}%</option>
                ))}
              </select>
              <ChevronDown className="size-3 text-muted-foreground/70" />
            </label>
            <Switch
              checked={settings.botAutoCompactionEnabled}
              onCheckedChange={(next) => void saveBotCompaction({ botAutoCompactionEnabled: next })}
              disabled={savingCompaction}
              aria-label="Automatically refresh full bot contexts"
            />
          </div>
        </div>
      </div>
      {/* Pause new agents and Archive idle agents were removed entirely (both
          the switches and the server-side gate/sweeper behind them) rather
          than just hidden — Benny's call, since a soft "off" switch nobody
          can see is worse than no switch. What is left to explain is just the
          limit above: it is a live-agent ceiling, not a full drain, and it is
          soft on purpose (see GlobalSettings.maxLiveAgents). */}
      <p className="px-4 text-xs text-muted-foreground">
        The limit counts every live agent, idle ones included — an idle agent has stopped
        using CPU but still holds its memory. New agents past the limit are rejected;
        in-flight agents keep running. The systemd slice is the hard memory bound.
      </p>
    </section>
  );
}

/* Storage & performance — its own page, reached from Settings. Keeps the
   one-pager calm: a headline capacity read here rather than four live gauges
   on the settings root. Disk totals come from the same /api/server/stats
   poll that backs the capacity section. */
function StoragePage() {
  const stats = useServerStats(true);
  const diskTotal = stats?.disk?.totalBytes ?? null;
  const diskFree = stats?.disk?.freeBytes ?? null;
  const diskUsed =
    diskTotal != null && diskFree != null ? Math.max(0, diskTotal - diskFree) : null;
  const diskPct =
    diskUsed != null && diskTotal != null && diskTotal > 0
      ? Math.min(100, Math.round((diskUsed / diskTotal) * 100))
      : null;

  return (
    <div className="mx-auto max-w-xl space-y-8 pb-10" data-lfg-page-column>
      <div className="px-1">
        <h1 className="text-lg font-semibold leading-tight">Storage &amp; performance</h1>
        <p className="text-sm text-muted-foreground">This computer</p>
      </div>

      <section className="space-y-2">
        <h2 className="px-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Storage
        </h2>
        <div className="overflow-hidden rounded-2xl border border-border bg-card/40">
          <div className="px-4 pt-4">
            <div className="text-2xl font-semibold tabular-nums tracking-tight">
              {diskUsed != null ? formatBytes(diskUsed) : "—"}
              {diskTotal != null ? (
                <span className="text-sm font-medium text-muted-foreground">
                  {" "}of {formatBytes(diskTotal)} used
                </span>
              ) : null}
            </div>
            <div className="mt-1 text-xs text-muted-foreground">
              {diskFree != null
                ? `${formatBytes(diskFree)} available`
                : "Capacity unavailable on this filesystem"}
            </div>
          </div>
          <div
            className="mx-4 mb-4 mt-3 h-4 overflow-hidden rounded-md bg-foreground/[0.08]"
            role="progressbar"
            aria-label="Disk usage"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={diskPct ?? 0}
          >
            <div
              className={cn(
                "h-full rounded-md transition-all duration-300 ease-ios",
                diskPct != null && diskPct >= 90
                  ? "bg-destructive"
                  : diskPct != null && diskPct >= 75
                    ? "bg-amber-500"
                    : "bg-primary",
              )}
              style={{ width: `${diskPct ?? 0}%` }}
            />
          </div>
        </div>
        <p className="px-4 text-xs text-muted-foreground">
          Whole-filesystem usage for the volume holding omg.dev&apos;s data directory.
        </p>
      </section>

      <ServerPerformancePanel stats={stats} />
      <SessionUsagePanel />
    </div>
  );
}

// Severity of a metric. Drives the status colour AND a text word, so state is
// never conveyed by colour alone.
type MetricTone = "ok" | "warn" | "crit" | "neutral";

const TONE_TEXT: Record<MetricTone, string> = {
  ok: "text-primary",
  warn: "text-amber-500",
  crit: "text-destructive",
  neutral: "text-muted-foreground",
};

const TONE_WORD: Record<MetricTone, string | null> = {
  ok: null,
  warn: "elevated",
  crit: "high",
  neutral: null,
};

function toneFor(value: number, warn: number, crit: number): MetricTone {
  if (value >= crit) return "crit";
  if (value >= warn) return "warn";
  return "ok";
}

// A single-series inline time-series. No axes, no gridlines, no legend: the
// row's icon + label name the series, and the current value is the direct
// label. Colour comes from `tone` (the status job), and the stroke uses
// currentColor so light/dark follow the design tokens.
function Sparkline({
  values,
  max,
  tone,
  label,
  format,
}: {
  values: number[];
  max?: number;
  tone: MetricTone;
  label: string;
  format: (v: number) => string;
}) {
  const [hover, setHover] = useState<number | null>(null);
  const W = 240;
  const H = 34;
  const PAD = 3;

  if (values.length < 2) {
    return (
      <div className="mt-2 flex h-[34px] items-center text-[11px] text-muted-foreground">
        Collecting…
      </div>
    );
  }

  const hi = Math.max(max ?? 0, ...values, 1e-6);
  const n = values.length;
  const px = (i: number) => (i / (n - 1)) * W;
  const py = (v: number) => H - PAD - (Math.min(v, hi) / hi) * (H - PAD * 2);
  const line = values.map((v, i) => `${i ? "L" : "M"}${px(i).toFixed(1)},${py(v).toFixed(1)}`).join(" ");
  const area = `${line} L${W.toFixed(1)},${H} L0,${H} Z`;
  const cur = values[values.length - 1]!;
  const shown = hover != null ? values[hover]! : cur;

  return (
    <div className={cn("relative mt-2", TONE_TEXT[tone])}>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        preserveAspectRatio="none"
        className="h-[34px] w-full overflow-visible"
        role="img"
        aria-label={`${label}: ${format(cur)} now, ${values.length} samples over the last ${Math.round((values.length * 5) / 60)} minutes`}
        onMouseLeave={() => setHover(null)}
        onMouseMove={(e) => {
          const r = e.currentTarget.getBoundingClientRect();
          if (r.width <= 0) return;
          const frac = Math.min(1, Math.max(0, (e.clientX - r.left) / r.width));
          setHover(Math.round(frac * (n - 1)));
        }}
      >
        <title>{`${label}: ${format(cur)}`}</title>
        <path d={area} fill="currentColor" fillOpacity={0.12} stroke="none" />
        <path
          d={line}
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
        {hover != null ? (
          <line
            x1={px(hover)}
            x2={px(hover)}
            y1={0}
            y2={H}
            stroke="currentColor"
            strokeWidth={1}
            strokeOpacity={0.45}
            vectorEffect="non-scaling-stroke"
          />
        ) : null}
      </svg>
      {hover != null ? (
        <div className="pointer-events-none absolute -top-1 right-0 rounded bg-popover px-1.5 py-0.5 text-[10px] font-medium tabular-nums text-popover-foreground shadow-sm">
          {format(shown)}
        </div>
      ) : null}
    </div>
  );
}

function MetricCard({
  icon,
  label,
  value,
  sub,
  values,
  max,
  tone,
  format,
}: {
  icon: ReactNode;
  label: string;
  value: string;
  sub?: string;
  values: number[];
  max?: number;
  tone: MetricTone;
  format: (v: number) => string;
}) {
  const word = TONE_WORD[tone];
  return (
    <div className="px-4 py-3">
      <div className="flex items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <span className="flex size-7 shrink-0 items-center justify-center rounded-[7px] bg-muted text-foreground/70">
            {icon}
          </span>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5 text-sm font-medium">
              {label}
              {word ? (
                <span className={cn("text-[10px] font-semibold uppercase tracking-wide", TONE_TEXT[tone])}>
                  {word}
                </span>
              ) : null}
            </div>
            {sub ? <div className="text-xs text-muted-foreground tabular-nums">{sub}</div> : null}
          </div>
        </div>
        <div className="shrink-0 text-sm font-semibold tabular-nums">{value}</div>
      </div>
      <Sparkline values={values} max={max} tone={tone} label={label} format={format} />
    </div>
  );
}

function ServerPerformancePanel({ stats }: { stats: ServerStats | null }) {
  const cpuPct = stats ? Math.min(100, Math.round((stats.cpu.load1 / Math.max(1, stats.cpu.cores)) * 100)) : 0;
  const hostUsed = stats ? stats.memory.hostTotalBytes - stats.memory.hostFreeBytes : 0;
  const hostPct = stats && stats.memory.hostTotalBytes > 0
    ? Math.round((hostUsed / stats.memory.hostTotalBytes) * 100)
    : 0;
  const hist = stats?.history ?? [];
  const psi = stats?.pressure;
  const rate = (v: number) => `${formatBytes(v)}/s`;
  const pct = (v: number) => `${Math.round(v)}%`;

  const psiMem = psi?.memory?.some10 ?? 0;
  const psiCpu = psi?.cpu?.some10 ?? 0;
  const psiIo = psi?.io?.some10 ?? 0;
  const hasPsi = !!psi && (psi.memory != null || psi.cpu != null || psi.io != null);

  return (
    <>
      <section className="space-y-2">
        <h2 className="px-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Performance
        </h2>
        <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
          <MetricCard
            icon={<Cpu className="size-4" />}
            label="CPU load"
            value={stats ? `${cpuPct}%` : "—"}
            sub={stats ? `load ${stats.cpu.load1.toFixed(2)} · ${stats.cpu.cores} cores` : undefined}
            values={hist.map((h) => h.cpuPct)}
            max={100}
            tone={toneFor(cpuPct, 70, 90)}
            format={pct}
          />
          <MetricCard
            icon={<MemoryStick className="size-4" />}
            label="Host memory"
            value={stats ? `${hostPct}%` : "—"}
            sub={stats ? `${formatBytes(hostUsed)} of ${formatBytes(stats.memory.hostTotalBytes)}` : undefined}
            values={hist.map((h) => h.memPct)}
            max={100}
            tone={toneFor(hostPct, 75, 90)}
            format={pct}
          />
          <MetricCard
            icon={<ArrowDown className="size-4" />}
            label="Network in"
            value={stats?.network ? rate(stats.network.rxBps) : "—"}
            values={hist.map((h) => h.rxBps)}
            tone="neutral"
            format={rate}
          />
          <MetricCard
            icon={<ArrowUp className="size-4" />}
            label="Network out"
            value={stats?.network ? rate(stats.network.txBps) : "—"}
            values={hist.map((h) => h.txBps)}
            tone="neutral"
            format={rate}
          />
        </div>
      </section>

      <section className="space-y-2">
        <h2 className="px-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Resource pressure
        </h2>
        {hasPsi ? (
          <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
            <MetricCard
              icon={<MemoryStick className="size-4" />}
              label="Memory pressure"
              value={`${psiMem.toFixed(1)}%`}
              sub="time tasks stalled waiting for memory"
              values={hist.map((h) => h.psiMem ?? 0)}
              tone={toneFor(psiMem, 10, 30)}
              format={(v) => `${v.toFixed(1)}%`}
            />
            <MetricCard
              icon={<Cpu className="size-4" />}
              label="CPU pressure"
              value={`${psiCpu.toFixed(1)}%`}
              sub="time tasks stalled waiting for CPU"
              values={hist.map((h) => h.psiCpu ?? 0)}
              tone={toneFor(psiCpu, 30, 60)}
              format={(v) => `${v.toFixed(1)}%`}
            />
            <MetricCard
              icon={<Gauge className="size-4" />}
              label="I/O pressure"
              value={`${psiIo.toFixed(1)}%`}
              sub="time tasks stalled waiting for disk"
              values={hist.map((h) => h.psiIo ?? 0)}
              tone={toneFor(psiIo, 20, 50)}
              format={(v) => `${v.toFixed(1)}%`}
            />
          </div>
        ) : (
          <div className="rounded-2xl border border-border bg-card/40 px-4 py-3 text-xs text-muted-foreground">
            Pressure metrics need Linux PSI (/proc/pressure) — unavailable on this host.
          </div>
        )}
        <p className="px-4 text-xs text-muted-foreground">
          Pressure is the share of time work was stalled waiting on a resource. It rises
          before capacity runs out, so it warns earlier than a percentage-used bar.
        </p>
      </section>
    </>
  );
}

// One colour per footprint component. Colour is never the only carrier: every
// segment is also named with its size in the legend under the bar.
const USAGE_COMPONENT_META: Record<UsageComponent, { label: string; bar: string }> = {
  harness: { label: "Harness", bar: "bg-primary" },
  backend: { label: "Backend", bar: "bg-sky-500" },
  mcp: { label: "MCP servers", bar: "bg-violet-500" },
  devserver: { label: "Dev servers", bar: "bg-amber-500" },
  browser: { label: "Browser", bar: "bg-emerald-500" },
  other: { label: "Other", bar: "bg-muted-foreground/40" },
};

const USAGE_COMPONENT_ORDER: UsageComponent[] = [
  "harness",
  "backend",
  "mcp",
  "devserver",
  "browser",
  "other",
];

function formatAge(sec: number | null): string {
  if (sec == null) return "";
  if (sec < 60) return `${sec}s`;
  if (sec < 3600) return `${Math.round(sec / 60)}m`;
  if (sec < 86400) return `${(sec / 3600).toFixed(1)}h`;
  return `${(sec / 86400).toFixed(1)}d`;
}

// A session's footprint as a single proportional bar. Widths are a share of the
// session's own total, so every row fills its track and rows stay comparable by
// their number rather than by bar length.
function SessionUsageComponentBar({ row }: { row: SessionUsageRow }) {
  const total = Math.max(1, row.memBytes);
  return (
    <div className="mt-2 flex h-2 overflow-hidden rounded-full bg-foreground/[0.08]">
      {USAGE_COMPONENT_ORDER.map((component) => {
        const bytes = row.byComponent[component] ?? 0;
        if (bytes <= 0) return null;
        return (
          <div
            key={component}
            className={cn("h-full", USAGE_COMPONENT_META[component].bar)}
            style={{ width: `${(bytes / total) * 100}%` }}
          />
        );
      })}
    </div>
  );
}

function SessionUsageRowView({ row, hostTotal }: { row: SessionUsageRow; hostTotal: number }) {
  const [open, setOpen] = useState(false);
  const share = hostTotal > 0 ? Math.round((row.memBytes / hostTotal) * 100) : 0;
  const parts = USAGE_COMPONENT_ORDER.filter((c) => (row.byComponent[c] ?? 0) > 0);
  const name = row.managedName ?? row.sessionId?.slice(0, 8) ?? "unknown";

  return (
    <div className="px-4 py-3">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="flex w-full items-start justify-between gap-3 text-left"
      >
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            <span className="truncate text-sm font-medium tabular-nums">{name}</span>
            {row.orphan ? (
              <span className="shrink-0 rounded bg-amber-500/15 px-1.5 py-px text-[10px] font-semibold uppercase tracking-wide text-amber-600 dark:text-amber-500">
                orphaned
              </span>
            ) : null}
          </div>
          {row.title ? (
            <div className="truncate text-xs text-muted-foreground">{row.title}</div>
          ) : null}
          <div className="text-xs text-muted-foreground tabular-nums">
            {row.procCount} {row.procCount === 1 ? "process" : "processes"}
            {share > 0 ? ` · ${share}% of RAM` : ""}
            {row.diskBytes != null ? ` · ${formatBytes(row.diskBytes)} on disk` : ""}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <span className="text-sm font-semibold tabular-nums">{formatBytes(row.memBytes)}</span>
          <ChevronDown
            className={cn(
              "size-4 text-muted-foreground transition-transform duration-200",
              open && "rotate-180",
            )}
          />
        </div>
      </button>

      <SessionUsageComponentBar row={row} />

      <div className="mt-1.5 flex flex-wrap gap-x-3 gap-y-1">
        {parts.map((component) => (
          <span
            key={component}
            className="flex items-center gap-1 text-[11px] text-muted-foreground tabular-nums"
          >
            <span
              className={cn("size-2 shrink-0 rounded-[2px]", USAGE_COMPONENT_META[component].bar)}
            />
            {USAGE_COMPONENT_META[component].label} {formatBytes(row.byComponent[component] ?? 0)}
          </span>
        ))}
      </div>

      {open ? (
        <div className="mt-3 space-y-1 border-t border-border pt-2">
          {row.procs.map((proc) => (
            <div key={proc.pid} className="flex items-baseline justify-between gap-3 text-xs">
              <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-muted-foreground">
                <span
                  className={cn(
                    "mr-1.5 inline-block size-2 rounded-[2px] align-middle",
                    USAGE_COMPONENT_META[proc.component].bar,
                  )}
                />
                {proc.pid} {proc.label}
              </span>
              <span className="shrink-0 tabular-nums text-muted-foreground">
                {formatAge(proc.ageSec)}
              </span>
              <span className="w-16 shrink-0 text-right tabular-nums">
                {formatBytes(proc.pssBytes ?? proc.rssBytes)}
              </span>
            </div>
          ))}
          {row.worktreePath ? (
            <div className="truncate pt-1 font-mono text-[11px] text-muted-foreground">
              {row.worktreePath}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

// Which session is eating the box. The aggregate panel above says the host is
// under pressure; this says what to close, which is the only actionable form of
// that information short of SSHing in and reading `ps`.
function SessionUsagePanel() {
  const [open, setOpen] = useState(false);
  const usage = useSessionUsage(open);
  const host = usage?.host;
  const rows = usage?.sessions ?? [];
  const orphanRows = rows.filter((row) => row.orphan);
  // PSS divides each shared page among the processes mapping it, so per-session
  // totals add up instead of counting a shared library once per process.
  const anyRss = rows.some((row) => row.memBasis === "rss");

  return (
    <section className="space-y-2">
      <h2 className="px-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        Per-session breakdown
      </h2>
      <div className="overflow-hidden rounded-2xl border border-border bg-card/40">
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left"
        >
          <div className="flex min-w-0 items-center gap-3">
            <span className="flex size-7 shrink-0 items-center justify-center rounded-[7px] bg-muted text-foreground/70">
              <Layers className="size-4" />
            </span>
            <div className="min-w-0">
              <div className="text-sm font-medium">Details</div>
              <div className="text-xs text-muted-foreground">
                {open && usage
                  ? `${rows.length} ${rows.length === 1 ? "session" : "sessions"} · scanned in ${usage.scanMs}ms`
                  : "Memory and disk per session"}
              </div>
            </div>
          </div>
          <ChevronDown
            className={cn(
              "size-4 shrink-0 text-muted-foreground transition-transform duration-200",
              open && "rotate-180",
            )}
          />
        </button>

        {open ? (
          usage && host ? (
            <>
              <div className="border-t border-border bg-muted/30 px-4 py-2.5">
                <div className="text-xs text-muted-foreground tabular-nums">
                  <span className="font-medium text-foreground">
                    {formatBytes(host.memAvailableBytes)} available
                  </span>{" "}
                  of {formatBytes(host.memTotalBytes)} ·{" "}
                  {host.swapTotalBytes > 0
                    ? `${formatBytes(host.swapTotalBytes - host.swapFreeBytes)} swap used`
                    : "no swap"}{" "}
                  · load {host.load1.toFixed(2)} on {host.cores} cores
                </div>
                {host.swapTotalBytes === 0 ? (
                  <div className="mt-0.5 text-[11px] text-muted-foreground">
                    With no swap, exhausting memory means the kernel kills processes rather
                    than slowing down.
                  </div>
                ) : null}
              </div>

              {orphanRows.length ? (
                <div className="border-t border-border bg-amber-500/[0.07] px-4 py-2.5">
                  <div className="text-xs font-medium text-amber-600 dark:text-amber-500">
                    {formatBytes(usage.orphanBytes)} held by {orphanRows.length} closed{" "}
                    {orphanRows.length === 1 ? "session" : "sessions"}
                  </div>
                  <div className="mt-0.5 text-[11px] text-muted-foreground">
                    Closing a session stops its agent, tmux and browser, but not the dev
                    servers it started — those keep running until something reclaims them.
                  </div>
                </div>
              ) : null}

              <div className="divide-y divide-border border-t border-border">
                {rows.length ? (
                  rows.map((row) => (
                    <SessionUsageRowView
                      key={row.key}
                      row={row}
                      hostTotal={host.memTotalBytes}
                    />
                  ))
                ) : (
                  <div className="px-4 py-3 text-xs text-muted-foreground">
                    No session processes found.
                  </div>
                )}
              </div>

              <div className="border-t border-border px-4 py-2.5 text-[11px] text-muted-foreground tabular-nums">
                {formatBytes(usage.unattributedBytes)} in processes owned by no session
                (the omg.dev server, system daemons, your own shells).
              </div>
            </>
          ) : (
            <div className="border-t border-border px-4 py-3 text-xs text-muted-foreground">
              Measuring…
            </div>
          )
        ) : null}
      </div>
      {open ? (
        <p className="px-4 text-xs text-muted-foreground">
          Memory is {anyRss ? "resident set size" : "proportional set size"} — shared pages
          are {anyRss ? "counted once per process" : "split between the processes sharing them"}
          , so session totals {anyRss ? "may overstate" : "add up"}. Disk is the session&apos;s
          worktree, measured at most every 10 minutes.
        </p>
      ) : null}
    </section>
  );
}

function CodingAgentAuthPanel({
  session,
  onSessionChange,
  onComplete,
  onDismiss,
  inline = false,
}: {
  session: CodingAgentAuthSession;
  onSessionChange: (session: CodingAgentAuthSession | null) => void;
  onComplete: () => void | Promise<void>;
  onDismiss: () => void | Promise<void>;
  inline?: boolean;
}) {
  const [code, setCode] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    setCode("");
    setSubmitting(false);
  }, [session?.id]);

  useEffect(() => {
    if (session.status === "complete" || session.status === "error") return;
    let stopped = false;
    const poll = async () => {
      try {
        const next = await api<CodingAgentAuthSession>(`/api/coding-agents/auth/${session.id}`);
        if (stopped) return;
        if (next.status === "complete") {
          toast.success(`${authProviderLabel(next.provider)} connected`);
          await onComplete();
          return;
        }
        onSessionChange(next);
      } catch (e) {
        if (!stopped) {
          onSessionChange({ ...session, status: "error", error: e instanceof Error ? e.message : "Login check failed" });
        }
      }
    };
    const timer = window.setInterval(() => void poll(), 1_500);
    return () => {
      stopped = true;
      window.clearInterval(timer);
    };
  }, [session.id, session.status, onComplete, onSessionChange]);

  async function close() {
    await onDismiss();
  }

  async function submitCode(event: FormEvent) {
    event.preventDefault();
    if (!code.trim() || submitting) return;
    setSubmitting(true);
    try {
      const next = await api<CodingAgentAuthSession>(`/api/coding-agents/auth/${session.id}/code`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: code.trim() }),
      });
      onSessionChange(next);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Couldn't submit the code");
    } finally {
      setSubmitting(false);
    }
  }

  const providerLabel = authProviderLabel(session.provider);
  return (
    <div className={cn("space-y-4", inline && "mt-3 rounded-xl border border-warning/25 bg-background/70 p-3")}>
      {session.status === "error" ? (
        <div className="space-y-3">
          <p className="rounded-2xl bg-destructive/10 px-4 py-3 text-sm text-destructive">
            {session.error || "Login failed. Please try again."}
          </p>
          <Button variant="outline" className="w-full" onClick={() => void close()}>Close</Button>
        </div>
      ) : (
        <>
          {session.userCode ? (
            <div className="rounded-2xl bg-muted px-4 py-4 text-center">
              <p className="mb-2 text-xs text-muted-foreground">
                {session.provider === "grok"
                  ? "Confirm this code in your browser"
                  : "Enter this one-time code"}
              </p>
              <button
                type="button"
                onClick={() => {
                  void navigator.clipboard.writeText(session.userCode!);
                  toast.success("Code copied");
                }}
                className="inline-flex items-center gap-2 font-mono text-2xl font-semibold tracking-[0.15em]"
              >
                {session.userCode}
                <Copy className="size-4 text-muted-foreground" />
              </button>
            </div>
          ) : null}

          {/* The URL is already in hand here, so this opens straight at the
              provider — no placeholder step. It is gated on the URL being a
              real http(s) one for the same reason the popup carrier is: the
              CLI's URL is scraped from its stdout, and a button that opens
              nowhere is the blank tab wearing a different hat. */}
          {isAuthorizationUrl(session.authorizationUrl) ? (
            <Button
              variant="brand"
              className="w-full"
              onClick={() => window.open(session.authorizationUrl, "_blank", "noopener,noreferrer")}
            >
              <ExternalLink className="size-4" />
              Open {providerLabel} sign in
            </Button>
          ) : null}

          {/* Driven by the session, not by a provider allow-list: pi's Anthropic
              sign-in asks for the same pasted code the Claude CLI's does. */}
          {session.needsCode ? (
            <form className="space-y-2" onSubmit={(event) => void submitCode(event)}>
              <label className="block text-xs font-medium text-muted-foreground" htmlFor={`claude-auth-code-${inline ? "inline" : "dialog"}`}>
                {session.provider === "jcode-openai"
                  ? "Paste the callback URL from the address bar after approval"
                  : session.provider === "jcode-claude"
                    ? "Paste the code or callback URL Claude shows after approval"
                    : "Paste the code Claude shows after approval"}
              </label>
              <div className="flex gap-2">
                <input
                  id={`claude-auth-code-${inline ? "inline" : "dialog"}`}
                  value={code}
                  onChange={(event) => setCode(event.target.value)}
                  autoComplete="off"
                  autoCapitalize="none"
                  spellCheck={false}
                  placeholder={
                    session.provider === "jcode-openai"
                      ? "http://localhost:1455/auth/callback?..."
                      : "Authorization code"
                  }
                  className="min-w-0 flex-1 rounded-2xl border border-border bg-input/30 px-3 py-2 text-sm outline-none focus:border-ring focus:ring-2 focus:ring-ring/30"
                />
                <Button type="submit" disabled={!code.trim() || submitting}>
                  {submitting ? <Loader2 className="size-4 animate-spin" /> : "Continue"}
                </Button>
              </div>
            </form>
          ) : (
            <div className="flex items-center justify-center gap-2 py-1 text-xs text-muted-foreground">
              <Loader2 className="size-3.5 animate-spin" />
              Waiting for approval…
            </div>
          )}
        </>
      )}
    </div>
  );
}

function CodingAgentAuthDialog({
  session,
  pendingLabel,
  onSessionChange,
  onComplete,
}: {
  session: CodingAgentAuthSession | null;
  /** Provider name while the login is still being prepared, before a session. */
  pendingLabel?: string | null;
  onSessionChange: (session: CodingAgentAuthSession | null) => void;
  onComplete: () => void | Promise<void>;
}) {
  // Pending and session are the same dialog at two moments, so the title comes
  // from whichever is current rather than from the session alone — otherwise
  // the loading state would be headed "Connect Account".
  const providerLabel = session ? authProviderLabel(session.provider) : (pendingLabel ?? "your account");
  async function close() {
    if (session && session.status !== "complete") {
      await api(`/api/coding-agents/auth/${session.id}`, { method: "DELETE" }).catch(() => {});
    }
    onSessionChange(null);
  }
  return (
    <Dialog
      // Open on the CLICK. The pending flag is set before the round trip, so
      // this surface exists for the whole wait instead of appearing after it.
      open={!!session || !!pendingLabel}
      onOpenChange={(open) => {
        // Not dismissible while preparing: there is no session to cancel yet,
        // and closing would strand the CLI the server just spawned.
        if (!open && !pendingLabel) void close();
      }}
    >
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Connect {providerLabel}</DialogTitle>
          <DialogDescription>
            {session
              ? "Finish signing in in the browser. omg.dev will detect approval automatically."
              : `Starting the ${providerLabel} sign-in on your Computer.`}
          </DialogDescription>
        </DialogHeader>
        {session ? (
          <CodingAgentAuthPanel
            session={session}
            onSessionChange={onSessionChange}
            onComplete={onComplete}
            onDismiss={() => void close()}
          />
        ) : (
          // The wait, given a shape. This is the state the browser tab used to
          // stand in for — same seconds, but spent on a surface that says what
          // is happening and keeps the user where the next control appears.
          <div className="space-y-3 py-2">
            <div className="flex items-center justify-center gap-2 py-4 text-sm text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
              Preparing your sign-in link…
            </div>
            <p className="text-center text-xs text-muted-foreground/70">
              Your Computer is starting the {providerLabel} CLI. The sign-in
              button appears here when it is ready.
            </p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

function fmtReset(ms: number | null): string {
  if (!ms) return "";
  const diff = ms - Date.now();
  if (diff <= 0) return "resets now";
  const mins = Math.round(diff / 60000);
  if (mins < 60) return `resets in ${mins}m`;
  const hrs = Math.round(mins / 60);
  if (hrs < 48) return `resets in ${hrs}h`;
  return `resets in ${Math.round(hrs / 24)}d`;
}

function UsageBar({ w }: { w: UsageWindow }) {
  const pct = w.pct == null ? null : Math.max(0, Math.min(100, w.pct));
  const tone =
    pct == null
      ? "bg-muted-foreground/40"
      : pct >= 90
        ? "bg-destructive"
        : pct >= 70
          ? "bg-amber-500"
          : "bg-primary";
  return (
    <div className="space-y-1">
      <div className="flex items-baseline justify-between text-xs">
        <span className="font-medium text-muted-foreground">{w.label}</span>
        <span className="tabular-nums">
          {pct == null ? "—" : `${Math.round(pct)}%`}
          {w.resetsAt ? (
            <span className="ml-2 text-muted-foreground/70">{fmtReset(w.resetsAt)}</span>
          ) : null}
        </span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-foreground/[0.08]">
        <div
          className={cn("h-full rounded-full transition-all duration-300 ease-ios", tone)}
          style={{ width: `${pct ?? 0}%` }}
        />
      </div>
    </div>
  );
}

function UsageLimitsSection() {
  // Rows come from the source directory and fill in one by one, so a Claude
  // account that answers fast isn't held behind a slow provider — and each
  // connected account gets its own row with its own windows.
  const { refs, providers, error, refreshing, refresh } = useUsageFeed();
  const byId = useMemo(
    () => new Map(providers.map((provider) => [provider.id, provider])),
    [providers],
  );

  return (
    <section className="space-y-2">
      <div className="flex items-center justify-between px-4">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Usage &amp; limits
        </h2>
        <button
          type="button"
          onClick={refresh}
          disabled={refreshing}
          className="flex items-center gap-1 text-xs text-muted-foreground transition-colors hover:text-foreground disabled:opacity-50"
        >
          <RotateCcw className={cn("size-3.5", refreshing && "animate-spin")} />
          Refresh
        </button>
      </div>
      <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
        {refs == null && !error ? (
          <div className="px-4 py-6 text-center text-sm text-muted-foreground">Loading…</div>
        ) : error ? (
          <div className="px-4 py-6 text-center text-sm text-destructive">{error}</div>
        ) : (
          refs!.map((ref) => {
            const p = byId.get(ref.id);
            return (
              <div key={ref.id} className="flex flex-col gap-2.5 px-4 py-3">
                <div className="flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <span className="flex size-7 items-center justify-center rounded-[7px] border border-border bg-background">
                      <img
                        src={agentIconSrc(ref.kind)}
                        alt={agentIconAlt(ref.kind)}
                        className="size-4"
                      />
                    </span>
                    <span className="text-sm font-medium">{ref.label}</span>
                    {p?.plan ? (
                      <span className="rounded-full bg-secondary px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
                        {p.plan}
                      </span>
                    ) : null}
                  </div>
                  {p && !p.available ? (
                    <span className="text-xs text-muted-foreground/70">unavailable</span>
                  ) : null}
                </div>
                {!p ? (
                  <p className="pl-10 text-xs text-muted-foreground">Reading limits…</p>
                ) : p.available && p.windows?.length ? (
                  <div className="space-y-2 pl-10">
                    {p.windows.map((w) => (
                      <UsageBar key={w.label} w={w} />
                    ))}
                  </div>
                ) : (
                  <p className="pl-10 text-xs text-muted-foreground">{p.note ?? "No data"}</p>
                )}
              </div>
            );
          })
        )}
      </div>
      <p className="px-4 text-xs text-muted-foreground">
        Claude reads the live subscription usage endpoint once per connected account; Codex
        reflects the latest rate-limit snapshot from its most recent session; Grok pulls monthly
        and weekly credits from the cli-chat-proxy billing API. Press{" "}
        <kbd className="rounded bg-muted px-1 font-mono text-[10px]">Shift</kbd> anywhere (or
        long-press the composer activity rings) for the campfire view of every agent.
      </p>
    </section>
  );
}

// Usage lives on its own page (opened from Settings) rather than inline, so the
// per-provider limit bars get the full width instead of crowding the settings list.
function UsagePage() {
  return (
    <div className="mx-auto max-w-xl space-y-8 pb-10" data-lfg-page-column>
      <UsageLimitsSection />
    </div>
  );
}

export type GalleryArtifact = {
  id: string;
  kind: "image" | "video" | "html";
  url: string;
  name: string;
  title?: string;
  caption?: string;
  sessionId?: string;
  sessionTitle?: string;
  agent?: string;
  project?: string;
  sessionStartedAt?: number;
  ts: number;
  version?: number;
  size?: number;
  lastRefreshedAt?: number;
  refreshStatus?: "idle" | "running" | "success" | "error";
  refreshEnabled?: boolean;
};

export type ShipMediaItem = {
  artifactId: string;
  kind: "image" | "video" | "html";
  url: string;
  name: string;
  caption?: string;
  version?: number;
  updatedAt?: number;
  lastRefreshedAt?: number;
  refreshStatus?: "idle" | "running" | "success" | "error";
};

export type ShipProvenance = {
  state: "uncommitted" | "unlanded" | "landed" | "clean" | "unknown";
  branch?: string;
  head?: string;
  dirty: number;
  /** Commits origin/main lacks entirely — the unlanded ones. */
  ahead: number;
  /** Commits ahead of origin/main by sha, squash-merged ones included. */
  commits: number;
};

export type ShipPost = {
  id: string;
  rev: number;
  ts: number;
  firstTs: number;
  title: string;
  // Clamped by the server for the feed; the session transcript has the rest.
  summary?: string;
  summaryTruncated?: boolean;
  sessionId?: string;
  sessionTitle?: string;
  agent?: string;
  project?: string;
  // Capped at four by the server; `mediaTotal` is the true count so the
  // thumbnail can show "+N" without shipping the rest of the gallery.
  mediaItems: ShipMediaItem[];
  mediaTotal?: number;
  // Git state of the posting session's worktree at ship time, kept for tracing
  // a post back to a commit. Not rendered: a ship whose code did not land is
  // refused outright, so there is no "untrustworthy post" state to badge.
  code?: ShipProvenance;
};

/**
 * Account icon fetch/upload/remove, against an endpoint that works identically
 * on a roster box (icon keyed by the selected profile, `identityEmail`) and a
 * roster-less hosted Computer (identityEmail is null there — the server
 * resolves identity from the paired omg account instead; see
 * iconIdentityKey in src/users.ts).
 *
 * Split out of what used to be one component (UserIconSettingsSection) so the
 * Settings identity row and the icon-only card below it could share ONE
 * avatar instead of drawing two different answers to "who am I" a centimetre
 * apart — the identity row's own letter tile, and this one's real picture,
 * with the letter on top. See IdentitySettingsHeader.
 */
function useAccountIcon(identityEmail: string | null) {
  const [state, setState] = useState<{ avatar: string; hasCustomIcon: boolean } | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const query = identityEmail ? `?email=${encodeURIComponent(identityEmail)}` : "";

  const load = useCallback(() => {
    void omgFetch(`/api/settings/icon${query}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((d: { avatar?: string; hasCustomIcon?: boolean } | null) => {
        if (d?.avatar) setState({ avatar: d.avatar, hasCustomIcon: !!d.hasCustomIcon });
      })
      .catch(() => {});
  }, [query]);

  useEffect(() => {
    load();
  }, [load]);

  const upload = useCallback(async (file: File) => {
    setBusy(true);
    setError(null);
    try {
      const res = await api<{ avatar: string }>(`/api/settings/icon${query}`, {
        method: "POST",
        headers: { "Content-Type": file.type || "application/octet-stream" },
        body: file,
      });
      setState({ avatar: res.avatar, hasCustomIcon: true });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't upload that image");
    } finally {
      setBusy(false);
    }
  }, [query]);

  const remove = useCallback(async () => {
    setBusy(true);
    setError(null);
    try {
      const res = await api<{ avatar: string }>(`/api/settings/icon${query}`, {
        method: "DELETE",
      });
      setState({ avatar: res.avatar, hasCustomIcon: false });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't remove that image");
    } finally {
      setBusy(false);
    }
  }, [query]);

  return { state, busy, error, upload, remove };
}

/**
 * The avatar itself: the uploaded picture, or a plain fallback glyph until
 * something is uploaded. Sized by the caller so the same element can be the
 * icon card's size-14 circle or the identity row's size-12 one.
 */
function AccountAvatarImage({
  avatar,
  busy,
  sizeClassName = "size-14",
}: {
  avatar: string | undefined;
  busy: boolean;
  sizeClassName?: string;
}) {
  return (
    <span className={cn(
      "relative flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted",
      sizeClassName,
    )}>
      {avatar ? (
        <img src={avatar} alt="" className="size-full object-cover" />
      ) : (
        <UserRound className="size-6 text-muted-foreground" />
      )}
      {busy ? (
        <span className="absolute inset-0 flex items-center justify-center bg-background/60">
          <Loader2 className="size-4 animate-spin text-muted-foreground" />
        </span>
      ) : null}
    </span>
  );
}

/**
 * Icon-only fallback for a bare/host-mounted surface, which renders no
 * identity row of its own (the host already shows the signed-in account — see
 * IdentitySettingsHeader's comment) but still needs somewhere to manage the
 * icon, since that feature is ours, not the host's.
 */
function UserIconSettingsSection({ identityEmail }: { identityEmail: string | null }) {
  const { state, busy, error, upload, remove } = useAccountIcon(identityEmail);
  const fileInputRef = useRef<HTMLInputElement>(null);

  return (
    // No section header: this card's own avatar + "Upload"/"Replace" buttons
    // already say "this is your icon" without a label repeating it above.
    <section className="space-y-2">
      <div className="flex items-center gap-4 rounded-2xl border border-border bg-card/40 px-4 py-3.5">
        <AccountAvatarImage avatar={state?.avatar} busy={busy} />
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          {/* The picker enforces the formats and the size cap, and rejects
              anything else with a message naming what it got. Spelling them out
              here made a permanent paragraph out of a constraint you only meet
              when you break it. */}
          <div className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={busy}
              onClick={() => fileInputRef.current?.click()}
            >
              <Camera className="size-3.5" />
              {state?.hasCustomIcon ? "Replace" : "Upload"}
            </Button>
            {state?.hasCustomIcon ? (
              <Button type="button" variant="outline" size="sm" disabled={busy} onClick={() => void remove()}>
                <Trash2 className="size-3.5" />
                Remove
              </Button>
            ) : null}
          </div>
          {error ? <p className="text-xs text-destructive">{error}</p> : null}
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,image/gif"
          className="hidden"
          onChange={(e) => {
            const file = e.target.files?.[0];
            e.target.value = "";
            if (file) void upload(file);
          }}
        />
      </div>
    </section>
  );
}

/**
 * The Settings identity row for a standalone (non-bare) surface: name, device
 * status, and now the real account avatar with its upload/replace/remove
 * actions folded in, rather than a plain initial-letter tile above a separate
 * icon card making the same claim with a real picture underneath it.
 */
function IdentitySettingsHeader({ user }: { user: string | null }) {
  const { state, busy, error, upload, remove } = useAccountIcon(user);
  const fileInputRef = useRef<HTMLInputElement>(null);

  return (
    <div className="flex items-center gap-3.5 px-1">
      <AccountAvatarImage avatar={state?.avatar} busy={busy} sizeClassName="size-12" />
      <div className="min-w-0 flex-1">
        <div className="truncate text-lg font-semibold leading-tight">
          {user ?? "No user selected"}
        </div>
        <div className="text-sm text-muted-foreground">
          {user ? "Signed in on this device" : "Pick your name in the top filter"}
        </div>
        <div className="mt-1.5 flex gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={busy}
            onClick={() => fileInputRef.current?.click()}
          >
            <Camera className="size-3.5" />
            {state?.hasCustomIcon ? "Replace" : "Upload"}
          </Button>
          {state?.hasCustomIcon ? (
            <Button type="button" variant="outline" size="sm" disabled={busy} onClick={() => void remove()}>
              <Trash2 className="size-3.5" />
              Remove
            </Button>
          ) : null}
        </div>
        {error ? <p className="mt-1 text-xs text-destructive">{error}</p> : null}
      </div>
      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        className="hidden"
        onChange={(e) => {
          const file = e.target.files?.[0];
          e.target.value = "";
          if (file) void upload(file);
        }}
      />
    </div>
  );
}

/**
 * One version row in Settings > Computer.
 *
 * Copy is offered only when there is a real version behind it. "Unavailable"
 * and "Disconnected" are states, not values, and putting either on someone's
 * clipboard to paste into a bug report would be worse than offering nothing.
 */
function VersionRow({
  icon,
  iconClassName,
  label,
  value,
  copyValue,
}: {
  icon: ReactNode;
  iconClassName: string;
  label: string;
  value: string;
  copyValue: string | null;
}) {
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) return;
    const id = setTimeout(() => setCopied(false), 1200);
    return () => clearTimeout(id);
  }, [copied]);

  // min-w-0 + truncate on the label column and shrink-0 on the value keeps a
  // long label from pushing the number off a 320px screen.
  const body = (
    <>
      <div className="flex min-w-0 items-center gap-3">
        <span
          className={cn(
            "flex size-7 shrink-0 items-center justify-center rounded-[7px]",
            iconClassName,
          )}
        >
          {icon}
        </span>
        <span className="min-w-0 truncate text-sm font-medium">{label}</span>
      </div>
      <span className="flex shrink-0 items-center gap-2">
        <span
          className={cn(
            "text-sm font-semibold tabular-nums",
            copyValue ? "font-mono" : "text-muted-foreground",
          )}
        >
          {value}
        </span>
        {copyValue ? (
          copied ? (
            <Check className="size-3.5 text-success" />
          ) : (
            <Copy className="size-3.5 text-muted-foreground/60" />
          )
        ) : null}
      </span>
    </>
  );

  if (!copyValue) {
    return <div className="flex items-center justify-between gap-3 px-4 py-2.5">{body}</div>;
  }

  return (
    <button
      type="button"
      aria-label={`Copy ${label} version ${copyValue}`}
      onClick={() => {
        void copyMessageText(copyValue)
          .then(() => setCopied(true))
          .catch(() => toast.error("Could not copy the version"));
      }}
      className="flex w-full items-center justify-between gap-3 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
    >
      {body}
    </button>
  );
}

/**
 * Version + Updates, collapsed into one row in Settings > Computer.
 *
 * Used to be three separate rows (Frontend, Computer, Updates) always on
 * screen — Benny's call was one row that expands, since most of the time
 * nobody needs the breakdown. The one thing that can't wait for a tap is a
 * skew between Frontend and Computer: that pair exists ONLY to make a skew
 * visible, so the collapsed subtitle says so directly (versionNote) instead
 * of hiding it behind the same disclosure as the routine breakdown.
 */
function VersionUpdatesRow({
  frontendVersion,
  computerVersion,
  versionSkew,
  versionNote,
}: {
  frontendVersion: string | null;
  computerVersion: ComputerVersionState;
  versionSkew: VersionRelation;
  versionNote: string | null;
}) {
  const [open, setOpen] = useState(false);
  const mismatch = isVersionMismatch(versionSkew);
  const subtitle = mismatch
    ? versionNote
    : versionSkew === "match"
      ? "Frontend and Computer match"
      : null;

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <CollapsibleTrigger
        className="flex w-full items-center justify-between gap-4 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
        aria-label="Version and updates"
        aria-expanded={open}
      >
        <div className="flex min-w-0 items-center gap-3">
          <span className={cn(
            "flex size-7 shrink-0 items-center justify-center rounded-[7px]",
            mismatch ? "bg-warning text-white" : "bg-muted text-foreground/70",
          )}>
            {mismatch ? <TriangleAlert className="size-4" /> : <Layers className="size-4" />}
          </span>
          <div className="min-w-0">
            <div className="text-sm font-medium">Version</div>
            {subtitle ? (
              <div className={cn(
                "text-xs text-pretty",
                mismatch ? "font-medium text-warning" : "text-muted-foreground",
              )}>
                {subtitle}
              </div>
            ) : null}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          <span className="text-sm font-semibold tabular-nums text-muted-foreground">
            {formatVersion(frontendVersion)}
          </span>
          <ChevronDown className={cn(
            "size-3.5 text-muted-foreground/70 transition-transform duration-150",
            open && "rotate-180",
          )} />
        </div>
      </CollapsibleTrigger>
      <CollapsibleContent className="divide-y divide-border border-t border-border">
        <VersionRow
          icon={<Layers className="size-4" />}
          iconClassName="bg-muted text-foreground/70"
          label="Frontend"
          value={formatVersion(frontendVersion)}
          copyValue={frontendVersion ? `v${frontendVersion}` : null}
        />
        <VersionRow
          icon={<Cpu className="size-4" />}
          iconClassName="bg-foreground text-background"
          label="Computer"
          value={formatComputerVersion(computerVersion)}
          copyValue={copyableVersion(computerVersion)}
        />
        {/* Same disclosure as the two versions above: between them they answer
            one question — what is running here, and is anything newer. */}
        <ErrorBoundary variant="card" boundary="omg-update">
          <UpdateSettingsRow />
        </ErrorBoundary>
      </CollapsibleContent>
    </Collapsible>
  );
}

function SettingsView({
  user,
  settings,
  onSettingsChange,
  onOpenCodingAgents,
  onOpenAuto,
  onOpenStorage,
  onOpenMore,
  connection,
  computerVersionReport,
}: {
  user: string | null;
  settings: GlobalSettings;
  onSettingsChange: (patch: Partial<GlobalSettings>) => Promise<void>;
  onOpenCodingAgents: () => void;
  onOpenAuto: () => void;
  onOpenStorage: () => void;
  onOpenMore: () => void;
  connection: ConnectionState | null;
  computerVersionReport: { version: string | null; generation: number } | null;
}) {
  // A host mounting this page renders the signed-in account itself — and its
  // account is the real one, where ours is only a per-device session tag. Two
  // identity blocks on one page is worse than none.
  const bare = useBareSurface();

  // The two halves of "what am I actually looking at", resolved from two
  // independent sources: FRONTEND_VERSION is stamped into this bundle at build
  // time, and the Computer value comes only from that box's own bootstrap
  // response. Neither falls back to the other — see version-diagnostics.ts.
  const computerVersion = resolveComputerVersion({
    reported: computerVersionReport?.version,
    loaded: computerVersionReport != null,
    connection: connection?.status ?? null,
    // A number captured over a previous transport describes the machine we
    // just switched away from, so it is dropped rather than relabelled.
    stale:
      computerVersionReport != null &&
      computerVersionReport.generation !== omgTransportGeneration(),
  });
  const versionSkew = versionRelation(FRONTEND_VERSION, computerVersion);
  const versionNote = versionMismatchNote(versionSkew);

  return (
    <div className="mx-auto max-w-xl space-y-8 pb-10" data-lfg-page-column>
      {bare ? <UserIconSettingsSection identityEmail={user} /> : <IdentitySettingsHeader user={user} />}

      {/* Computer — in standalone LFG this box IS the computer, so the row is
          static. When these sections are mounted by a host (omg) this is the
          slot that becomes a machine switcher. */}
      <section className="space-y-2">
        {/* Not uppercased — see RailGroup: group labels read quieter lowercase. */}
        <h2 className="px-4 text-xs font-semibold text-muted-foreground">
          Computer
        </h2>
        <div className="overflow-hidden rounded-2xl border border-border bg-card/40 divide-y divide-border">
          <button
            type="button"
            onClick={onOpenCodingAgents}
            className="flex w-full items-center justify-between gap-4 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
          >
            <div className="flex items-center gap-3">
              <span className="flex size-7 items-center justify-center rounded-[7px] bg-foreground text-background">
                <Bot className="size-4" />
              </span>
              <span className="text-sm font-medium">Coding agents</span>
            </div>
            <ChevronRight className="size-4 text-muted-foreground/60" />
          </button>
          <button
            type="button"
            onClick={onOpenAuto}
            className="flex w-full items-center justify-between gap-4 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
          >
            <div className="flex items-center gap-3">
              <span className="flex size-7 items-center justify-center rounded-[7px] bg-primary text-white">
                <CalendarClock className="size-4" />
              </span>
              <span className="text-sm font-medium">Schedules</span>
            </div>
            <ChevronRight className="size-4 text-muted-foreground/60" />
          </button>
          <button
            type="button"
            onClick={onOpenStorage}
            className="flex w-full items-center justify-between gap-4 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
          >
            <div className="flex items-center gap-3">
              <span className="flex size-7 items-center justify-center rounded-[7px] bg-foreground text-background">
                <HardDrive className="size-4" />
              </span>
              <span className="text-sm font-medium">Storage &amp; performance</span>
            </div>
            <ChevronRight className="size-4 text-muted-foreground/60" />
          </button>
          {/* One row for what used to be three (Frontend, Computer, Updates):
              which UI build is rendering, what the selected Computer is
              really executing, and whether either has an update. A skew
              between the first two is still legible collapsed — see
              VersionUpdatesRow's own comment. */}
          <VersionUpdatesRow
            frontendVersion={FRONTEND_VERSION}
            computerVersion={computerVersion}
            versionSkew={versionSkew}
            versionNote={versionNote}
          />
        </div>
      </section>

      <AgentConcurrencySettingsSection
        settings={settings}
        onChange={onSettingsChange}
      />

      {/* More — the long tail lives on its own page so this one stays scannable.
          Hidden on a host-mounted surface: everything behind it (push,
          appearance, sound, haptics, install) describes the DEVICE, and the
          host already owns those for its own app. Showing ours put a second
          set of switches next to the host's, and ours were the ones that could
          not work — the push toggle would have had to borrow a service worker
          from an origin we do not own. `bare` is true only for
          OmgSettingsSurface, which is exactly the host-mounted case. */}
      {bare ? null : (
      <section className="space-y-2">
        <div className="overflow-hidden rounded-2xl border border-border bg-card/40">
          <button
            type="button"
            onClick={onOpenMore}
            className="flex w-full items-center justify-between gap-4 px-4 py-2.5 text-left transition-colors duration-150 ease-ios hover:bg-foreground/[0.03] active:bg-foreground/[0.06]"
          >
            <div className="flex items-center gap-3">
              <span className="flex size-7 items-center justify-center rounded-[7px] bg-muted text-foreground/70">
                <Ellipsis className="size-4" />
              </span>
              <span>
                <span className="block text-sm font-medium">More</span>
                <span className="block text-xs text-muted-foreground">
                  Tools, appearance, notifications, voice, help
                </span>
              </span>
            </div>
            <ChevronRight className="size-4 text-muted-foreground/60" />
          </button>
        </div>
      </section>
      )}
    </div>
  );
}

